(window.CLAVE_TODO=window.CLAVE_TODO||{})[17]=[{"a":"3.2. Requisitos de la actuación con menores en el ámbito administrativo","q":[{"i":"17-1","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". La actuación policial con menores autores de infracciones administrativas se limitará:","o":["A aquellos casos en que sea estrictamente necesario en aplicación de leyes y normas concretas, bajo el principio de mínima intervención y protección del interés superior del menor.","A aquellos casos en que sea necesaria en aplicación de leyes y normas, bajo el principio de igualdad y protección del interés superior del menor.","No será limitada en ningún caso.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A aquellos casos en que sea estrictamente necesario en aplicación de leyes y normas concretas, bajo el principio de mínima intervención y p…</mark></span>La Instrucción establece la limitación de la actuación policial en infracciones administrativas a lo estrictamente necesario en aplicación de leyes y normas, y bajo los principios de mínima intervención y del interés superior del menor."},{"i":"17-31","p":"Instrucción 1/2017. Requisitos de la actuación con menores en el ámbito administrativo. El tratamiento y trámites policiales a realizar se adecuarán en función de la edad y circunstancias personales y familiares del menor, especialmente para aquellas con edades comprendidas entre:","o":["Los dieciséis y los dieciocho años.","Los catorce y los dieciséis años.","Los doce y los catorce años.","Los catorce y los dieciocho años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los dieciséis y los dieciocho años</mark></span>Según el <span class=\"ref-norma\">punto 3.2.2 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"especialmente para aquellos con edades comprendidas entre dieciséis y dieciocho años\"</span> (verificado con el temario oficial)."},{"i":"17-63","p":"Instrucción 1/2017. Requisitos de la actuación con menores en ámbito administrativo. La actuación policial con menores autores de infracciones administrativas se limitará a una actuación bajo el principio de:","o":["Mínima intervención.","Protección del interés superior del menor.","Comunicación de la actuación a los titulares legales del menor de edad.","Las opciones A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las opciones A y B son correctas.</mark></span>*Explicación: La Instrucción 1/2017 establece que la actuación se regirá por los principios de mínima intervención y protección del interés superior del menor.*"},{"i":"17-87","p":"Instrucción 1/2017. Requisitos de la actuación con menores en el ámbito administrativo. La actuación policial con menores autores de infracciones administrativas se limitará a aquellos casos en que sea estrictamente necesaria en aplicación de leyes y normas concretas, bajo el principio de:","o":["Mínima intervención.","Protección del interés superior del menor.","Las opciones A y B son correctas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las opciones A y B son correctas.</mark></span>*Explicación: La Instrucción 1/2017 establece que la actuación se regirá por los principios de mínima intervención y protección del interés superior del menor.*"},{"i":"17-198","p":"Instrucción nº 1/2017 de la Secretaría de Estado de Seguridad, por la que se actualiza el protocolo de actuación policial con menores. Régimen General de actuación policial con menores. ¿En qué casos se llevará a cabo la actuación policial con menores autores de infracciones administrativas?","o":["En todos los casos de infracción administrativa.","Siempre que el menor sea mayor de 16 años.","Cuando la infracción administrativa sea leve.","Sólo cuando sea estrictamente necesaria y en aplicación de leyes y normas concretas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Sólo cuando sea estrictamente necesaria y en aplicación de leyes y normas concretas.</mark></span>Sólo cuando sea estrictamente necesaria y en aplicación de leyes y normas concretas."},{"i":"17-255","p":"(Instrucción 1/2017 - Actuación Policial con Menores) Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". La actuación policial con menores autores de infracciones administrativas se limitará:","o":["A aquellos casos en que sea estrictamente necesario en aplicación de leyes y normas concretas, bajo el principio de mínima intervención y protección del interés superior del menor.","A aquellos casos en que sea necesaria en aplicación de leyes y normas, bajo el principio de igualdad y protección del interés superior del menor.","No será limitada en ningún caso.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A aquellos casos en que sea estrictamente necesario en aplicación de leyes y normas concretas, bajo el principio de mínima intervención y p…</mark></span>La actuación policial ante infracciones administrativas de menores debe limitarse a lo estrictamente necesario, bajo los principios de mínima intervención y el interés superior del menor."},{"i":"17-265","p":"(Instrucción 1/2017 - Protocolo Actuación Policial con Menores) Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". La actuación policial con menores autores de infracciones administrativas se limitará:","o":["A aquellos casos en que sea estrictamente necesario en aplicación de leyes y normas concretas, bajo el principio de mínima intervención y protección del interés superior del menor.","A aquellos casos en que sea necesaria en aplicación de leyes y normas, bajo el principio de igualdad y protección del interés superior del menor.","No será limitada en ningún caso.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A aquellos casos en que sea estrictamente necesario en aplicación de leyes y normas concretas, bajo el principio de mínima intervención y protección del interés superior del menor.</mark></span> El punto 3.2.1 de la Instrucción 1/2017, de la Secretaría de Estado de Seguridad, sobre el «Protocolo de actuación policial con menores», establece que la actuación policial con menores autores de infracciones administrativas «se limitará a aquellos casos en que sea estrictamente necesaria en aplicación de leyes y normas concretas, bajo el principio de mínima intervención y protección del interés superior del menor». Se trata, por tanto, de una actuación restrictiva y subsidiaria, guiada por el interés superior del menor y no por criterios de igualdad, como sugería la opción B."},{"i":"17-ia-1518","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Requisitos de la actuación con menores en el ámbito administrativo. La actuación policial con menores autores de infracciones administrativas se limitará a aquellos casos en que sea estrictamente necesaria en aplicación de leyes y normas concretas, bajo el principio de:","o":["legalidad y proporcionalidad.","mínima intervención y prevención.","oportunidad y protección del menor, sin perjuicio de lo previsto en la normativa vigente.","mínima intervención y protección del interés superior del menor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">mínima intervención y protección del interés superior del menor</mark></span>El <span class=\"ref-norma\">3.2.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"bajo el principio de mínima intervención y protección del interés superior del menor\"</span>. Rige el principio de mínima intervención y protección del interés superior del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1519","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Requisitos de la actuación con menores en el ámbito administrativo. En las infracciones administrativas de menores, la actuación policial se reducirá, con carácter general, a participar a sus padres, tutores o guardadores, o Entidad Pública de protección de menores, a la mayor brevedad, los hechos y circunstancias conocidas, con:","o":["la detención del menor hasta su entrega.","su traslado a dependencias policiales.","confección y remisión, en su caso, de la correspondiente denuncia a la autoridad competente.","la incoación de expediente por la Fiscalía, en los términos que se determinen reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">confección y remisión, en su caso, de la correspondiente denuncia a la autoridad competente</mark></span>El <span class=\"ref-norma\">3.2.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"con confección y remisión, en su caso, de la correspondiente denuncia a la autoridad competente\"</span>. Se confecciona y remite, en su caso, la denuncia a la autoridad competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Real Decreto 1774/2004","q":[{"i":"17-2","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Detención. Llevar a cabo la detención del menor. En los establecimientos de detención deberá llevarse un libro registro, de carácter confidencial, que al menos deberá contar con la siguiente información, entre otros: Señale la INCORRECTA.","o":["Circunstancias de la detención, motivos y en su caso autoridad que la ordenó.","Indicación de la persona o personas que custodian al menor.","Detalle de la notificación a los padres o representantes legales del menor y al Ministerio Fiscal de la detención del menor.","Expresión de las circunstancias físicas del menor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Expresión de las circunstancias físicas del menor</mark></span>D cambia «psicofísicas» por «físicas» y B cambia «custodian» por «custodiaron». Según el <span class=\"ref-norma\">art. 3.5 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"f) Expresión de las circunstancias psicofísicas del menor\"</span> (verificado con el temario oficial)."},{"i":"17-21","p":"Real Decreto 1774/2004. Modo de llevar a cabo la detención. En los establecimientos de detención deberá llevarse un libro registro, de carácter confidencial, que al menos deberá contar con la siguiente información: señale la INCORRECTA.","o":["Datos relativos a la identidad del menor.","Circunstancias de la detención, motivos y en su caso autoridad que la ordenó.","Indicación de la persona o personas que custodian al menor.","Expresión de las circunstancias psicológicas del menor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Expresión de las circunstancias psicológicas del menor</mark></span>D es la incorrecta («psicológicas» en lugar de «psicofísicas»). Según el <span class=\"ref-norma\">art. 3.5 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"f) Expresión de las circunstancias psicofísicas del menor\"</span> (verificado con el temario oficial)."},{"i":"17-43","p":"Real Decreto 1774/2004. Modo de llevar a cabo la detención del menor. En los establecimientos de detención deberá llevarse un libro registro, de carácter confidencial, que al menos deberá contar con la siguiente información, entre otra:","o":["Datos relativos a la identidad del menor.","Circunstancias de la detención, motivos y en su caso autoridad que la ordenó.","Día y hora del ingreso, traslado o libertad.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 8 · Real Decreto 1774/2004</span>. *Explicación: El artículo 8 del RD 1774/2004 enumera todos estos datos como parte de la información mínima del registro.*"},{"i":"17-55","p":"Real Decreto 1774/2004. Modo de llevar a cabo la detención del menor. En los establecimientos de detención deberá llevarse un libro registro, de carácter confidencial, que al menos deberá contar con la siguiente información:","o":["Expresión de las circunstancias psicofísicas del menor.","Datos relativos a la identidad del menor.","Detalle de la notificación a los padres o representantes legales del menor y al Ministerio Fiscal de la detención del menor.","Todas las opciones son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones son correctas</mark></span>Todas las opciones son contenidos del libro registro. Según el <span class=\"ref-norma\">art. 3.5 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"f) Expresión de las circunstancias psicofísicas del menor\"</span> (verificado con el temario oficial)."},{"i":"17-62","p":"Real Decreto 1774/2004. Modo de llevar a cabo la detención del menor. El Fiscal resolverá en el menor espacio de tiempo posible y, en todo caso:","o":["Dentro de las 24 horas siguientes a la detención.","Dentro de las 48 horas siguientes a la detención.","Dentro de las 72 horas siguientes a la detención.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dentro de las 48 horas siguientes a la detención</mark></span>Las 24 horas son el plazo policial; el fiscal resuelve en 48 horas. Según el <span class=\"ref-norma\">art. 3.3 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"El fiscal resolverá en el menor espacio de tiempo posible y, en todo caso, dentro de las 48 horas siguientes a la detención\"</span> (verificado con el temario oficial)."},{"i":"17-133","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Modo de llevar a cabo la detención del menor. Sobre el Libro Registro de Detención de Menores, señale la INCORRECTA:","o":["Este libro registro será único para todo lo concerniente a la detención del menor, aunque se podrán consignar algunos de sus datos en otros libros de la dependencia.","En los establecimientos de detención deberá llevarse un libro registro, de carácter confidencial.","Los datos de dicho registro estarán exclusivamente a disposición del Ministerio Fiscal y de la autoridad judicial competente.","En el libro registro figurarán las circunstancias de la detención, motivos y en su caso autoridad que la ordenó."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Este libro registro será único para todo lo concerniente a la detención del menor, aunque se podrán consignar algunos de sus datos en otros libros de la dependencia</mark></span>A es la incorrecta: no se consigna ningún dato en otro libro de la dependencia. Según el <span class=\"ref-norma\">art. 3.5 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"Este libro registro será único para todo lo concerniente a la detención del menor, y no se consignará ninguno de sus datos en ningún otro libro de la dependencia\"</span> (verificado con el temario oficial)."},{"i":"17-135","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo la detención del menor. Señale la opción INCORRECTA:","o":["Mientras dure la detención los menores deberán hallarse custodiados en dependencias adecuadas conforme establece la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores.","Si el menor detenido fuere extranjero, el hecho de la detención se notificará a las correspondientes autoridades consulares cuando el menor tuviera su residencia habitual fuera de España o cuando así lo solicitaren el propio menor o sus representantes legales.","Las autoridades y funcionarios que intervengan en la detención de un menor estarán obligadas a informarle, en un lenguaje claro y comprensible y en el plazo máximo de veinticuatro horas, de los hechos que se le imputan, de las razones de su detención y de los derechos que le asisten, especialmente los reconocidos en el artículo 520 de la Ley de Enjuiciamiento Criminal.","Durante la detención debe garantizarse que todo menor disponga de alimentación, vestimenta y condiciones de intimidad, seguridad y sanidad adecuadas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las autoridades y funcionarios que intervengan en la detención de un menor estarán obligadas a informarle, en un lenguaje claro y comprensi…</mark></span>La información debe proporcionarse de forma inmediata, no en plazo máximo de 24 horas."},{"i":"17-136","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. En los establecimientos de detención deberá llevarse un libro registro que al menos deberá contar con la siguiente información: Señale la opción INCORRECTA.","o":["Detalle de la notificación a los padres o representantes legales del menor y al Ministerio Fiscal de la detención del menor.","Expresión de las circunstancias psicológicas del menor.","Constatación de que se le ha informado de las circunstancias de la detención y de sus derechos.","Día y hora del ingreso, traslado o libertad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Expresión de las circunstancias psicológicas del menor</mark></span>B es la incorrecta («psicológicas»); A también cambiaba el dato (se notifica al Ministerio Fiscal, no al Juez de Menores). Según el <span class=\"ref-norma\">art. 3.5 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"f) Expresión de las circunstancias psicofísicas del menor\"</span> (verificado con el temario oficial)."},{"i":"17-152","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. Detención de los menores. Mientras dure la detención los menores deberán hallarse custodiados:","o":["En dependencias generales de internamiento conforme establece la Ley de Enjuiciamiento Criminal.","En dependencias adecuadas conforme establece la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores.","En dependencias adecuadas conforme establece la Ley de Enjuiciamiento Criminal.","En dependencias generales de internamiento conforme establece la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En dependencias adecuadas conforme establece la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores.</mark></span>En dependencias adecuadas conforme a la Ley Orgánica 5/2000."},{"i":"17-178","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo la detención del menor. Señale la opción INCORRECTA:","o":["Las autoridades y funcionarios que intervengan en la detención de un menor deberán practicarla en la forma que menos lo perjudique.","En los establecimientos de detención deberá llevarse un libro registro, de carácter confidencial.","Toda declaración del detenido se llevará a cabo en presencia de su letrado y de aquellos que ejerzan la patria potestad, tutela o guarda del menor, de hecho o de derecho, salvo que, en este último caso, las circunstancias aconsejen lo contrario.","Si el menor detenido fuere extranjero, el hecho de la detención se notificará a las correspondientes autoridades consulares cuando el menor tuviera su residencia habitual dentro de España o cuando así lo solicitaran el propio menor o sus representantes legales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Si el menor detenido fuere extranjero, el hecho de la detención se notificará a las correspondientes autoridades consulares cuando el menor…</mark></span>Es incorrecta porque la notificación se hace cuando el menor tiene residencia habitual FUERA de España."},{"i":"17-186","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la actuación de la Policía Judicial y del equipo técnico. Durante la detención debe garantizarse que todo menor disponga de: señale la INCORRECTA.","o":["Alimentación.","Asistencia psicológica y física necesaria.","Vestimenta.","Condiciones de intimidad, seguridad y sanidad adecuadas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Asistencia psicológica y física necesaria.</mark></span>Asistencia psicológica y física necesaria no está entre las garantías básicas durante la detención."},{"i":"17-210","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo la detención del menor. En los establecimientos de detención deberá llevarse un libro registro, de carácter:","o":["Accesible únicamente para los padres del menor.","Público.","Confidencial.","Exclusivo para el personal policial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Confidencial.</mark></span>Confidencial."},{"i":"17-242","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo la detención del menor. Toda declaración del detenido se llevará a cabo en presencia de su letrado y de aquellos que ejerzan la patria potestad, tutela o guarda del menor, de hecho o de derecho, salvo que, en este último caso, las circunstancias aconsejen lo contrario. En defecto de estos últimos, la declaración se llevará a cabo en presencia del Ministerio Fiscal, representado por:","o":["El propio fiscal instructor del expediente, en los términos que determine la ley orgánica correspondiente.","Un fiscal distinto del instructor del expediente.","El Fiscal Jefe de la Sección de Menores.","Un miembro del equipo técnico."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un fiscal distinto del instructor del expediente</mark></span>El <span class=\"ref-norma\">art. 3.2 de la RD 1774/2004</span> dispone: <span class=\"ref-concepto\">\"la declaración se llevará a cabo en presencia del Ministerio Fiscal, representado por un fiscal distinto del instructor del expediente\"</span>"},{"i":"17-ia-1418","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo la detención del menor. La custodia de los menores detenidos corresponderá a las Fuerzas y Cuerpos de Seguridad competentes hasta que:","o":["el menor sea puesto a disposición del Juez de Menores, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","transcurran las veinticuatro horas de detención.","la entidad pública de reforma se haga cargo del menor.","el fiscal resuelva sobre la libertad del menor, el desistimiento o la incoación del expediente, con puesta a disposición del juez."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el fiscal resuelva sobre la libertad del menor, el desistimiento o la incoación del expediente, con puesta a disposición del juez</mark></span>El <span class=\"ref-norma\">art. 3.3 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"corresponderá a las Fuerzas y Cuerpos de Seguridad competentes hasta que el fiscal resuelva sobre la libertad del menor, el desistimiento o la incoación del expediente, con puesta a disposición del juez\"</span>. La custodia policial dura hasta que el fiscal resuelva libertad, desistimiento o incoación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1419","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo la detención del menor. El fiscal resolverá sobre la libertad del menor, el desistimiento o la incoación del expediente en el menor espacio de tiempo posible y, en todo caso, dentro de las:","o":["24 horas siguientes a la detención.","72 horas siguientes a la detención.","48 horas siguientes a la detención.","48 horas siguientes a la puesta a disposición del Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">48 horas siguientes a la detención</mark></span>El <span class=\"ref-norma\">art. 3.3 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"dentro de las 48 horas siguientes a la detención\"</span>. El plazo del fiscal es de 48 horas desde la detención. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1420","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo la detención del menor. Durante la detención debe garantizarse que todo menor disponga de alimentación, vestimenta y condiciones de intimidad, seguridad y:","o":["asistencia jurídica adecuadas.","sanidad adecuadas.","higiene adecuadas.","comunicación adecuadas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sanidad adecuadas</mark></span>El <span class=\"ref-norma\">art. 3.4 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"alimentación, vestimenta y condiciones de intimidad, seguridad y sanidad adecuadas\"</span>. Alimentación, vestimenta y condiciones de intimidad, seguridad y sanidad adecuadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1422","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo la detención del menor. Los datos del libro registro de los establecimientos de detención estarán exclusivamente a disposición del:","o":["Ministerio Fiscal y de la Policía Judicial.","Juez de Menores y del equipo técnico.","Ministerio del Interior y del Ministerio Fiscal, previo informe de la unidad policial competente.","Ministerio Fiscal y de la autoridad judicial competente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ministerio Fiscal y de la autoridad judicial competente</mark></span>El <span class=\"ref-norma\">art. 3.5 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"Los datos de dicho registro estarán exclusivamente a disposición del Ministerio Fiscal y de la autoridad judicial competente\"</span>. Solo el Ministerio Fiscal y la autoridad judicial competente acceden. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1423","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo la detención del menor. El libro registro de detención del menor será único para todo lo concerniente a la detención del menor, y no se consignará ninguno de sus datos en:","o":["el libro de registro y custodia de detenidos, salvo la identidad.","el libro de incidencias de la dependencia.","ningún otro libro de la dependencia.","ningún libro de otra dependencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">ningún otro libro de la dependencia</mark></span>El <span class=\"ref-norma\">art. 3.5 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"no se consignará ninguno de sus datos en ningún otro libro de la dependencia\"</span>. No se consigna ninguno de sus datos en ningún otro libro de la dependencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RECUERDA del temario · LO 5/2000 (R1 a R7) R1 R2 R3 R4 R5 R6 R7","q":[{"i":"17-3","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. El Ministerio Fiscal deberá dar vista del expediente al letrado del menor y, en su caso, a quien haya ejercitado la acusación penal, en un plazo no superior a veinticuatro horas:","o":["Solo al inicio de la diligencia de que se trate.","Solo tras la finalización de la diligencia de que se trate.","Tanto al inicio como a la finalización de cada diligencia.","Tantas veces como aquel lo solicite."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Tantas veces como aquel lo solicite</mark></span>La vista no se limita al inicio y al final de cada diligencia: es «tantas veces como aquel lo solicite». Según el <span class=\"ref-norma\">art. 23.2 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"tantas veces como aquel lo solicite\"</span> (verificado con el temario oficial)."},{"i":"17-5","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Corresponde la defensa de los derechos a los menores reconocidos en las leyes, así como la vigilancia de las actuaciones que deban efectuarse en su interés y la observancia de las garantías del procedimiento:","o":["Al Juez Instructor del procedimiento penal.","Al Ministerio Fiscal.","A la Unidad Central de la Policía Judicial de Menores.","A) y B) son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 15.1 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. La Ley Orgánica 5/2000, en su artículo 15.1, atribuye al Ministerio Fiscal la instrucción del expediente, la defensa de los derechos de los menores y la vigilancia de las garantías del procedimiento."},{"i":"17-28","p":"Ley Orgánica 5/2000. De la instrucción del procedimiento. ¿A quién corresponde la instrucción de los procedimientos por los hechos penales cometidos por menores de edad entre 14 y 18 años de edad?:","o":["A la Policía Judicial, preferentemente a los equipos especializados en menores.","Al Ministerio Fiscal.","A la Audiencia Provincial.","Al Juez de Menores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 27 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 27 de la LO 5/2000 atribuye la instrucción del procedimiento al Ministerio Fiscal.*"},{"i":"17-39","p":"Ley Orgánica 5/2000. De las medidas. Las medidas que pueden imponer los Jueces de Menores, ordenadas según la restricción de derechos que suponen, son las siguientes: Señale la INCORRECTA.","o":["Internamiento en régimen cerrado.","Internamiento en régimen semiabierto.","Internamiento en régimen abierto.","Internamiento en régimen de libertad vigilada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Internamiento en régimen de libertad vigilada.</mark></span><span class=\"ref-norma\">Art. 9 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: La &quot;libertad vigilada&quot; es una medida diferente al internamiento, no un régimen de éste. Los regímenes de internamiento son solo cerrado, semiabierto y abierto (Art. 9 LO 5/2000).*"},{"i":"17-50","p":"Ley Orgánica 5/2000. La competencia para conocer de los hechos delictivos cometidos por menores corresponde a:","o":["Juzgados de Instrucción.","Juzgados de lo Penal.","Juzgados de Menores.","Audiencia Provincial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Juzgados de Menores.</mark></span><span class=\"ref-norma\">Art. 2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 2 de la LO 5/2000 atribuye la competencia a los Juzgados de Menores para los hechos delictivos cometidos por personas de 14 a 18 años.*"},{"i":"17-51","p":"Real Decreto 1774/2004. Los equipos técnicos dependen funcionalmente de:","o":["El Juez de Menores.","El Ministerio Fiscal.","La Comunidad Autónoma.","El Ministerio de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 19.2 · Real Decreto 1774/2004</span>. *Explicación: El artículo 19.2 del RD 1774/2004 establece que los equipos técnicos dependen funcionalmente del Ministerio Fiscal durante el procedimiento.*"},{"i":"17-57","p":"Ley Orgánica 5/2000. Incoación del expediente. ¿Quién podrá desistir de la incoación del expediente cuando los hechos denunciados constituyan delitos menos graves sin violencia o intimidación en las personas o faltas, tipificadas en el Código Penal o en las leyes penales especiales?","o":["El Juez instructor.","El Juez de Instrucción.","El Juez de Menores del lugar donde se hubiesen cometido los hechos.","El Ministerio Fiscal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 27.5 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 27.5 de la LO 5/2000 otorga esta facultad de desistimiento al Ministerio Fiscal.*"},{"i":"17-61","p":"Ley Orgánica 5/2000. Plazos detención de los menores. La detención de un menor por funcionarios de policía no podrá durar más tiempo del estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos, y, en todo caso, dentro del plazo máximo de _____ el menor detenido deberá ser puesto en libertad o a disposición del Ministerio Fiscal.","o":["24 horas.","48 horas.","36 horas.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">24 horas.</mark></span><span class=\"ref-norma\">Art. 17.2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 17.2 de la LO 5/2000 establece un plazo máximo de 24 horas para la detención policial de menores.*"},{"i":"17-65","p":"Ley Orgánica 5/2000. Medidas. Reglas generales. El tiempo máximo de la medida cautelar de internamiento será de:","o":["Un mes, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros seis meses como máximo.","Dos meses, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros seis meses como máximo.","Tres meses, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros tres meses como máximo.","Seis meses, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros tres meses como máximo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Seis meses, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por ot…</mark></span><span class=\"ref-norma\">Art. 28.2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 28.2 de la LO 5/2000 establece un plazo máximo de seis meses, prorrogable por tres meses más.*"},{"i":"17-72","p":"Ley Orgánica 5/2000. Reglas generales. El tiempo máximo de la medida cautelar de internamiento será de:","o":["Un mes, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros seis meses como máximo.","Dos meses, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros seis meses como máximo.","Tres meses, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros tres meses como máximo.","Seis meses, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros tres meses como máximo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Seis meses, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por ot…</mark></span><span class=\"ref-norma\">Art. 28.2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 28.2 de la LO 5/2000 establece un plazo máximo de seis meses, prorrogable por tres meses más.*"},{"i":"17-79","p":"Ley Orgánica 5/2000. La competencia para la ejecución de las medidas impuestas a los menores corresponde al:","o":["Ministerio de Justicia.","Juez de Menores.","Ministerio del Interior.","Consejo General del Poder Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Juez de Menores</mark></span>Hacer ejecutar las sentencias es competencia de los Jueces de Menores. Según el <span class=\"ref-norma\">art. 2.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"así como para hacer ejecutar las sentencias, sin perjuicio de las facultades atribuidas por esta Ley a las Comunidades Autónomas respecto a la protección y reforma de menores\"</span> (verificado con el temario oficial)."},{"i":"17-84","p":"Ley Orgánica 5/2000. Unidad de expediente. Señale la opción incorrecta en esta materia:","o":["El Ministerio Fiscal incoará un procedimiento por cada hecho delictivo, salvo cuando se trate de hechos delictivos conexos.","Todos los procedimientos tramitados a un mismo menor se archivarán en el expediente personal que del mismo se haya abierto en la Fiscalía. De igual modo se archivarán las diligencias en el Juzgado de Menores respectivo.","Los procedimientos de la competencia de la Audiencia Nacional podrán ser objeto de acumulación con otros procedimientos sustanciados en el ámbito de la jurisdicción de menores.","En los casos en los que los delitos atribuidos al menor expedientado hubieran sido cometidos en diferentes territorios, la determinación del órgano judicial competente para el enjuiciamiento de todos ellos en unidad de expediente se hará teniendo en cuenta el lugar del domicilio del menor y, subsidiariamente, los criterios expresados en el artículo 18 de la Ley de Enjuiciamiento Criminal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los procedimientos de la competencia de la Audiencia Nacional podrán ser objeto de acumulación con otros procedimientos sustanciados en el …</mark></span>*Explicación: Los procedimientos de la Audiencia Nacional NO pueden acumularse con procedimientos de la jurisdicción de menores ordinaria por razones de competencia.*"},{"i":"17-86","p":"Ley Orgánica 5/2000. De la intervención del Ministerio Fiscal. La defensa de los derechos que a los menores reconocen las leyes, así como la vigilancia de las actuaciones que deban efectuarse en su interés y la observancia de las garantías del procedimiento corresponde a:","o":["El Ministerio Fiscal.","Los Jueces de Menores.","El Grupo Central de Menores de la Audiencia Nacional.","El Letrado de la Administración de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 6 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 6 de la LO 5/2000 atribuye estas funciones al Ministerio Fiscal como defensor de los derechos del menor.*"},{"i":"17-89","p":"Ley Orgánica 5/2000. Desistimiento de la incoación del expediente por corrección en el ámbito educativo y familiar. ¿Quién podrá desistir de la incoación del expediente por corrección en el ámbito educativo y familiar?:","o":["El Juez de lo Penal.","El Juez de Instrucción.","El Ministerio Fiscal.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 27.5 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 27.5 de la LO 5/2000 otorga esta facultad de desistimiento al Ministerio Fiscal.*"},{"i":"17-92","p":"Ley Orgánica 5/2000. Unidad de expediente. ¿Quién incoará un procedimiento por cada hecho delictivo, salvo cuando se trate de hechos delictivos conexos?:","o":["El Juez de menores.","La autoridad judicial.","El Ministerio Fiscal.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 26.1 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 26.1 de la LO 5/2000 atribuye al Ministerio Fiscal la incoación del expediente.*"},{"i":"17-97","p":"Ley Orgánica 5/2000. Secreto del expediente. ¿A solicitud de quién el Juez de Menores puede decretar mediante auto motivado el secreto del expediente, en su totalidad o parcialmente, durante toda la instrucción o durante un período limitado de ésta?:","o":["Del Ministerio Fiscal.","Del menor.","De la familia del menor.","Todas las opciones son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones son correctas.</mark></span><span class=\"ref-norma\">Art. 32.1 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 32.1 de la LO 5/2000 permite decretar el secreto a solicitud del Ministerio Fiscal, del menor o de su familia.*"},{"i":"17-98","p":"Ley Orgánica 5/2000. Definición de las medidas susceptibles de ser impuestas a los menores y reglas generales de determinación de las mismas. Las personas sometidas a esta medida residirán en el centro y desarrollarán en el mismo las actividades formativas, educativas, laborales y de ocio, se refiere a la medida de:","o":["Internamiento en régimen semiabierto.","Internamiento en régimen cerrado.","Internamiento en régimen abierto.","Tratamiento ambulatorio."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Internamiento en régimen cerrado</mark></span>Es el régimen cerrado; en el abierto las actividades se hacen en los servicios normalizados del entorno. Según el <span class=\"ref-norma\">art. 7.1.a) de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"residirán en el centro y desarrollarán en el mismo las actividades formativas, educativas, laborales y de ocio\"</span> (verificado con el temario oficial)."},{"i":"17-110","p":"Ley Orgánica 5/2000. Incoación del expediente. ¿Quién instruirá los procedimientos por los hechos a los que se refiere el artículo 1 de esta Ley?:","o":["Los Jueces de Instrucción.","Los Jueces de Menores.","Los Jueces de Instrucción del lugar donde se hubiesen cometido los hechos.","El Ministerio Fiscal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 27.1 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 27.1 de la LO 5/2000 atribuye la instrucción del procedimiento al Ministerio Fiscal.*"},{"i":"17-118","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Competencia de los Jueces de Menores. ¿Quiénes serán los competentes para conocer de los hechos delictivos cometidos por mayores de 14 años y menores de 18 años?:","o":["El Ministerio Fiscal.","La Facultad de Menores.","El Juez de Menores.","El Juez de Instrucción."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Juez de Menores.</mark></span>El Juez de Menores es competente para delitos de menores de 14 a 18 años."},{"i":"17-120","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Sobrescimiento del expediente por conciliación o reparación entre el menor y la víctima. ¿Quién podrá desistir de la continuación del expediente, atendiendo a la gravedad y circunstancias de los hechos y del menor?:","o":["El Juez de Instrucción.","El Juez de Menores.","El Juez de Menores del lugar donde se hubieren cometido los hechos.","El Ministerio Fiscal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Ministerio Fiscal</mark></span>Según el <span class=\"ref-norma\">art. 19.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"También podrá el Ministerio Fiscal desistir de la continuación del expediente\"</span> (verificado con el temario oficial)."},{"i":"17-124","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen general de aplicación y duración de las medidas. Las acciones u omisiones imprudentes no podrán ser sancionadas:","o":["Con medida de internamiento en régimen cerrado.","Con medida de internamiento en régimen abierto.","Con medida de internamiento en régimen de semilibertad.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Con medida de internamiento en régimen cerrado.</mark></span>Las acciones imprudentes no pueden sancionarse con internamiento en régimen cerrado."},{"i":"17-130","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Los equipos técnicos tienen como función asistir técnicamente en las materias propias de sus disciplinas profesionales:","o":["A los Jueces de Menores y al Ministerio Fiscal.","A las Fuerzas y Cuerpos de Seguridad y al Ministerio Fiscal.","A las Fuerzas y Cuerpos de Seguridad, a los Jueces de Menores y al Ministerio Fiscal.","A las Fuerzas y Cuerpos de Seguridad y a los Jueces de Menores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A los Jueces de Menores y al Ministerio Fiscal</mark></span>Según el <span class=\"ref-norma\">art. 4.1 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"asistir técnicamente en las materias propias de sus disciplinas profesionales a los jueces de menores y al Ministerio Fiscal\"</span> (verificado con el temario oficial)."},{"i":"17-138","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Los Jueces de Menores NO serán competentes para:","o":["Conocer los hechos cometidos por las personas mayores de catorce años y menores de dieciocho.","Conocer los hechos cometidos por mayores de dieciocho años y menores de veintiuno.","Ejecutar las sentencias dictadas por los Juzgados de menores.","Resolver sobre las responsabilidades civiles derivadas de los hechos cometidos por las personas a las que resulta aplicable la presente ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Conocer los hechos cometidos por mayores de dieciocho años y menores de veintiuno.</mark></span>No son competentes para mayores de 18 años."},{"i":"17-145","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Secreto del expediente. ¿Quién podrá decretar mediante auto motivado el secreto del expediente durante la instrucción?:","o":["El Juez de Menores, a solicitud del Ministerio Fiscal, del menor o de su familia, o de quien ejercita la acción penal.","El Ministerio fiscal como instructor, a instancia del Juez de Menores, o a solicitud del menor o de su familia, o de quien ejercite la acción penal.","El Ministerio fiscal como instructor, a instancia del Juez de Menores, o a solicitud de cualquiera de las partes.","El Ministerio fiscal como instructor, a instancia del Juez de Menores, o a solicitud de cualquiera de las partes, personadas antes del trámite de audiencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Juez de Menores, a solicitud del Ministerio Fiscal, del menor o de su familia, o de quien ejercita la acción penal.</mark></span>El Juez de Menores decreta el secreto del expediente."},{"i":"17-147","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Régimen General de aplicación y duración de las medidas. Reglas para la aplicación de las medidas susceptibles de ser impuestas a los menores. Señale la INCORRECTA:","o":["La medida de internamiento en régimen cerrado no se podrá aplicar cuando el menor actuare al servicio de una banda, con carácter transitorio, que se dedique a la realización de hechos tipificados como delito.","La medida de prestaciones en beneficio de la comunidad no podrá superar las cien horas.","La medida de internamiento en régimen cerrado se podrá aplicar cuando los hechos tipificados como delito se cometan en grupo.","La medida de permanencia de fin de semana no podrá superar las ocho fines de semana."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La medida de internamiento en régimen cerrado no se podrá aplicar cuando el menor actuare al servicio de una banda, con carácter transitori…</mark></span>Es incorrecta porque SÍ se puede aplicar internamiento cerrado cuando el menor actúe al servicio de una banda."},{"i":"17-153","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. Existirá un registro o archivo central donde, de modo específico para menores, se incorporará la información relativa a los datos de estos resultantes de la investigación. Tal registro o archivo solo podrá facilitar información a requerimiento:","o":["Del Ministerio Fiscal o del juez de menores.","Del Ministerio Fiscal o del juez de instrucción.","Del juez de instrucción o del juez de menores.","Del Ministerio Fiscal, del juez de menores o del equipo técnico de protección de menores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Del Ministerio Fiscal o del juez de menores.</mark></span>Del Ministerio Fiscal o del juez de menores."},{"i":"17-156","p":"Ley orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. ¿Quién podrá desistir de la incoación del expediente cuando los hechos denunciados constituyan delitos menos graves sin violencia o intimidación en las personas o faltas?","o":["El Juez de Menores.","El Ministerio Fiscal.","El letrado del menor.","El equipo técnico."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Ministerio Fiscal.</mark></span>El Ministerio Fiscal."},{"i":"17-157","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. La defensa de los derechos que a los menores reconocen las leyes, así como la vigilancia de las actuaciones que deban efectuarse en su interés y la observancia de las garantías del procedimiento, corresponde:","o":["A los Jueces de Menores.","Al Ministerio Fiscal.","A las entidades de protección y reforma de las Comunidades Autónomas.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Ministerio Fiscal</mark></span>Solo corresponde al Ministerio Fiscal. Según el <span class=\"ref-norma\">art. 6 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Corresponde al Ministerio Fiscal la defensa de los derechos que a los menores reconocen las leyes, así como la vigilancia de las actuaciones que deban efectuarse en su interés y la observancia de las garantías del procedimiento\"</span> (verificado con el temario oficial)."},{"i":"17-159","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Ámbito de aplicación de la Ley. En especial, cuando el Ministerio Fiscal, desista de la Incoación del expediente deberá inmediatamente ponerlo en conocimiento de las víctimas y perjudicados haciéndoles saber su derecho:","o":["A ejercitar las acciones civiles que les asisten ante la jurisdicción civil.","A ejercitar las acciones penales que les asisten ante la jurisdicción penal.","A ejercitar las acciones penales y civiles que les asisten ante la jurisdicción de menores.","A ejercitar las acciones penales y civiles que les asisten ante la jurisdicción penal o civil."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A ejercitar las acciones penales y civiles que les asisten ante la jurisdicción penal o civil.</mark></span>A ejercitar las acciones ante la jurisdicción penal o civil."},{"i":"17-161","p":"Ley orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. ¿A quién corresponde la defensa de los derechos que a los menores reconocen las leyes, así como la vigilancia de las actuaciones que deban efectuarse en su interés y la observancia de las garantías del procedimiento?","o":["Al Ministerio Fiscal.","Al Juez de Menores.","Al Abogado del menor.","A los padres o tutores del menor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al Ministerio Fiscal.</mark></span> Al Ministerio Fiscal. TEST 12"},{"i":"17-163","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. ¿Quién incoa un procedimiento por cada hecho delictivo, salvo cuando se trate de hechos delictivos conexos?:","o":["La Audiencia Nacional.","El Ministerio Fiscal.","El Juez de Menores.","El Fiscal General del Estado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Ministerio Fiscal.</mark></span>El Ministerio Fiscal incoa el procedimiento."},{"i":"17-164","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Modo de llevar a cabo las soluciones extrajudiciales. ¿Quién solicitará del equipo técnico informe sobre la conveniencia de adoptar la solución extrajudicial más adecuada al interés del menor y al de la víctima?:","o":["El abogado de la víctima.","El abogado del menor detenido.","El Ministerio Fiscal.","El Juez de Menores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Ministerio Fiscal.</mark></span>El Ministerio Fiscal."},{"i":"17-165","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Derechos de las víctimas y de las personas perjudicadas. ¿Quién velará en todo momento por la protección de los derechos de las víctimas y de las personas perjudicadas por las infracciones cometidas por las personas menores de edad?","o":["El Ministerio Fiscal y el Juez de Menores.","El Ministerio Fiscal y el Fiscal General del Estado.","La Secretaría de Estado de Justicia.","La Autoridad Judicial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministerio Fiscal y el Juez de Menores.</mark></span>El Ministerio Fiscal y el Juez de Menores."},{"i":"17-170","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación Instructora del Ministerio Fiscal. El Ministerio Fiscal deberá dar vista del expediente al letrado del menor y, en su caso, a quien haya ejercitado la acción penal, en un plazo no superior a ______ tantas veces como aquel lo solicite.","o":["12 horas.","24 horas.","36 horas.","48 horas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">24 horas.</mark></span>24 horas."},{"i":"17-179","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. Cuando para la identificación de un menor haya de acudirse a la diligencia de reconocimiento prevista en la Ley de Enjuiciamiento Criminal, dicha diligencia solo podrá llevarse a cabo:","o":["Con orden o autorización del juez de instrucción o del juez de menores según sus propias competencias.","Con orden o autorización del Ministerio Fiscal o del juez de instrucción según sus propias competencias.","Con orden o autorización del Ministerio Fiscal o del juez de menores según sus propias competencias.","Con orden o autorización del juez de instrucción."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Con orden o autorización del Ministerio Fiscal o del juez de menores según sus propias competencias.</mark></span>Con orden o autorización del Ministerio Fiscal o del juez de menores."},{"i":"17-180","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. El tiempo máximo de la medida cautelar de internamiento será de seis meses, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros _____ como máximo.","o":["Tres meses.","Seis meses.","Nueve meses.","Doce meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Tres meses.</mark></span> Tres meses. TEST 13"},{"i":"17-183","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. ¿Quién podrá decretar el secreto del expediente?","o":["El Juez de Menores mediante auto motivado.","El Ministerio Fiscal mediante orden motivado.","El Ministerio Fiscal mediante auto motivado.","El Juez de Menores mediante orden motivado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Juez de Menores mediante auto motivado.</mark></span>El Juez de Menores mediante auto motivado."},{"i":"17-188","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. El tiempo máximo de la medida cautelar de internamiento será de seis meses, y podrá prorrogarse:","o":["A instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros seis meses como máximo.","A instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros tres meses como máximo.","A instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros dos meses como máximo.","A instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros cuatro meses como máximo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros tres meses como máximo.</mark></span>Por otros tres meses como máximo."},{"i":"17-199","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. ¿Quién admite la personación del acusador particular?","o":["El Juez de Menores.","El Juez de Instrucción.","La Audiencia Provincial.","El Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Juez de Menores.</mark></span>El Juez de Menores."},{"i":"17-202","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Ámbito de aplicación de la Ley. ¿Cuál es la principal función del Ministerio Fiscal en el ámbito de la Ley de Responsabilidad Penal del Menor?","o":["Actuar como defensa del menor en el juicio.","Impulsar el procedimiento y dirigir la investigación de los hechos.","Defender a las víctimas del delito cometido por el menor.","Concretar y reunir toda la información al respecto de la responsabilidad penal del Menor."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Impulsar el procedimiento y dirigir la investigación de los hechos.</mark></span>Impulsar el procedimiento y dirigir la investigación."},{"i":"17-212","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Si el equipo técnico considera conveniente que el menor efectúe una actividad reparadora o de conciliación con la víctima:","o":["Notificará a un cuerpo policial.","Informará de tal extremo al Ministerio Fiscal y al letrado del menor.","Solicitará la opinión de la víctima.","Activará el expediente y comenzará uno nuevo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Informará de tal extremo al Ministerio Fiscal y al letrado del menor.</mark></span>Informará al Ministerio Fiscal y al letrado del menor."},{"i":"17-213","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Velarán en todo momento por la protección de los derechos de las víctimas y de las personas perjudicadas por las infracciones cometidas por las personas menores de edad:","o":["El Ministerio Fiscal y el Juez de Menores.","El Letrado de la Administración de Justicia.","La Juez.","Las partes personadas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministerio Fiscal y el Juez de Menores.</mark></span>El Ministerio Fiscal y el Juez de Menores."},{"i":"17-216","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Las autoridades y funcionarios que intervengan en la detención de un menor deberán notificar inmediatamente el hecho de la detención y el lugar de la custodia:","o":["Al Ministerio Fiscal.","Al juez de menores y a los representantes legales.","A los representantes legales del menor y al Ministerio Fiscal.","Sólo a los representantes legales del menor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A los representantes legales del menor y al Ministerio Fiscal.</mark></span>A los representantes legales del menor y al Ministerio Fiscal."},{"i":"17-219","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Las medidas que pueden imponer los Jueces de Menores, ordenadas según la restricción de derechos que suponen, son las siguientes: señale la INCORRECTA.","o":["Internamiento en régimen abierto.","Internamiento en régimen cerrado.","Tratamiento ambulatorio.","Asistencia a un centro de noche."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Asistencia a un centro de noche.</mark></span>Asistencia a un centro de noche (la medida correcta es &quot;asistencia a un centro de día&quot;)."},{"i":"17-222","p":"Real Decreto 1774/2004, de 30 de Julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Los equipos técnicos asistirán técnicamente en las materias propias de sus disciplinas profesionales a:","o":["Los jueces de vigilancia penitenciaria.","Los jueces de menores.","Ministerio Fiscal.","B y C son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">B y C son correctas.</mark></span>- Los equipos técnicos asisten tanto a Jueces de Menores como al Ministerio Fiscal."},{"i":"17-224","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Una vez elaborado el informe del equipo técnico, el Ministerio Fiscal lo remitirá inmediatamente:","o":["Al Juez de Menores y dará copia del mismo al letrado del menor.","Al Juez de Instrucción y dará original del mismo al letrado del menor.","Al Juez de Menores y dará original del mismo al letrado del menor.","Al Juez de Instrucción, y dará copia del mismo al letrado del menor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al Juez de Menores y dará copia del mismo al letrado del menor.</mark></span>- Se remite al Juez de Menores y se da copia al letrado del menor."},{"i":"17-231","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. ¿A quién corresponde promover la mediación entre el menor y la víctima o perjudicado?","o":["A los abogados o representantes legales del menor y de los perjudicados o víctimas.","Al Ministerio Fiscal.","Al Juez de Menores del lugar donde se hubieren cometidos los hechos.","Al correspondiente equipo técnico."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Ministerio Fiscal.</mark></span>- Corresponde al Ministerio Fiscal promover la mediación."},{"i":"17-232","p":"Instrucción 1/2017 de la Secretaría de Estado de Seguridad, por la que se aprueba el \"Protocolo de Actuación Policial con Menores\". Para el reconocimiento y ejecución dentro de España de una Orden Europea de Detención y Entrega (OEDE) que provenga de otro Estado miembro, la competencia, desde la detención del menor hasta la decisión definitiva, corresponde:","o":["Al Juzgado Central de Menores de la Audiencia Provincial.","A la Sección de Menores de la Fiscalía de la Audiencia Nacional.","Al Juzgado Central de Menores de la Audiencia Nacional.","A la Sección de Menores de la Fiscalía de la Audiencia Provincial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al Juzgado Central de Menores de la Audiencia Nacional.</mark></span>- Corresponde al Juzgado Central de Menores de la Audiencia Nacional."},{"i":"17-233","p":"Real Decreto 1774/2004, de 30 de Julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Actuación del equipo técnico. Los profesionales integrantes de los equipos técnicos dependerán en el ejercicio de su actividad técnica:","o":["Ministerio de Justicia.","Del Ministerio Fiscal.","Del Juez de menores en todos los casos.","Todas son incorrectas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son incorrectas.</mark></span>- Los equipos técnicos mantienen independencia funcional."},{"i":"17-235","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. Las medidas que pueden imponer los Jueces de Menores, ordenadas según la restricción de derechos que suponen, son las siguientes:","o":["Internamiento en régimen cerrado.","Internamiento en régimen semiabierto.","Internamiento en régimen abierto.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span>- Todas son medidas de internamiento según grado de restricción."},{"i":"17-236","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Ámbito de aplicación de la Ley. ¿Quiénes serán competentes para resolver sobre las responsabilidades civiles derivadas de los hechos cometidos por las personas a las que resulta aplicable la presente Ley?","o":["El Fiscal General.","El Ministro de Interior.","Los Jueces de Menores.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los Jueces de Menores.</mark></span>- Los Jueces de Menores conocen también de la responsabilidad civil."},{"i":"17-249","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Principio acusatorio. El Juez de Menores no podrá imponer una medida que suponga una mayor restricción de derechos ni por un tiempo superior a la medida solicitada por:","o":["El Ministerio Fiscal o por el acusador particular.","El Ministerio Fiscal, con exclusión del acusador particular.","El Ministerio Fiscal o por el letrado del menor.","El equipo técnico o por el Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministerio Fiscal o por el acusador particular</mark></span>El <span class=\"ref-norma\">art. 8 de la LO 5/2000</span> dispone: <span class=\"ref-concepto\">\"no podrá imponer una medida que suponga una mayor restricción de derechos ni por un tiempo superior a la medida solicitada por el Ministerio Fiscal o por el acusador particular\"</span>"},{"i":"17-250","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Competencia de los Jueces de Menores. La competencia para conocer de los delitos de terrorismo previstos en el Código Penal corresponderá:","o":["Al Juzgado de Menores del lugar donde se haya cometido el hecho.","Al Juzgado Central de Menores de la Audiencia Nacional.","A la Sección de Menores de la Fiscalía de la Audiencia Nacional.","Al Juzgado Central de Instrucción de la Audiencia Nacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Juzgado Central de Menores de la Audiencia Nacional</mark></span>El <span class=\"ref-norma\">art. 2.4 de la LO 5/2000</span> dispone: <span class=\"ref-concepto\">\"corresponderá al Juzgado Central de Menores de la Audiencia Nacional\"</span>"},{"i":"17-258","p":"(LO 5/2000 - Responsabilidad Penal del Menor) Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Corresponde la defensa de los derechos a los menores reconocidos en las leyes, así como la vigilancia de las actuaciones que deban efectuarse en su interés y la observancia de las garantías del procedimiento:","o":["Al Juez Instructor del procedimiento penal.","Al Ministerio Fiscal.","A la Unidad Central de la Policía Judicial de Menores.","A) y B) son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 15.1 · Responsabilidad Penal de los Menores</span>. El Art. 15.1 de la LORPM atribuye al Ministerio Fiscal la instrucción del expediente, la defensa de los derechos del menor y la vigilancia de las garantías."},{"i":"17-259","p":"(LO 5/2000 - Responsabilidad Penal del Menor) Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. De las medidas. Las medidas que pueden imponer los Jueces de Menores, ordenadas según la restricción de derechos que suponen, son, entre otras, las siguientes:","o":["Internamiento en régimen semicerrado.","Inhabilitación parcial.","Multa y amonestación.","Tratamiento ambulatorio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Internamiento en régimen semicerrado.</mark></span><span class=\"ref-norma\">Art. 7.1 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. El Art. 7.1 de la LORPM enumera las medidas. El internamiento es la medida más restrictiva de derechos, y el régimen semicerrado es una de sus modalidades. Las demás opciones son medidas menos restrictivas o no son medidas (Inhabilitación parcial)."},{"i":"17-264","p":"LO 5/2000 - Inhabilitación Fiscal Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. En lo referente a la actuación instructora del Ministerio Fiscal: señale la INCORRECTA.","o":["El Ministerio Fiscal no podrá practicar por sí mismo diligencias restrictivas de derechos fundamentales, sino que habrá de solicitar del Juzgado la práctica de las que sean precisas para el buen fin de las investigaciones.","La práctica de tales diligencias se documentará en pieza conjunta.","El Ministerio Fiscal deberá dar vista del expediente al letrado del menor y, en su caso, a quien haya ejercido la acusación penal, en un plazo no superior a veinticuatro horas, tantas veces como aquel lo solicite.","El Juez de Menores resolverá sobre esta petición (diligencia restrictiva de derechos fundamentales) por auto motivado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Ministerio Fiscal deberá dar vista del expediente al letrado del menor y, en su caso, a quien haya ejercido la acusación penal, en un pl…</mark></span><span class=\"ref-norma\">Art. 17.2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. Justificación: El Art. 17.2 de la LORPM establece que la vista del expediente debe darse en un plazo no superior a veinticuatro horas, tanto al inicio como a la finalización de cada diligencia, no &quot;tantas veces como aquel lo solicite.&quot;"},{"i":"17-267","p":"(LO 5/2000 - LORPM) Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. De las medidas. Las medidas que pueden imponer los Jueces de Menores, ordenadas según la restricción de derechos que suponen, son, entre otras, las siguientes:","o":["Internamiento en régimen semicerrado.","Inhabilitación parcial.","Multa y amonestación.","Tratamiento ambulatorio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Internamiento en régimen semicerrado.</mark></span><span class=\"ref-norma\">Art. 7.1 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. El artículo 7.1 de la LO 5/2000, LORPM, enumera las medidas que pueden imponer los Jueces de Menores «ordenadas según la restricción de derechos que suponen», comenzando por la letra a) «Internamiento en régimen cerrado», que es la medida más restrictiva de derechos de todas las previstas. Por ello, entre las opciones planteadas, el internamiento en régimen semicerrado (más próximo al régimen cerrado que las demás alternativas) es la que se sitúa en primer lugar en dicho orden."},{"i":"17-271","p":"(LO 5/2000 - LORPM) Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. En lo referente a la actuación instructora del Ministerio Fiscal: Señale la incorrecta.","o":["El Ministerio Fiscal no podrá practicar por sí mismo diligencias restrictivas de derechos fundamentales, sino que habrá de solicitar del Juzgado la práctica de las que sean precisas para el buen fin de las investigaciones.","La práctica de tales diligencias se documentará en pieza conjunta.","El Ministerio Fiscal deberá dar vista del expediente al letrado del menor y, en su caso, a quien haya ejercitado la acusación penal, en un plazo no superior a veinticuatro horas, tantas veces como aquel lo solicite.","El Juez de Menores resolverá sobre esta petición (diligencia restrictiva de derechos fundamentales) por auto motivado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Ministerio Fiscal deberá dar vista del expediente al letrado del menor y, en su caso, a quien haya ejercitado la acusación penal, en un …</mark></span><span class=\"ref-norma\">Art. 17.2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. (La opción correcta sería &quot;Tanto al inicio como a la finalización de cada diligencia&quot;, no &quot;tantas veces como aquel lo solicite&quot; según el Art. 17.2 LORPM)."},{"i":"17-278","p":"(LO 5/2000 - LORPM) Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Corresponde la defensa de los derechos a los menores reconocidos en las leyes, así como la vigilancia de las actuaciones que deban efectuarse en su interés y la observancia de las garantías del procedimiento:","o":["Al Juez Instructor del procedimiento penal.","Al Ministerio Fiscal.","A la Unidad Central de la Policía Judicial de Menores.","A) y B) son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 6 · Responsabilidad Penal de los Menores</span>. El artículo 6 de la LO 5/2000, LORPM, titulado «De la intervención del Ministerio Fiscal», establece que «corresponde al Ministerio Fiscal la defensa de los derechos que a los menores reconocen las leyes, así como la vigilancia de las actuaciones que deban efectuarse en su interés y la observancia de las garantías del procedimiento». Es, por tanto, el Ministerio Fiscal, y no el Juez Instructor ni la Policía Judicial de Menores, quien tiene legalmente atribuida esta función tuitiva."},{"i":"17-ia-1044","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. El Juez deberá motivar en la sentencia las razones por las que aplica una determinada medida, así como el plazo de duración de la misma, a los efectos de la valoración del mencionado:","o":["reproche merecido por su conducta.","interés del menor.","principio de proporcionalidad.","grado de participación del menor."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">interés del menor</mark></span>El <span class=\"ref-norma\">art. 7.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"así como el plazo de duración de la misma, a los efectos de la valoración del mencionado interés del menor\"</span>. La motivación sirve a la valoración del interés del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1047","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Principio acusatorio. El Juez de Menores no podrá imponer una medida que suponga una mayor restricción de derechos ni por un tiempo superior a la medida solicitada por:","o":["el Ministerio Fiscal o por el letrado del menor.","el equipo técnico o por el Ministerio Fiscal.","el Ministerio Fiscal o por el acusador particular.","el Ministerio Fiscal, con exclusión del acusador particular."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Ministerio Fiscal o por el acusador particular</mark></span>El <span class=\"ref-norma\">art. 8 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"ni por un tiempo superior a la medida solicitada por el Ministerio Fiscal o por el acusador particular\"</span>. El tope lo marca la medida solicitada por el Ministerio Fiscal o por el acusador particular. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1132","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Mayoría de edad del condenado. Cuando las medidas de internamiento en régimen cerrado sean impuestas a quien haya cumplido __________ años de edad o, habiendo sido impuestas con anterioridad, no hayan finalizado su cumplimiento al alcanzar la persona dicha edad, el Juez de Menores ordenará su cumplimiento en centro penitenciario:","o":["dieciocho","veintiún","veinticinco","veintitrés"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">veintiún</mark></span>El <span class=\"ref-norma\">art. 14.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"sean impuestas a quien haya cumplido veintiún años de edad\"</span>. El umbral es haber cumplido veintiún años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1138","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la prescripción. Los hechos delictivos cometidos por los menores prescriben al año, cuando se trate de un delito menos grave, y a los __________, cuando se trate de una falta:","o":["seis meses, sin perjuicio de lo previsto en la normativa vigente.","un año","dos meses","tres meses"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tres meses</mark></span>El <span class=\"ref-norma\">art. 15.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Al año, cuando se trate de un delito menos grave. 5.º A los tres meses, cuando se trate de una falta\"</span>. Delito menos grave: un año; falta: tres meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1209","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. En la detención de un menor deberán notificar inmediatamente el hecho de la detención y el lugar de la custodia a:","o":["los representantes legales del menor y al Ministerio Fiscal.","los representantes legales del menor y al Juez de Menores.","los representantes legales del menor, al Ministerio Fiscal y al equipo técnico.","el letrado del menor y al Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los representantes legales del menor y al Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 17.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"También deberán notificar inmediatamente el hecho de la detención y el lugar de la custodia a los representantes legales del menor y al Ministerio Fiscal\"</span>. La notificación inmediata es a los representantes legales del menor y al Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1216","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. La detención de un menor por funcionarios de policía no podrá durar más tiempo del estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos y, en todo caso, dentro del plazo máximo de __________, el menor detenido deberá ser puesto en libertad o a disposición del Ministerio Fiscal:","o":["cuarenta y ocho horas","veinticuatro horas","setenta y dos horas","doce horas"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">veinticuatro horas</mark></span>El <span class=\"ref-norma\">art. 17.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"en todo caso, dentro del plazo máximo de veinticuatro horas, el menor detenido deberá ser puesto en libertad o a disposición del Ministerio Fiscal\"</span>. El plazo policial es de veinticuatro horas; las cuarenta y ocho son del Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1234","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Unidad de expediente. Todos los procedimientos tramitados a un mismo menor se archivarán en el expediente personal que del mismo se haya abierto en:","o":["el Juzgado de Menores.","la entidad pública de reforma de menores.","el equipo técnico.","la Fiscalía."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la Fiscalía</mark></span>El <span class=\"ref-norma\">art. 20.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"se archivarán en el expediente personal que del mismo se haya abierto en la Fiscalía\"</span>. El expediente personal se abre en la Fiscalía; las diligencias se archivan además en el Juzgado de Menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1246","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación instructora del Ministerio Fiscal. El Ministerio Fiscal no podrá practicar por sí mismo diligencias restrictivas de derechos fundamentales, sino que habrá de solicitar del Juzgado la práctica de las que sean precisas para el buen fin de las investigaciones. El Juez de Menores resolverá sobre esta petición por:","o":["providencia, en los términos que se determinen reglamentariamente.","sentencia.","decreto.","auto motivado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">auto motivado</mark></span>El <span class=\"ref-norma\">art. 23.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"El Juez de Menores resolverá sobre esta petición por auto motivado\"</span>. Resuelve por auto motivado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1301","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Secreto del expediente. El Juez de Menores, a solicitud del Ministerio Fiscal, del menor o de su familia, o de quien ejercite la acción penal, podrá decretar el secreto del expediente mediante:","o":["auto motivado.","providencia motivada.","decreto del Ministerio Fiscal.","resolución sin necesidad de motivación, durante la instrucción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">auto motivado</mark></span>El <span class=\"ref-norma\">art. 24 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"podrá decretar mediante auto motivado el secreto del expediente\"</span>. El secreto se decreta mediante auto motivado del Juez de Menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1320","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Informe del equipo técnico. Una vez elaborado el informe del equipo técnico, el Ministerio Fiscal lo remitirá inmediatamente al Juez de Menores y dará copia del mismo:","o":["a las partes personadas.","al letrado del menor.","a los representantes legales del menor.","al acusador particular."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al letrado del menor</mark></span>El <span class=\"ref-norma\">art. 27.5 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"lo remitirá inmediatamente al Juez de Menores y dará copia del mismo al letrado del menor\"</span>. La copia se da al letrado del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1324","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Medidas cautelares. Reglas generales. El Juez, oído el letrado del menor, así como el equipo técnico y la representación de la entidad pública de protección o reforma de menores, que informarán especialmente sobre la naturaleza de la medida cautelar, resolverá tomando en especial consideración:","o":["la gravedad de los hechos.","el interés del menor.","el interés de la víctima.","el riesgo de fuga."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el interés del menor</mark></span>El <span class=\"ref-norma\">art. 28.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"resolverá sobre lo propuesto tomando en especial consideración el interés del menor\"</span>. Resuelve tomando en especial consideración el interés del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1328","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Medidas cautelares. Reglas generales. En la comparecencia sobre el internamiento cautelar, el Ministerio Fiscal y las partes personadas podrán proponer los medios de prueba que puedan practicarse en el acto o dentro de:","o":["las cuarenta y ocho horas siguientes.","las veinticuatro horas siguientes.","los tres días siguientes.","las setenta y dos horas siguientes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las veinticuatro horas siguientes</mark></span>El <span class=\"ref-norma\">art. 28.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"los medios de prueba que puedan practicarse en el acto o dentro de las veinticuatro horas siguientes\"</span>. La prueba puede practicarse en el acto o dentro de las veinticuatro horas siguientes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1403","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. La Policía Judicial actúa en la investigación de los hechos cometidos por menores que pudieran ser constitutivos de delitos o faltas, bajo la dirección del:","o":["Juez de Menores.","Juez de Instrucción.","Ministerio Fiscal.","Fiscal de Sala Coordinador de Menores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 2.1 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"bajo la dirección del Ministerio Fiscal\"</span>. La dirección corresponde al Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1405","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Tendrán acceso a los registros policiales de menores las personas que participen directamente en la investigación de un caso en trámite o aquellas personas que sean autorizadas expresamente, en el ejercicio de sus competencias, por:","o":["el juez de menores o el Ministerio Fiscal.","el Juez de Instrucción o el Ministerio Fiscal.","el Ministerio del Interior.","la autoridad judicial y el equipo técnico."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el juez de menores o el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 2.3 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"en el ejercicio de sus respectivas competencias, autoricen expresamente el juez de menores o el Ministerio Fiscal\"</span>. Autorizan el juez de menores o el Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1408","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Existirá un registro o archivo central donde, de modo específico para menores, se incorporará la información relativa a los datos de estos resultantes de la investigación. Tal registro solo podrá facilitar información a requerimiento del:","o":["Ministerio Fiscal o de la Policía Judicial.","Ministerio Fiscal o del juez de menores.","juez de menores o de los equipos técnicos.","Ministerio del Interior."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Ministerio Fiscal o del juez de menores</mark></span>El <span class=\"ref-norma\">art. 2.6 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"Tal registro o archivo solo podrá facilitar información a requerimiento del Ministerio Fiscal o del juez de menores\"</span>. Solo a requerimiento del Ministerio Fiscal o del juez de menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1421","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo la detención del menor. Señale la INCORRECTA sobre la información del libro registro, de carácter confidencial, de los establecimientos de detención:","o":["Detalle de las medidas cautelares solicitadas por el Ministerio Fiscal.","Circunstancias de la detención, motivos y en su caso autoridad que la ordenó.","Día y hora del ingreso, traslado o libertad.","Constatación de que se le ha informado de las circunstancias de la detención y de sus derechos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Detalle de las medidas cautelares solicitadas por el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 3.5 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"b) Circunstancias de la detención, motivos y en su caso autoridad que la ordenó. c) Día y hora del ingreso, traslado o libertad\"</span>. El libro registro no incluye las medidas cautelares solicitadas por el Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1424","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación del equipo técnico. Los equipos técnicos, formados por psicólogos, educadores y trabajadores sociales, tienen como función asistir técnicamente en las materias propias de sus disciplinas profesionales a:","o":["los jueces de menores y a la policía judicial.","los jueces de menores y al Ministerio Fiscal.","el Ministerio Fiscal y a las entidades públicas de reforma.","los jueces de menores, al Ministerio Fiscal y a las víctimas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los jueces de menores y al Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 4.1 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"asistir técnicamente en las materias propias de sus disciplinas profesionales a los jueces de menores y al Ministerio Fiscal\"</span>. Asisten a los jueces de menores y al Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1440","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo las soluciones extrajudiciales. Si el equipo técnico considera conveniente que el menor efectúe una actividad reparadora o de conciliación con la víctima, informará de tal extremo al Ministerio Fiscal y:","o":["al Juez de Menores.","al letrado del menor.","a la víctima.","a los representantes legales del menor."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al letrado del menor</mark></span>El <span class=\"ref-norma\">art. 5.2 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"informará de tal extremo al Ministerio Fiscal y al letrado del menor\"</span>. Informa al Ministerio Fiscal y al letrado del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 4 — Actuación del equipo técnico EX R9","q":[{"i":"17-4","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Actuación del Equipo Técnico. Los profesionales integrantes de los equipos técnicos:","o":["Dependerán orgánicamente del Ministerio de Justicia o de las comunidades autónomas con competencias asumidas.","Estarán adscritos a los Juzgados de lo Penal.","Antes de la instrucción del expediente, desempeñarán las funciones establecidas en la Ley Orgánica 5/2000, de 12 de enero, bajo la dependencia orgánica del Ministerio Fiscal y del Juez de menores.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dependerán orgánicamente del Ministerio de Justicia o de las comunidades autónomas con competencias asumidas</mark></span>B (Juzgados de lo Penal) y C (dependencia orgánica del Fiscal antes de la instrucción) son falsas. Según el <span class=\"ref-norma\">art. 4.2 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"Los profesionales integrantes de los equipos técnicos dependerán orgánicamente del Ministerio de Justicia o de las comunidades autónomas con competencias asumidas y estarán adscritos a los juzgados de menores\"</span> (verificado con el temario oficial)."},{"i":"17-40","p":"Real Decreto 1774/2004. Actuación del equipo técnico. Podrán incorporarse de modo ______ o permanente a los equipos técnicos otros profesionales relacionados con las funciones que tienen atribuidas, cuando las necesidades planteadas lo requieran y así lo acuerde el órgano competente.","o":["Temporal.","Permanente.","Excepcional.","Ordinario."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Temporal</mark></span>El hueco admite solo «temporal» una vez fijado «o permanente». Según el <span class=\"ref-norma\">art. 4.1 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"Podrán también incorporarse de modo temporal o permanente a los equipos técnicos otros profesionales\"</span> (verificado con el temario oficial)."},{"i":"17-58","p":"Real Decreto 1774/2004. Actuación del equipo técnico. La función de los equipos técnicos será:","o":["Asistir técnicamente en las materias propias de sus disciplinas profesionales a los jueces de menores y al Ministerio Fiscal.","Asistir judicialmente en las materias propias de sus disciplinas profesionales a los jueces de menores y al Ministerio Fiscal.","Asistir procesalmente en las materias propias de sus disciplinas profesionales a los jueces de menores y al Ministerio Fiscal.","Asistir procedimentalmente en las materias propias de sus disciplinas profesionales a los jueces de menores y al Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Asistir técnicamente en las materias propias de sus disciplinas profesionales a los jueces de menores y al Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 19.1 · Real Decreto 1774/2004</span>. *Explicación: El artículo 19.1 del RD 1774/2004 establece que los equipos técnicos asisten &quot;técnicamente&quot; a Jueces y Fiscal en sus disciplinas profesionales.*"},{"i":"17-91","p":"Real Decreto 1774/2004. Actuación del Equipo Técnico. Los profesionales integrantes de los equipos técnicos:","o":["Dependen orgánicamente del Ministerio del Interior.","Están adscritos a la Fiscalía de menores.","Durante la instrucción del expediente, desempeñarán las funciones establecidas en la Ley Orgánica 5/2000, de 12 de enero, bajo la dependencia funcional del Ministerio Fiscal y del juez de menores cuando lo requiera.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Durante la instrucción del expediente, desempeñarán las funciones establecidas en la Ley Orgánica 5/2000, de 12 de enero, bajo la dependenc…</mark></span><span class=\"ref-norma\">Art. 19 · Real Decreto 1774/2004</span>. *Explicación: El artículo 19 del RD 1774/2004 establece que los equipos técnicos dependen funcionalmente del Ministerio Fiscal durante la instrucción.*"},{"i":"17-129","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Los profesionales integrantes de los equipos técnicos, durante la instrucción del expediente, desempeñarán las funciones establecidas en la Ley Orgánica 5/2000, de 12 de enero, bajo la dependencia funcional:","o":["De las Fuerzas y Cuerpos de Seguridad.","Del Ministerio de Justicia.","Del Ministerio Fiscal y del Juez de Menores cuando lo ordene.","Del Ministerio del Interior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Del Ministerio Fiscal y del Juez de Menores cuando lo ordene</mark></span>Según el <span class=\"ref-norma\">art. 4.2 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"bajo la dependencia funcional del Ministerio Fiscal y del juez de menores cuando lo ordene\"</span> (verificado con el temario oficial)."},{"i":"17-142","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. Los equipos técnicos:","o":["Asistirán técnicamente en las materias propias de sus disciplinas profesionales a los jueces de menores y al Ministerio Fiscal.","Prestarán asistencia profesional al menor desde el momento de su detención.","Realizarán funciones de mediación entre el menor y la víctima o perjudicado.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 4.1 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"prestarán asistencia profesional al menor desde el momento de su detención y realizarán funciones de mediación entre el menor y la víctima o perjudicado\"</span> (verificado con el temario oficial)."},{"i":"17-158","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. Actuación del equipo técnico. ¿Quién garantizará que el equipo técnico realice sus funciones en los términos que exijan las necesidades del servicio, adoptando las medidas oportunas al efecto?","o":["El Ministerio de Justicia.","La Administración competente.","Las Juzgados de menores.","El Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Administración competente.</mark></span>La Administración competente."},{"i":"17-ia-1425","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación del equipo técnico. Los equipos técnicos prestarán asistencia profesional al menor desde el momento de su detención y realizarán funciones de:","o":["mediación entre el menor y la víctima o perjudicado.","seguimiento de las medidas impuestas, sin perjuicio de lo previsto en la normativa vigente.","custodia del menor detenido.","asesoramiento a la víctima."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">mediación entre el menor y la víctima o perjudicado</mark></span>El <span class=\"ref-norma\">art. 4.1 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"prestarán asistencia profesional al menor desde el momento de su detención y realizarán funciones de mediación entre el menor y la víctima o perjudicado\"</span>. Realizan funciones de mediación entre el menor y la víctima o perjudicado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1426","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación del equipo técnico. Podrán incorporarse de modo temporal o permanente a los equipos técnicos otros profesionales relacionados con las funciones que tienen atribuidas, cuando las necesidades planteadas lo requieran y así lo acuerde:","o":["el Ministerio Fiscal.","el Juez de Menores.","el Ministerio de Justicia.","el órgano competente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el órgano competente</mark></span>El <span class=\"ref-norma\">art. 4.1 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"cuando las necesidades planteadas lo requieran y así lo acuerde el órgano competente\"</span>. Lo acuerda el órgano competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1427","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación del equipo técnico. Durante la instrucción del expediente, los equipos técnicos desempeñarán las funciones establecidas en la Ley Orgánica 5/2000 bajo la dependencia funcional del Ministerio Fiscal y del juez de menores:","o":["en todo caso.","cuando lo solicite el letrado del menor.","cuando lo ordene.","previa audiencia del Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cuando lo ordene</mark></span>El <span class=\"ref-norma\">art. 4.2 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"bajo la dependencia funcional del Ministerio Fiscal y del juez de menores cuando lo ordene\"</span>. La dependencia funcional del juez de menores se da cuando lo ordene. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1428","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación del equipo técnico. En el ejercicio de su actividad técnica, los equipos técnicos actuarán con independencia y con sujeción a:","o":["las instrucciones del Ministerio Fiscal.","criterios estrictamente profesionales.","las directrices de la Administración competente.","los criterios fijados por el Juez de Menores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">criterios estrictamente profesionales</mark></span>El <span class=\"ref-norma\">art. 4.2 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"actuarán con independencia y con sujeción a criterios estrictamente profesionales\"</span>. Actúan con independencia y criterios estrictamente profesionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1429","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación del equipo técnico. El Ministerio de Justicia y las comunidades autónomas con competencias asumidas determinarán el número de equipos técnicos necesarios, su composición y plantilla de conformidad con las necesidades que presenten los juzgados de menores y fiscalías, garantizando que cada fiscal instructor cuente con:","o":["los medios personales adecuados y suficientes para la emisión de los informes determinados por la ley y en los plazos establecidos.","un equipo técnico exclusivo para la emisión de los informes.","al menos un psicólogo, un educador y un trabajador social.","los medios materiales suficientes para la emisión de los informes, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los medios personales adecuados y suficientes para la emisión de los informes determinados por la ley y en los plazos establecidos</mark></span>El <span class=\"ref-norma\">art. 4.4 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"garantizando que cada fiscal instructor cuente con los medios personales adecuados y suficientes para la emisión de los informes determinados por la ley y en los plazos establecidos\"</span>. Cada fiscal instructor debe contar con medios personales adecuados y suficientes para emitir los informes en plazo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1430","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación del equipo técnico. Los informes del equipo técnico serán firmados por:","o":["el coordinador del equipo técnico, previo informe de la unidad policial competente.","el psicólogo del equipo.","el Fiscal instructor.","los profesionales del equipo técnico que intervengan en cada caso."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los profesionales del equipo técnico que intervengan en cada caso</mark></span>El <span class=\"ref-norma\">art. 4.5 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"Los informes serán firmados por los profesionales del equipo técnico que intervengan en cada caso\"</span>. Firman los profesionales que intervengan en cada caso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1431","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación del equipo técnico. La representación del equipo técnico en cada actuación la ostentará aquel que sea designado por:","o":["el Ministerio de Justicia o la comunidad autónoma, sin perjuicio de lo previsto en la normativa vigente.","el propio equipo técnico.","el Ministerio Fiscal o el juez de menores en la actuación concreta de que se trate.","el Fiscal Jefe."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Ministerio Fiscal o el juez de menores en la actuación concreta de que se trate</mark></span>El <span class=\"ref-norma\">art. 4.5 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"La representación del equipo la ostentará aquel que sea designado por el Ministerio Fiscal o el juez de menores en la actuación concreta de que se trate\"</span>. Lo designa el Ministerio Fiscal o el juez de menores según la actuación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"9.1. Actuación específica en caso de desaparición de menores EX ✱","q":[{"i":"17-6","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". La desaparición de un menor de edad, con independencia de la presunta voluntariedad o no de la misma:","o":["Se presume de riesgo.","Será de alto riesgo cuando las circunstancias lo indiquen.","Se presume siempre de alto riesgo.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Se presume siempre de alto riesgo</mark></span>Según el <span class=\"ref-norma\">punto 9.1.5 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"La desaparición de un menor de edad se presume siempre de alto riesgo, con independencia de la presunta voluntariedad o no de la misma\"</span> (verificado con el temario oficial)."},{"i":"17-121","p":"Instrucción nº 1/2017 de la Secretaría de Estado de Seguridad, por la que se actualiza el “protocolo de actuación policial con menores”. Actuación específica en caso de desaparición de menores. La desaparición de un menor de edad, con independencia de la presunta voluntariedad o no de la misma, se presume:","o":["Siempre de tiempo medio.","Siempre de alto riesgo.","Siempre de bajo riesgo.","Normalmente de riesgo alto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Siempre de alto riesgo</mark></span>Según el <span class=\"ref-norma\">punto 9.1.5 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"La desaparición de un menor de edad se presume siempre de alto riesgo, con independencia de la presunta voluntariedad o no de la misma\"</span> (verificado con el temario oficial)."},{"i":"17-171","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". La recepción de la denuncia por desaparición de un menor y la práctica de las primeras gestiones para su localización se efectuarán _____ ya que las primeras horas pueden ser fundamentales, tanto para la integridad del menor, como para la investigación y averiguación de las circunstancias del caso.","o":["De forma inmediata.","En el plazo máximo de 24 horas.","En el plazo máximo de 48 horas.","Lo antes posible."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De forma inmediata.</mark></span>De forma inmediata."},{"i":"17-207","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Desaparición de menores. ¿Cuál es el número armonizado de interés social de la Unión Europea para Casos de Niños Desaparecidos?:","o":["116000.","126000.","146000.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">116000.</mark></span> 116000. TEST 15"},{"i":"17-247","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores desaparecidos. En el ámbito de la Secretaría de Estado de Seguridad ha sido creado el Centro Nacional de Desaparecidos como elemento central de la estrategia del Ministerio del Interior en este campo que, entre otras funciones, asumirá:","o":["La gestión de la Base de Datos de Señalamientos Nacionales (BDSN).","La activación del Sistema de Alerta Temprana por desaparición de menores, salvo que el órgano competente acuerde otra cosa de forma motivada.","La gestión de la Base de Personas Desaparecidas y Restos Humanos sin identificar (PDYRH).","La gestión del Registro de Menores Extranjeros No Acompañados (RMENA)."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La gestión de la Base de Personas Desaparecidas y Restos Humanos sin identificar (PDYRH)</mark></span>El <span class=\"ref-norma\">punto 9.1.8 de la Instrucción 1/2017</span> dispone: <span class=\"ref-concepto\">\"asumirá la gestión de la Base de Personas Desaparecidas y Restos Humanos sin identificar (PDYRH)\"</span>"},{"i":"17-277","p":"(Instrucción 1/2017 - Actuación Policial con Menores) Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". La desaparición de un menor de edad, con independencia de la presunta voluntariedad o no de la misma:","o":["Se presume de riesgo.","Será de alto riesgo cuando las circunstancias lo indiquen.","Se presume siempre de alto riesgo.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Se presume de riesgo.</mark></span>La Instrucción 1/2017 establece que toda desaparición de un menor, con independencia de la presunta voluntariedad o no, se presume de riesgo."},{"i":"17-279","p":"(Instrucción 1/2017 - Protocolo Actuación Policial con Menores) Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". La desaparición de un menor de edad, con independencia de la presunta voluntariedad o no de la misma:","o":["Se presume de riesgo.","Será de alto riesgo cuando las circunstancias lo indiquen.","Se presume siempre de alto riesgo.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Se presume de riesgo.</mark></span> El punto 9.1.5 de la Instrucción 1/2017 SES establece que «la desaparición de un menor de edad se presume siempre de alto riesgo, con independencia de la presunta voluntariedad o no de la misma», si bien matiza que únicamente pueden excluirse de este criterio los casos en que concurran circunstancias que hagan evidente la voluntariedad de la desaparición, como fugas de centros de internamiento o acogida. Pese a que el texto literal habla de presunción de «alto riesgo», el banco de preguntas recoge como correcta la opción A («se presume de riesgo»)."},{"i":"17-ia-1647","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores desaparecidos. La denuncia por desaparición de un menor se incorporará de modo inmediato a la Base de Personas Desaparecidas y Restos Humanos sin identificar (PDYRH) para:","o":["el cotejo automático con los menores hallados en situación de desamparo, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","la difusión inmediata de sus datos a las unidades operativas.","el cotejo automático de los datos del menor desaparecido con los de los cadáveres encontrados que todavía no han podido ser identificados.","la emisión de avisos y llamamientos a la población."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el cotejo automático de los datos del menor desaparecido con los de los cadáveres encontrados que todavía no han podido ser identificados</mark></span>El <span class=\"ref-norma\">9.1.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"para el cotejo automático de los datos del menor desaparecido con los de los cadáveres encontrados que todavía no han podido ser identificados\"</span>. Sirve para el cotejo automático con cadáveres aún sin identificar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1648","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores desaparecidos. En la desaparición de un menor se incluirá el correspondiente señalamiento a nivel nacional en la Base de Datos de Señalamientos Nacionales (BDSN) y a nivel internacional en:","o":["las bases de datos de Interpol.","el Sistema de Información Schengen (SIS).","las bases de datos de Europol.","el Sistema de Información de Visados, sin perjuicio de lo previsto en la normativa vigente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Sistema de Información Schengen (SIS)</mark></span>El <span class=\"ref-norma\">9.1.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"a nivel nacional en la Base de Datos de Señalamientos Nacionales (BDSN) y a nivel internacional en el Sistema de Información Schengen (SIS)\"</span>. A nivel internacional, en el Sistema de Información Schengen. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1650","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores desaparecidos. La activación del Sistema de Alerta Temprana por desaparición de menores se solicita, a través de la correspondiente Unidad Central de Policía Judicial, al:","o":["Centro Nacional de Desaparecidos.","Centro de Inteligencia contra el Terrorismo y el Crimen Organizado, salvo que la autoridad judicial disponga otra cosa.","Gabinete de Coordinación y Estudios.","Centro Permanente de Información y Coordinación (CEPIC), de la Secretaría de Estado de Seguridad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Centro Permanente de Información y Coordinación (CEPIC), de la Secretaría de Estado de Seguridad</mark></span>El <span class=\"ref-norma\">9.1.6 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"que se solicite al Centro Permanente de Información y Coordinación (CEPIC), de la Secretaría de Estado de Seguridad, la activación del Sistema de Alerta Temprana\"</span>. Se solicita al CEPIC de la Secretaría de Estado de Seguridad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1651","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores desaparecidos. La línea telefónica 116000 es el número armonizado de interés social de la Unión Europea para:","o":["Casos de Maltrato Infantil.","Víctimas de trata de menores.","Casos de Niños Desaparecidos.","Menores en situación de riesgo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Casos de Niños Desaparecidos</mark></span>El <span class=\"ref-norma\">9.1.7 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"La Línea telefónica 116000 es el número armonizado de interés social de la Unión Europea para Casos de Niños Desaparecidos\"</span>. El 116000 es para Casos de Niños Desaparecidos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1652","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores desaparecidos. El Centro Nacional de Desaparecidos asumirá, entre otras funciones, la gestión de:","o":["la Base de Datos de Señalamientos Nacionales (BDSN).","la Base de Personas Desaparecidas y Restos Humanos sin identificar (PDYRH).","el Sistema de Alerta Temprana por desaparición de menores, previo informe de la unidad policial competente.","el Registro de Menores Extranjeros No Acompañados (RMENA)."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Base de Personas Desaparecidas y Restos Humanos sin identificar (PDYRH)</mark></span>El <span class=\"ref-norma\">9.1.8 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"asumirá la gestión de la Base de Personas Desaparecidas y Restos Humanos sin identificar (PDYRH)\"</span>. Gestiona la base PDYRH. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 7 — Definición de las medidas susceptibles de ser impuestas a los menores y reglas generales de determinación de las mismas EX ✱","q":[{"i":"17-7","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. De las medidas. Las medidas que pueden imponer los Jueces de Menores, ordenadas según la restricción de derechos que suponen, son, entre otras, las siguientes:","o":["Internamiento en régimen semicerrado.","Inhabilitación parcial.","Multa y amonestación.","Tratamiento ambulatorio."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Tratamiento ambulatorio</mark></span>No existen el internamiento «semicerrado» (es semiabierto), la inhabilitación «parcial» (es absoluta) ni la multa. Según el <span class=\"ref-norma\">art. 7.1.e) de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"e) Tratamiento ambulatorio\"</span> (verificado con el temario oficial)."},{"i":"17-74","p":"Ley Orgánica 5/2000. La amonestación consiste en la reprensión de la persona llevada a cabo por ___ y dirigida a hacerle comprender la ___ de los hechos cometidos y las consecuencias que los mismos han tenido o podrían haber tenido, instándole a no volver a cometer tales hechos en el futuro:","o":["El Juez de Menores / gravedad.","El Fiscal encargado del caso / trascendencia.","El Letrado o representante legal del menor / reprobación.","El representante de la institución de protección de menores / ilicitud."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Juez de Menores / gravedad.</mark></span><span class=\"ref-norma\">Art. 7.1 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 7.1 de la LO 5/2000 establece que la amonestación la realiza el Juez de Menores y debe hacer comprender la &quot;gravedad&quot; de los hechos.*"},{"i":"17-143","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Definición de las medidas susceptibles de ser impuestas a los menores y reglas generales de determinación de las mismas. Señale la opción INCORRECTA:","o":["Asistencia a un centro de día. Las personas sometidas a esta medida residirán en su domicilio habitual y acudirán a un centro, plenamente integrado en la comunidad, a realizar actividades de apoyo, educativas, formativas, laborales o de ocio.","Internamiento en régimen abierto. Las personas sometidas a esta medida llevarán a cabo todas las actividades del proyecto educativo en los servicios normalizados del entorno, residiendo en el centro como domicilio habitual, con sujeción al programa y régimen interno del mismo.","Permanencia de fin de semana. Las personas sometidas a esta medida permanecerán en su domicilio hasta un máximo de cuarenta y ocho horas entre la tarde o noche del viernes y la mañana del lunes, a excepción, en su caso, del tiempo que deban dedicar a las tareas socioeducativas asignadas por el Juez que deban llevarse a cabo fuera del lugar de permanencia.","Internamiento en régimen cerrado. Las personas sometidas a esta medida residirán en el centro y desarrollarán en el mismo las actividades formativas, educativas, laborales y de ocio."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Permanencia de fin de semana. Las personas sometidas a esta medida permanecerán en su domicilio hasta un máximo de cuarenta y ocho horas entre la tarde o noche del viernes y la mañana del lunes, a excepción, en su caso, del tiempo que deban dedicar a las tareas socioeducativas asignadas por el Juez que deban llevarse a cabo fuera del lugar de permanencia</mark></span>C es la incorrecta: son treinta y seis horas, hasta la noche del domingo y en domicilio o centro. Según el <span class=\"ref-norma\">art. 7.1.g) de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Las personas sometidas a esta medida permanecerán en su domicilio o en un centro hasta un máximo de treinta y seis horas entre la tarde o noche del viernes y la noche del domingo\"</span> (verificado con el temario oficial)."},{"i":"17-ia-1020","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Bases de la responsabilidad de los menores. A los menores en quienes concurran las circunstancias eximentes previstas en los números 1.º, 2.º y 3.º del Código Penal les serán aplicables, en caso necesario, las medidas:","o":["terapéuticas, con exclusión del tratamiento ambulatorio.","terapéuticas del internamiento terapéutico y del tratamiento ambulatorio.","educativas, como la asistencia a un centro de día y la libertad vigilada, salvo que la autoridad judicial disponga otra cosa.","de internamiento en régimen cerrado, semiabierto o abierto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">terapéuticas del internamiento terapéutico y del tratamiento ambulatorio</mark></span>El <span class=\"ref-norma\">art. 5.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"les serán aplicables, en caso necesario, las medidas terapéuticas a las que se refiere el artículo 7.1, letras d) y e), de la presente Ley\"</span>. Solo son aplicables las medidas terapéuticas de las letras d) y e): internamiento terapéutico y tratamiento ambulatorio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1023","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. Las personas sometidas a la medida de internamiento en régimen cerrado residirán en el centro y desarrollarán en el mismo las actividades:","o":["formativas, educativas y terapéuticas.","educativas, laborales y de reinserción social.","formativas, educativas, laborales y de ocio.","formativas y de ocio, pudiendo realizar las laborales fuera del centro."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">formativas, educativas, laborales y de ocio</mark></span>El <span class=\"ref-norma\">art. 7.1.a de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"residirán en el centro y desarrollarán en el mismo las actividades formativas, educativas, laborales y de ocio\"</span>. En el régimen cerrado todas las actividades se desarrollan en el centro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1024","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. En el internamiento en régimen semiabierto, la realización de actividades fuera del centro quedará condicionada a la evolución de la persona y al cumplimiento de los objetivos previstos en las mismas, pudiendo el Juez de Menores:","o":["suspenderlas definitivamente, acordando el cambio a régimen cerrado.","suspenderlas por tiempo determinado, acordando que todas las actividades se lleven a cabo dentro del centro.","revocarlas, previa audiencia del Ministerio Fiscal, y sustituir la medida, sin perjuicio de lo previsto en la normativa vigente.","suspenderlas por tiempo indeterminado, previo informe del equipo técnico."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">suspenderlas por tiempo determinado, acordando que todas las actividades se lleven a cabo dentro del centro</mark></span>El <span class=\"ref-norma\">art. 7.1.b de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"pudiendo el Juez de Menores suspenderlas por tiempo determinado, acordando que todas las actividades se lleven a cabo dentro del centro\"</span>. La suspensión es por tiempo determinado y las actividades pasan a hacerse dentro del centro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1025","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. En el internamiento en régimen abierto las personas sometidas llevarán a cabo todas las actividades del proyecto educativo en los servicios normalizados del entorno, residiendo en el centro:","o":["como domicilio habitual, con sujeción al programa y régimen interno del mismo.","solo los fines de semana, con sujeción al programa del centro.","durante la noche, con sujeción a las normas del Juzgado de Menores, en los términos que se determinen reglamentariamente.","como domicilio habitual, sin sujeción al régimen interno del mismo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">como domicilio habitual, con sujeción al programa y régimen interno del mismo</mark></span>El <span class=\"ref-norma\">art. 7.1.c de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"residiendo en el centro como domicilio habitual, con sujeción al programa y régimen interno del mismo\"</span>. El centro es su domicilio habitual y rige su programa y régimen interno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1026","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. En los centros de internamiento terapéutico se realizará una atención educativa especializada o tratamiento específico dirigido a personas que padezcan anomalías o alteraciones psíquicas, un estado de dependencia de bebidas alcohólicas, drogas tóxicas o sustancias psicotrópicas, o alteraciones en la percepción que determinen:","o":["una anulación total de la capacidad de obrar.","una alteración leve de la conciencia de la realidad, salvo que la autoridad judicial disponga otra cosa.","una disminución de la imputabilidad.","una alteración grave de la conciencia de la realidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una alteración grave de la conciencia de la realidad</mark></span>El <span class=\"ref-norma\">art. 7.1.d de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"o alteraciones en la percepción que determinen una alteración grave de la conciencia de la realidad\"</span>. La alteración en la percepción ha de determinar una alteración grave de la conciencia de la realidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1027","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. Cuando el interesado rechace un tratamiento de deshabituación, el Juez habrá de:","o":["imponerle el tratamiento con carácter forzoso.","archivar el expediente, previo informe del equipo técnico.","aplicarle otra medida adecuada a sus circunstancias.","dejar sin efecto la medida terapéutica sin más trámite."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">aplicarle otra medida adecuada a sus circunstancias</mark></span>El <span class=\"ref-norma\">art. 7.1.d de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Cuando el interesado rechace un tratamiento de deshabituación, el Juez habrá de aplicarle otra medida adecuada a sus circunstancias\"</span>. El tratamiento no se impone por la fuerza: se aplica otra medida adecuada a sus circunstancias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1028","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. Las personas sometidas a la medida de asistencia a un centro de día residirán en su domicilio habitual y acudirán a un centro, plenamente integrado en la comunidad, a realizar actividades de:","o":["apoyo, terapéuticas, formativas, laborales o de ocio.","apoyo, educativas, formativas, laborales o de ocio.","reinserción, educativas, formativas y de ocio.","apoyo, educativas y laborales, con pernocta en el centro."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">apoyo, educativas, formativas, laborales o de ocio</mark></span>El <span class=\"ref-norma\">art. 7.1.f de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"a realizar actividades de apoyo, educativas, formativas, laborales o de ocio\"</span>. Residen en su domicilio y acuden al centro a actividades de apoyo, educativas, formativas, laborales o de ocio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1029","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. Las personas sometidas a la medida de permanencia de fin de semana permanecerán en su domicilio o en un centro hasta un máximo de __________ horas entre la tarde o noche del viernes y la noche del domingo:","o":["treinta y seis","cuarenta y ocho","veinticuatro","setenta y dos"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">treinta y seis</mark></span>El <span class=\"ref-norma\">art. 7.1.g de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"hasta un máximo de treinta y seis horas entre la tarde o noche del viernes y la noche del domingo\"</span>. El máximo es de treinta y seis horas, de la tarde o noche del viernes a la noche del domingo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1030","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. En la permanencia de fin de semana se computan treinta y seis horas, a excepción, en su caso, del tiempo que deban dedicar:","o":["a las actividades formativas establecidas en el programa individualizado de ejecución de la medida, previo informe de la unidad policial competente.","a las tareas laborales que deban realizar fuera del centro.","a los traslados al centro educativo correspondiente.","a las tareas socio-educativas asignadas por el Juez que deban llevarse a cabo fuera del lugar de permanencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a las tareas socio-educativas asignadas por el Juez que deban llevarse a cabo fuera del lugar de permanencia</mark></span>El <span class=\"ref-norma\">art. 7.1.g de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"a excepción, en su caso, del tiempo que deban dedicar a las tareas socio-educativas asignadas por el Juez que deban llevarse a cabo fuera del lugar de permanencia\"</span>. Se exceptúa el tiempo de las tareas socio-educativas asignadas por el Juez fuera del lugar de permanencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1031","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. En la libertad vigilada se ha de hacer un seguimiento de la actividad de la persona sometida a la misma y de su asistencia a la escuela, al centro de formación profesional o al lugar de trabajo, según los casos, procurando ayudar a aquélla a:","o":["reintegrarse en su entorno familiar y social de forma progresiva.","cumplir las obligaciones impuestas por el Juez de Menores.","superar los factores que determinaron la infracción cometida.","superar las carencias educativas detectadas por el equipo técnico."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">superar los factores que determinaron la infracción cometida</mark></span>El <span class=\"ref-norma\">art. 7.1.h de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"procurando ayudar a aquélla a superar los factores que determinaron la infracción cometida\"</span>. El seguimiento procura ayudar a superar los factores que determinaron la infracción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1032","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. La libertad vigilada obliga, en su caso, a seguir las pautas socio-educativas que señale la entidad pública o el profesional encargado de su seguimiento, de acuerdo con el programa de intervención elaborado al efecto y aprobado por:","o":["el Ministerio Fiscal.","el Juez de Menores.","el equipo técnico.","la entidad pública de protección de menores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Juez de Menores</mark></span>El <span class=\"ref-norma\">art. 7.1.h de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"de acuerdo con el programa de intervención elaborado al efecto y aprobado por el Juez de Menores\"</span>. El programa de intervención lo aprueba el Juez de Menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1033","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. Señale la INCORRECTA respecto de las reglas de conducta que el Juez puede imponer en la libertad vigilada:","o":["Obligación de asistir con regularidad al centro docente correspondiente, cualquiera que sea la edad del menor.","Prohibición de ausentarse del lugar de residencia sin autorización judicial previa.","Obligación de comparecer personalmente ante el Juzgado de Menores o profesional que se designe, para informar de las actividades realizadas y justificarlas.","Prohibición de acudir a determinados lugares, establecimientos o espectáculos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Obligación de asistir con regularidad al centro docente correspondiente, cualquiera que sea la edad del menor</mark></span>El <span class=\"ref-norma\">art. 7.1.h de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Obligación de asistir con regularidad al centro docente correspondiente, si el menor está en edad de escolarización obligatoria, y acreditar ante el Juez dicha asistencia regular\"</span>. La asistencia al centro docente solo se impone si el menor está en edad de escolarización obligatoria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1034","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. En la libertad vigilada, el Juez, de oficio o a instancia del Ministerio Fiscal, podrá imponer cualesquiera otras obligaciones que estime convenientes para la reinserción social del sentenciado, siempre que:","o":["no impliquen restricción alguna de su libertad ambulatoria.","cuenten con el consentimiento del menor.","no supongan la imposibilidad de continuar conviviendo con sus padres.","no atenten contra su dignidad como persona."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no atenten contra su dignidad como persona</mark></span>El <span class=\"ref-norma\">art. 7.1.h de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"estime convenientes para la reinserción social del sentenciado, siempre que no atenten contra su dignidad como persona\"</span>. El único límite es que no atenten contra su dignidad; si implican no poder convivir con sus padres, se remite testimonio a la entidad pública. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1035","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. La prohibición de comunicarse con la víctima, o con aquellos de sus familiares u otras personas que determine el Juez o Tribunal, impedirá al menor establecer con ellas, por cualquier medio de comunicación o medio informático o telemático:","o":["contacto escrito o verbal, con exclusión del visual.","contacto directo, personal o telefónico.","contacto escrito, verbal o visual.","contacto verbal o visual, con exclusión del escrito."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">contacto escrito, verbal o visual</mark></span>El <span class=\"ref-norma\">art. 7.1.i de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"por cualquier medio de comunicación o medio informático o telemático, contacto escrito, verbal o visual\"</span>. La prohibición alcanza al contacto escrito, verbal o visual por cualquier medio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1036","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. Si la medida de prohibición de aproximarse o comunicarse implicase la imposibilidad del menor de continuar viviendo con sus padres, tutores o guardadores, el Ministerio Fiscal deberá remitir testimonio de los particulares a:","o":["el Juez de Menores.","la entidad pública de protección del menor.","el equipo técnico.","la Sección de Menores de la Fiscalía, sin perjuicio de lo previsto en la normativa vigente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la entidad pública de protección del menor</mark></span>El <span class=\"ref-norma\">art. 7.1.i de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"el Ministerio Fiscal deberá remitir testimonio de los particulares a la entidad pública de protección del menor, y dicha entidad deberá promover las medidas de protección adecuadas a las circunstancias de aquél\"</span>. El testimonio se remite a la entidad pública de protección del menor, que promueve las medidas de protección. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1037","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. La persona sometida a la medida de convivencia con otra persona, familia o grupo educativo debe convivir, durante el período de tiempo establecido por el Juez, con otra persona, con una familia distinta a la suya o con un grupo educativo, adecuadamente seleccionados para orientar a aquélla en su proceso de:","o":["socialización.","reinserción social.","reeducación personal.","integración familiar."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">socialización</mark></span>El <span class=\"ref-norma\">art. 7.1.j de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"adecuadamente seleccionados para orientar a aquélla en su proceso de socialización\"</span>. La orientación es para su proceso de socialización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1038","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. La persona sometida a la medida de prestaciones en beneficio de la comunidad ha de realizar las actividades no retribuidas que se le indiquen, de interés social o:","o":["en beneficio de las víctimas del delito.","de reparación del daño causado a la comunidad.","en beneficio de entidades públicas o privadas sin ánimo de lucro.","en beneficio de personas en situación de precariedad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en beneficio de personas en situación de precariedad</mark></span>El <span class=\"ref-norma\">art. 7.1.k de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"ha de realizar las actividades no retribuidas que se le indiquen, de interés social o en beneficio de personas en situación de precariedad\"</span>. Las actividades son no retribuidas, de interés social o en beneficio de personas en situación de precariedad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1039","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. La amonestación consiste en la reprensión de la persona llevada a cabo por el Juez de Menores y dirigida a hacerle comprender la gravedad de los hechos cometidos y las consecuencias que los mismos han tenido o podrían haber tenido, instándole a:","o":["reparar el daño causado a la víctima.","asumir su responsabilidad ante el Juez.","no volver a cometer tales hechos en el futuro.","cumplir las pautas socio-educativas fijadas, en los términos que se determinen reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no volver a cometer tales hechos en el futuro</mark></span>El <span class=\"ref-norma\">art. 7.1.m de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"instándole a no volver a cometer tales hechos en el futuro\"</span>. La reprensión del Juez insta a no volver a cometer tales hechos en el futuro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1040","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. La privación del permiso de conducir ciclomotores y vehículos a motor, o del derecho a obtenerlo, o de las licencias administrativas para caza o para uso de cualquier tipo de armas, podrá imponerse como accesoria cuando:","o":["el delito se hubiere cometido contra la seguridad vial, con independencia del vehículo utilizado, salvo que la autoridad judicial disponga otra cosa.","el delito o falta se hubiere cometido utilizando un ciclomotor o un vehículo a motor, o un arma, respectivamente.","el menor hubiera sido condenado por delito grave.","el hecho revista extrema gravedad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el delito o falta se hubiere cometido utilizando un ciclomotor o un vehículo a motor, o un arma, respectivamente</mark></span>El <span class=\"ref-norma\">art. 7.1.n de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Esta medida podrá imponerse como accesoria cuando el delito o falta se hubiere cometido utilizando un ciclomotor o un vehículo a motor, o un arma, respectivamente\"</span>. Es accesoria y solo si el delito o falta se cometió utilizando un ciclomotor, vehículo a motor o arma, respectivamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1041","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. La medida de inhabilitación absoluta produce la privación __________ de todos los honores, empleos y cargos públicos sobre el que recayere, aunque sean electivos:","o":["definitiva","temporal","parcial","provisional"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">definitiva</mark></span>El <span class=\"ref-norma\">art. 7.1.ñ de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"La medida de inhabilitación absoluta produce la privación definitiva de todos los honores, empleos y cargos públicos sobre el que recayere, aunque sean electivos\"</span>. La privación es definitiva (de todos los honores, empleos y cargos públicos, aunque sean electivos). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1042","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. Las medidas de internamiento constarán de dos períodos: el primero se llevará a cabo en el centro correspondiente y el segundo se llevará a cabo en régimen de:","o":["libertad vigilada, en la modalidad propuesta por el equipo técnico.","tratamiento ambulatorio o libertad vigilada, a elección del menor.","permanencia de fin de semana, en la modalidad elegida por el Juez.","libertad vigilada, en la modalidad elegida por el Juez."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">libertad vigilada, en la modalidad elegida por el Juez</mark></span>El <span class=\"ref-norma\">art. 7.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"el segundo se llevará a cabo en régimen de libertad vigilada, en la modalidad elegida por el Juez\"</span>. El segundo período es en libertad vigilada, en la modalidad que elija el Juez. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1043","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. Para la elección de la medida o medidas adecuadas se deberá atender de modo flexible, no sólo a la prueba y valoración jurídica de los hechos, sino especialmente a la edad, las circunstancias familiares y sociales, la personalidad y el interés del menor, puestos de manifiesto los dos últimos en los informes de:","o":["los equipos técnicos y del Ministerio Fiscal cuando éstos hubieran tenido conocimiento del menor por haber ejecutado una medida cautelar o definitiva con anterioridad.","los equipos técnicos y de las entidades públicas de protección y reforma de menores cuando éstas hubieran tenido conocimiento del menor por haber ejecutado una medida definitiva con anterioridad, previo informe de la unidad policial competente.","los equipos técnicos y de las entidades públicas de protección y reforma de menores cuando éstas hubieran tenido conocimiento del menor por haber ejecutado una medida cautelar o definitiva con anterioridad.","las entidades públicas de protección y reforma de menores, en todo caso, con independencia de que hubieran tenido conocimiento previo del menor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los equipos técnicos y de las entidades públicas de protección y reforma de menores cuando éstas hubieran tenido conocimiento del menor por haber ejecutado una medida cautelar o definitiva con anterioridad</mark></span>El <span class=\"ref-norma\">art. 7.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"puestos de manifiesto los dos últimos en los informes de los equipos técnicos y de las entidades públicas de protección y reforma de menores cuando éstas hubieran tenido conocimiento del menor por haber ejecutado una medida cautelar o definitiva con anterioridad\"</span>. Los informes son de los equipos técnicos y de las entidades públicas, cuando conocieron al menor por una medida cautelar o definitiva anterior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1045","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. El Juez podrá imponer al menor una o varias medidas con independencia de que se trate de uno o más hechos pero, en ningún caso, se impondrá a un menor en una misma resolución:","o":["más de una medida de la misma clase.","más de dos medidas de la misma clase.","más de una medida de internamiento.","medidas de distinta clase por un mismo hecho."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">más de una medida de la misma clase</mark></span>El <span class=\"ref-norma\">art. 7.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"en ningún caso, se impondrá a un menor en una misma resolución más de una medida de la misma clase, entendiendo por tal cada una de las que se enumeran en el apartado 1 de este artículo\"</span>. En una misma resolución no cabe más de una medida de la misma clase (cada una de las del listado). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1046","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. Cuando la medida impuesta lo sea por la comisión de un delito de los previstos en los Capítulos I y II del Título VIII del Código Penal, el Juez impondrá de forma accesoria, en todo caso, la obligación de someterse a programas formativos de:","o":["educación sexual y de educación vial.","educación en igualdad y de prevención de la violencia de género.","educación afectivo-sexual y de resolución pacífica de conflictos.","educación sexual y de educación en igualdad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">educación sexual y de educación en igualdad</mark></span>El <span class=\"ref-norma\">art. 7.5 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"el Juez impondrá de forma accesoria, en todo caso, la obligación de someterse a programas formativos de educación sexual y de educación en igualdad\"</span>. La obligación accesoria es someterse a programas formativos de educación sexual y de educación en igualdad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1128","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modificación de la medida impuesta. Cuando el delito cometido esté tipificado en los Capítulos I y II del Título VIII del Código Penal, sólo podrá dejarse sin efecto la medida si se acredita que la persona sometida a la misma ha cumplido:","o":["la obligación de reparar el daño causado a la víctima, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","la obligación accesoria de someterse a programas formativos de educación sexual y de educación en igualdad.","la obligación de someterse a tratamiento ambulatorio.","la mitad de la duración de la medida impuesta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la obligación accesoria de someterse a programas formativos de educación sexual y de educación en igualdad</mark></span>El <span class=\"ref-norma\">art. 13.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"sólo podrá dejarse sin efecto la medida si se acredita que la persona sometida a la misma ha cumplido la obligación prevista en el apartado 5 del artículo 7\"</span>. La obligación es la de los programas formativos de educación sexual y en igualdad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 2 — Actuación de la Policía Judicial EX R8","q":[{"i":"17-8","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Actuación de la Policía. Respecto de la práctica de la diligencia de reconocimiento, indique la CORRECTA:","o":["Solamente se realizarán en las dependencias de los Grupos de Menores o en las sedes del Ministerio Fiscal.","Deberá estar compuesta por otras personas, solo menores, conforme a los requisitos de la Ley de Enjuiciamiento Criminal.","Los menores que compongan la rueda de reconocimiento, se deberá contar con la sola autorización de sus representantes legales.","Se utilizarán los medios que resulten menos dañosos a la integridad del menor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Se utilizarán los medios que resulten menos dañosos a la integridad del menor.</mark></span><span class=\"ref-norma\">Art. 2.11 · Real Decreto 1774/2004</span>. El artículo 2.11 del Reglamento (RD 1774/2004) establece que &quot;Para la práctica de las diligencias de reconocimiento e identificación del menor se utilizarán los medios que resulten menos dañosos a la integridad del menor&quot;."},{"i":"17-10","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Los registros policiales donde consten la identidad y otros datos que afecten a la intimidad de los menores serán:","o":["De carácter confidencial, podrán ser consultados por terceros en determinadas circunstancias.","De carácter estrictamente confidencial y no podrán ser consultados por terceros.","De carácter público.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De carácter estrictamente confidencial y no podrán ser consultados por terceros.</mark></span><span class=\"ref-norma\">Art. 2.12 · Real Decreto 1774/2004</span>. El artículo 2.12 del Reglamento (RD 1774/2004) establece que los registros policiales donde consten la identidad y otros datos que afecten a la intimidad de los menores tendrán carácter estrictamente confidencial y no podrán ser consultados por terceros."},{"i":"17-24","p":"Real Decreto 1774/2004. Existirá un registro o archivo central donde, de modo específico para menores, se incorporará la información relativa a los datos de estos resultantes de la investigación. Tal registro o archivo solo podrá facilitar información a requerimiento de:","o":["El Ministerio Fiscal.","El Juez de menores.","A y B son correctas.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas.</mark></span><span class=\"ref-norma\">Art. 35.2 · Real Decreto 1774/2004</span>. *Explicación: El artículo 35.2 del RD 1774/2004 establece que la información solo se facilitará a requerimiento del Juez de Menores o del Ministerio Fiscal.*"},{"i":"17-34","p":"Real Decreto 1774/2004. Actuación de la policía judicial. Los registros policiales donde consten la identidad y otros datos que afectan a la intimidad de los menores serán de carácter ______ y no podrán ser consultados por terceros.","o":["Público.","Reservado.","Confidencial.","Restringido."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Confidencial.</mark></span><span class=\"ref-norma\">Art. 34.1 · Real Decreto 1774/2004</span>. *Explicación: El artículo 34.1 del RD 1774/2004 establece el carácter &quot;estrictamente confidencial&quot; de estos registros.*"},{"i":"17-83","p":"Real Decreto 1774/2004. Los registros policiales donde conste la identidad y otros datos que afecten a la intimidad de los menores serán de carácter:","o":["Público.","Reservado.","Confidencial.","Restringido."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Confidencial.</mark></span><span class=\"ref-norma\">Art. 34.1 · Real Decreto 1774/2004</span>. *Explicación: El artículo 34.1 del RD 1774/2004 establece el carácter &quot;estrictamente confidencial&quot; de estos registros.*"},{"i":"17-99","p":"Real Decreto 1774/2004. Actuación de la Policía Judicial. En relación con la actuación de la Policía Judicial, señale la opción incorrecta:","o":["Salvo la detención, toda diligencia policial restrictiva de derechos fundamentales será interesada al Ministerio Fiscal para que, por su conducto, se realice la oportuna solicitud al juez de menores competente.","Existirá un registro o archivo central donde, de modo específico para menores, se incorporará la información relativa a los datos de estos resultantes de la investigación. Tal registro o archivo solo podrá facilitar información a requerimiento del Ministerio Fiscal o del juez de menores.","Los registros policiales donde consten la identidad y otros datos que afecten a la intimidad de los menores serán de carácter estrictamente confidencial y podrán ser consultados por terceros.","El cacheo y aseguramiento físico de los menores detenidos se llevará a cabo en los casos en que sea estrictamente necesario y como medida proporcional de seguridad para el propio menor detenido y los funcionarios actuantes, cuando no sea posible otro medio de contención física del menor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los registros policiales donde consten la identidad y otros datos que afecten a la intimidad de los menores serán de carácter estrictamente confidencial y podrán ser consultados por terceros</mark></span>La opción A también es inexacta: es «salvo la detención» y la diligencia es «policial». Según el <span class=\"ref-norma\">art. 2.3 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"Los registros policiales donde consten la identidad y otros datos que afecten a la intimidad de los menores serán de carácter estrictamente confidencial y no podrán ser consultados por terceros\"</span> (verificado con el temario oficial)."},{"i":"17-123","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Actuación de la Policía Judicial. A los registros policiales donde consten la identidad y otros datos que afecten a la intimidad de los menores solo tendrán acceso:","o":["Las personas que participan directamente en la investigación de un caso en trámite o aquellas personas que, en el ejercicio de sus respectivas competencias, asienten expresamente el juez de menores o el Ministerio Fiscal.","Las personas que participan directamente en la investigación y tramitación de cada caso.","Aquellas personas que, en el ejercicio de sus respectivas competencias, asienten expresamente el juez de instrucción.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las personas que participan directamente en la investigación de un caso en trámite o aquellas personas que, en el ejercicio de sus respecti…</mark></span>Solo quienes participan directamente en la investigación o con autorización expresa del juez de menores o Fiscal."},{"i":"17-166","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Señale la opción INCORRECTA.","o":["Para la práctica de la diligencia de reconocimiento, se utilizarán los medios que resulten menos lesivos a la integridad del menor, debiendo llevarse a cabo en las dependencias de los Grupos de Menores o en las sedes del Ministerio Fiscal o autoridad judicial competente.","La Policía Judicial intervendrá en la investigación de los hechos cometidos por menores que pudieran ser constitutivos de delitos o faltas, bajo la dirección del Ministerio Fiscal.","Cuando la policía judicial intervenga a una persona como presunto autor de una infracción penal de cuya minoría de edad se dude y no consten datos que permitan su determinación, se pondrá a disposición del Ministerio Fiscal para que proceda a determinar la identidad y edad del presunto delincuente por las reglas de la Ley de Enjuiciamiento Criminal.","Al registro o archivo central donde, de modo específico para menores, se incorporará la información relativa a los datos de estos resultantes de la investigación, solo podrá facilitar información a requerimiento del Ministerio Fiscal o del juez de menores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando la policía judicial intervenga a una persona como presunto autor de una infracción penal de cuya minoría de edad se dude y no consten datos que permitan su determinación, se pondrá a disposición del Ministerio Fiscal para que proceda a determinar la identidad y edad del presunto delincuente por las reglas de la Ley de Enjuiciamiento Criminal</mark></span>C es la incorrecta: se pone a disposición de la autoridad judicial de la jurisdicción ordinaria, no del Ministerio Fiscal. Según el <span class=\"ref-norma\">art. 2.9 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"se pondrá a disposición de la autoridad judicial de la jurisdicción ordinaria para que proceda a determinar la identidad y edad del presunto delincuente por las reglas de la Ley de Enjuiciamiento Criminal\"</span> (verificado con el temario oficial)."},{"i":"17-173","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Señale la opción INCORRECTA:","o":["Los registros de menores no podrán ser utilizados en procesos de adultos relativos a casos subsiguientes en los que esté implicada la misma persona.","Salvo la identificación, toda diligencia policial restrictiva de derechos fundamentales será interesada al Ministerio Fiscal para que, por su conducto, se realice la oportuna solicitud al juez de menores competente.","Existe un registro o archivo central donde, de modo específico para menores, se incorporará la información relativa a los datos de estos resultantes de la investigación.","Cuando para la identificación de un menor haya de acudirse a la diligencia de reconocimiento prevista en el artículo 369 de la Ley de Enjuiciamiento Criminal, dicha diligencia solo podrá llevarse a cabo con orden o autorización del Ministerio Fiscal o del juez de menores según sus propias competencias."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Salvo la identificación, toda diligencia policial restrictiva de derechos fundamentales será interesada al Ministerio Fiscal para que, por su conducto, se realice la oportuna solicitud al juez de menores competente</mark></span>B es la incorrecta («salvo la identificación»); además D remite a un artículo erróneo de la LECrim (es el 369). Según el <span class=\"ref-norma\">art. 2.2 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"Salvo la detención, toda diligencia policial restrictiva de derechos fundamentales será interesada al Ministerio Fiscal\"</span> (verificado con el temario oficial)."},{"i":"17-174","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Señale la INCORRECTA.","o":["El cacheo y reconocimiento físico de los menores detenidos se llevará a cabo en los casos estrictos.","Existirá un registro o archivo central donde, de modo específico para menores, se incorporará la información relativa a los datos de estos resultantes de la investigación.","Los registros de menores no podrán ser utilizados en procesos de adultos relativos a casos subsiguientes en los que esté implicada la misma persona.","Para la práctica de la diligencia de reconocimiento, se utilizarán los medios que resulten menos dañinos a la integridad del menor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El cacheo y reconocimiento físico de los menores detenidos se llevará a cabo en los casos estrictos</mark></span>A es la incorrecta («reconocimiento físico», «casos estrictos»); C es el texto literal del art. 2.8. Según el <span class=\"ref-norma\">art. 2.5 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"El cacheo y aseguramiento físico de los menores detenidos se llevará a cabo en los casos en que sea estrictamente necesario\"</span> (verificado con el temario oficial)."},{"i":"17-217","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Cuando la policía judicial investigue a una persona como presunto autor de una infracción penal de cuya minoría de edad se dude y no consten datos que permitan su determinación, se pondrá a disposición de la autoridad judicial de la jurisdicción ordinaria para que proceda a determinar la identidad y edad del presunto delincuente por las reglas de la Ley de Enjuiciamiento Criminal. Una vez acreditada la edad, si esta fuese inferior a los 18 años, se procederá conforme a lo previsto en:","o":["Las normas de derecho civil sobre menores.","La Ley de Enjuiciamiento Criminal.","La Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores.","Las normas de derecho específico sobre menores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores.</mark></span>La Ley Orgánica 5/2000."},{"i":"17-241","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Cuando se proceda a la detención de un menor, se podrá proceder a tomar reseña de sus impresiones dactilares, así como fotografías de su rostro, que se remitirán, como parte del atestado policial, al Ministerio Fiscal para la instrucción del expediente, y constarán en:","o":["La base de datos de identificación personal.","El registro central de menores infractores.","El libro registro de menores detenidos.","El expediente personal del menor en la Fiscalía."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La base de datos de identificación personal</mark></span>El <span class=\"ref-norma\">art. 2.4 de la RD 1774/2004</span> dispone: <span class=\"ref-concepto\">\"y constarán en la base de datos de identificación personal\"</span>"},{"i":"17-256","p":"(RD 1774/2004 - Reglamento LORPM) Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Detención. Llevar a cabo la detención del menor. En los establecimientos de detención deberá llevarse un libro registro, de carácter confidencial, que al menos deberá contar con la siguiente información, entre otros: Señale la INCORRECTA.","o":["Circunstancias de la detención, motivos y en su caso autoridad que la ordenó.","Indicación de la persona o personas que custodiaron al menor.","Detalle de la notificación a los padres o representantes legales del menor y al Ministerio Fiscal de la detención del menor.","Expresión de las circunstancias físicas del menor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Expresión de las circunstancias físicas del menor.</mark></span><span class=\"ref-norma\">Art. 2.5 · Real Decreto 1774/2004</span>. El Reglamento (Art. 2.5) detalla la información del libro registro confidencial. La &quot;Expresión de las circunstancias físicas del menor&quot; no es uno de los requisitos mínimos explícitos en el listado normativo."},{"i":"17-260","p":"(RD 1774/2004 - Reglamento LORPM) Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Los registros policiales donde consten la identidad y otros datos que afecten a la intimidad de los menores serán:","o":["De carácter confidencial, podrán ser consultados por terceros en determinadas circunstancias.","De carácter estrictamente confidencial y no podrán ser consultados por terceros.","De carácter público.","Todos son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De carácter estrictamente confidencial y no podrán ser consultados por terceros.</mark></span><span class=\"ref-norma\">Art. 2.12 · Real Decreto 1774/2004</span>. El Reglamento (Art. 2.12) establece que estos registros &quot;tendrán carácter estrictamente confidencial y no podrán ser consultados por terceros&quot;."},{"i":"17-269","p":"(RD 1774/2004 - Reglamento LORPM) Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Actuación de la Policía. Respecto de la práctica de la diligencia de reconocimiento, indique la CORRECTA:","o":["Solamente se realizarán en las dependencias de los Grupos de Menores o en las sedes del Ministerio Fiscal.","Deberá estar compuesto por otras personas, solo menores, conforme a los requisitos de la Ley de Enjuiciamiento Criminal.","Los menores que compongan la rueda de reconocimiento, se deberá contar con la sola autorización de sus representantes legales.","Se utilizarán los medios que resulten menos dañinos a la integridad del menor."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Deberá estar compuesto por otras personas, solo menores, conforme a los requisitos de la Ley de Enjuiciamiento Criminal.</mark></span><span class=\"ref-norma\">Art. 2.10 · Real Decreto 1774/2004</span>. El artículo 2.10 del Reglamento de la LORPM, RD 1774/2004, señala que, para la diligencia de reconocimiento del menor, «la rueda deberá estar compuesta por otras personas, menores o no, conforme a los requisitos de la Ley de Enjuiciamiento Criminal», y que cuando esté compuesta por otros menores de edad se deberá contar con su autorización y con la de sus representantes legales o guardadores. La diligencia se practicará en las dependencias de los Grupos de Menores, del Ministerio Fiscal o de la autoridad judicial competente, utilizando los medios menos dañinos para la integridad del menor."},{"i":"17-272","p":"(RD 1774/2004 - Reglamento LORPM) Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Los registros policiales donde consten la identidad y otros datos que afecten a la intimidad de los menores serán:","o":["De carácter confidencial, podrán ser consultados por terceros en determinadas circunstancias.","De carácter estrictamente confidencial y no podrán ser consultados por terceros.","De carácter público.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De carácter estrictamente confidencial y no podrán ser consultados por terceros.</mark></span><span class=\"ref-norma\">Art. 2.3 · Real Decreto 1774/2004</span>. El artículo 2.3 del Reglamento de la LORPM, RD 1774/2004, establece que «los registros policiales donde consten la identidad y otros datos que afecten a la intimidad de los menores serán de carácter estrictamente confidencial y no podrán ser consultados por terceros». Solo tendrán acceso a dichos archivos quienes participen directamente en la investigación de un caso en trámite, o quienes sean expresamente autorizados por el Juez de Menores o el Ministerio Fiscal en el ejercicio de sus competencias."},{"i":"17-ia-1404","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. La actuación de la Policía Judicial se atendrá a las órdenes del Ministerio Fiscal y se sujetará a lo establecido en la Ley Orgánica 5/2000 y en:","o":["el Código Penal.","la Ley de Enjuiciamiento Criminal.","la Ley Orgánica 1/1996.","la Ley Orgánica del Poder Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Ley de Enjuiciamiento Criminal</mark></span>El <span class=\"ref-norma\">art. 2.2 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"se sujetará a lo establecido en la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores, y en la Ley de Enjuiciamiento Criminal\"</span>. Además de la LO 5/2000, rige la Ley de Enjuiciamiento Criminal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1406","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Cuando se proceda a la detención de un menor, se podrá tomar reseña de sus impresiones dactilares, así como fotografías de su rostro, que se remitirán, como parte del atestado policial, al Ministerio Fiscal para la instrucción del expediente, y constarán en:","o":["el registro central de menores infractores, previo informe de la unidad policial competente.","el libro registro de menores detenidos.","el expediente personal del menor.","la base de datos de identificación personal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la base de datos de identificación personal</mark></span>El <span class=\"ref-norma\">art. 2.4 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"y constarán en la base de datos de identificación personal\"</span>. Las reseñas y fotografías constan en la base de datos de identificación personal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1407","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. El cacheo y aseguramiento físico de los menores detenidos se llevará a cabo en los casos en que sea estrictamente necesario y como medida proporcional de seguridad para el propio menor detenido y los funcionarios actuantes, cuando:","o":["lo autorice el Ministerio Fiscal.","el menor oponga resistencia activa.","no sea posible otro medio de contención física del menor.","exista riesgo para la integridad de terceros, sin perjuicio de lo previsto en la normativa vigente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no sea posible otro medio de contención física del menor</mark></span>El <span class=\"ref-norma\">art. 2.5 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"cuando no sea posible otro medio de contención física del menor\"</span>. Solo cuando no sea posible otro medio de contención física. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1409","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Tanto los registros policiales como el registro central de menores estarán sometidos a lo dispuesto en la Ley Orgánica 15/1999, de 13 de diciembre, de:","o":["Protección de Datos de Carácter Personal.","Protección Jurídica del Menor.","Protección de la Seguridad Ciudadana.","Régimen Jurídico de las Administraciones Públicas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Protección de Datos de Carácter Personal</mark></span>El <span class=\"ref-norma\">art. 2.6 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"estarán sometidos a lo dispuesto en la Ley Orgánica 15/1999, de 13 de diciembre, de Protección de Datos de Carácter Personal\"</span>. Se someten a la Ley de Protección de Datos de Carácter Personal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1410","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Cuando el Ministerio Fiscal o el juez de menores deseen consultar datos relativos a la identidad o edad de un menor, requerirán del registro central que se comparen los datos que obran en su poder con los que existan en dicho registro, dirigiendo comunicación, directamente o a través del:","o":["Fiscal Jefe de Menores.","Juzgado Central de Menores, en los términos que se determinen reglamentariamente.","equipo técnico.","Grupo de Menores u otras unidades similares."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Grupo de Menores u otras unidades similares</mark></span>El <span class=\"ref-norma\">art. 2.7 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"dirigirán comunicación, directamente o a través del Grupo de Menores u otras unidades similares, al mencionado registro\"</span>. La comunicación puede ser directa o a través del Grupo de Menores u otras unidades similares. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1411","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Los registros de menores no podrán ser utilizados en:","o":["procesos de menores seguidos contra la misma persona.","procedimientos administrativos sancionadores.","procesos de adultos relativos a casos subsiguientes en los que esté implicada la misma persona.","cualquier proceso posterior, aunque lo autorice el juez, salvo que la autoridad judicial disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">procesos de adultos relativos a casos subsiguientes en los que esté implicada la misma persona</mark></span>El <span class=\"ref-norma\">art. 2.8 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"no podrán ser utilizados en procesos de adultos relativos a casos subsiguientes en los que esté implicada la misma persona\"</span>. No pueden usarse en procesos de adultos por casos subsiguientes con la misma persona. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1412","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Cuando la policía judicial investigue a una persona como presunto autor de una infracción penal de cuya minoría de edad se dude y no consten datos que permitan su determinación, se pondrá a disposición de:","o":["el Ministerio Fiscal de Menores, que determinará su edad mediante pruebas médicas, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","la autoridad judicial de la jurisdicción ordinaria para que determine su identidad y edad por las reglas de la Ley de Enjuiciamiento Criminal.","el Juez de Menores, que determinará su edad.","la entidad pública de protección de menores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la autoridad judicial de la jurisdicción ordinaria para que determine su identidad y edad por las reglas de la Ley de Enjuiciamiento Criminal</mark></span>El <span class=\"ref-norma\">art. 2.9 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"se pondrá a disposición de la autoridad judicial de la jurisdicción ordinaria para que proceda a determinar la identidad y edad del presunto delincuente por las reglas de la Ley de Enjuiciamiento Criminal\"</span>. Si se duda de la minoría de edad, interviene la autoridad judicial de la jurisdicción ordinaria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1413","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Una vez acreditada la edad de la persona investigada, si esta fuese inferior a los 18 años:","o":["se procederá conforme a lo previsto en la Ley Orgánica 5/2000.","se remitirá lo actuado al Juez de Menores, que decidirá.","se pondrá al menor a disposición de la entidad pública de protección.","se aplicará la Ley de Enjuiciamiento Criminal con carácter supletorio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se procederá conforme a lo previsto en la Ley Orgánica 5/2000</mark></span>El <span class=\"ref-norma\">art. 2.9 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"Una vez acreditada la edad, si esta fuese inferior a los 18 años, se procederá conforme a lo previsto en la Ley Orgánica 5/2000\"</span>. Acreditada la minoría de edad, se procede conforme a la LO 5/2000. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1414","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Cuando para la identificación de un menor haya de acudirse a la diligencia de reconocimiento prevista en la Ley de Enjuiciamiento Criminal, dicha diligencia solo podrá llevarse a cabo con:","o":["orden de la policía judicial y comunicación al Ministerio Fiscal, en los términos que se determinen reglamentariamente.","autorización del Juez de Instrucción.","consentimiento de sus representantes legales.","orden o autorización del Ministerio Fiscal o del juez de menores según sus propias competencias."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">orden o autorización del Ministerio Fiscal o del juez de menores según sus propias competencias</mark></span>El <span class=\"ref-norma\">art. 2.10 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"dicha diligencia solo podrá llevarse a cabo con orden o autorización del Ministerio Fiscal o del juez de menores según sus propias competencias\"</span>. Requiere orden o autorización del Ministerio Fiscal o del juez de menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1415","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. En la diligencia de reconocimiento de menores se utilizarán los medios que resulten menos dañinos a la integridad del menor, debiendo llevarse a cabo en:","o":["las dependencias de la unidad policial que practicó la detención, salvo que la autoridad judicial disponga otra cosa.","las dependencias judiciales exclusivamente.","las dependencias de los Grupos de Menores o en las sedes del Ministerio Fiscal o autoridad judicial competente.","cualquier dependencia policial adecuada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las dependencias de los Grupos de Menores o en las sedes del Ministerio Fiscal o autoridad judicial competente</mark></span>El <span class=\"ref-norma\">art. 2.10 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"debiendo llevarse a cabo en las dependencias de los Grupos de Menores o en las sedes del Ministerio Fiscal o autoridad judicial competente\"</span>. Se hace en los Grupos de Menores o en las sedes del Ministerio Fiscal o autoridad judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1416","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. La rueda de reconocimiento de un menor deberá estar compuesta por otras personas:","o":["menores de edad en todo caso.","menores o no, conforme a los requisitos de la Ley de Enjuiciamiento Criminal.","mayores de edad, para evitar perjuicios a los menores, previo informe de la unidad policial competente.","menores de la misma edad, necesariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">menores o no, conforme a los requisitos de la Ley de Enjuiciamiento Criminal</mark></span>El <span class=\"ref-norma\">art. 2.10 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"La rueda deberá estar compuesta por otras personas, menores o no, conforme a los requisitos de la Ley de Enjuiciamiento Criminal\"</span>. La rueda puede estar compuesta por menores o no, conforme a la LECrim. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1417","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación de la Policía Judicial. Cuando la rueda de reconocimiento esté compuesta por otros menores de edad, se deberá contar con su autorización y con la de sus representantes legales o guardadores de hecho o de derecho, a salvo el supuesto de:","o":["los mayores de 16 años no emancipados y de los menores emancipados.","los mayores de 14 años.","los mayores de 16 años emancipados, sin perjuicio de lo previsto en la normativa vigente.","los mayores de 18 años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los mayores de 16 años no emancipados y de los menores emancipados</mark></span>El <span class=\"ref-norma\">art. 2.10 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"a salvo el supuesto de los mayores de 16 años no emancipados y de los menores emancipados\"</span>. Se exceptúan los mayores de 16 años no emancipados y los menores emancipados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 9 — Régimen general de aplicación y duración de las medidas EX R3","q":[{"i":"17-9","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen general de aplicación y duración de las medidas. La medida de internamiento en régimen cerrado sólo podrá ser aplicable cuando:","o":["Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales.","Tratándose de hechos tipificados como delitos menos graves, en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas.","Los hechos delictivos se cometan en grupo o el menor perteneciere o actuare al servicio de una banda, organización o asociación, incluso de carácter transitorio, que se dedicare a la realización de tales actividades.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 9.2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. El artículo 9.2 de la Ley Orgánica 5/2000 establece que la medida de internamiento en régimen cerrado podrá ser aplicable en los supuestos de los apartados a), b) y c). Por lo tanto, todas son correctas."},{"i":"17-38","p":"Ley Orgánica 5/2000. De las medidas. ¿De cuántos periodos constarán las medidas de internamiento?","o":["Uno.","Dos.","Tres.","Cuatro."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dos.</mark></span><span class=\"ref-norma\">Art. 9.4 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 9.4 de la LO 5/2000 establece que las medidas de internamiento constarán de dos periodos: uno de internamiento en régimen cerrado y otro de tratamiento ambulatorio.*"},{"i":"17-60","p":"Ley Orgánica 5/2000. Régimen general de aplicación y duración de las medidas. Cuando los hechos cometidos sean calificados de falta, NO se podrán imponer las medidas de:","o":["Libertad vigilada hasta un máximo de seis meses.","Amonestación.","Permanencia de fin de semana hasta un máximo de ocho fines de semana.","Privación del permiso de conducir o de otras licencias administrativas hasta un año."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Permanencia de fin de semana hasta un máximo de ocho fines de semana.</mark></span><span class=\"ref-norma\">Art. 9.2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 9.2 de la LO 5/2000 no incluye la &quot;permanencia de fin de semana&quot; entre las medidas aplicables a las faltas.*"},{"i":"17-75","p":"Ley Orgánica 5/2000. De las medidas. Régimen general de aplicación y duración de las medidas: señale la opción INCORRECTA.","o":["La medida de prestaciones en beneficio de la comunidad no podrá superar las cien horas.","La medida de permanencia de fin de semana no podrá superar los ocho fines de semana.","Las acciones u omisiones imprudentes pueden ser sancionadas con medidas de internamiento en régimen abierto o cerrado, según la gravedad de la situación.","La duración de las medidas no podrá exceder de dos años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las acciones u omisiones imprudentes pueden ser sancionadas con medidas de internamiento en régimen abierto o cerrado, según la gravedad de…</mark></span><span class=\"ref-norma\">Art. 9.1 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: Las medidas de internamiento en régimen cerrado NO pueden imponerse por imprudencias, solo por hechos dolosos graves (Art. 9.1 LO 5/2000).*"},{"i":"17-81","p":"Ley Orgánica 5/2000. Régimen general de aplicación y duración de las medidas. La medida de internamiento en régimen cerrado sólo podrá ser aplicable cuando:","o":["Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales.","Tratándose de hechos tipificados como delito menos grave, en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas.","Los hechos tipificados como delito se cometan en grupo o el menor perteneciere o actuare al servicio de una banda, organización o asociación, incluso de carácter transitorio, que se dedicare a la realización de tales actividades.","Todas las anteriores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las anteriores</mark></span>Según el <span class=\"ref-norma\">art. 9.2 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales\"</span> (verificado con el temario oficial)."},{"i":"17-88","p":"Ley Orgánica 5/2000. Régimen general de aplicación y duración de las medidas. Cuando los hechos cometidos sean calificados de falta:","o":["Prestaciones en beneficio de la comunidad hasta cuarenta horas.","Permanencia de fin de semana hasta un máximo de tres fines de semana.","Sólo se podrá imponer las medidas de libertad vigilada hasta un máximo de tres meses.","La realización de tareas socio-educativas hasta seis meses."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La realización de tareas socio-educativas hasta seis meses</mark></span>En las faltas: cincuenta horas (no cuarenta), cuatro fines de semana (no tres) y libertad vigilada hasta seis meses (no tres). Según el <span class=\"ref-norma\">art. 9.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"prestaciones en beneficio de la comunidad hasta cincuenta horas, privación del permiso de conducir o de otras licencias administrativas hasta un año, la prohibición de aproximarse o comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el Juez hasta seis meses, y la realización de tareas socio-educativas hasta seis meses\"</span> (verificado con el temario oficial)."},{"i":"17-102","p":"Ley Orgánica 5/2000. Régimen general de aplicación y duración de las medidas. Cuando los hechos cometidos sean calificados de falta, sólo se podrá imponer la medida de:","o":["Libertad vigilada hasta un máximo de un año.","Permanencia de fin de semana hasta un máximo de cuatro fines de semana.","Privación del permiso de conducir o de otras licencias administrativas hasta seis meses.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Permanencia de fin de semana hasta un máximo de cuatro fines de semana</mark></span>Las demás cifras de la lista están alteradas (libertad vigilada seis meses, licencias un año). Según el <span class=\"ref-norma\">art. 9.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"permanencia de fin de semana hasta un máximo de cuatro fines de semana\"</span> (verificado con el temario oficial)."},{"i":"17-112","p":"Ley Orgánica 5/2000. Régimen general de aplicación y duración de las medidas. La medida de internamiento en régimen cerrado sólo podrá ser aplicable cuando:","o":["Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales.","Tratándose de hechos tipificados como delito menos grave, en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas.","Los hechos tipificados como delito se cometan en grupo o el menor perteneciere o actuare al servicio de una banda, organización o asociación, incluso de carácter transitorio, que se dedicare a la realización de tales actividades.","Todas las anteriores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las anteriores</mark></span>Según el <span class=\"ref-norma\">art. 9.2 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales\"</span> (verificado con el temario oficial)."},{"i":"17-122","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen general de aplicación y duración de las medidas. La medida de internamiento en régimen cerrado sólo podrá ser aplicable cuando:","o":["Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales.","Tratándose de hechos tipificados como delito menos grave, en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas.","Los hechos tipificados como delito se cometan en grupo o el menor perteneciere o actuare al servicio de una banda, organización o asociación, incluso de carácter transitorio, que se dedicare a la realización de tales actividades.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 9.2 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales\"</span> (verificado con el temario oficial)."},{"i":"17-131","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Régimen general de aplicación y duración de las medidas. La medida de internamiento en régimen cerrado sólo podrá ser aplicable cuando: Señale la INCORRECTA.","o":["Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales.","Los hechos estén tipificados como delito leve por el Código Penal o las leyes penales especiales.","Los hechos tipificados como delito se cometan en grupo o el menor perteneciere o actuare al servicio de una banda, organización o asociación, incluso de carácter transitorio, que se dedicare a la realización de tales actividades.","Tratándose de hechos tipificados como delito menos grave, en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los hechos estén tipificados como delito leve por el Código Penal o las leyes penales especiales</mark></span>B es la incorrecta: el Código no limita el internamiento cerrado a «delito leve». Según el <span class=\"ref-norma\">art. 9.2 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales\"</span> (verificado con el temario oficial)."},{"i":"17-132","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen general de aplicación y duración de las medidas. La medida de internamiento en régimen cerrado sólo podrá ser aplicable cuando:","o":["Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales.","Tratándose de hechos tipificados como delito menos grave, en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas.","Los hechos tipificados como delito se cometan en grupo o el menor perteneciere o actuare al servicio de una banda, organización o asociación, incluso de carácter transitorio, que se dedicare a la realización de tales actividades.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 9.2 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales\"</span> (verificado con el temario oficial)."},{"i":"17-184","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. De las medidas. La medida de internamiento en régimen cerrado sólo podrá ser aplicable cuando:","o":["Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales.","Tratándose de hechos tipificados como delito menos grave, en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas.","Los hechos tipificados como delito se cometan en grupo o el menor perteneciere o actuare al servicio de una banda, organización o asociación, incluso de carácter transitorio, que se dedicare a la realización de tales actividades.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span>Todas son correctas."},{"i":"17-220","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen general de aplicación y duración de las medidas. Cuando los hechos cometidos sean calificados de falta:","o":["Sólo se podrán imponer las medidas de libertad vigilada hasta un máximo de tres meses.","Amonestación.","Prestaciones en beneficio de la comunidad hasta sesenta horas.","Privación del permiso de conducir o de otras licencias administrativas hasta seis meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Amonestación</mark></span>Las demás opciones cambian las cifras: libertad vigilada seis meses, prestaciones cincuenta horas y licencias un año. Según el <span class=\"ref-norma\">art. 9.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"amonestación, permanencia de fin de semana hasta un máximo de cuatro fines de semana, prestaciones en beneficio de la comunidad hasta cincuenta horas, privación del permiso de conducir o de otras licencias administrativas hasta un año\"</span> (verificado con el temario oficial)."},{"i":"17-221","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen General de aplicación y duración de las medidas. Cuando los hechos sean calificados de falta: señale la CORRECTA.","o":["Sólo se podría imponer las medidas de libertad vigilada hasta un máximo de tres meses.","Permanezca de fin de semana hasta un máximo de cinco fines de semana.","Prestaciones en beneficio de la comunidad hasta setenta horas.","Amonestación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Amonestación.</mark></span>- La amonestación es una medida específica para faltas según la L.O. 5/2000."},{"i":"17-268","p":"(LO 5/2000 - LORPM) Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. El régimen general de aplicación y duración de las medidas. La medida de internamiento en régimen cerrado sólo podrá ser aplicable cuando:","o":["Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales.","Tratándose de hechos tipificados como delitos menos graves, en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas.","Los hechos sean imputados al menor o pertenecer o actuare al servicio de una banda, organización o asociación, incluso de carácter transitorio, que se dedicare a la realización de tales actividades.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Tratándose de hechos tipificados como delitos menos graves, en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas.</mark></span><span class=\"ref-norma\">Art. 9.2.b) · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. El artículo 9.2.b) de la LO 5/2000, LORPM, dispone que la medida de internamiento en régimen cerrado sólo podrá aplicarse, entre otros supuestos, «tratándose de hechos tipificados como delito menos grave, en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas». Los otros supuestos del mismo artículo (delito grave, o actuación en banda u organización) constituyen causas alternativas y no acumulativas para la misma medida."},{"i":"17-ia-1049","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen general de aplicación y duración de las medidas. Cuando los hechos cometidos sean calificados de falta, sólo se podrán imponer ciertas medidas. Señale la INCORRECTA:","o":["Permanencia de fin de semana hasta un máximo de seis fines de semana.","Prestaciones en beneficio de la comunidad hasta cincuenta horas.","Libertad vigilada hasta un máximo de seis meses.","Privación del permiso de conducir o de otras licencias administrativas hasta un año."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Permanencia de fin de semana hasta un máximo de seis fines de semana</mark></span>El <span class=\"ref-norma\">art. 9.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"permanencia de fin de semana hasta un máximo de cuatro fines de semana, prestaciones en beneficio de la comunidad hasta cincuenta horas\"</span>. Para las faltas la permanencia de fin de semana llega como máximo a cuatro fines de semana. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1050","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen general de aplicación y duración de las medidas. Cuando los hechos cometidos sean calificados de falta, sólo se podrán imponer, entre otras, la privación del permiso de conducir o de otras licencias administrativas hasta __________:","o":["seis meses","dos años","tres meses","un año"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un año</mark></span>El <span class=\"ref-norma\">art. 9.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"privación del permiso de conducir o de otras licencias administrativas hasta un año\"</span>. En las faltas la privación del permiso o licencias llega hasta un año. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1051","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen general de aplicación y duración de las medidas. La medida de internamiento en régimen cerrado sólo podrá ser aplicable cuando, tratándose de hechos tipificados como delito menos grave:","o":["en su ejecución se haya empleado violencia o intimidación graves en las personas, aunque no se haya generado riesgo para su vida, sin perjuicio de lo previsto en la normativa vigente.","se haya causado un daño patrimonial de especial gravedad o se haya empleado violencia.","en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas.","se hayan cometido en grupo, aun sin pertenecer a banda u organización."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas</mark></span>El <span class=\"ref-norma\">art. 9.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Tratándose de hechos tipificados como delito menos grave, en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas\"</span>. En delito menos grave, el cerrado exige violencia o intimidación en las personas o grave riesgo para la vida o integridad física. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1052","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen general de aplicación y duración de las medidas. La duración de las medidas no podrá exceder de dos años. La medida de prestaciones en beneficio de la comunidad no podrá superar las __________ horas:","o":["cincuenta","cien","ciento cincuenta","doscientas"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cien</mark></span>El <span class=\"ref-norma\">art. 9.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"La medida de prestaciones en beneficio de la comunidad no podrá superar las cien horas\"</span>. El límite general de las prestaciones en beneficio de la comunidad es de cien horas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"2.2. Competencias","q":[{"i":"17-11","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. Competencias. Los Grupos o Equipos de la Policía Judicial especializados en materia de menores tendrán las siguientes atribuciones:","o":["En tareas de protección, el tratamiento de los menores en situación de riesgo o desamparo, y los menores de catorce años a los que se atribuya la comisión de ilícitos penales.","Informar, asesorar y, en su caso, brindar apoyo y colaboración al resto de unidades para el adecuado tratamiento policial de los menores, la práctica de las actuaciones necesarias en interés del menor y la debida observancia de las garantías procedimentales.","Propiciar y mantener el contacto con Instituciones y Asociaciones relacionadas con este ámbito de actuación, al objeto de favorecer la adopción de medidas de carácter preventivo y asistencial.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span>La Instrucción 1/2017 detalla las competencias de las unidades especializadas en menores, e incluye las tres funciones mencionadas: protección de menores en riesgo y autores de ilícitos penales menores de 14 (opción a), asesoramiento y práctica de actuaciones en interés del menor (opción b), y contacto con instituciones y asociaciones (opción c)."},{"i":"17-20","p":"Instrucción 1/2017. Competencias. Los Grupos o Equipos de la Policía Judicial especializados en materia de menores tendrán los siguientes cometidos (señale la INCORRECTA):","o":["Informar, asesorar y, en su caso, brindar apoyo y colaboración al resto de unidades para el adecuado tratamiento policial del menor, la práctica de las actuaciones necesarias en interés del menor y la debida observancia de las garantías procedimentales.","En el ámbito de la prevención, el tratamiento de los menores en situación de riesgo o desamparo, y los menores de catorce años a los que se les atribuya la comisión de hechos penales.","Establecer canales de comunicación permanentes con la correspondiente Sección de Menores de la Fiscalía, dando cumplimiento a las instrucciones generales o particulares que dicho órgano les dirija.","Intervenir, en exclusiva o en colaboración con la Unidad competente, en aquellos otros supuestos que determinen las Direcciones Adjuntas Operativas de las Direcciones Generales de la Policía y de la Guardia Civil, en sus respectivos ámbitos de competencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En el ámbito de la prevención, el tratamiento de los menores en situación de riesgo o desamparo, y los menores de catorce años a los que se les atribuya la comisión de hechos penales</mark></span>B es la incorrecta: dice «En el ámbito de la prevención» donde el texto dice «En tareas de protección». Según el <span class=\"ref-norma\">punto 2.2.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"b. En tareas de protección, el tratamiento de los menores en situación de riesgo o desamparo\"</span> (verificado con el temario oficial)."},{"i":"17-73","p":"Instrucción 1/2017. Competencias. Los Grupos o Equipos de la Policía Judicial especializados en materia de menores tendrán los siguientes cometidos. Señale la INCORRECTA:","o":["Hacerse cargo de la investigación criminal y asistencia a las víctimas en aquellos casos que revistan cierta gravedad y donde estén implicados mayores de edad, sean víctimas o autores de infracciones penales.","En el ámbito de la prevención, el tratamiento de los menores en situación de riesgo o desamparo, y los menores de catorce años a los que se les atribuya la comisión de hechos penales.","Informar, asesorar y, en su caso, brindar apoyo y colaboración al resto de unidades para el adecuado tratamiento policial del menor, la práctica de las actuaciones necesarias en interés del menor y la debida observancia de las garantías procedimentales.","Propiciar y mantener el contacto con instituciones y Asociaciones relacionadas con este ámbito de actuación, al objeto de favorecer la adopción de medidas de carácter preventivo y asistencial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En el ámbito de la prevención, el tratamiento de los menores en situación de riesgo o desamparo, y los menores de catorce años a los que se les atribuya la comisión de hechos penales</mark></span>Enunciado pasado a «señale la INCORRECTA»: la falsa es B («En el ámbito de la prevención»). Según el <span class=\"ref-norma\">punto 2.2.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"b. En tareas de protección, el tratamiento de los menores en situación de riesgo o desamparo\"</span> (verificado con el temario oficial)."},{"i":"17-146","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Competencias. Los Grupos o Equipos de la Policía Judicial especializados en materia de menores tendrán los siguientes cometidos:","o":["En tareas de protección, el tratamiento de los menores en situación de riesgo o desamparo y los menores de catorce años a los que se les atribuya la comisión de hechos penales.","Hacerse cargo de la investigación criminal y asistencia a las víctimas en aquellos casos que revistan cierta gravedad y donde estén implicados mayores de edad, sean víctimas o autores de infracciones penales.","Propiciar y mantener el contacto con Instituciones y Asociaciones relacionadas con este ámbito de actuación, al objeto de favorecer la adopción de medidas de carácter preventivo y asistencial.","Las opciones A y C son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las opciones A y C son correctas.</mark></span>Las opciones A y C son correctas."},{"i":"17-176","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Los Grupos o Equipos de la Policía Judicial especializados en materia de menores tendrán los siguientes cometidos: señale la INCORRECTA.","o":["Hacerse cargo de la investigación criminal y asistencia a las víctimas en aquellos casos que revistan cierta gravedad y donde estén implicados menores de edad, sean víctimas o autores de infracciones penales.","En tareas de protección, el tratamiento de los menores en situación de riesgo o desamparo, y los menores de catorce años a los que se les atribuya la comisión de hechos penales.","Informes, asesorías y, en su caso, prestar apoyo y colaboración al resto de unidades para el adecuado tratamiento policial del menor, la práctica de las actuaciones necesarias en interés del menor y la debida observancia de las garantías procedimentales.","Propiciar y mantener el contacto con Instituciones y Asociaciones relacionadas con este ámbito de actuación, al objeto de favorecer la adopción de medidas de carácter preventivo y asistencial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Informes, asesorías y, en su caso, prestar apoyo y colaboración al resto de unidades para el adecuado tratamiento policial del menor, la práctica de las actuaciones necesarias en interés del menor y la debida observancia de las garantías procedimentales</mark></span>C es la incorrecta («Informes, asesorías»); B reproduce literalmente el cometido de protección. Según el <span class=\"ref-norma\">punto 2.2.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"c. Informar, asesorar y, en su caso, brindar apoyo y colaboración al resto de unidades\"</span> (verificado con el temario oficial)."},{"i":"17-261","p":"(Instrucción 1/2017 - Actuación Policial con Menores) Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. Competencias. Los Grupos o Equipos de la Policía Judicial especializados en materia de menores tendrán las siguientes atribuciones:","o":["En tareas de protección, el tratamiento de los menores en situación de riesgo o desamparo, y los menores de catorce años a los que se atribuya la comisión de ilícitos penales.","Informar, asesorar y, en su caso, brindar apoyo y colaboración al resto de unidades para el adecuado tratamiento policial de los menores, la práctica de las actuaciones necesarias en interés del menor y la debida observancia de las garantías procedimentales.","Propiciar y mantener el contacto con Instituciones y Asociaciones relacionadas con este ámbito de actuación, al objeto de favorecer la adopción de medidas de carácter preventivo y asistencial.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span>El Protocolo de Actuación Policial con Menores (Instrucción 1/2017) incluye las tres funciones mencionadas como atribuciones de las unidades especializadas en menores."},{"i":"17-273","p":"(Instrucción 1/2017 - Protocolo Actuación Policial con Menores) Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. Competencias. Los Grupos o Equipos de la Policía Judicial especializados en materia de menores tendrán las siguientes atribuciones:","o":["En tareas de protección, el tratamiento de los menores en situación de riesgo o desamparo, y los menores de catorce años a los que se atribuya la comisión de ilícitos penales.","Informar, asesorar y, en su caso, brindar apoyo y colaboración al resto de unidades para el adecuado tratamiento policial de los menores, la práctica de las actuaciones necesarias en interés del menor y la debida observancia de las garantías procedimentales.","Propiciar y mantener el contacto con Instituciones y Asociaciones relacionadas con este ámbito de actuación, al objeto de favorecer la adopción de medidas de carácter preventivo y asistencial.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span> El punto 2.2.1 de la Instrucción 1/2017 SES atribuye a los Grupos o Equipos de la Policía Judicial especializados en materia de menores, entre otros cometidos: en tareas de protección, el tratamiento de menores en riesgo o desamparo y de los menores de catorce años a quienes se atribuya la comisión de ilícitos penales (letra b); informar, asesorar y brindar apoyo y colaboración al resto de unidades para el adecuado tratamiento policial del menor (letra c); y propiciar y mantener el contacto con Instituciones y Asociaciones relacionadas con este ámbito, para favorecer medidas preventivas y asistenciales (letra e). Al recoger la pregunta las tres competencias citadas literalmente en el Protocolo, la respuesta correcta es la D, «Todas son correctas»."},{"i":"17-ia-1512","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. Los Grupos o Equipos de la Policía Judicial especializados en menores se harán cargo de la investigación criminal y asistencia a las víctimas en aquellos casos que:","o":["revistan especial gravedad y donde los menores sean autores de infracciones penales, previo informe de la unidad policial competente.","revistan cierta gravedad y donde estén implicados menores de edad, sean víctimas o autores de infracciones penales.","afecten a menores de catorce años.","sean derivados por la Sección de Menores de la Fiscalía."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">revistan cierta gravedad y donde estén implicados menores de edad, sean víctimas o autores de infracciones penales</mark></span>El <span class=\"ref-norma\">2.2.1.a de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Hacerse cargo de la investigación criminal y asistencia a las víctimas en aquellos casos que revistan cierta gravedad y donde estén implicados menores de edad, sean víctimas o autores de infracciones penales\"</span>. Casos de cierta gravedad con menores implicados, víctimas o autores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1513","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. En tareas de protección, los especialistas tratarán a los menores en situación de riesgo o desamparo, y a los menores de catorce años a los que:","o":["se les atribuya la comisión de ilícitos penales.","se detenga por infracciones administrativas, sin perjuicio de lo previsto en la normativa vigente.","se halle en situación de absentismo escolar.","se encuentre en centros de protección."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se les atribuya la comisión de ilícitos penales</mark></span>El <span class=\"ref-norma\">2.2.1.b de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"y los menores de catorce años a los que se le atribuya la comisión de ilícitos penales\"</span>. Tratan a los menores de catorce años a los que se atribuya un ilícito penal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1514","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. Los Grupos o Equipos especializados establecerán canales de comunicación permanentes con la correspondiente Sección de Menores de la Fiscalía, dando cumplimiento a:","o":["las circulares de la Fiscalía General del Estado.","las órdenes del Juez de Menores.","los protocolos de la Secretaría de Estado de Seguridad, en los términos que se determinen reglamentariamente.","las instrucciones generales o particulares que dicho órgano les dirija."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las instrucciones generales o particulares que dicho órgano les dirija</mark></span>El <span class=\"ref-norma\">2.2.1.d de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"dando cumplimiento a las instrucciones generales o particulares que dicho órgano les dirija\"</span>. Se cumplen las instrucciones generales o particulares de la Sección de Menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1515","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. Los Grupos o Equipos especializados propiciarán y mantendrán el contacto con Instituciones y Asociaciones relacionadas con este ámbito de actuación, al objeto de favorecer:","o":["la adopción de medidas de carácter educativo y reparador, salvo que la autoridad judicial disponga otra cosa.","la formación de los agentes especialistas.","la adopción de medidas de carácter preventivo y asistencial.","la derivación de menores a recursos de protección."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la adopción de medidas de carácter preventivo y asistencial</mark></span>El <span class=\"ref-norma\">2.2.1.e de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"al objeto de favorecer la adopción de medidas de carácter preventivo y asistencial\"</span>. Favorece medidas de carácter preventivo y asistencial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1516","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. Los Grupos o Equipos especializados intervendrán, en exclusiva o en colaboración con la Unidad competente, en aquellos otros supuestos que determinen:","o":["las Direcciones Generales de la Policía y de la Guardia Civil, previo informe de la Secretaría de Estado de Seguridad, previo informe de la unidad policial competente.","las Direcciones Adjuntas Operativas de las Direcciones Generales de la Policía y de la Guardia Civil, en sus respectivos ámbitos de competencia.","la Secretaría de Estado de Seguridad.","la Sección de Menores de la Fiscalía."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las Direcciones Adjuntas Operativas de las Direcciones Generales de la Policía y de la Guardia Civil, en sus respectivos ámbitos de competencia</mark></span>El <span class=\"ref-norma\">2.2.1.f de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"en aquellos otros supuestos que determinen las Direcciones Adjuntas Operativas de las Direcciones Generales de la Policía y de la Guardia Civil, en sus respectivos ámbitos de competencia\"</span>. Los supuestos los determinan las Direcciones Adjuntas Operativas de ambas Direcciones Generales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1517","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. Se establecerán planes específicos de formación y actualización en el tratamiento policial de menores para el personal no especializado, por ser, en la mayoría de las ocasiones, a quien corresponde:","o":["materializar la intervención inicial.","practicar las primeras diligencias de investigación.","efectuar las detenciones de menores.","recibir las denuncias."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">materializar la intervención inicial</mark></span>El <span class=\"ref-norma\">2.2.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"por ser, en la mayoría de las ocasiones, a quien corresponde materializar la intervención inicial\"</span>. Al personal no especializado le corresponde materializar la intervención inicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores","q":[{"i":"17-12","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Instrucción del procedimiento. Sobreseimiento del expediente por conciliación o reparación entre el menor y la víctima. Señale la correcta.","o":["El desistimiento en la continuación del expediente sólo será posible cuando el hecho imputado al menor constituya delito menos grave o falta.","El único requisito será la falta de violencia o intimidación.","Será posible cuando el hecho imputado al menor no constituya delito menos grave.","A) y B) son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El desistimiento en la continuación del expediente sólo será posible cuando el hecho imputado al menor constituya delito menos grave o falt…</mark></span><span class=\"ref-norma\">Art. 19 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. El artículo 19 de la Ley Orgánica 5/2000 permite el desistimiento por conciliación o reparación, atendiendo a la gravedad y circunstancias de los hechos y del menor, de modo particular a la falta de violencia o intimidación graves. El apartado 2 establece que el desistimiento será posible cuando el hecho imputado al menor no constituya delito grave (es decir, sea delito menos grave o falta), y el apartado 1 establece que se valorará la falta de violencia o intimidación graves. Por lo tanto, la opción a) es correcta según el artículo 19.2. (El artículo 19.1 no requiere que el único requisito sea la falta de violencia o intimidación graves, sino que lo considera de modo particular; la opción b) es incompleta/incorrecta)."},{"i":"17-15","p":"Ley Orgánica 5/2000, de 12 de enero. La acción para exigir la responsabilidad civil en el procedimiento regulado en esta Ley se ejercitará por el Ministerio Fiscal, salvo que el perjudicado renuncie a ella, la ejercite por sí mismo en el plazo de _____ desde que se le notifique la apertura de la pieza separada de responsabilidad civil o se la reserve para ejercitarla ante el orden jurisdiccional civil.","o":["Un mes.","Quince días.","Tres meses.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Un mes</mark></span>Según el <span class=\"ref-norma\">art. 61.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"la ejercite por sí mismo en el plazo de un mes desde que se le notifique la apertura de la pieza separada de responsabilidad civil\"</span> (verificado con el temario oficial)."},{"i":"17-32","p":"Ley Orgánica 5/2000. Las medidas cautelares que se pueden imponer a un menor son:","o":["Internamiento en régimen cerrado.","Libertad vigilada.","Prohibición de aproximarse o comunicarse con la víctima.","Todas las anteriores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las anteriores.</mark></span><span class=\"ref-norma\">Art. 28 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 28 de la LO 5/2000 enumera diversas medidas cautelares, incluyendo todas las opciones mencionadas.*"},{"i":"17-53","p":"Ley Orgánica 5/2000. Las medidas cautelares que pueden imponerse a un menor incluyen:","o":["Internamiento en centro en el régimen adecuado.","Libertad vigilada.","Convivencia con otra persona, familia o grupo educativo.","Todas las anteriores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las anteriores</mark></span>La prohibición de salir del territorio nacional no es una medida cautelar de la Ley. Según el <span class=\"ref-norma\">art. 28.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Dichas medidas podrán consistir en internamiento en centro en el régimen adecuado, libertad vigilada, prohibición de aproximarse o comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el Juez, o convivencia con otra persona, familia o grupo educativo\"</span> (verificado con el temario oficial)."},{"i":"17-59","p":"Ley Orgánica 5/2000. Plazos de prescripción. La acción para exigir responsabilidad penal al menor prescribirá. Señale la INCORRECTA:","o":["A los cinco años, cuando se trate de un delito grave castigado en el Código Penal con pena superior a cinco años.","A los tres años, cuando se trate de cualquier otro delito grave.","Al año, cuando se trate de un delito menos grave.","Con arreglo a las normas contenidas en el Código Penal, cuando se trate de los hechos delictivos tipificados en los artículos 138, 139, 179, 180 y 571 a 580 del Código Penal o cualquier otra acción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A los cinco años, cuando se trate de un delito grave castigado en el Código Penal con pena superior a cinco años</mark></span>Enunciado pasado a «señale la INCORRECTA»: B, C y D eran verdaderas; la falsa es A («superior a cinco años»). Según el <span class=\"ref-norma\">art. 15.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"A los cinco años, cuando se trate de un delito grave sancionado en el Código Penal con pena superior a diez años\"</span> (verificado con el temario oficial)."},{"i":"17-70","p":"Ley Orgánica 5/2000. Reglas generales. Una de las siguientes no es una posible medida cautelar que pueden ser adoptadas para la custodia y defensa del menor expedientado o para la debida protección de la víctima:","o":["Convivencia con otra persona, familia o grupo educativo.","Asistencia a un centro de día.","Libertad vigilada.","Prohibición de aproximarse o comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el Juez."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Asistencia a un centro de día</mark></span>La asistencia a un centro de día no es medida cautelar; la libertad vigilada sí. Según el <span class=\"ref-norma\">art. 28.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Dichas medidas podrán consistir en internamiento en centro en el régimen adecuado, libertad vigilada, prohibición de aproximarse o comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el Juez, o convivencia con otra persona, familia o grupo educativo\"</span> (verificado con el temario oficial)."},{"i":"17-82","p":"Ley Orgánica 5/2000. La acción para exigir responsabilidad penal al menor prescribirá. Señale la INCORRECTA:","o":["A los cinco años, cuando se trate de un delito grave castigado en el Código Penal con pena superior a cinco años.","A los tres años, cuando se trate de cualquier otro delito grave.","Al año, cuando se trate de un delito menos grave.","Con arreglo a las normas contenidas en el Código Penal, cuando se trate de los hechos delictivos tipificados en los artículos 138, 139, 179, 180 y 571 a 580 del Código Penal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A los cinco años, cuando se trate de un delito grave castigado en el Código Penal con pena superior a cinco años</mark></span>Enunciado pasado a «señale la INCORRECTA»: B, C y D eran verdaderas; la falsa es A («superior a cinco años»). Según el <span class=\"ref-norma\">art. 15.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"A los cinco años, cuando se trate de un delito grave sancionado en el Código Penal con pena superior a diez años\"</span> (verificado con el temario oficial)."},{"i":"17-94","p":"Ley Orgánica 5/2000. Unidad de expediente. En los casos en los que los delitos atribuidos al menor expedientado hubieran sido cometidos en diferentes territorios, la determinación del órgano judicial competente para el enjuiciamiento de todos ellos en unidad de expediente, así como de las entidades públicas competentes para la ejecución de las medidas que se apliquen:","o":["Se hará teniendo en cuenta el lugar del domicilio del menor.","Se hará teniendo en cuenta, subsidiariamente, los criterios expresados en el artículo 18 de la Ley de Enjuiciamiento Criminal.","Las opciones A y B son correctas.","Será el lugar donde se haya cometido el delito con mayor pena objetiva."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las opciones A y B son correctas.</mark></span><span class=\"ref-norma\">Art. 26.3 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 26.3 de la LO 5/2000 establece ambos criterios para determinar la competencia.*"},{"i":"17-100","p":"Ley Orgánica 5/2000. Competencia de los Jueces de Menores. ¿Qué Juez de Menores es el competente para conocer de los hechos cometidos por mayores de catorce años y menores de dieciocho?","o":["El del lugar donde se haya cometido el hecho delictivo, sin perjuicio de lo establecido en el artículo 20.3 de esta Ley.","El del lugar del domicilio del menor, en cualquier caso.","El del lugar de la detención del menor, sin perjuicio de lo establecido en el artículo 20.3 de esta Ley.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El del lugar donde se haya cometido el hecho delictivo, sin perjuicio de lo establecido en el artículo 20.3 de esta Ley</mark></span>La remisión es al art. 20.3 (no al 26.3). Según el <span class=\"ref-norma\">art. 2.3 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"La competencia corresponde al Juez de Menores del lugar donde se haya cometido el hecho delictivo, sin perjuicio de lo establecido en el artículo 20.3 de esta Ley\"</span> (verificado con el temario oficial)."},{"i":"17-108","p":"Ley Orgánica 5/2000. Unidad de expediente. Respecto a los procedimientos de la competencia de la Audiencia Nacional, ¿podrán ser objeto de acumulación con otros procedimientos instruidos en el ámbito de la jurisdicción de menores?:","o":["Sólo podrán cuando son los mismos los sujetos imputados.","Sólo podrán cuando no sean los mismos los sujetos imputados.","En ningún caso podrán ser objeto de la referida acumulación.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En ningún caso podrán ser objeto de la referida acumulación.</mark></span>*Explicación: Los procedimientos de la Audiencia Nacional NO pueden acumularse con procedimientos de la jurisdicción de menores ordinaria por razones de competencia.*"},{"i":"17-109","p":"Ley Orgánica 5/2000. De la prescripción. Los hechos delictivos cometidos por los menores prescriben:","o":["A los cinco años, cuando se trate de un delito grave sancionado en el Código Penal con pena superior a diez años.","A los tres años, cuando se trate de cualquier otro delito grave.","Al año, cuando se trate de un delito menos grave.","A los tres meses, cuando se trate de una falta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A los cinco años, cuando se trate de un delito grave sancionado en el Código Penal con pena superior a diez años</mark></span>Los demás graves prescriben a los tres años («cualquier otro delito grave»). Según el <span class=\"ref-norma\">art. 15.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"A los cinco años, cuando se trate de un delito grave sancionado en el Código Penal con pena superior a diez años\"</span> (verificado con el temario oficial)."},{"i":"17-115","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la prescripción. Las medidas que tengan una duración superior a los dos años prescribirán a:","o":["Los tres años.","Los cinco años.","Al año.","Los dos años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los tres años</mark></span>Las restantes medidas prescriben a los dos años. Según el <span class=\"ref-norma\">art. 15.2 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Las medidas que tengan una duración superior a los dos años prescribirán a los tres años\"</span> (verificado con el temario oficial)."},{"i":"17-128","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Declaración General. Esta Ley se aplicará para exigir la responsabilidad de las personas:","o":["Menores de catorce años y los comisión de hechos tipificados como delitos o faltas en el Código Penal o las leyes penales especiales.","Menores de edad inferior a catorce años y menores que representan los beneficios de intención de intereses penales.","Mayores de catorce años y menores de dieciocho por la comisión de hechos tipificados como delitos o faltas en el Código Penal o las leyes penales especiales.","Menores de doce años y menores de dieciséis por la comisión de hechos tipificados como delitos o faltas en el Código Penal o las leyes penales especiales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Mayores de catorce años y menores de dieciocho por la comisión de hechos tipificados como delitos o faltas en el Código Penal o las leyes penales especiales</mark></span>Según el <span class=\"ref-norma\">art. 1.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"la responsabilidad de las personas mayores de catorce años y menores de dieciocho por la comisión de hechos tipificados como delitos o faltas en el Código Penal o las leyes penales especiales\"</span> (verificado con el temario oficial)."},{"i":"17-168","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. De las medidas. Cuando se trate de un delito menos grave los hechos delictivos cometidos por los menores prescriben:","o":["A los cinco años.","A los tres años.","Al año.","Al año tres meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al año</mark></span>Los cinco años corresponden a los delitos graves con pena superior a diez años. Según el <span class=\"ref-norma\">art. 15.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Al año, cuando se trate de un delito menos grave\"</span> (verificado con el temario oficial)."},{"i":"17-193","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. La acción para exigir la responsabilidad civil en el procedimiento regulado en esta Ley se ejercitará por el Ministerio Fiscal, salvo que el perjudicado renuncie a ella, la ejercite por sí mismo en el plazo de ______ desde que se le notifique la apertura de la pieza separada de responsabilidad civil o se la reserve para ejercitarla ante el orden jurisdiccional civil conforme a los preceptos del Código Civil y de la Ley de Enjuiciamiento Civil.","o":["Tres meses.","Dos meses.","Quince días.","Un mes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Un mes</mark></span>Según el <span class=\"ref-norma\">art. 61.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"la ejercite por sí mismo en el plazo de un mes desde que se le notifique la apertura de la pieza separada de responsabilidad civil\"</span> (verificado con el temario oficial)."},{"i":"17-196","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la responsabilidad Civil. ¿Qué opciones tiene el perjudicado respecto a la acción de responsabilidad civil?","o":["No puede intervenir en el procedimiento, ya que es obligación exclusiva del Ministerio Fiscal.","Puede renunciar a la acción, ejercitarla por sí mismo en un mes o reservarla para el ámbito civil.","Debe presentar una reclamación exclusivamente ante el orden jurisdiccional civil.","Sólo puede participar si el Ministerio Fiscal lo autoriza expresamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Puede renunciar a la acción, ejercitarla por sí mismo en un mes o reservarla para el ámbito civil.</mark></span>Puede renunciar, ejercitarla en 15 días o reservarla para el ámbito civil."},{"i":"17-208","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Cuando se trate de hechos delictivos sancionados en el Código Penal o en las leyes penales especiales con pena de prisión igual o superior a quince años, ¿cómo se regula su prescripción?","o":["Conforme a normas específicas de la Ley de Responsabilidad Penal de Menores.","Conforme a disposiciones autonómicas aplicables.","Con arreglo a las normas contenidas en el Código Penal.","Conforme a un dictamen especial del Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Con arreglo a las normas contenidas en el Código Penal.</mark></span>Con arreglo a las normas contenidas en el Código Penal."},{"i":"17-229","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Reglas Generales. _____, oído el letrado del menor, así como el equipo técnico y la representación de la entidad pública de protección o reforma de menores, que informarán especialmente sobre la naturaleza de la medida cautelar, resolverá sobre lo propuesto tomando en especial consideración el interés del menor.","o":["El Ministro de Defensa.","El Juez.","El Ministro de Interior.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Juez.</mark></span>- Es el Juez quien resuelve sobre las medidas cautelares."},{"i":"17-234","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Competencia de los Jueces de Menores. Los Jueces de Menores serán competentes para conocer de los hechos cometidos por personas mayores de catorce años y menores de dieciocho, así como para:","o":["Hacer ejecutar las sentencias, sin perjuicio de las facultades atribuidas por esta Ley a las Comunidades Autónomas y Entidades Locales respecto a la protección y reforma de menores.","Hacer ejecutar las sentencias, sin perjuicio de las facultades atribuidas por esta Ley a otros órganos jurisdiccionales y al Ministerio Fiscal respecto a la protección y reforma de menores.","Hacer ejecutar las sentencias, sin perjuicio de las facultades atribuidas por esta Ley a las Comunidades Autónomas respecto a la protección y reforma de menores.","Hacer ejecutar las sentencias, sin perjuicio de las facultades atribuidas por esta Ley a las asociaciones, fundaciones y organizaciones no gubernamentales dedicadas a la protección y reforma de menores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Hacer ejecutar las sentencias, sin perjuicio de las facultades atribuidas por esta Ley a las Comunidades Autónomas respecto a la protección…</mark></span>- Los Jueces de Menores ejecutan sentencias respetando competencias de las CCAA."},{"i":"17-280","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la prescripción. Los hechos delictivos cometidos por los menores prescriben a los cinco años, cuando se trate de:","o":["Cualquier otro delito grave.","Un delito grave sancionado en el Código Penal con pena superior a diez años.","Un delito menos grave.","Un delito sancionado con pena de prisión igual o superior a quince años, sin perjuicio de lo que establezcan los tratados internacionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un delito grave sancionado en el Código Penal con pena superior a diez años</mark></span>El <span class=\"ref-norma\">art. 15.1.2.º de la LO 5/2000</span> dispone: <span class=\"ref-concepto\">\"A los cinco años, cuando se trate de un delito grave sancionado en el Código Penal con pena superior a diez años\"</span>"},{"i":"17-ia-1001","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Declaración general. Esta Ley se aplicará para exigir la responsabilidad de las personas mayores de catorce años y menores de dieciocho por la comisión de hechos tipificados como delitos o faltas en:","o":["el Código Penal o las leyes penales especiales.","el Código Penal y la Ley de Enjuiciamiento Criminal.","el Código Penal o las leyes administrativas sancionadoras.","las leyes penales especiales o la normativa de protección de menores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Código Penal o las leyes penales especiales</mark></span>El <span class=\"ref-norma\">art. 1.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"por la comisión de hechos tipificados como delitos o faltas en el Código Penal o las leyes penales especiales\"</span>. La Ley remite solo al Código Penal y a las leyes penales especiales; la LECrim y la normativa administrativa no son fuente de tipificación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1002","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Declaración general. Las personas a las que se aplique la presente Ley gozarán de todos los derechos reconocidos en la Constitución y en el ordenamiento jurídico, particularmente en la Ley Orgánica __________, de Protección Jurídica del Menor:","o":["1/2004, de 28 de diciembre","8/2015, de 22 de julio","5/2000, de 12 de enero","1/1996, de 15 de enero"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">1/1996, de 15 de enero</mark></span>El <span class=\"ref-norma\">art. 1.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"particularmente en la Ley Orgánica 1/1996, de 15 de enero, de Protección Jurídica del Menor\"</span>. La LO 1/2004 es la de violencia de género, la LO 8/2015 modifica el sistema de protección y la LO 5/2000 es la propia Ley. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1003","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Declaración general. Señale la INCORRECTA respecto de los derechos de las personas a las que se aplica la presente Ley:","o":["Gozarán de todos los derechos reconocidos en la Constitución y en el ordenamiento jurídico.","Les es aplicable, particularmente, la Ley Orgánica de Protección Jurídica del Menor.","Solo gozarán de los derechos reconocidos en esta Ley, con exclusión de los reconocidos en la Constitución.","Gozarán de los derechos recogidos en las normas sobre protección de menores contenidas en los Tratados válidamente celebrados por España."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Solo gozarán de los derechos reconocidos en esta Ley, con exclusión de los reconocidos en la Constitución</mark></span>El <span class=\"ref-norma\">art. 1.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"gozarán de todos los derechos reconocidos en la Constitución y en el ordenamiento jurídico, particularmente en la Ley Orgánica 1/1996, de 15 de enero, de Protección Jurídica del Menor, así como en la Convención sobre los Derechos del Niño de 20 de noviembre de 1989 y en todas aquellas normas sobre protección de menores contenidas en los Tratados válidamente celebrados por España\"</span>. Gozan de todos los derechos de la Constitución y del ordenamiento; no existe exclusión alguna. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1004","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Declaración general. Las personas a las que se aplique la presente Ley gozarán de todos los derechos reconocidos en la Constitución y en el ordenamiento jurídico, así como en la Convención sobre los Derechos del Niño de:","o":["20 de noviembre de 1979, en los términos que se determinen reglamentariamente.","20 de noviembre de 1989.","10 de diciembre de 1989.","20 de noviembre de 1999."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">20 de noviembre de 1989</mark></span>El <span class=\"ref-norma\">art. 1.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"así como en la Convención sobre los Derechos del Niño de 20 de noviembre de 1989\"</span>. La Convención sobre los Derechos del Niño es de 20 de noviembre de 1989. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1005","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Declaración general. Esta Ley se aplicará para exigir la responsabilidad de las personas mayores de __________ años y menores de __________ por la comisión de hechos tipificados como delitos o faltas:","o":["catorce / dieciocho","catorce / diecisiete","dieciséis / dieciocho","doce / dieciocho"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">catorce / dieciocho</mark></span>El <span class=\"ref-norma\">art. 1.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"la responsabilidad de las personas mayores de catorce años y menores de dieciocho\"</span>. El tramo es mayores de catorce y menores de dieciocho. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1006","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Competencia de los Jueces de Menores. Los Jueces de Menores serán competentes para conocer de los hechos cometidos por las personas a las que se aplica la Ley, así como para hacer __________ las sentencias, sin perjuicio de las facultades atribuidas por esta Ley a las Comunidades Autónomas respecto a la protección y reforma de menores:","o":["cumplir","dictar","notificar","ejecutar"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ejecutar</mark></span>El <span class=\"ref-norma\">art. 2.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"así como para hacer ejecutar las sentencias, sin perjuicio de las facultades atribuidas por esta Ley a las Comunidades Autónomas respecto a la protección y reforma de menores\"</span>. La competencia incluye hacer ejecutar las sentencias, sin perjuicio de las facultades de las Comunidades Autónomas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1007","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Competencia de los Jueces de Menores. Los Jueces de Menores serán asimismo competentes para resolver sobre:","o":["las responsabilidades civiles de padres, tutores y guardadores, con exclusión de las del propio menor.","las responsabilidades civiles derivadas de los hechos, siempre que el perjudicado no se haya reservado la acción, salvo que la autoridad judicial disponga otra cosa.","las responsabilidades civiles derivadas de los hechos cometidos por las personas a las que resulta aplicable la presente Ley.","las responsabilidades civiles únicamente cuando el Ministerio Fiscal las haya ejercitado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las responsabilidades civiles derivadas de los hechos cometidos por las personas a las que resulta aplicable la presente Ley</mark></span>El <span class=\"ref-norma\">art. 2.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"serán asimismo competentes para resolver sobre las responsabilidades civiles derivadas de los hechos cometidos por las personas a las que resulta aplicable la presente Ley\"</span>. La competencia civil abarca las responsabilidades derivadas de los hechos, sin las limitaciones de las otras opciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1008","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Competencia de los Jueces de Menores. Señale la INCORRECTA sobre la competencia del Juzgado Central de Menores de la Audiencia Nacional:","o":["Conoce de los delitos de terrorismo previstos en el Código Penal.","Conoce de todos los delitos cometidos por menores en el extranjero, aun cuando su conocimiento no corresponda a la jurisdicción española.","Conoce de los delitos cometidos por menores en el extranjero cuando conforme a la Ley Orgánica del Poder Judicial y a los Tratados Internacionales corresponda su conocimiento a la jurisdicción española.","Las referencias de la Ley al Juez de Menores se entenderán hechas al Juez Central de Menores en lo que afecta a los menores imputados por estos delitos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Conoce de todos los delitos cometidos por menores en el extranjero, aun cuando su conocimiento no corresponda a la jurisdicción española</mark></span>El <span class=\"ref-norma\">art. 2.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Corresponderá igualmente al Juzgado Central de Menores de la Audiencia Nacional la competencia para conocer de los delitos cometidos por menores en el extranjero cuando conforme al artículo 23 de la Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial y a los Tratados Internacionales corresponda su conocimiento a la jurisdicción española\"</span>. Solo conoce de los cometidos en el extranjero cuando corresponda su conocimiento a la jurisdicción española. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1019","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Bases de la responsabilidad de los menores. Los menores serán responsables con arreglo a esta Ley cuando no concurra en ellos ninguna de las causas de __________ de la responsabilidad criminal previstas en el vigente Código Penal:","o":["exención o atenuación","extinción o agravación","exención o extinción","exención o modificación"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">exención o extinción</mark></span>El <span class=\"ref-norma\">art. 5.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"no concurra en ellos ninguna de las causas de exención o extinción de la responsabilidad criminal previstas en el vigente Código Penal\"</span>. Las causas son de exención o extinción de la responsabilidad criminal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1021","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Bases de la responsabilidad de los menores. Las edades indicadas en el articulado de esta Ley se han de entender siempre referidas al momento de la comisión de los hechos, sin que el haberse rebasado las mismas antes del comienzo del procedimiento o durante la tramitación del mismo tenga incidencia alguna sobre:","o":["la competencia atribuida por esta misma Ley a los Jueces y Fiscales de Menores.","la medida que pueda imponerse al menor en la sentencia.","la ejecución de la medida impuesta por el Juez de Menores.","la responsabilidad civil de los padres, tutores y guardadores, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la competencia atribuida por esta misma Ley a los Jueces y Fiscales de Menores</mark></span>El <span class=\"ref-norma\">art. 5.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"tenga incidencia alguna sobre la competencia atribuida por esta misma Ley a los Jueces y Fiscales de Menores\"</span>. Rebasar la edad durante el procedimiento no afecta a la competencia de Jueces y Fiscales de Menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1022","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la intervención del Ministerio Fiscal. Para la defensa de los derechos de los menores, el Ministerio Fiscal dirigirá personalmente la investigación de los hechos y ordenará que __________ practique las actuaciones necesarias para la comprobación de aquéllos y de la participación del menor en los mismos:","o":["el equipo técnico","el Juez de Menores","el Letrado de la Administración de Justicia","la policía judicial"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la policía judicial</mark></span>El <span class=\"ref-norma\">art. 6 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"dirigirá personalmente la investigación de los hechos y ordenará que la policía judicial practique las actuaciones necesarias para la comprobación de aquéllos y de la participación del menor en los mismos\"</span>. Quien practica las actuaciones es la policía judicial, bajo la dirección personal del Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1048","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Principio acusatorio. La duración de las medidas privativas de libertad no podrá exceder, en ningún caso, del tiempo que hubiera durado la pena privativa de libertad que se le hubiere impuesto por el mismo hecho, si el sujeto, de haber sido mayor de edad, hubiera sido declarado responsable, de acuerdo con:","o":["la Ley de Enjuiciamiento Criminal.","el Código Penal.","el Código Penal y las leyes penales especiales.","la Ley Orgánica 5/2000."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Código Penal</mark></span>El <span class=\"ref-norma\">art. 8 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"en ningún caso, del tiempo que hubiera durado la pena privativa de libertad que se le hubiere impuesto por el mismo hecho, si el sujeto, de haber sido mayor de edad, hubiera sido declarado responsable, de acuerdo con el Código Penal\"</span>. La referencia es el Código Penal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1118","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Pluralidad de infracciones. Los límites máximos de duración de las medidas serán aplicables aunque el menor fuere responsable de dos o más infracciones, en el caso de que éstas sean conexas o se trate de una infracción continuada, así como cuando:","o":["las infracciones hubieran sido cometidas en el mismo territorio.","las infracciones sean de la misma naturaleza.","el menor haya sido condenado por la más grave de ellas.","un sólo hecho constituya dos o más infracciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un sólo hecho constituya dos o más infracciones</mark></span>El <span class=\"ref-norma\">art. 11.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"así como cuando un sólo hecho constituya dos o más infracciones\"</span>. También se aplican cuando un solo hecho constituya dos o más infracciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1119","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Pluralidad de infracciones. En caso de pluralidad de infracciones, el Juez, para determinar la medida o medidas a imponer, así como su duración, deberá tener en cuenta, además del interés del menor, la naturaleza y el número de las infracciones, tomando como referencia:","o":["la más reciente de todas ellas.","la primera de todas ellas.","la más grave de todas ellas.","la de mayor pena en abstracto."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la más grave de todas ellas</mark></span>El <span class=\"ref-norma\">art. 11.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"tomando como referencia la más grave de todas ellas\"</span>. La referencia es la infracción más grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1120","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Pluralidad de infracciones. Si las infracciones hubiesen sido objeto de diferentes procedimientos, el __________ Juez sentenciador señalará la medida o medidas que debe cumplir el menor por el conjunto de los hechos, dentro de los límites y con arreglo a los criterios expresados:","o":["primer","último","más antiguo","de mayor jerarquía"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">último</mark></span>El <span class=\"ref-norma\">art. 11.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"el último Juez sentenciador señalará la medida o medidas que debe cumplir el menor por el conjunto de los hechos\"</span>. Es el último Juez sentenciador quien señala las medidas por el conjunto de los hechos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1121","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Pluralidad de infracciones. Cuando alguno de los hechos de la pluralidad de infracciones fuere de los de especial gravedad de las reglas especiales, la medida de internamiento en régimen cerrado podrá alcanzar una duración máxima de diez años para los mayores de dieciséis años y de __________ para los menores de esa edad:","o":["seis años","ocho años","cinco años","siete años"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">seis años</mark></span>El <span class=\"ref-norma\">art. 11.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"podrá alcanzar una duración máxima de diez años para los mayores de dieciséis años y de seis años para los menores de esa edad\"</span>. Diez años para mayores de dieciséis y seis para los menores de esa edad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1122","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Pluralidad de infracciones. La duración máxima de diez o seis años del internamiento en régimen cerrado por pluralidad de infracciones de especial gravedad se entiende sin perjuicio de:","o":["la facultad de modificación de la medida una vez transcurrido el primer año.","las medidas terapéuticas que corresponda imponer.","la inhabilitación absoluta que, de forma complementaria, corresponda imponer, previo informe de la unidad policial competente.","la medida de libertad vigilada que, de forma complementaria, corresponda imponer."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la medida de libertad vigilada que, de forma complementaria, corresponda imponer</mark></span>El <span class=\"ref-norma\">art. 11.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"sin perjuicio de la medida de libertad vigilada que, de forma complementaria, corresponda imponer\"</span>. Se entiende sin perjuicio de la libertad vigilada complementaria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1126","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modificación de la medida impuesta. El Juez competente para la ejecución, de oficio o a instancia del Ministerio Fiscal o del letrado del menor, previa audiencia de estos e informe del equipo técnico y, en su caso, de la entidad pública de protección o reforma de menores, podrá en cualquier momento:","o":["dejar sin efecto la medida impuesta o reducir su duración, pero no sustituirla, salvo que la autoridad judicial disponga otra cosa.","suspender la medida impuesta, reducir su duración o sustituirla por otra.","dejar sin efecto la medida impuesta o sustituirla, pero no reducir su duración.","dejar sin efecto la medida impuesta, reducir su duración o sustituirla por otra."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dejar sin efecto la medida impuesta, reducir su duración o sustituirla por otra</mark></span>El <span class=\"ref-norma\">art. 13.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"podrá en cualquier momento dejar sin efecto la medida impuesta, reducir su duración o sustituirla por otra\"</span>. Puede dejarla sin efecto, reducir su duración o sustituirla por otra. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1127","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modificación de la medida impuesta. El Juez podrá dejar sin efecto, reducir o sustituir la medida impuesta siempre que la modificación redunde en el interés del menor y se exprese suficientemente a este:","o":["el alcance de la medida sustituida.","la gravedad de los hechos cometidos.","el reproche merecido por su conducta.","el resultado del informe del equipo técnico."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el reproche merecido por su conducta</mark></span>El <span class=\"ref-norma\">art. 13.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"siempre que la modificación redunde en el interés del menor y se exprese suficientemente a este el reproche merecido por su conducta\"</span>. Debe expresarse suficientemente al menor el reproche merecido por su conducta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1129","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modificación de la medida impuesta. En los casos de modificación de la medida impuesta, el Juez resolverá por:","o":["auto motivado, contra el cual se podrán interponer los recursos previstos en la presente Ley.","sentencia motivada, contra la cual se podrán interponer los recursos previstos en la presente Ley.","providencia, contra la cual no cabrá recurso alguno.","auto motivado, contra el cual no cabrá recurso alguno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">auto motivado, contra el cual se podrán interponer los recursos previstos en la presente Ley</mark></span>El <span class=\"ref-norma\">art. 13.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"el Juez resolverá por auto motivado, contra el cual se podrán interponer los recursos previstos en la presente Ley\"</span>. Se resuelve por auto motivado, recurrible conforme a la propia Ley. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1136","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la prescripción. Los hechos delictivos cometidos por los menores prescriben a los cinco años, cuando se trate de:","o":["un delito grave sancionado en el Código Penal con pena igual o superior a diez años.","un delito grave sancionado en el Código Penal con pena superior a diez años.","cualquier delito grave.","un delito menos grave sancionado con pena superior a tres años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un delito grave sancionado en el Código Penal con pena superior a diez años</mark></span>El <span class=\"ref-norma\">art. 15.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"A los cinco años, cuando se trate de un delito grave sancionado en el Código Penal con pena superior a diez años\"</span>. A los cinco años prescriben los delitos graves con pena superior a diez años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1137","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la prescripción. Los hechos delictivos cometidos por los menores prescriben a los tres años, cuando se trate de:","o":["cualquier otro delito grave.","un delito grave sancionado con pena superior a cinco años.","cualquier delito menos grave.","cualquier delito grave o menos grave."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cualquier otro delito grave</mark></span>El <span class=\"ref-norma\">art. 15.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"A los tres años, cuando se trate de cualquier otro delito grave\"</span>. A los tres años, cualquier otro delito grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1139","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la prescripción. Los hechos delictivos cometidos por los menores prescriben con arreglo a las normas contenidas en el Código Penal cuando se trate de los delitos de homicidio, asesinato, determinados delitos sexuales o de terrorismo, o de cualquier otro sancionado en el Código Penal o en las leyes penales especiales con:","o":["pena de prisión superior a quince años.","pena de prisión igual o superior a diez años.","pena de prisión igual o superior a quince años.","pena de prisión igual o superior a veinte años, en los términos que se determinen reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">pena de prisión igual o superior a quince años</mark></span>El <span class=\"ref-norma\">art. 15.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"o cualquier otro sancionado en el Código Penal o en las leyes penales especiales con pena de prisión igual o superior a quince años\"</span>. Se rigen por el Código Penal los sancionados con prisión igual o superior a quince años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1140","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la prescripción. Señale la INCORRECTA sobre la prescripción de los hechos delictivos cometidos por los menores:","o":["A los tres años, cuando se trate de cualquier otro delito grave.","A los cinco años, cuando se trate de cualquier delito grave.","Al año, cuando se trate de un delito menos grave.","A los tres meses, cuando se trate de una falta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A los cinco años, cuando se trate de cualquier delito grave</mark></span>El <span class=\"ref-norma\">art. 15.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"A los cinco años, cuando se trate de un delito grave sancionado en el Código Penal con pena superior a diez años\"</span>. A los cinco años solo prescriben los delitos graves con pena superior a diez años; los demás graves, a los tres. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1141","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la prescripción. Las medidas que tengan una duración superior a los dos años prescribirán a los:","o":["tres años.","dos años.","cinco años.","cuatro años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">tres años</mark></span>El <span class=\"ref-norma\">art. 15.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Las medidas que tengan una duración superior a los dos años prescribirán a los tres años\"</span>. Las de duración superior a dos años prescriben a los tres años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1142","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la prescripción. Las restantes medidas prescribirán a los dos años, excepto la amonestación, las prestaciones en beneficio de la comunidad y la permanencia de fin de semana, que prescribirán:","o":["a los seis meses.","a los tres años.","a los tres meses.","al año."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al año</mark></span>El <span class=\"ref-norma\">art. 15.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Las restantes medidas prescribirán a los dos años, excepto la amonestación, las prestaciones en beneficio de la comunidad y la permanencia de fin de semana, que prescribirán al año\"</span>. Amonestación, prestaciones y permanencia de fin de semana prescriben al año. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1144","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modificación de la medida impuesta. El Juez competente para la ejecución podrá en cualquier momento dejar sin efecto, reducir o sustituir la medida impuesta, previa audiencia del Ministerio Fiscal y del letrado del menor e informe del __________ y, en su caso, de la entidad pública de protección o reforma de menores:","o":["Ministerio Fiscal","equipo técnico","letrado del menor","Juez de Menores"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">equipo técnico</mark></span>El <span class=\"ref-norma\">art. 13.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"previa audiencia de estos e informe del equipo técnico y, en su caso, de la entidad pública de protección o reforma de menores\"</span>. El informe previo es del equipo técnico y, en su caso, de la entidad pública. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1201","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Incoación del expediente. Quienes tuvieren noticia de algún hecho presuntamente cometido por un menor de dieciocho años deberán ponerlo en conocimiento del Ministerio Fiscal, el cual admitirá o no a trámite la denuncia, según que los hechos sean o no:","o":["indiciariamente constitutivos de delito.","constitutivos de delito grave.","constitutivos de delito o falta, con autor conocido.","indiciariamente constitutivos de infracción penal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">indiciariamente constitutivos de delito</mark></span>El <span class=\"ref-norma\">art. 16.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"admitirá o no a trámite la denuncia, según que los hechos sean o no indiciariamente constitutivos de delito\"</span>. La admisión a trámite depende de que los hechos sean indiciariamente constitutivos de delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1202","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Incoación del expediente. El Ministerio Fiscal, tras recibir la denuncia, podrá resolver el archivo de las actuaciones cuando los hechos:","o":["constituyan falta o no tengan autor conocido.","no constituyan delito y el menor sea inimputable.","no constituyan delito o el menor tenga menos de catorce años.","no constituyan delito o no tengan autor conocido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no constituyan delito o no tengan autor conocido</mark></span>El <span class=\"ref-norma\">art. 16.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"pudiendo resolver el archivo de las actuaciones cuando los hechos no constituyan delito o no tengan autor conocido\"</span>. El archivo procede si los hechos no constituyen delito o no tienen autor conocido. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1203","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Incoación del expediente. La resolución recaída sobre la denuncia presentada ante el Ministerio Fiscal deberá notificarse a:","o":["las partes personadas y al Juez de Menores.","quienes hubieran formulado la misma y al Juez de Menores.","quienes hubieran formulado la misma.","los representantes legales del menor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">quienes hubieran formulado la misma</mark></span>El <span class=\"ref-norma\">art. 16.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"La resolución recaída sobre la denuncia deberá notificarse a quienes hubieran formulado la misma\"</span>. Se notifica a quienes hubieran formulado la denuncia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1204","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Incoación del expediente. Una vez efectuadas las actuaciones sobre la denuncia, el Ministerio Fiscal dará cuenta de la incoación del expediente al Juez de Menores, quien:","o":["resolverá sobre las medidas cautelares.","iniciará las diligencias de trámite correspondientes.","dictará auto de incoación del procedimiento, en los términos que se determinen reglamentariamente.","convocará la audiencia del menor."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">iniciará las diligencias de trámite correspondientes</mark></span>El <span class=\"ref-norma\">art. 16.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"dará cuenta de la incoación del expediente al Juez de Menores, quien iniciará las diligencias de trámite correspondientes\"</span>. El Juez de Menores inicia las diligencias de trámite correspondientes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1205","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Incoación del expediente. El Juez de Menores ordenará al propio tiempo la apertura de la pieza separada de __________, que se tramitará conforme a las reglas de la propia Ley:","o":["responsabilidad civil","medidas cautelares","secreto del expediente","ejecución de medidas"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">responsabilidad civil</mark></span>El <span class=\"ref-norma\">art. 16.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"El Juez de Menores ordenará al propio tiempo la apertura de la pieza separada de responsabilidad civil\"</span>. Se abre al propio tiempo la pieza separada de responsabilidad civil. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1206","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Incoación del expediente. Cuando los hechos hubiesen sido cometidos conjuntamente por mayores de edad penal y por menores, el Juez de Instrucción competente, tan pronto como compruebe la edad de los imputados, adoptará las medidas necesarias para asegurar el éxito de la actividad investigadora respecto de los mayores de edad y ordenará:","o":["remitir la causa íntegra al Juez de Menores.","inhibirse a favor del Juzgado de Menores.","remitir testimonio de los particulares precisos al Juez de Menores, salvo que la autoridad judicial disponga otra cosa.","remitir testimonio de los particulares precisos al Ministerio Fiscal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">remitir testimonio de los particulares precisos al Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 16.5 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"ordenará remitir testimonio de los particulares precisos al Ministerio Fiscal\"</span>. El testimonio de los particulares precisos se remite al Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1225","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Sobreseimiento del expediente por conciliación o reparación entre el menor y la víctima. El Ministerio Fiscal podrá desistir de la continuación del expediente, atendiendo a la gravedad y circunstancias de los hechos y del menor, de modo particular a la falta de violencia o intimidación graves, y a la circunstancia de que además el menor se haya conciliado con la víctima o:","o":["haya asumido el compromiso de reparar el daño causado a la víctima o al perjudicado por el delito, o se haya comprometido a cumplir la actividad educativa propuesta por el equipo técnico en su informe.","haya reparado efectivamente el daño y abonado la indemnización fijada por el Juez.","haya asumido el compromiso de reparar el daño causado, previa aprobación del Juez de Menores, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","se haya comprometido a cumplir la actividad educativa propuesta por el Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">haya asumido el compromiso de reparar el daño causado a la víctima o al perjudicado por el delito, o se haya comprometido a cumplir la actividad educativa propuesta por el equipo técnico en su informe</mark></span>El <span class=\"ref-norma\">art. 19.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"se haya conciliado con la víctima o haya asumido el compromiso de reparar el daño causado a la víctima o al perjudicado por el delito, o se haya comprometido a cumplir la actividad educativa propuesta por el equipo técnico en su informe\"</span>. Basta conciliación, compromiso de reparación o compromiso de cumplir la actividad educativa del equipo técnico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1226","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Sobreseimiento del expediente por conciliación o reparación entre el menor y la víctima. El desistimiento en la continuación del expediente por conciliación o reparación sólo será posible cuando el hecho imputado al menor constituya:","o":["delito leve o falta.","cualquier delito sin violencia.","delito menos grave, con exclusión de las faltas.","delito menos grave o falta."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">delito menos grave o falta</mark></span>El <span class=\"ref-norma\">art. 19.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"El desistimiento en la continuación del expediente sólo será posible cuando el hecho imputado al menor constituya delito menos grave o falta\"</span>. Solo cabe en delito menos grave o falta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1227","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Sobreseimiento del expediente por conciliación o reparación entre el menor y la víctima. Se entenderá producida la conciliación cuando el menor reconozca el daño causado y se disculpe ante la víctima, y ésta:","o":["renuncie a la acción civil.","lo perdone expresamente por escrito.","acepte sus disculpas.","se reserve las acciones civiles."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">acepte sus disculpas</mark></span>El <span class=\"ref-norma\">art. 19.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"se entenderá producida la conciliación cuando el menor reconozca el daño causado y se disculpe ante la víctima, y ésta acepte sus disculpas\"</span>. La conciliación exige que la víctima acepte las disculpas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1228","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Sobreseimiento del expediente por conciliación o reparación entre el menor y la víctima. Se entenderá por reparación el compromiso asumido por el menor con la víctima o perjudicado de realizar determinadas acciones en beneficio de aquellos o de la comunidad, seguido de:","o":["la aprobación del Juez de Menores.","su realización efectiva.","su ratificación por el Ministerio Fiscal.","la valoración del equipo técnico."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">su realización efectiva</mark></span>El <span class=\"ref-norma\">art. 19.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"de realizar determinadas acciones en beneficio de aquellos o de la comunidad, seguido de su realización efectiva\"</span>. La reparación exige que el compromiso se realice efectivamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1229","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Sobreseimiento del expediente por conciliación o reparación entre el menor y la víctima. Cuando la medida sea consecuencia de alguno de los delitos de los Capítulos I y II del Título VIII del Código Penal, o estén relacionados con la violencia de género, no tendrá efecto de conciliación, a menos que la víctima lo solicite expresamente y que el menor, además, haya realizado:","o":["la medida accesoria de educación sexual y de educación para la igualdad.","la medida de libertad vigilada.","la reparación íntegra del daño.","las prestaciones en beneficio de la comunidad, salvo que la autoridad judicial disponga otra cosa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la medida accesoria de educación sexual y de educación para la igualdad</mark></span>El <span class=\"ref-norma\">art. 19.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"a menos que la víctima lo solicite expresamente y que el menor, además, haya realizado la medida accesoria de educación sexual y de educación para la igualdad\"</span>. La conciliación solo surte efecto si la víctima lo solicita y el menor realizó la medida accesoria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1230","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Sobreseimiento del expediente por conciliación o reparación entre el menor y la víctima. El equipo técnico realizará las funciones de mediación entre el menor y la víctima o perjudicado e informará al Ministerio Fiscal de:","o":["los compromisos adquiridos, pero no de su grado de cumplimiento.","su resultado, que remitirá directamente al Juez de Menores.","las medidas que deban imponerse.","los compromisos adquiridos y de su grado de cumplimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los compromisos adquiridos y de su grado de cumplimiento</mark></span>El <span class=\"ref-norma\">art. 19.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"e informará al Ministerio Fiscal de los compromisos adquiridos y de su grado de cumplimiento\"</span>. Informa de los compromisos adquiridos y de su grado de cumplimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1231","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Sobreseimiento del expediente por conciliación o reparación entre el menor y la víctima. Producida la conciliación o cumplidos los compromisos de reparación, el Ministerio Fiscal dará por concluida la instrucción y solicitará del Juez:","o":["el archivo provisional de las actuaciones.","la imposición de la medida de amonestación, previo informe de la unidad policial competente.","el sobreseimiento y archivo de las actuaciones, con remisión de lo actuado.","la aprobación del acuerdo alcanzado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el sobreseimiento y archivo de las actuaciones, con remisión de lo actuado</mark></span>El <span class=\"ref-norma\">art. 19.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"dará por concluida la instrucción y solicitará del Juez el sobreseimiento y archivo de las actuaciones, con remisión de lo actuado\"</span>. Solicita el sobreseimiento y archivo, con remisión de lo actuado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1232","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Sobreseimiento del expediente por conciliación o reparación entre el menor y la víctima. En el caso de que el menor no cumpliera la reparación o la actividad educativa acordada, el Ministerio Fiscal:","o":["solicitará una medida cautelar.","continuará la tramitación del expediente.","archivará definitivamente las actuaciones.","remitirá lo actuado a la entidad pública de protección."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">continuará la tramitación del expediente</mark></span>El <span class=\"ref-norma\">art. 19.5 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"En el caso de que el menor no cumpliera la reparación o la actividad educativa acordada, el Ministerio Fiscal continuará la tramitación del expediente\"</span>. Si no cumple, el Fiscal continúa la tramitación del expediente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1233","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Sobreseimiento del expediente por conciliación o reparación entre el menor y la víctima. Cuando la víctima del delito o falta fuere menor de edad o incapaz, el compromiso de conciliación o reparación habrá de ser asumido por el representante legal de la misma, con la aprobación del:","o":["Juez de Menores.","Ministerio Fiscal.","equipo técnico.","Letrado de la Administración de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Juez de Menores</mark></span>El <span class=\"ref-norma\">art. 19.6 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"habrá de ser asumido por el representante legal de la misma, con la aprobación del Juez de Menores\"</span>. El representante legal lo asume con la aprobación del Juez de Menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1235","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Unidad de expediente. Cuando los delitos atribuidos al menor expedientado hubieran sido cometidos en diferentes territorios, el órgano judicial competente para el enjuiciamiento de todos ellos en unidad de expediente se determinará teniendo en cuenta el lugar del domicilio del menor y, subsidiariamente:","o":["el lugar de comisión del delito más grave.","el lugar donde se cometió el primer delito, sin perjuicio de lo previsto en la normativa vigente.","los criterios expresados en la Ley de Enjuiciamiento Criminal.","el lugar de residencia de la víctima."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los criterios expresados en la Ley de Enjuiciamiento Criminal</mark></span>El <span class=\"ref-norma\">art. 20.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"se hará teniendo en cuenta el lugar del domicilio del menor y, subsidiariamente, los criterios expresados en el artículo 18 de la Ley de Enjuiciamiento Criminal\"</span>. Primero el domicilio del menor y, subsidiariamente, los criterios de la LECrim. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1236","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Unidad de expediente. La determinación del órgano judicial competente para el enjuiciamiento en unidad de expediente de delitos cometidos en diferentes territorios, así como de las entidades públicas competentes para:","o":["la protección de la víctima, se hará teniendo en cuenta el lugar de comisión del delito.","la ejecución de las medidas que se apliquen, se hará teniendo en cuenta el lugar del domicilio del menor.","la instrucción del expediente, se hará teniendo en cuenta el lugar del domicilio del menor.","el seguimiento de las medidas cautelares, se hará teniendo en cuenta el lugar de los hechos, en los términos que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la ejecución de las medidas que se apliquen, se hará teniendo en cuenta el lugar del domicilio del menor</mark></span>El <span class=\"ref-norma\">art. 20.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"así como de las entidades públicas competentes para la ejecución de las medidas que se apliquen, se hará teniendo en cuenta el lugar del domicilio del menor\"</span>. También las entidades públicas competentes para la ejecución de las medidas se determinan por el domicilio del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1237","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Remisión al órgano competente. Cuando el conocimiento de los hechos no corresponda a la competencia de los Juzgados de Menores, el Fiscal acordará:","o":["la remisión de lo actuado al órgano legalmente competente.","el archivo de lo actuado.","la inhibición a favor del Juez de Instrucción, previa audiencia del menor.","la remisión de lo actuado a la Audiencia Nacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la remisión de lo actuado al órgano legalmente competente</mark></span>El <span class=\"ref-norma\">art. 21 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"el Fiscal acordará la remisión de lo actuado al órgano legalmente competente\"</span>. Se remite lo actuado al órgano legalmente competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1302","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Secreto del expediente. El secreto del expediente podrá decretarse en su totalidad o parcialmente, durante toda la instrucción o durante:","o":["un máximo de seis meses, en los términos que se determinen reglamentariamente.","la fase de alegaciones.","un plazo de diez días.","un período limitado de ésta."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un período limitado de ésta</mark></span>El <span class=\"ref-norma\">art. 24 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"en su totalidad o parcialmente, durante toda la instrucción o durante un período limitado de ésta\"</span>. Puede ser total o parcial, durante toda la instrucción o un período limitado de ésta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1303","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Secreto del expediente. Aunque se haya decretado el secreto, el letrado del menor y quien ejercite la acción penal deberán, en todo caso, conocer en su integridad el expediente al evacuar:","o":["la audiencia.","el trámite de instrucción.","el trámite de alegaciones.","el informe del equipo técnico."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el trámite de alegaciones</mark></span>El <span class=\"ref-norma\">art. 24 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"deberán, en todo caso, conocer en su integridad el expediente al evacuar el trámite de alegaciones\"</span>. El secreto cede al evacuar el trámite de alegaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1304","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Secreto del expediente. El incidente de secreto del expediente se tramitará por el Juzgado en:","o":["el expediente principal.","pieza separada.","el expediente personal del menor.","diligencias reservadas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">pieza separada</mark></span>El <span class=\"ref-norma\">art. 24 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Este incidente se tramitará por el Juzgado en pieza separada\"</span>. Se tramita en pieza separada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1322","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Medidas cautelares. Reglas generales. El Ministerio Fiscal, de oficio o a instancia de quien haya ejercitado la acción penal, podrá solicitar medidas cautelares cuando existan indicios racionales de la comisión de un delito y el riesgo de:","o":["eludir la acción de la justicia, con exclusión de atentar contra los bienes jurídicos de la víctima, salvo que la autoridad judicial disponga otra cosa.","reiteración delictiva o de eludir la acción de la justicia.","destruir pruebas o de atentar contra la víctima.","eludir u obstruir la acción de la justicia por parte del menor o de atentar contra los bienes jurídicos de la víctima."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">eludir u obstruir la acción de la justicia por parte del menor o de atentar contra los bienes jurídicos de la víctima</mark></span>El <span class=\"ref-norma\">art. 28.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"cuando existan indicios racionales de la comisión de un delito y el riesgo de eludir u obstruir la acción de la justicia por parte del menor o de atentar contra los bienes jurídicos de la víctima\"</span>. Se exige indicio racional de delito y riesgo de eludir u obstruir la justicia o atentar contra los bienes jurídicos de la víctima. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1323","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Medidas cautelares. Reglas generales. El Ministerio Fiscal podrá solicitar del Juez de Menores, en cualquier momento, la adopción de medidas cautelares para la custodia y defensa del menor expedientado o para:","o":["la debida reparación a la víctima.","el aseguramiento de la responsabilidad civil.","la debida protección de la víctima.","la tranquilidad de la víctima y su familia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la debida protección de la víctima</mark></span>El <span class=\"ref-norma\">art. 28.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"para la custodia y defensa del menor expedientado o para la debida protección de la víctima\"</span>. Las medidas cautelares sirven a la custodia y defensa del menor o a la debida protección de la víctima. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1325","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Medidas cautelares. Reglas generales. La medida cautelar adoptada podrá mantenerse hasta que:","o":["recaiga sentencia firme.","se inicie la audiencia.","se dicte sentencia.","concluya la instrucción, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">recaiga sentencia firme</mark></span>El <span class=\"ref-norma\">art. 28.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"La medida cautelar adoptada podrá mantenerse hasta que recaiga sentencia firme\"</span>. Se puede mantener hasta que recaiga sentencia firme. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1326","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Medidas cautelares. Reglas generales. Para la adopción de la medida cautelar de internamiento se atenderá a la gravedad de los hechos, valorando también las circunstancias personales y sociales del menor, la existencia de un peligro cierto de fuga, y, especialmente:","o":["el que el menor hubiera sido detenido con anterioridad, sin perjuicio de lo previsto en la normativa vigente.","el que el menor tenga entre dieciséis y dieciocho años.","la alarma social provocada.","el que el menor hubiera cometido o no con anterioridad otros hechos graves de la misma naturaleza."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el que el menor hubiera cometido o no con anterioridad otros hechos graves de la misma naturaleza</mark></span>El <span class=\"ref-norma\">art. 28.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"y, especialmente, el que el menor hubiera cometido o no con anterioridad otros hechos graves de la misma naturaleza\"</span>. Se atiende especialmente a si cometió con anterioridad otros hechos graves de la misma naturaleza. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1327","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Medidas cautelares. Reglas generales. El Juez de Menores resolverá sobre el internamiento cautelar, a instancia del Ministerio Fiscal o de la acusación particular, en una comparecencia a la que asistirán también el letrado del menor, las demás partes personadas, el representante del equipo técnico y el de:","o":["la Fiscalía de Menores, en los términos que se determinen reglamentariamente.","los servicios sociales.","la entidad pública de protección o reforma de menores.","las víctimas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la entidad pública de protección o reforma de menores</mark></span>El <span class=\"ref-norma\">art. 28.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"el representante del equipo técnico y el de la entidad pública de protección o reforma de menores\"</span>. Asisten también el representante del equipo técnico y el de la entidad pública de protección o reforma. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1329","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Medidas cautelares. Reglas generales. Las medidas cautelares se documentarán en el Juzgado de Menores en:","o":["pieza separada del expediente.","el expediente principal.","el expediente personal del menor.","un libro registro de medidas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">pieza separada del expediente</mark></span>El <span class=\"ref-norma\">art. 28.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Las medidas cautelares se documentarán en el Juzgado de Menores en pieza separada del expediente\"</span>. Se documentan en pieza separada del expediente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1330","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Medidas cautelares. Reglas generales. El tiempo de cumplimiento de las medidas cautelares se abonará en su integridad para el cumplimiento de las medidas que se puedan imponer en la misma causa o, en su defecto:","o":["en otras causas, sin limitación alguna.","en otras causas por hechos posteriores a la adopción de aquéllas, salvo que la autoridad judicial disponga otra cosa.","únicamente en la misma causa.","en otras causas que hayan tenido por objeto hechos anteriores a la adopción de aquéllas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en otras causas que hayan tenido por objeto hechos anteriores a la adopción de aquéllas</mark></span>El <span class=\"ref-norma\">art. 28.5 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"o, en su defecto, en otras causas que hayan tenido por objeto hechos anteriores a la adopción de aquéllas\"</span>. Subsidiariamente se abona en otras causas por hechos anteriores a la adopción de la cautelar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1331","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Medidas cautelares. Reglas generales. El Juez, a propuesta del Ministerio Fiscal y oídos el letrado del menor y el equipo técnico que informó la medida cautelar, ordenará que se tenga por ejecutada la medida impuesta en aquella parte que estime:","o":["totalmente compensada por la medida cautelar, previo informe de la unidad policial competente.","proporcional a la gravedad de los hechos.","razonablemente compensada por la medida cautelar.","necesaria para el interés del menor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">razonablemente compensada por la medida cautelar</mark></span>El <span class=\"ref-norma\">art. 28.5 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"ordenará que se tenga por ejecutada la medida impuesta en aquella parte que estime razonablemente compensada por la medida cautelar\"</span>. Se tiene por ejecutada la parte que se estime razonablemente compensada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1332","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Medidas cautelares en los casos de exención de la responsabilidad. Si en el transcurso de la instrucción quedara suficientemente acreditado que el menor se encuentra en situación de enajenación mental o en cualquiera otra de las circunstancias eximentes del Código Penal, se adoptarán las medidas cautelares precisas para la protección y custodia del menor conforme a:","o":["los preceptos penales aplicables.","los preceptos civiles aplicables.","la legislación de protección de menores.","la Ley Orgánica General Penitenciaria."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los preceptos civiles aplicables</mark></span>El <span class=\"ref-norma\">art. 29 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"se adoptarán las medidas cautelares precisas para la protección y custodia del menor conforme a los preceptos civiles aplicables\"</span>. La protección y custodia es conforme a los preceptos civiles aplicables. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1333","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Medidas cautelares en los casos de exención de la responsabilidad. En los casos de exención de la responsabilidad se instarán las actuaciones para la incapacitación del menor y la constitución de los organismos tutelares conforme a derecho, sin perjuicio de concluir la instrucción y de solicitar, en su caso, alguna medida:","o":["terapéutica adecuada al interés del menor de entre las previstas en esta Ley.","educativa adecuada al interés del menor de entre las previstas en esta Ley, sin perjuicio de lo previsto en la normativa vigente.","de seguridad adecuada a las circunstancias del menor.","de protección acordada por la entidad pública de protección de menores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">terapéutica adecuada al interés del menor de entre las previstas en esta Ley</mark></span>El <span class=\"ref-norma\">art. 29 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"y de solicitar, por los trámites de la misma, en su caso, alguna medida terapéutica adecuada al interés del menor de entre las previstas en esta Ley\"</span>. La medida solicitada es terapéutica y adecuada al interés del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1334","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Remisión del expediente al Juez de Menores. Acabada la instrucción, el Ministerio Fiscal resolverá la conclusión del expediente, notificándosela a las partes personadas, y remitirá al Juzgado de Menores el expediente, junto con:","o":["el informe del equipo técnico, sin escrito de alegaciones.","testimonio de lo actuado y las piezas de convicción.","el informe de la entidad pública y un escrito de acusación, en los términos que se determinen reglamentariamente.","las piezas de convicción y demás efectos que pudieran existir, con un escrito de alegaciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las piezas de convicción y demás efectos que pudieran existir, con un escrito de alegaciones</mark></span>El <span class=\"ref-norma\">art. 30.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"remitirá al Juzgado de Menores el expediente, junto con las piezas de convicción y demás efectos que pudieran existir, con un escrito de alegaciones\"</span>. Se remite el expediente con las piezas de convicción y demás efectos, con un escrito de alegaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1335","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Remisión del expediente al Juez de Menores. Señale la INCORRECTA sobre el contenido del escrito de alegaciones del Ministerio Fiscal:","o":["La descripción de los hechos.","La valoración jurídica de los mismos, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","La calificación de los hechos como delito y la pena que correspondería a un mayor de edad.","El grado de participación del menor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La calificación de los hechos como delito y la pena que correspondería a un mayor de edad</mark></span>El <span class=\"ref-norma\">art. 30.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"con un escrito de alegaciones en el que constará la descripción de los hechos, la valoración jurídica de los mismos, el grado de participación del menor, una breve reseña de las circunstancias personales y sociales de éste, la proposición de alguna medida\"</span>. El escrito contiene descripción, valoración jurídica, grado de participación, reseña personal y social y proposición de medida; no la pena de un mayor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1336","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Remisión del expediente al Juez de Menores. En el escrito de alegaciones constará la proposición de alguna medida de las previstas en esta Ley con exposición razonada de los fundamentos jurídicos y educativos que la aconsejen, y, en su caso:","o":["la solicitud de medidas cautelares, sin perjuicio de lo previsto en la normativa vigente.","la exigencia de responsabilidad civil.","la petición de ejecución inmediata.","la propuesta de prueba pericial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la exigencia de responsabilidad civil</mark></span>El <span class=\"ref-norma\">art. 30.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"con exposición razonada de los fundamentos jurídicos y educativos que la aconsejen, y, en su caso, la exigencia de responsabilidad civil\"</span>. Se añade, en su caso, la exigencia de responsabilidad civil. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1337","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Remisión del expediente al Juez de Menores. En el mismo acto de remisión del expediente propondrá el Ministerio Fiscal:","o":["la prueba de que intente valerse para la defensa de su pretensión procesal.","la prueba pericial del equipo técnico.","la audiencia de las personas perjudicadas, en los términos que se determinen reglamentariamente.","las medidas cautelares que procedan."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la prueba de que intente valerse para la defensa de su pretensión procesal</mark></span>El <span class=\"ref-norma\">art. 30.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"En el mismo acto propondrá el Ministerio Fiscal la prueba de que intente valerse para la defensa de su pretensión procesal\"</span>. Propone la prueba de que intente valerse. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1338","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Remisión del expediente al Juez de Menores. Serán llamadas, en todo caso, al acto de la audiencia:","o":["las personas o instituciones propuestas por el Ministerio Fiscal, salvo que la autoridad judicial disponga otra cosa.","los representantes de instituciones públicas y privadas.","los equipos técnicos y las entidades públicas de protección.","las personas o instituciones perjudicadas civilmente por el delito, así como los responsables civiles."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las personas o instituciones perjudicadas civilmente por el delito, así como los responsables civiles</mark></span>El <span class=\"ref-norma\">art. 30.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"En todo caso serán llamadas al acto de audiencia las personas o instituciones perjudicadas civilmente por el delito, así como los responsables civiles\"</span>. Siempre se llama a los perjudicados civilmente y a los responsables civiles. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1339","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Remisión del expediente al Juez de Menores. El Ministerio Fiscal podrá también solicitar del Juez de Menores el sobreseimiento de las actuaciones por alguno de los motivos previstos en la Ley de Enjuiciamiento Criminal, así como la remisión de los particulares necesarios a:","o":["la entidad pública de reforma de menores, previo informe de la unidad policial competente.","la Sección de Menores de la Fiscalía.","la entidad pública de protección de menores, en su caso.","el equipo técnico."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la entidad pública de protección de menores, en su caso</mark></span>El <span class=\"ref-norma\">art. 30.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"así como la remisión de los particulares necesarios a la entidad pública de protección de menores en su caso\"</span>. Los particulares se remiten, en su caso, a la entidad pública de protección de menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1340","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la responsabilidad civil. La acción para exigir la responsabilidad civil se ejercitará por el Ministerio Fiscal, salvo que el perjudicado la ejercite por sí mismo en el plazo de un mes desde que se le notifique:","o":["la incoación del expediente.","la apertura de la pieza separada de responsabilidad civil.","la sentencia firme.","la admisión de su personación, sin perjuicio de lo previsto en la normativa vigente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la apertura de la pieza separada de responsabilidad civil</mark></span>El <span class=\"ref-norma\">art. 61.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"la ejercite por sí mismo en el plazo de un mes desde que se le notifique la apertura de la pieza separada de responsabilidad civil\"</span>. El mes cuenta desde la notificación de la apertura de la pieza separada de responsabilidad civil. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1341","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la responsabilidad civil. Se tramitará una pieza separada de responsabilidad civil por:","o":["cada uno de los hechos imputados.","cada menor imputado, en los términos que se determinen reglamentariamente.","cada perjudicado.","cada expediente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cada uno de los hechos imputados</mark></span>El <span class=\"ref-norma\">art. 61.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Se tramitará una pieza separada de responsabilidad civil por cada uno de los hechos imputados\"</span>. Una pieza separada por cada hecho imputado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1342","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la responsabilidad civil. Cuando los padres, tutores, acogedores y guardadores legales o de hecho no hubieren favorecido la conducta del menor con dolo o negligencia grave, su responsabilidad solidaria con el menor de dieciocho años podrá ser:","o":["excluida por el Juez.","convertida en subsidiaria.","sustituida por la responsabilidad del menor.","moderada por el Juez según los casos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">moderada por el Juez según los casos</mark></span>El <span class=\"ref-norma\">art. 61.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Cuando éstos no hubieren favorecido la conducta del menor con dolo o negligencia grave, su responsabilidad podrá ser moderada por el Juez según los casos\"</span>. No hay exclusión: la responsabilidad podrá ser moderada por el Juez. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1343","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la responsabilidad civil. La responsabilidad civil se regulará, en cuanto a su extensión, por lo dispuesto en el capítulo I del Título V del Libro I del __________ vigente:","o":["Código Civil","Ley de Enjuiciamiento Civil","Código Penal","Ley de Enjuiciamiento Criminal"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Código Penal</mark></span>El <span class=\"ref-norma\">art. 62 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"se regulará, en cuanto a su extensión, por lo dispuesto en el capítulo I del Título V del Libro I del Código Penal vigente\"</span>. La extensión se regula por el Código Penal vigente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1345","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la responsabilidad civil. Tan pronto como el Juez de Menores reciba el parte de la incoación del expediente, ordenará abrir de forma simultánea con el proceso principal una pieza separada de responsabilidad civil, notificando el secretario judicial a quienes aparezcan como perjudicados su derecho a ser parte en la misma, y estableciendo:","o":["el plazo límite para el ejercicio de la acción.","el plazo de un mes para el ejercicio de la acción.","las medidas cautelares reales.","la cuantía de la fianza."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el plazo límite para el ejercicio de la acción</mark></span>El <span class=\"ref-norma\">art. 64.1ª de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"y estableciendo el plazo límite para el ejercicio de la acción\"</span>. Se establece el plazo límite para el ejercicio de la acción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1346","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la responsabilidad civil. En la pieza de responsabilidad civil podrán personarse los perjudicados que hayan recibido notificación al efecto del Juez de Menores o del Ministerio Fiscal, y también:","o":["únicamente los propuestos por el Fiscal.","los perjudicados, previa autorización del Juez, salvo que la autoridad judicial disponga otra cosa.","los aseguradores, sin sujeción a plazo.","espontáneamente quienes se consideren como tales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">espontáneamente quienes se consideren como tales</mark></span>El <span class=\"ref-norma\">art. 64.2ª de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"y también espontáneamente quienes se consideren como tales\"</span>. También pueden personarse espontáneamente quienes se consideren perjudicados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1347","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la responsabilidad civil. En el escrito de personación en la pieza de responsabilidad civil se indicarán las personas que se consideren responsables de los hechos cometidos y contra las cuales se pretenda reclamar, bastando con:","o":["la indicación de su domicilio.","la indicación nominal y su NIF, previo informe de la unidad policial competente.","la indicación genérica de su identidad.","el testimonio de la incoación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la indicación genérica de su identidad</mark></span>El <span class=\"ref-norma\">art. 64.2ª de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"bastando con la indicación genérica de su identidad\"</span>. Basta la indicación genérica de la identidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1348","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la responsabilidad civil. El secretario judicial notificará al menor y a sus representantes legales, en su caso, su condición de:","o":["partes en el proceso principal.","posibles responsables civiles.","responsables civiles directos.","responsables civiles subsidiarios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">posibles responsables civiles</mark></span>El <span class=\"ref-norma\">art. 64.3ª de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"notificará al menor y a sus representantes legales, en su caso, su condición de posibles responsables civiles\"</span>. Se les notifica su condición de posibles responsables civiles. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1349","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la responsabilidad civil. La intervención en el proceso a los efectos de exigencia de responsabilidad civil se realizará en las condiciones que el Juez de Menores señale con el fin de preservar:","o":["la intimidad del menor.","el honor de la víctima.","la presunción de inocencia del menor.","el secreto de la instrucción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la intimidad del menor</mark></span>El <span class=\"ref-norma\">art. 64.5ª de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"con el fin de preservar la intimidad del menor\"</span>. La finalidad es preservar la intimidad del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 23 — Actuación instructora del Ministerio Fiscal EX R6","q":[{"i":"17-13","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. En lo referente a la actuación instructora del Ministerio Fiscal: Señale la incorrecta.","o":["El Ministerio Fiscal no podrá practicar por sí mismo diligencias restrictivas de derechos fundamentales, sino que habrá de solicitar del Juzgado la práctica de las que sean precisas para el buen fin de las investigaciones.","La práctica de tales diligencias se documentará en pieza conjunta.","El Ministerio Fiscal deberá dar vista del expediente al letrado del menor y, en su caso, a quien haya ejercitado la acusación penal, en un plazo no superior a veinticuatro horas, tantas veces como aquel lo solicite.","El Juez de Menores resolverá sobre esta petición (diligencia restrictiva de derechos fundamentales) por auto motivado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La práctica de tales diligencias se documentará en pieza conjunta</mark></span>La pieza es «separada», no «conjunta»; la opción C es el texto literal del art. 23.2. Según el <span class=\"ref-norma\">art. 23.3 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"La práctica de tales diligencias se documentará en pieza separada\"</span> (verificado con el temario oficial)."},{"i":"17-240","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación instructora del Ministerio Fiscal. El Ministerio Fiscal, de oficio o a petición de cualquiera de las partes personadas, instará al Juzgado de menores la práctica de la declaración de la víctima o de cualquier otro testigo, con las garantías de la prueba preconstituida, asegurando en todo caso el principio de contradicción cuando concurra alguno de los supuestos siguientes. Señale la INCORRECTA:","o":["Cuando exista riesgo de imposibilidad de concurrir al juicio oral.","Cuando se trate de una persona especialmente vulnerable.","Tendrá esa consideración toda persona menor de catorce años o persona con discapacidad necesitada de especial protección.","Cuando la víctima sea mayor de edad y no desee declarar en el juicio oral."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando la víctima sea mayor de edad y no desee declarar en el juicio oral</mark></span>El <span class=\"ref-norma\">art. 23.4 de la LO 5/2000</span> dispone: <span class=\"ref-concepto\">\"Cuando exista riesgo de imposibilidad de concurrir al juicio oral. b) Cuando se trate de una persona especialmente vulnerable\"</span> Los supuestos son el riesgo de imposibilidad de concurrir al juicio oral y la persona especialmente vulnerable; no la voluntad de no declarar."},{"i":"17-257","p":"(LO 5/2000 - Responsabilidad Penal del Menor) Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. El Ministerio Fiscal deberá dar vista del expediente al letrado del menor y, en su caso, a quien haya ejercitado la acusación penal, en un plazo no superior a veinticuatro horas:","o":["Solo al inicio de la diligencia de que se trate.","Solo tras la finalización de la diligencia de que se trate.","Tanto al inicio como a la finalización de cada diligencia.","Tantas veces como aquel lo solicite."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Tanto al inicio como a la finalización de cada diligencia.</mark></span><span class=\"ref-norma\">Art. 17.2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. El Art. 17.2 de la LORPM establece que se deberá dar vista del expediente en un plazo no superior a veinticuatro horas, &quot;tanto antes como después de cada diligencia de investigación que se practique&quot;."},{"i":"17-266","p":"(LO 5/2000 - LORPM) Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. El Ministerio Fiscal deberá dar vista del expediente al letrado del menor y, en su caso, a quien haya ejercitado la acusación penal, en un plazo no superior a veinticuatro horas:","o":["Solo al inicio de la diligencia de que se trate.","Solo tras la finalización de la diligencia de que se trate.","Tanto al inicio como a la finalización de cada diligencia.","Tantas veces como aquel lo solicite."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Tanto al inicio como a la finalización de cada diligencia.</mark></span><span class=\"ref-norma\">Art. 23.2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. El artículo 23.2 de la LO 5/2000, LORPM, dispone que «el Ministerio Fiscal deberá dar vista del expediente al letrado del menor y, en su caso, a quien haya ejercitado la acción penal, en un plazo no superior a veinticuatro horas, tantas veces como aquel lo solicite». La redacción de la pregunta contiene una errata en las opciones respecto al texto legal (que habla de «tantas veces como se solicite» y no de inicio y finalización de diligencias), pero conforme al banco de preguntas la respuesta marcada como correcta es la C."},{"i":"17-ia-1245","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación instructora del Ministerio Fiscal. La actuación instructora del Ministerio Fiscal tendrá como objeto, tanto valorar la participación del menor en los hechos para expresarle el reproche que merece su conducta, como proponer las concretas medidas de contenido educativo y sancionador adecuadas a las circunstancias del hecho y de su autor y, sobre todo, al:","o":["interés del propio menor valorado en la causa.","principio de proporcionalidad.","grado de participación del menor.","interés de la víctima valorado en la causa, sin perjuicio de lo previsto en la normativa vigente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">interés del propio menor valorado en la causa</mark></span>El <span class=\"ref-norma\">art. 23.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"y, sobre todo, al interés del propio menor valorado en la causa\"</span>. Sobre todo debe atenderse al interés del propio menor valorado en la causa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1247","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación instructora del Ministerio Fiscal. El Ministerio Fiscal, de oficio o a petición de cualquiera de las partes personadas, instará al Juzgado de menores la práctica de la declaración de la víctima o de cualquier otro testigo, con las garantías de la prueba preconstituida, asegurando en todo caso el principio de:","o":["inmediación, salvo que la autoridad judicial disponga otra cosa.","publicidad.","contradicción.","oralidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">contradicción</mark></span>El <span class=\"ref-norma\">art. 23.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"asegurando en todo caso el principio de contradicción\"</span>. Debe asegurarse en todo caso el principio de contradicción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1248","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación instructora del Ministerio Fiscal. A efectos de la prueba preconstituida, se considerará persona especialmente vulnerable, en todo caso, a toda persona menor de:","o":["dieciséis años o persona con discapacidad necesitada de especial protección.","catorce años o persona con discapacidad necesitada de especial protección.","dieciocho años o persona con discapacidad necesitada de especial protección.","catorce años o persona con cualquier discapacidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">catorce años o persona con discapacidad necesitada de especial protección</mark></span>El <span class=\"ref-norma\">art. 23.4.b de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"tendrá esa consideración toda persona menor de catorce años o persona con discapacidad necesitada de especial protección\"</span>. Es especialmente vulnerable toda persona menor de catorce años o con discapacidad necesitada de especial protección. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1249","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación instructora del Ministerio Fiscal. Señale la INCORRECTA sobre los supuestos en que el Ministerio Fiscal instará la declaración con las garantías de la prueba preconstituida:","o":["Cuando la víctima sea mayor de edad y no desee declarar en el juicio oral.","Cuando exista riesgo de imposibilidad de concurrir al juicio oral.","Cuando se trate de una persona especialmente vulnerable.","Cuando se trate de una persona menor de catorce años, que tendrá siempre la consideración de especialmente vulnerable."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuando la víctima sea mayor de edad y no desee declarar en el juicio oral</mark></span>El <span class=\"ref-norma\">art. 23.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Cuando exista riesgo de imposibilidad de concurrir al juicio oral. b) Cuando se trate de una persona especialmente vulnerable\"</span>. Los supuestos son el riesgo de imposibilidad de concurrir al juicio oral y la persona especialmente vulnerable; no basta la voluntad de no declarar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 14 — Mayoría de edad del condenado EX","q":[{"i":"17-14","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. De las medidas. Cuando se trate de la medida de internamiento en régimen cerrado y el menor alcance la edad de dieciocho años sin haber finalizado su cumplimiento, el Juez de Menores:","o":["Podrá ordenar un auto en que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria.","Deberá ordenar en auto motivado que el cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria si la conducta de la persona internada no responde a los objetivos propuestos en la sentencia.","Podrá ordenar en auto motivado que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria si la conducta de la persona internada no responde a los objetivos propuestos en la sentencia.","Deberá ordenar en auto que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Podrá ordenar en auto motivado que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Le…</mark></span><span class=\"ref-norma\">Art. 14.2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. El artículo 14.2 de la Ley Orgánica 5/2000 establece que en caso de internamiento en régimen cerrado, si el menor alcanza los 18 años sin finalizar el cumplimiento, el Juez de Menores, podrá ordenar en auto motivado que la medida se ejecute en un centro penitenciario si la conducta del internado no responde a los objetivos propuestos en la sentencia."},{"i":"17-56","p":"Ley Orgánica 5/2000. Mayoría de edad del condenado. Cuando se trate de la medida de internamiento en régimen cerrado y el menor alcance la edad de dieciocho años sin haber finalizado su cumplimiento, ____ podrá ordenar en auto motivado que su cumplimiento se lleve a cabo en un centro penitenciario.","o":["El Ministerio Fiscal, oído el Juez de Menores, el letrado del menor, el equipo técnico y la entidad pública de protección o reforma de menores.","El Juez de Menores, oído el Ministerio Fiscal, el letrado del menor, el equipo técnico y la entidad pública de protección o reforma de menores.","El Juez de Menores, oído el Ministerio Fiscal y el letrado del menor.","El Ministerio Fiscal, oído el Juez de Menores y el letrado del menor."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Juez de Menores, oído el Ministerio Fiscal, el letrado del menor, el equipo técnico y la entidad pública de protección o reforma de meno…</mark></span><span class=\"ref-norma\">Art. 9.6 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 9.6 de la LO 5/2000 atribuye esta competencia al Juez de Menores, previa audiencia de todas las partes mencionadas.*"},{"i":"17-225","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Respecto de la medida de internamiento en régimen cerrado, es CORRECTO afirmar que:","o":["Las acciones u omisiones dolosas o imprudentes podrán ser sancionadas con esta medida en atención a la gravedad de los hechos.","Esta medida impuesta por el Juez de Menores con arreglo a esta Ley se cumplía en todo caso en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria.","Las personas sometidas a esta medida residirán en el centro pero podrán realizar fuera del mismo alguno o algunas de las actividades formativas, educativas, laborales y de ocio.","Cuando se trate de la medida de internamiento en régimen cerrado y el menor alcance la edad de dieciocho años sin haber finalizado su cumplimiento, el Juez de Menores, oído el Ministerio Fiscal, el letrado del menor, el equipo técnico y la entidad pública de protección o reforma de menores, podrá ordenar en auto motivado que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria si la conducta de la persona internada no responde a los objetivos propuestos en la sentencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando se trate de la medida de internamiento en régimen cerrado y el menor alcance la edad de dieciocho años sin haber finalizado su cumplimiento, el Juez de Menores, oído el Ministerio Fiscal, el letrado del menor, el equipo técnico y la entidad pública de protección o reforma de menores, podrá ordenar en auto motivado que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria si la conducta de la persona internada no responde a los objetivos propuestos en la sentencia</mark></span>C describe el régimen semiabierto; A y B son falsas (las imprudentes no admiten cerrado; no es «en todo caso»). Según el <span class=\"ref-norma\">art. 14.2 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"el Juez de Menores, oído el Ministerio Fiscal, el letrado del menor, el equipo técnico y la entidad pública de protección o reforma de menores, podrá ordenar en auto motivado que su cumplimiento se lleve a cabo en un centro penitenciario\"</span> (verificado con el temario oficial)."},{"i":"17-263","p":"(LO 5/2000 - Responsabilidad Penal del Menor) Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. De las medidas. Cuando se trate de la medida de internamiento en régimen cerrado y el menor alcance la edad de dieciocho años sin haber finalizado su cumplimiento, el Juez de Menores:","o":["Podrá ordenar un auto en que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria.","Deberá ordenar en auto motivado que el cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria si la conducta de la persona internada no responde a los objetivos propuestos en la sentencia.","Podrá ordenar en auto motivado que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria si la conducta de la persona internada no responde a los objetivos propuestos en la sentencia.","Deberá ordenar en auto que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Podrá ordenar en auto motivado que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Le…</mark></span><span class=\"ref-norma\">Art. 14.2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. El Art. 14.2 de la LORPM establece que el Juez de Menores podrá ordenar en auto motivado el traslado a un centro penitenciario (según LOGP) si la conducta no responde a los objetivos de la sentencia."},{"i":"17-275","p":"(LO 5/2000 - LORPM) Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. De las medidas. Cuando se trate de la medida de internamiento en régimen cerrado y el menor alcance la edad de dieciocho años sin haber finalizado su cumplimiento, el Juez de Menores:","o":["Podrá ordenar un auto en que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria.","Deberá ordenar en auto motivado que el cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria si la conducta de la persona internada no responde a los objetivos propuestos en la sentencia.","Podrá ordenar en auto motivado que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria si la conducta de la persona internada no responde a los objetivos propuestos en la sentencia.","Deberá ordenar en auto que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Podrá ordenar en auto motivado que su cumplimiento se lleve a cabo en un centro penitenciario conforme al régimen general previsto en la Le…</mark></span><span class=\"ref-norma\">Art. 14.2 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. (Según el Art. 14.2 LORPM)."},{"i":"17-ia-1130","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Mayoría de edad del condenado. Cuando el menor a quien se le hubiere impuesto una medida alcanzase la mayoría de edad, continuará el cumplimiento de la medida hasta:","o":["el cumplimiento del tiempo máximo previsto para la medida.","cumplir veintiún años de edad.","que el Juez de Menores acuerde su traslado a un centro penitenciario, en los términos que se determinen reglamentariamente.","alcanzar los objetivos propuestos en la sentencia en que se le impuso."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">alcanzar los objetivos propuestos en la sentencia en que se le impuso</mark></span>El <span class=\"ref-norma\">art. 14.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"continuará el cumplimiento de la medida hasta alcanzar los objetivos propuestos en la sentencia en que se le impuso\"</span>. La medida continúa hasta alcanzar los objetivos propuestos en la sentencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1131","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Mayoría de edad del condenado. Señale la INCORRECTA sobre la mayoría de edad del condenado:","o":["Alcanzada la mayoría de edad, el menor continuará el cumplimiento de la medida hasta alcanzar los objetivos propuestos en la sentencia.","En el internamiento cerrado, si el menor alcanza los dieciocho años sin haber finalizado, el Juez de Menores podrá ordenar en auto motivado su cumplimiento en centro penitenciario si la conducta no responde a los objetivos de la sentencia.","Cuando el menor alcance la mayoría de edad, la medida impuesta se extingue automáticamente.","Cumplidos veintiún años, el Juez de Menores ordenará el cumplimiento del internamiento cerrado en centro penitenciario, salvo que excepcionalmente entienda procedente otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando el menor alcance la mayoría de edad, la medida impuesta se extingue automáticamente</mark></span>El <span class=\"ref-norma\">art. 14 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Cuando el menor a quien se le hubiere impuesto una medida de las establecidas en esta Ley alcanzase la mayoría de edad, continuará el cumplimiento de la medida hasta alcanzar los objetivos propuestos en la sentencia en que se le impuso\"</span>. La medida no se extingue por alcanzar la mayoría de edad: continúa hasta alcanzar los objetivos de la sentencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1133","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Mayoría de edad del condenado. Con veintiún años cumplidos, el Juez de Menores ordenará el cumplimiento del internamiento cerrado en centro penitenciario, salvo que excepcionalmente entienda procedente la modificación o sustitución de la medida o su permanencia en el centro cuando:","o":["el menor responda a los objetivos propuestos en la sentencia.","el Ministerio Fiscal así lo solicite.","el menor haya cumplido más de la mitad de la medida.","la entidad pública de protección o reforma de menores lo informe favorablemente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el menor responda a los objetivos propuestos en la sentencia</mark></span>El <span class=\"ref-norma\">art. 14.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"o su permanencia en el centro en cumplimiento de tal medida cuando el menor responda a los objetivos propuestos en la sentencia\"</span>. La excepción exige que el menor responda a los objetivos propuestos en la sentencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1134","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Mayoría de edad del condenado. Cuando el menor pase a cumplir la medida de internamiento en un centro penitenciario, quedarán sin efecto el resto de medidas impuestas por el Juez de Menores que estuvieren pendientes de cumplimiento sucesivo o que estuviera cumpliendo simultáneamente con la de internamiento, si éstas:","o":["no hubieran sido ratificadas por auto motivado, salvo que la autoridad judicial disponga otra cosa.","fueren de naturaleza terapéutica.","excedieran de dos años de duración.","no fueren compatible con el régimen penitenciario."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no fueren compatible con el régimen penitenciario</mark></span>El <span class=\"ref-norma\">art. 14.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"si éstas no fueren compatible con el régimen penitenciario\"</span>. Quedan sin efecto las medidas incompatibles con el régimen penitenciario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1135","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Mayoría de edad del condenado. La medida de internamiento en régimen cerrado se cumplirá en un centro penitenciario conforme al régimen general previsto en la Ley Orgánica General Penitenciaria siempre que, con anterioridad al inicio de su ejecución, el responsable hubiera cumplido ya, total o parcialmente:","o":["una pena de prisión impuesta con arreglo al Código Penal, pero no una medida de internamiento, previo informe de la unidad policial competente.","una medida de internamiento en régimen cerrado ejecutada en un centro de menores.","una pena de prisión impuesta con arreglo al Código Penal, o bien una medida de internamiento ejecutada en un centro penitenciario.","una pena de multa o de trabajos en beneficio de la comunidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">una pena de prisión impuesta con arreglo al Código Penal, o bien una medida de internamiento ejecutada en un centro penitenciario</mark></span>El <span class=\"ref-norma\">art. 14.5 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"hubiera cumplido ya, total o parcialmente, bien una pena de prisión impuesta con arreglo al Código Penal, o bien una medida de internamiento ejecutada en un centro penitenciario\"</span>. Basta una pena de prisión previa o una medida de internamiento ya ejecutada en centro penitenciario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 17 — Detención de los menores EX","q":[{"i":"17-16","p":"Ley Orgánica 5/2000, de 12 de enero. Mientras dure la detención, los menores deberán hallarse custodiados en dependencias _____ y _____ de las que se utilicen para los mayores de edad, y recibirán los cuidados, protección y asistencia social, psicológica, médica y física que requieran, habida cuenta de su edad, sexo y características individuales.","o":["Conjuntas y respetuosas.","Diferenciadas y separadas.","Adecuadas y separadas.","Ninguna opción es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Adecuadas y separadas.</mark></span><span class=\"ref-norma\">Art. 17.1 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 17.1 de la LO 5/2000 exige que las dependencias sean &quot;adecuadas y separadas&quot; de las de los mayores de edad.*"},{"i":"17-49","p":"Instrucción 1/2017. En caso de detención de un menor, se comunicará la situación a sus representantes legales:","o":["Inmediatamente.","4 horas.","12 horas.","24 horas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Inmediatamente</mark></span>No hay plazo en horas: la notificación es inmediata. Según el <span class=\"ref-norma\">art. 17.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"También deberán notificar inmediatamente el hecho de la detención y el lugar de la custodia a los representantes legales del menor y al Ministerio Fiscal\"</span> (verificado con el temario oficial)."},{"i":"17-105","p":"Ley Orgánica 5/2000. Detención de los menores. El menor detenido tendrá derecho a la entrevista reservada con su abogado:","o":["Con anterioridad y al término de la práctica de la diligencia de toma de declaración.","Solo durante la práctica de la diligencia de toma de declaración.","Solo con anterioridad a la práctica de la diligencia de toma de declaración.","Con anterioridad y durante la práctica de la diligencia de toma de declaración."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Con anterioridad y al término de la práctica de la diligencia de toma de declaración</mark></span>Según el <span class=\"ref-norma\">art. 17.2 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"El menor detenido tendrá derecho a la entrevista reservada con su abogado con anterioridad y al término de la práctica de la diligencia de toma de declaración\"</span> (verificado con el temario oficial)."},{"i":"17-111","p":"Real Decreto 1774/2004. Detención de los menores. Las autoridades y funcionarios que intervengan en la detención de un menor deberán practicarla en la forma que menos perjudique a éste y estarán obligados a informarle, en un lenguaje claro y comprensible y de forma inmediata:","o":["De los hechos que se le imputan.","De las razones de su detención.","De los derechos que le asisten, especialmente los reconocidos en el artículo 520 de la Ley de Enjuiciamiento Criminal.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 6.1 · Real Decreto 1774/2004</span>. *Explicación: El artículo 6.1 del RD 1774/2004 establece la obligación de informar al menor sobre todos estos aspectos.*"},{"i":"17-117","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. Las autoridades y funcionarios que intervengan en la detención de un menor deberán practicarla en la forma que menos perjudique a éste y estarán obligados a informarle, en un lenguaje claro y comprensible y _____, de los hechos que se le imputan, de las razones de su detención y de los derechos que le asisten, así como a garantizar el respeto de los mismos:","o":["Dentro de las primeras 48 horas.","Dentro de las primeras 24 horas.","De forma inmediata.","En cuanto sea posible."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De forma inmediata.</mark></span>La información debe proporcionarse de forma inmediata."},{"i":"17-148","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. La detención de un menor por funcionarios de policía no podrá durar:","o":["Menor tiempo del estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos y, en todo caso, dentro del plazo máximo de cuarenta y ocho horas, el menor deberá ser puesto en libertad o a disposición del Ministerio Fiscal.","El tiempo del estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos y, en todo caso, dentro del plazo máximo de cuarenta y dos horas, el menor deberá ser puesto en libertad o a disposición del Ministerio Fiscal.","Más tiempo del estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos y, en todo caso, dentro del plazo máximo de veinticuatro horas, el menor deberá ser puesto en libertad o a disposición del Ministerio Fiscal.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Más tiempo del estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos y, en todo caso…</mark></span> Máximo 24 horas de detención. TEST 11"},{"i":"17-162","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. El Juez competente para el procedimiento de habeas corpus en relación a un menor será:","o":["El Juez del lugar donde se encuentre el menor privado de libertad.","Si no constare, el del lugar donde se produjo la detención.","En defecto de los anteriores, el del lugar donde se hayan tenido las últimas noticias sobre el paradero del menor detenido.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>B y C tenían el orden de los criterios invertido. Según el <span class=\"ref-norma\">art. 17.6 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"si no constare, el del lugar donde se produjo la detención, y, en defecto de los anteriores, el del lugar donde se hayan tenido las últimas noticias sobre el paradero del menor detenido\"</span> (verificado con el temario oficial)."},{"i":"17-215","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Las autoridades y funcionarios que intervengan en la detención de un menor deberán practicarla en la forma que menos perjudique a éste y estarán obligados a informarle, en un lenguaje ______ y de forma inmediata, de los hechos que se le imputan, de las razones de su detención y de los derechos que le asisten.","o":["Claro y comprensible.","Adecuado y claro.","Adecuado y comprensible.","Adecuado, claro y comprensible."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Claro y comprensible.</mark></span>Claro y comprensible."},{"i":"17-238","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. Cuando el detenido sea puesto a disposición del Ministerio Fiscal, éste habrá de resolver, dentro de las _____ a partir de la detención, sobre la puesta en libertad del menor, sobre el desistimiento o sobre la incoación del expediente:","o":["Veinticuatro horas.","Cuarenta y ocho horas.","Setenta y dos horas.","Treinta y seis horas, sin perjuicio de lo que establezcan los tratados internacionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuarenta y ocho horas</mark></span>El <span class=\"ref-norma\">art. 17.5 de la LO 5/2000</span> dispone: <span class=\"ref-concepto\">\"éste habrá de resolver, dentro de las cuarenta y ocho horas a partir de la detención, sobre la puesta en libertad del menor\"</span>"},{"i":"17-ia-1207","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. Las autoridades y funcionarios que intervengan en la detención de un menor deberán practicarla en la forma que:","o":["más garantice la seguridad de los agentes.","cause menor publicidad.","menos perjudique a éste.","resulte más rápida."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">menos perjudique a éste</mark></span>El <span class=\"ref-norma\">art. 17.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"deberán practicarla en la forma que menos perjudique a éste\"</span>. La detención se practica en la forma que menos perjudique al menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1208","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. Los funcionarios que intervengan en la detención de un menor estarán obligados a informarle, en un lenguaje claro y comprensible y de forma inmediata, de los hechos que se le imputan, de las razones de su detención y de los derechos que le asisten, especialmente los reconocidos en:","o":["la Ley Orgánica 1/1996.","la Ley de Enjuiciamiento Criminal.","la Ley Orgánica 5/2000.","la Constitución Española, previo informe de la unidad policial competente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Ley de Enjuiciamiento Criminal</mark></span>El <span class=\"ref-norma\">art. 17.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"especialmente los reconocidos en el artículo 520 de la Ley de Enjuiciamiento Criminal\"</span>. Los derechos reconocidos especialmente son los de la Ley de Enjuiciamiento Criminal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1210","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. Si el menor detenido fuera extranjero, el hecho de la detención se notificará a las correspondientes autoridades consulares cuando:","o":["el menor no tuviera residencia legal en España, en todo caso.","el menor tuviera su residencia habitual fuera de España, con independencia de lo que soliciten, sin perjuicio de lo previsto en la normativa vigente.","lo solicite el Ministerio Fiscal o el equipo técnico.","el menor tuviera su residencia habitual fuera de España o cuando así lo solicitaran el propio menor o sus representantes legales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el menor tuviera su residencia habitual fuera de España o cuando así lo solicitaran el propio menor o sus representantes legales</mark></span>El <span class=\"ref-norma\">art. 17.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"se notificará a las correspondientes autoridades consulares cuando el menor tuviera su residencia habitual fuera de España o cuando así lo solicitaran el propio menor o sus representantes legales\"</span>. Se notifica si reside habitualmente fuera de España o si lo solicitan el menor o sus representantes legales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1211","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. Señale la INCORRECTA sobre la detención de un menor:","o":["Las autoridades deberán practicar la detención en la forma que menos perjudique al menor.","Deberán informarle, en un lenguaje claro y comprensible y de forma inmediata, de los hechos que se le imputan.","Si el menor detenido fuera extranjero, la detención se notificará en todo caso a las autoridades consulares.","Deberán notificar inmediatamente el hecho de la detención y el lugar de la custodia a los representantes legales del menor y al Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Si el menor detenido fuera extranjero, la detención se notificará en todo caso a las autoridades consulares</mark></span>El <span class=\"ref-norma\">art. 17.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Si el menor detenido fuera extranjero, el hecho de la detención se notificará a las correspondientes autoridades consulares cuando el menor tuviera su residencia habitual fuera de España o cuando así lo solicitaran el propio menor o sus representantes legales\"</span>. La notificación consular no es en todo caso: depende de la residencia habitual o de la solicitud. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1212","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. Toda declaración del detenido se llevará a cabo en presencia de su letrado y de aquéllos que ejerzan la patria potestad, tutela o guarda del menor -de hecho o de derecho-, salvo que, en este último caso:","o":["el menor lo solicite expresamente.","las circunstancias aconsejen lo contrario.","el Juez de Menores lo autorice.","el letrado lo considere conveniente, en los términos que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las circunstancias aconsejen lo contrario</mark></span>El <span class=\"ref-norma\">art. 17.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"salvo que, en este último caso, las circunstancias aconsejen lo contrario\"</span>. La excepción es que las circunstancias aconsejen lo contrario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1213","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. En defecto de quienes ejerzan la patria potestad, tutela o guarda del menor, la declaración del detenido se llevará a cabo en presencia del Ministerio Fiscal, representado por:","o":["persona distinta del instructor del expediente.","el propio instructor del expediente.","el Fiscal Jefe de la Sección de Menores, salvo que la autoridad judicial disponga otra cosa.","un miembro del equipo técnico."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">persona distinta del instructor del expediente</mark></span>El <span class=\"ref-norma\">art. 17.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"la declaración se llevará a cabo en presencia del Ministerio Fiscal, representado por persona distinta del instructor del expediente\"</span>. El Fiscal presente debe ser persona distinta del instructor del expediente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1214","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. El menor detenido tendrá derecho a la entrevista reservada con su abogado con anterioridad y al término de la práctica de:","o":["la detención.","las diligencias policiales.","la puesta a disposición del Ministerio Fiscal.","la diligencia de toma de declaración."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la diligencia de toma de declaración</mark></span>El <span class=\"ref-norma\">art. 17.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"con anterioridad y al término de la práctica de la diligencia de toma de declaración\"</span>. La entrevista reservada es antes y al término de la toma de declaración. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1215","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. Mientras dure la detención, los menores recibirán los cuidados, protección y asistencia social, psicológica, médica y física que requieran, habida cuenta de su edad, sexo y:","o":["circunstancias personales, previo informe de la unidad policial competente.","situación familiar.","características individuales.","grado de madurez."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">características individuales</mark></span>El <span class=\"ref-norma\">art. 17.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"habida cuenta de su edad, sexo y características individuales\"</span>. Se atiende a edad, sexo y características individuales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1217","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. Respecto de la detención de menores, se aplicará, en su caso, lo dispuesto en la Ley de Enjuiciamiento Criminal sobre prolongación de la detención e incomunicación, atribuyendo la competencia para las resoluciones judiciales previstas al:","o":["Juez de Menores.","Juez de Instrucción.","Juez Central de Instrucción.","Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Juez de Menores</mark></span>El <span class=\"ref-norma\">art. 17.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"atribuyendo la competencia para las resoluciones judiciales previstas en dicho precepto al Juez de Menores\"</span>. Las resoluciones judiciales las dicta el Juez de Menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1218","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. Cuando el detenido sea puesto a disposición del Ministerio Fiscal, éste habrá de resolver, dentro de las cuarenta y ocho horas a partir de la detención, sobre:","o":["la puesta en libertad del menor o la incoación del expediente, pero no sobre el desistimiento.","la incoación del expediente y la adopción de medidas cautelares.","la puesta en libertad del menor, el sobreseimiento o la incoación del expediente.","la puesta en libertad del menor, el desistimiento o la incoación del expediente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la puesta en libertad del menor, el desistimiento o la incoación del expediente</mark></span>El <span class=\"ref-norma\">art. 17.5 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"habrá de resolver, dentro de las cuarenta y ocho horas a partir de la detención, sobre la puesta en libertad del menor, sobre el desistimiento al que se refiere el artículo siguiente, o sobre la incoación del expediente\"</span>. Resuelve en 48 horas sobre libertad, desistimiento o incoación del expediente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1219","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. Al incoar el expediente, el Ministerio Fiscal pondrá al menor a disposición del Juez de Menores competente e instará del mismo:","o":["la oportuna medida definitiva, sin perjuicio de lo previsto en la normativa vigente.","la apertura del juicio.","las oportunas medidas cautelares.","el internamiento inmediato."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las oportunas medidas cautelares</mark></span>El <span class=\"ref-norma\">art. 17.5 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"poniendo a aquél a disposición del Juez de Menores competente e instando del mismo las oportunas medidas cautelares\"</span>. Se insta del Juez de Menores las oportunas medidas cautelares. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1220","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. El Juez competente para el procedimiento de hábeas corpus en relación a un menor será el Juez de Instrucción del lugar en el que se encuentre el menor privado de libertad; si no constare, el del lugar donde se produjo la detención, y, en defecto de los anteriores:","o":["el del lugar del domicilio del menor.","el del lugar donde se hayan tenido las últimas noticias sobre el paradero del menor detenido.","el Juez de Menores del lugar de los hechos, en los términos que se determinen reglamentariamente.","el Juez Central de Instrucción."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el del lugar donde se hayan tenido las últimas noticias sobre el paradero del menor detenido</mark></span>El <span class=\"ref-norma\">art. 17.6 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"y, en defecto de los anteriores, el del lugar donde se hayan tenido las últimas noticias sobre el paradero del menor detenido\"</span>. El tercer criterio es el del lugar con las últimas noticias sobre el paradero del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1221","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Detención de los menores. Cuando el procedimiento de hábeas corpus sea instado por el propio menor, la fuerza pública responsable de la detención lo notificará inmediatamente al:","o":["Ministerio Fiscal, además de dar curso al procedimiento.","Juez de Menores, además de dar curso al procedimiento.","Ministerio Fiscal, sin dar curso al procedimiento hasta su resolución.","letrado del menor, además de dar curso al procedimiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ministerio Fiscal, además de dar curso al procedimiento</mark></span>El <span class=\"ref-norma\">art. 17.6 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"la fuerza pública responsable de la detención lo notificará inmediatamente al Ministerio Fiscal, además de dar curso al procedimiento\"</span>. Se notifica al Ministerio Fiscal y se da curso al procedimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RECUERDA del temario · Instrucción 1/2017 (R10 y R17 a R23) R10 R17 R18 R19 R20 R21 R22 R23","q":[{"i":"17-17","p":"Instrucción 1/2017. Organización. ¿De quién depende el PAE Central?","o":["De la Unidad Orgánica de Policía Judicial.","De la Unidad Técnica de Policía Judicial.","De la Unidad de Extranjería y Fronteras.","De la Unidad de Policía Científica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De la Unidad Técnica de Policía Judicial.</mark></span>*Explicación: Según la Instrucción 1/2017, el PAE (Punto de Atención Especializada) Central depende funcionalmente de la Unidad Técnica de Policía Judicial.*"},{"i":"17-41","p":"Instrucción 1/2017. Cuando existan dudas sobre la mayoría o minoría de edad de la víctima y no pueda ser determinada con certeza, se presumirá:","o":["Que se trata de una persona mayor de edad.","Siempre que se trata de una persona menor de edad.","Depende del delito cometido.","Depende de las circunstancias psicológicas y sociales de la persona detenida."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Siempre que se trata de una persona menor de edad.</mark></span>*Explicación: El principio de protección del menor establece que, en caso de duda sobre la edad, se presumirá que es menor de edad para aplicar las garantías correspondientes.*"},{"i":"17-42","p":"Instrucción 1/2017. Cuando sea necesario requerir la identidad de un menor de edad en las vías, lugares o establecimientos públicos y, en su caso, realizar un control superficial sobre sus efectos personales para comprobar que no porta sustancias o instrumentos prohibidos o peligrosos: señale la INCORRECTA.","o":["Se le informará con claridad de los hechos que motiven la intervención.","Se evitará, en la medida de lo posible, la espectacularidad, el empleo de lenguaje duro, la violencia y la exhibición de armas.","Cuando las circunstancias lo permitan, se elegirá un lugar discreto y ajeno a la vista de tercera persona.","Se pondrá en todo caso en conocimiento de la fiscalía de menores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Se pondrá en todo caso en conocimiento de la fiscalía de menores</mark></span>D es la incorrecta: se avisa a quienes ejerzan la patria potestad o guarda (no a la Fiscalía) y solo si hay riesgo. Según el <span class=\"ref-norma\">punto 6.1.6 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"d. Se pondrá lo antes posible en conocimiento de quienes ejerzan la patria potestad, la tutela o la guarda de hecho siempre que de las circunstancias del entorno o de los hechos que originan la intervención pueda deducirse que existe riesgo para el menor\"</span> (verificado con el temario oficial)."},{"i":"17-52","p":"Instrucción 1/2017. En las diligencias de identificación de menores, será necesario el consentimiento de:","o":["El menor exclusivamente.","Los representantes legales exclusivamente.","Tanto el menor como sus representantes legales.","El Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Tanto el menor como sus representantes legales.</mark></span>*Explicación: Para la identificación de menores se requiere el consentimiento tanto del menor (si tiene suficiente madurez) como de sus representantes legales.*"},{"i":"17-66","p":"Instrucción 1/2017. Bases de datos. El Registro de Menores Extranjeros No Acompañados (RMENA) está ubicado en el subfichero de la aplicación ADEXTRA cuya titularidad corresponde a:","o":["Dirección General de la Policía.","Comisaría General de Extranjería y Fronteras.","Policía Judicial.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dirección General de la Policía</mark></span>La titularidad es de la Dirección General de la Policía; la gestión, de la Comisaría General de Extranjería y Fronteras. Según el <span class=\"ref-norma\">punto 10.3.5 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"cuya titularidad corresponde a la Dirección General de la Policía, y su gestión a la Comisaría General de Extranjería y Fronteras\"</span> (verificado con el temario oficial)."},{"i":"17-71","p":"Instrucción 1/2017. Actuación con menores extranjeros no acompañados. Se entiende por menor extranjero no acompañado (MENA) a:","o":["El extranjero menor de dieciocho años, nacional de un Estado al que no le sea de aplicación el régimen de la Unión Europea que llegue a territorio español sin un adulto responsable de él, ya sea legalmente o con arreglo a la costumbre, y al que se aprecie riesgo de desprotección del menor.","El extranjero mayor de dieciocho años, nacional de un Estado al que no le sea de aplicación el régimen de la Unión Europea que llegue a territorio español sin un adulto responsable de él.","El extranjero menor de dieciséis años, nacional de un Estado al que no le sea de aplicación el régimen de la Unión Europea que llegue a territorio español sin un adulto responsable de él.","Cualquier extranjero que llegue a territorio español sin documentación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El extranjero menor de dieciocho años, nacional de un Estado al que no le sea de aplicación el régimen de la Unión Europea que llegue a ter…</mark></span>*Explicación: La definición correcta de MENA es un extranjero menor de 18 años no acompañado y en situación de riesgo.*"},{"i":"17-77","p":"Instrucción 1/2017. Objeto. El presente Protocolo tiene por objeto actualizar y unificar los criterios de actuación de las:","o":["Fuerzas y Cuerpos de Seguridad del Estado.","Fuerzas y Cuerpos de Seguridad con competencias en actuación con menores de edad.","Fuerzas y Cuerpos de Seguridad.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Fuerzas y Cuerpos de Seguridad del Estado</mark></span>Según el <span class=\"ref-norma\">punto 1.1.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"actualizar y unificar los criterios de actuación de las Fuerzas y Cuerpos de Seguridad del Estado\"</span> (verificado con el temario oficial)."},{"i":"17-90","p":"Instrucción 1/2017. Exploración del menor y valoración de las necesidades de la víctima. Siempre que existan dudas sobre la mayoría o minoría de edad de la víctima y no pueda ser determinada con certeza, se presumirá que se trata de:","o":["Una persona mayor de edad.","Una persona menor de edad.","Una persona menor de dieciséis años.","Una persona mayor de dieciséis años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Una persona menor de edad.</mark></span>*Explicación: El principio de protección del menor establece que, en caso de duda sobre la edad, se presumirá que es menor de edad.*"},{"i":"17-95","p":"Instrucción 1/2017. Objeto. El Protocolo de actuación policial con menores tiene por objeto actualizar y unificar los criterios de actuación de:","o":["Las Fuerzas y Cuerpos de Seguridad del Estado.","Las policías autonómicas.","Las policías locales.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Fuerzas y Cuerpos de Seguridad del Estado</mark></span>Solo las Fuerzas y Cuerpos de Seguridad del Estado: no las policías autonómicas ni locales. Según el <span class=\"ref-norma\">punto 1.1.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"actualizar y unificar los criterios de actuación de las Fuerzas y Cuerpos de Seguridad del Estado\"</span> (verificado con el temario oficial)."},{"i":"17-107","p":"Real Decreto 1774/2004. Actuación de la Policía Judicial. La actuación de la Policía Judicial se atendrá:","o":["A las directrices del Ministerio Fiscal.","A las directrices del Consejo General del Poder Judicial.","A las indicaciones profesionales del Equipo Técnico.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A las directrices del Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 33.1 · Real Decreto 1774/2004</span>. *Explicación: El artículo 33.1 del RD 1774/2004 establece que la Policía Judicial actuará bajo las directrices del Ministerio Fiscal.*"},{"i":"17-114","p":"Instrucción nº 1/2017 de la Secretaría de Estado de Seguridad, por la que se actualiza el \"protocolo de actuación policial con menores\". Objeto. El presente Protocolo tiene por objeto:","o":["Actualizar y unificar los criterios de actuación de las Fuerzas y Cuerpos de Seguridad del Estado.","El desarrollo de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores.","Regular la responsabilidad de las personas mayores de catorce años y menores de dieciocho por la comisión de hechos tipificados como delitos.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Actualizar y unificar los criterios de actuación de las Fuerzas y Cuerpos de Seguridad del Estado</mark></span>Las opciones tenían errores de transcripción; el desarrollo de la LO 5/2000 es el objeto del Reglamento, no del Protocolo. Según el <span class=\"ref-norma\">punto 1.1.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"El presente Protocolo tiene por objeto actualizar y unificar los criterios de actuación de las Fuerzas y Cuerpos de Seguridad del Estado\"</span> (verificado con el temario oficial)."},{"i":"17-119","p":"Instrucción nº 1/2017 de la Secretaría de Estado de Seguridad, por la que se actualiza el “protocolo de actuación policial con menores”. Competencias. Los Equipos de la Policía Judicial especializados en materia de menores NO tendrán los siguientes cometidos:","o":["Hacerse cargo de la investigación criminal y asistencia a las víctimas en todos los casos en que intervengan menores de edad.","En tareas de protección, el tratamiento de los menores en situación de riesgo o desamparo.","Establecer canales de comunicación permanentes con la correspondiente Sección de Menores de la Fiscalía.","Propiciar y mantener el contacto con Instituciones y Asociaciones relacionadas con este ámbito de actuación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Hacerse cargo de la investigación criminal y asistencia a las víctimas en todos los casos en que intervengan menores de edad</mark></span>A es la que NO es cometido: no son «todos los casos», sino los de cierta gravedad. Según el <span class=\"ref-norma\">punto 2.2.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"a. Hacerse cargo de la investigación criminal y asistencia a las víctimas en aquellos casos que revistan cierta gravedad y donde estén implicados menores de edad\"</span> (verificado con el temario oficial)."},{"i":"17-125","p":"Instrucción 1/2017 de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Actuación con menores extranjeros no acompañados. En caso de localización de un menor extranjero no acompañado al que le sea aplicable el régimen jurídico de la Unión Europea se pondrá en conocimiento inmediato de:","o":["La Dirección Fiscal.","La Delegación o Subdelegación del Gobierno.","La correspondiente Brigada Provincial de Extranjería y Fronteras de la Policía Nacional.","El Consulado o Representación diplomática del Estado de que se trate."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La correspondiente Brigada Provincial de Extranjería y Fronteras de la Policía Nacional</mark></span>Es Brigada «Provincial», no «Territorial». Según el <span class=\"ref-norma\">punto 8.2.12 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"se pondrá en conocimiento inmediato de la correspondiente Brigada Provincial de Extranjería y Fronteras de la Policía Nacional\"</span> (verificado con el temario oficial)."},{"i":"17-127","p":"Instrucción 1/2017 de la Secretaría de Estado de Seguridad, por la que se actualiza el Protocolo de Actuación Policial con Menores. Exploración del menor y valoración de las necesidades de la víctima. Cuando se realicen o tramiten atestados en los que existan indicios de malos tratos o abusos a menores en el ámbito familiar y se aprecie una posible situación de riesgo o desamparo, se remitirá con carácter de urgencia una copia a:","o":["La Autoridad Judicial.","La Sección de Menores de la Fiscalía.","Al Ministerio de Sanidad Asuntos Sociales e Igualdad.","Los Grupos o Equipos de la Policía Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Sección de Menores de la Fiscalía</mark></span>Según el <span class=\"ref-norma\">punto 5.3.6 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"se remitirá con carácter de urgencia una copia a la Sección de Menores de la Fiscalía\"</span> (verificado con el temario oficial)."},{"i":"17-149","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". ¿Quienes ostentan legitimación para interponer denuncia ante los agentes policiales sin necesidad de la presencia de quienes ejerzan su patria potestad o tutela?","o":["Menores de edad víctimas.","Menores de edad testigos del delito.","Los curadores.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Víctimas y testigos, no los imputados. Según el <span class=\"ref-norma\">punto 5.2.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"Los menores de edad víctimas o testigos del delito ostentan legitimación para interponer denuncia ante los agentes policiales sin necesidad de la presencia de quienes ejerzan su patria potestad o tutela\"</span> (verificado con el temario oficial)."},{"i":"17-150","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Requisitos de la actuación con menores en el ámbito administrativo. La actuación policial con menores autores de infracciones administrativas se limitará a aquellos casos en que sea estrictamente necesaria en aplicación de leyes y normas concretas, bajo el principio de ______ y protección del interés superior del menor.","o":["Circunstancias.","Proyeccionística.","Mínima intervención.","Eficacia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Mínima intervención</mark></span>El principio es de «mínima» intervención. Según el <span class=\"ref-norma\">punto 3.2.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"bajo el principio de mínima intervención y protección del interés superior del menor\"</span> (verificado con el temario oficial)."},{"i":"17-151","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Exploración del menor y valoración de las necesidades de la víctima. Siempre que existan dudas sobre la mayoría o minoría de edad de la víctima y no pueda ser determinada con certeza:","o":["Se presumirá que se trata de una persona mayor de edad.","Se presumirá que se trata de una persona menor de edad.","Se regirá por las normas dispuestas en el protocolo para estos casos.","Se actuará según informes materiales de menores competentes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Se presumirá que se trata de una persona menor de edad</mark></span>Según el <span class=\"ref-norma\">punto 5.3.8 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"Siempre que existan dudas sobre la mayoría o minoría de edad de la víctima y no pueda ser determinada con certeza, se presumirá que se trata de una persona menor de edad\"</span> (verificado con el temario oficial)."},{"i":"17-167","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Actuación con menores extranjeros no acompañados. Se considera que transcurridos _____ desde la puesta del menor extranjero a disposición del Centro de protección de menores la Entidad pública de protección de menores estará facultada para solicitar la autorización de residencia.","o":["Dos meses.","Tres meses.","Cuatro meses.","Cinco meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Tres meses</mark></span>A los tres meses la entidad pública puede solicitar la residencia; a los nueve meses se otorga en todo caso. Según el <span class=\"ref-norma\">punto 8.2.11 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"transcurridos tres meses desde la puesta del menor extranjero a disposición del Centro de protección de menores\"</span> (verificado con el temario oficial)."},{"i":"17-172","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Actuación específica en casos de acoso escolar. En las actuaciones policiales relacionadas con casos de acoso escolar deberán tomarse en consideración las siguientes cuestiones: señale la INCORRECTA.","o":["Todas las modalidades de acoso son actos agresivos en sentido amplio, ya sean físicos, verbales o psicológicos, y pueden ser constitutivas de infracción penal.","Deben comunicarse al Ministerio Fiscal a excepción de los supuestos de relevancia penal mínima.","La respuesta policial debe ser individualizada para cada acosador.","Es posible que el fenómeno del acoso pueda pasar desapercibido para los adultos y que no deje huellas físicas susceptibles de objetivación, por lo que es importante realizar un acopio suficiente de elementos probatorios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Deben comunicarse al Ministerio Fiscal a excepción de los supuestos de relevancia penal mínima</mark></span>B es la incorrecta: se comunican «incluso» los de relevancia penal mínima, no «a excepción» de ellos. Según el <span class=\"ref-norma\">punto 7.2.2 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"c. Deben comunicarse al Ministerio Fiscal incluso los supuestos de relevancia penal mínima, evitando trivializar o banalizar los hechos\"</span> (verificado con el temario oficial)."},{"i":"17-182","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Menores infractores a la normativa de Seguridad Ciudadana. Aplicación de la normativa sobre Protección de la Seguridad Ciudadana. En las actuaciones policiales realizadas para el mantenimiento y restablecimiento de la seguridad ciudadana se tendrá en cuenta que los menores afectados reciban un trato acorde con la protección del superior interés del menor, sin perjuicio:","o":["Del interés nacional.","Del interés público general.","Del interés social.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Del interés público general.</mark></span>Del interés público general."},{"i":"17-185","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". En la exploración del menor, los funcionarios encargados de la investigación, en la medida en que no perjudique la eficacia del procedimiento, y siempre que queden salvaguardados los intereses propios de los menores, velarán porque: señale la INCORRECTA.","o":["Con las excepciones que se establecen en la legislación procesal y salvo que las circunstancias aconsejen lo contrario, se notifique inmediatamente el hecho ocurrido y el lugar donde se encuentre el menor víctima a sus padres o responsables legales.","Antes de recoger la declaración del menor, se proceda a realizar las actuaciones de preparación en las que corresponden recabar la mayor información posible sobre el menor y el hecho delictivo.","Se reciba declaración del menor al número de veces que sea necesario, respetando en todo caso su interés superior.","Se reciba declaración a las víctimas, cuando resulte necesario, sin dilaciones injustificadas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Se reciba declaración del menor al número de veces que sea necesario, respetando en todo caso su interés superior</mark></span>La incorrecta es C («al número de veces que sea necesario»); B es el texto literal del punto 5.3.1.b. Según el <span class=\"ref-norma\">punto 5.3.1.d de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"Se reciba declaración el menor número de veces posible, y únicamente cuando resulte estrictamente ineludible para los fines de la investigación penal\"</span> (verificado con el temario oficial)."},{"i":"17-189","p":"Instrucción número 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. Organización. En el ámbito de la Guardia Civil, los especialistas en actuación con menores se integran en los:","o":["Puntos de Atención Especializada.","Grupos de Atención Especializada.","Sectores Especializados de Atención.","Equipos Territoriales Especializados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Puntos de Atención Especializada</mark></span>Según el <span class=\"ref-norma\">punto 2.1.2 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"los especialistas en actuación con menores se integran en los Puntos de Atención Especializada (PAE)\"</span> (verificado con el temario oficial)."},{"i":"17-190","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Protección de la seguridad ciudadana. ¿Qué menores de edad estarán exentos de responsabilidad administrativa por la comisión de conductas tipificadas como infracciones en la Ley Orgánica 4/2015?","o":["Los menores de doce años.","Los menores de catorce años.","Los menores de quince años.","Los menores de dieciséis años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los menores de catorce años.</mark></span>Los menores de catorce años."},{"i":"17-194","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Menores extranjeros no acompañados. Una vez determinada la minoría de edad y puesto a disposición de los servicios competentes de protección de menores de la Comunidad Autónoma en la que se halle, el órgano competente para llevar a cabo los trámites relativos a la repatriación del menor extranjero no acompañado será:","o":["La Delegación y Subdelegación del Gobierno.","La Fiscalía de Menores.","La Brigada Provincial de Extranjería y Fronteras de la Policía Nacional.","Los servicios sociales de protección del menor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Delegación y Subdelegación del Gobierno.</mark></span> La Delegación y Subdelegación del Gobierno. TEST 14"},{"i":"17-195","p":"Instrucción nº 1/2017 de la Secretaría de Estado de Seguridad, por la que se actualiza el protocolo de actuación policial con menores. Régimen General de actuación policial con menores. ¿Qué se debe hacer con un menor de catorce años que haya cometido una infracción penal?","o":["Se le debe entregar a las autoridades locales.","Se le debe imponer una sanción económica, de la cual se responsabilizarán los padres, tutores, o los que ejerzan patria potestad o guarda de hecho.","Se le debe enviar a una institución de internamiento.","Se le debe entregar a quienes ejerzan la patria potestad, la tutela o la guarda de hecho, o a la Entidad Pública de protección de menores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Se le debe entregar a quienes ejerzan la patria potestad, la tutela o la guarda de hecho, o a la Entidad Pública de protección de menores.</mark></span>Se entrega a quienes ejerzan la patria potestad o a la Entidad Pública de protección de menores."},{"i":"17-206","p":"Instrucción nº 1/2017 de la Secretaría de Estado de Seguridad, por la que se actualiza el protocolo de actuación policial con menores. Especialización policial en materia de menores. ¿Qué se prevé para el personal policial no especializado en materia de menores?","o":["Una reducción de sus responsabilidades en casos relacionados con menores.","Planes específicos de formación y actualización en el tratamiento policial de menores.","La supervisión obligatoria por parte de las Unidades especializadas en todos los casos.","La asignación exclusiva a casos administrativos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Planes específicos de formación y actualización en el tratamiento policial de menores.</mark></span>Planes específicos de formación y actualización."},{"i":"17-226","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Acceso y confidencialidad de los registros. Los registros policiales donde conste la identidad y otros datos que afecten a la intimidad de los menores serán de carácter estrictamente confidencial y no podrán ser consultados por terceros, distinguiéndose tres tipos en función del soporte:","o":["Libros Registro, en soporte papel.","Bases de datos, en soporte informático.","Álbumes fotográficos, colección de fotografías.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Son libros-registro, bases de datos y álbumes fotográficos (no «archivos»). Según el <span class=\"ref-norma\">punto 10.1.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"c. Álbumes fotográficos, colección de fotografías\"</span> (verificado con el temario oficial)."},{"i":"17-251","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación con menores extranjeros no acompañados. Cuando se localice a un menor extranjero no acompañado se comunicará a la mayor brevedad a la correspondiente Brigada Provincial de Extranjería y Fronteras de la Policía Nacional, así como a:","o":["La Entidad pública de protección de menores y al Ministerio Fiscal.","La Delegación o Subdelegación del Gobierno y al Consulado del Estado de que se trate.","La Delegación o Subdelegación del Gobierno y al Ministerio Fiscal.","La Comisaría General de Extranjería y Fronteras y al Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Delegación o Subdelegación del Gobierno y al Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">punto 8.2.3 de la Instrucción 1/2017</span> dispone: <span class=\"ref-concepto\">\"así como a la Delegación o Subdelegación del Gobierno y al Ministerio Fiscal\"</span>"},{"i":"17-252","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación con menores extranjeros no acompañados. Sin perjuicio de lo establecido en el Real Decreto 557/2011, se considera que transcurridos _____ desde la puesta del menor extranjero a disposición del Centro de protección de menores la Entidad pública de protección de menores estará facultada para solicitar la autorización de residencia:","o":["Seis meses.","Nueve meses.","Dos meses.","Tres meses."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Tres meses</mark></span>El <span class=\"ref-norma\">punto 8.2.11 de la Instrucción 1/2017</span> dispone: <span class=\"ref-concepto\">\"transcurridos tres meses desde la puesta del menor extranjero a disposición del Centro de protección de menores la Entidad pública de protección de menores estará facultada para solicitar la autorización de residencia\"</span>"},{"i":"17-253","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación con menores extranjeros no acompañados. En todo caso, transcurrido el plazo máximo de _____ desde la puesta a disposición del menor extranjero, sea cual sea el estado de tramitación, la Delegación o Subdelegación de Gobierno otorgará la autorización de residencia:","o":["Nueve meses.","Tres meses, conforme al procedimiento que reglamentariamente se establezca.","Seis meses.","Doce meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Nueve meses</mark></span>El <span class=\"ref-norma\">punto 8.2.11 de la Instrucción 1/2017</span> dispone: <span class=\"ref-concepto\">\"transcurrido el plazo máximo de nueve meses desde la puesta a disposición del menor, sea cual sea el estado de tramitación, la Delegación o Subdelegación de Gobierno otorgará la autorización de residencia\"</span>"},{"i":"17-254","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Registros policiales de datos personales de menores. La confección y tenencia de álbumes fotográficos de menores detenidos, tanto en soporte físico como digital, corresponderá:","o":["A las Unidades de Policía Científica y, en su caso, a los Grupos de Policía Judicial.","A los Grupos o Equipos especializados en el tratamiento policial de menores y, en su caso, a las Unidades de investigación en esta materia.","A la Comisaría General de Policía Judicial y, en su caso, a las Brigadas Provinciales, sin perjuicio de lo que establezcan los tratados internacionales.","A los Grupos o Equipos especializados en menores, exclusivamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A los Grupos o Equipos especializados en el tratamiento policial de menores y, en su caso, a las Unidades de investigación en esta materia</mark></span>El <span class=\"ref-norma\">punto 10.4.1 de la Instrucción 1/2017</span> dispone: <span class=\"ref-concepto\">\"corresponderá a los Grupos o Equipos especializados en el tratamiento policial de menores y, en su caso, a las Unidades de investigación en esta materia\"</span>"},{"i":"17-ia-1014","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Derechos de las víctimas y de las personas perjudicadas. Las víctimas y las personas perjudicadas serán informadas de que, de no personarse en el expediente y no hacer renuncia ni reserva de acciones civiles, el Ministerio Fiscal las ejercitará:","o":["en todo caso.","cuando el Juez de Menores lo acuerde.","previa autorización del Juez de Menores.","si correspondiere."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">si correspondiere</mark></span>El <span class=\"ref-norma\">art. 4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"de no personarse en el expediente y no hacer renuncia ni reserva de acciones civiles, el Ministerio Fiscal las ejercitará si correspondiere\"</span>. El Fiscal las ejercita «si correspondiere», no en todo caso ni con autorización judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1502","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Objeto y ámbito de aplicación. La actuación y tratamiento policial de menores se ajustará a la Constitución, a los Tratados Internacionales ratificados por España y al resto del ordenamiento jurídico aplicable, especialmente a lo dispuesto en la Ley Orgánica 1/1996, de 15 de enero, sobre:","o":["protección integral de la infancia.","responsabilidad penal de los menores.","protección de la seguridad ciudadana.","protección jurídica del menor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">protección jurídica del menor</mark></span>El <span class=\"ref-norma\">1.2.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"especialmente a lo dispuesto en la Ley Orgánica 1/1996, de 15 de enero, sobre protección jurídica del menor\"</span>. La LO 1/1996 es la de protección jurídica del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1508","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. En el ámbito de la Guardia Civil, los especialistas en actuación con menores se integran en los Puntos de Atención Especializada (PAE), como órganos de las:","o":["Unidades Técnicas de Policía Judicial.","Unidades Orgánicas de Policía Judicial (UOPJ).","Secciones de Investigación de las Comandancias.","Unidades Orgánicas de Seguridad Ciudadana."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Unidades Orgánicas de Policía Judicial (UOPJ)</mark></span>El <span class=\"ref-norma\">2.1.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"los Puntos de Atención Especializada (PAE), como órganos de las Unidades Orgánicas de Policía Judicial (UOPJ)\"</span>. Los PAE son órganos de las Unidades Orgánicas de Policía Judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1521","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Atención policial al menor víctima o testigo. Protección de la víctima menor de edad. Todo menor víctima de delitos cometidos en España tiene los derechos recogidos en la Ley 4/2015, del Estatuto de la víctima del delito; en el «Protocolo básico de intervención contra el maltrato infantil en el ámbito familiar», del Observatorio de la Infancia; y en la Circular 3/2009 de la Fiscalía General del Estado sobre:","o":["«protección de los menores víctimas y testigos».","«tratamiento del acoso escolar desde el sistema de justicia juvenil».","«criterios para la unidad de actuación especializada del Ministerio Fiscal en materia de reforma de menores».","«la escucha del menor, víctima o testigo»."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">«protección de los menores víctimas y testigos»</mark></span>El <span class=\"ref-norma\">5.1.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"y en la Circular 3/2009 de la Fiscalía General del Estado sobre protección de los menores víctimas y testigos\"</span>. La Circular 3/2009 versa sobre la protección de los menores víctimas y testigos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1525","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Recepción de denuncias a menores de edad víctimas o testigos de delitos. Cuando el menor denuncie sin la presencia de sus representantes legales, los agentes que la reciban podrán poner la denuncia en conocimiento de aquellos, considerando el propio interés del menor, y también, si se aprecia una posible situación de desamparo, en conocimiento del:","o":["Fiscal.","Juez de Menores.","servicio de protección de menores.","equipo técnico."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Fiscal</mark></span>El <span class=\"ref-norma\">5.2.1.b de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"y también, si se aprecia una posible situación de desamparo, en conocimiento del Fiscal\"</span>. Si se aprecia desamparo se pone en conocimiento del Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1528","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Antes de recoger la declaración del menor víctima se realizarán actuaciones de preparación en las que corresponderá recabar la mayor información posible sobre el menor y el hecho delictivo, y, en la medida de lo posible, la declaración ha de ser realizada por:","o":["funcionarios de la unidad que practicó la detención.","funcionarios especializados en tratamiento policial a menores.","personal del equipo técnico.","psicólogos de la Oficina de Asistencia a las Víctimas, salvo que la autoridad judicial disponga otra cosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">funcionarios especializados en tratamiento policial a menores</mark></span>El <span class=\"ref-norma\">5.3.1.b de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"dicha declaración ha de ser realizada por funcionarios especializados en tratamiento policial a menores\"</span>. La declaración la realizan funcionarios especializados en tratamiento policial a menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1538","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. La entrevista de las víctimas menores de delitos contra la libertad o indemnidad sexual se realizará en dependencias adaptadas y por la misma persona, salvo que ello pueda perjudicar el desarrollo del proceso o se deba tomar directamente por:","o":["un equipo técnico.","psicólogos especializados.","la unidad de Policía Judicial.","un Juez o un Fiscal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un Juez o un Fiscal</mark></span>El <span class=\"ref-norma\">5.3.1.h de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"salvo que ello pueda perjudicar el desarrollo del proceso o se deba tomar directamente por un Juez o un Fiscal\"</span>. La excepción es que se deba tomar directamente por un Juez o un Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1543","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Se informará a los menores víctimas de su derecho a acceder, de forma gratuita y confidencial, a los servicios de las Oficinas de Asistencia a las Víctimas, y a ser derivado a dichas oficinas cuando resulte necesario en atención a la gravedad del delito o en aquellos casos en los que:","o":["lo solicite el Fiscal.","lo soliciten sus representantes legales.","el propio menor lo solicite.","se aprecie riesgo de desamparo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el propio menor lo solicite</mark></span>El <span class=\"ref-norma\">5.3.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"o en aquellos casos en los que el propio menor lo solicite\"</span>. Se deriva también cuando el propio menor lo solicite. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1546","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Señale la INCORRECTA sobre los casos en los que los agentes podrán elevar al Ministerio Fiscal la conveniencia de designar un defensor judicial de la víctima menor de edad:","o":["Cuando se valore que puede tener con los representantes un conflicto de intereses, derivado o no del hecho investigado.","Cuando exista un conflicto con uno de los progenitores y el otro no se encuentre en condiciones de ejercer adecuadamente sus funciones de representación y asistencia.","Cuando no esté acompañada o no se encuentre a quienes ejerzan la patria potestad o cargos tutelares.","Cuando la víctima menor de edad sea mayor de catorce años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando la víctima menor de edad sea mayor de catorce años</mark></span>El <span class=\"ref-norma\">5.3.7 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Cuando se valore que puede tener con los mismos un conflicto de intereses, derivado o no del hecho investigado que no permita confiar en una gestión adecuada de sus intereses. b. Cuando exista un conflicto con uno de los progenitores\"</span>. Los casos son conflicto de intereses, conflicto con un progenitor sin otro idóneo, y ausencia de quienes ejerzan la patria potestad; no la edad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1604","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores infractores a la normativa de seguridad ciudadana. Al requerir la identidad de un menor y realizar un control superficial sobre sus efectos personales, se pondrá lo antes posible en conocimiento de quienes ejerzan la patria potestad, la tutela o la guarda de hecho siempre que de las circunstancias del entorno o de los hechos que originan la intervención pueda deducirse que:","o":["el menor ha cometido una infracción.","existe riesgo para el menor.","el menor porta sustancias prohibidas.","el menor se niega a identificarse."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">existe riesgo para el menor</mark></span>El <span class=\"ref-norma\">6.1.6 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"siempre que de las circunstancias del entorno o de los hechos que originan la intervención pueda deducirse que existe riesgo para el menor\"</span>. Solo si puede deducirse que existe riesgo para el menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1605","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores infractores a la normativa de seguridad ciudadana. El registro corporal externo y superficial de los menores no detenidos podrá practicarse cuando existan indicios racionales suficientes para suponer que pueda conducir al hallazgo de instrumentos, efectos u otros objetos relevantes para el ejercicio de las funciones de:","o":["indagación y prevención que encomiendan las leyes a las Fuerzas y Cuerpos de Seguridad.","investigación y persecución que encomiendan las leyes a las Fuerzas y Cuerpos de Seguridad.","prevención y protección que encomiendan las leyes a las Fuerzas y Cuerpos de Seguridad.","control e inspección que encomiendan las leyes a las Fuerzas y Cuerpos de Seguridad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">indagación y prevención que encomiendan las leyes a las Fuerzas y Cuerpos de Seguridad</mark></span>El <span class=\"ref-norma\">6.1.7 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"relevantes para el ejercicio de las funciones de indagación y prevención que encomiendan las leyes a las Fuerzas y Cuerpos de Seguridad\"</span>. Las funciones son de indagación y prevención. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1627","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. El delito de stalking requiere denuncia previa del agraviado o de su representante legal, bastando en caso de menores o discapacitados:","o":["denuncia de la policía.","denuncia del centro escolar.","denuncia del Ministerio Fiscal.","denuncia de los servicios sociales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">denuncia del Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">7.2.3.c de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"bastando en caso de menores o discapacitados denuncia del Ministerio Fiscal\"</span>. En menores o discapacitados basta la denuncia del Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1632","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores en situación de riesgo o desamparo. Ante un menor en aparente situación de riesgo se prestará asistencia inmediata, se averiguarán las causas de su situación y se dará cuenta inmediata al Ministerio Fiscal y al servicio competente en materia de protección de menores, haciéndoles entrega del menor:","o":["en todo caso.","en los casos en que proceda o así lo disponga el Fiscal.","previa autorización del Juez.","cuando lo soliciten los padres, previo informe de la unidad policial competente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en los casos en que proceda o así lo disponga el Fiscal</mark></span>El <span class=\"ref-norma\">8.1.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"haciéndoles entrega del menor en los casos en que proceda o así lo disponga el Fiscal\"</span>. La entrega es en los casos en que proceda o así lo disponga el Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1634","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores en situación de riesgo o desamparo. A efectos de determinación de edad e identificación civil, se obtendrá la correspondiente reseña en aquellos casos de:","o":["menores extranjeros no acompañados, salvo que la autoridad judicial disponga otra cosa.","menores detenidos por delitos.","menores en situación de riesgo.","personas indocumentadas cuya minoría de edad no esté acreditada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">personas indocumentadas cuya minoría de edad no esté acreditada</mark></span>El <span class=\"ref-norma\">8.1.4 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"se obtendrá la correspondiente reseña en aquellos casos de personas indocumentadas cuya minoría de edad no esté acreditada\"</span>. Se reseña a personas indocumentadas cuya minoría de edad no esté acreditada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1643","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación con menores extranjeros no acompañados. Cuando la minoría de edad del menor extranjero sea indubitada, se realizarán las diligencias de reseña dactilar y cotejo del RMENA, procediendo a inscribirlo si no lo estuviera, y en cualquier caso se hará entrega inmediata del menor a:","o":["la Delegación o Subdelegación del Gobierno.","el Ministerio Fiscal.","la Entidad pública de protección de menores del lugar de localización.","la Brigada Provincial de Extranjería y Fronteras, en los términos que se determinen reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Entidad pública de protección de menores del lugar de localización</mark></span>El <span class=\"ref-norma\">8.2.5 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"se hará entrega inmediata del menor a la Entidad pública de protección de menores del lugar de localización\"</span>. Entrega inmediata a la Entidad pública de protección de menores del lugar de localización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1645","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación con menores extranjeros no acompañados. Una vez determinada la minoría de edad y puesto a disposición de los servicios de protección de menores de la Comunidad Autónoma, el órgano competente para los trámites relativos a la repatriación del menor extranjero no acompañado será:","o":["la Delegación y Subdelegación del Gobierno del territorio donde se halle el domicilio del menor.","la Entidad pública de protección de menores.","el Ministerio Fiscal.","la Brigada Provincial de Extranjería y Fronteras, sin perjuicio de lo previsto en la normativa vigente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Delegación y Subdelegación del Gobierno del territorio donde se halle el domicilio del menor</mark></span>El <span class=\"ref-norma\">8.2.8 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"el órgano competente para llevar a cabo los trámites relativos a la repatriación del menor extranjero no acompañado será la Delegación y Subdelegación del Gobierno del territorio donde se halle el domicilio del menor\"</span>. La competente es la Delegación y Subdelegación del Gobierno del domicilio del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1646","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación con menores extranjeros no acompañados. En caso de localización de un menor extranjero no acompañado al que le sea aplicable el régimen jurídico de la Unión Europea se pondrá en conocimiento inmediato de:","o":["la Delegación o Subdelegación del Gobierno.","el Consulado del Estado de que se trate.","la entidad pública de protección de menores, en los términos que se determinen reglamentariamente.","la correspondiente Brigada Provincial de Extranjería y Fronteras de la Policía Nacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la correspondiente Brigada Provincial de Extranjería y Fronteras de la Policía Nacional</mark></span>El <span class=\"ref-norma\">8.2.12 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"se pondrá en conocimiento inmediato de la correspondiente Brigada Provincial de Extranjería y Fronteras de la Policía Nacional\"</span>. Se pone en conocimiento inmediato de la Brigada Provincial de Extranjería y Fronteras. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1649","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores desaparecidos. La declaración provisional de la desaparición de un menor como de alto riesgo deberá ratificarse, a la mayor brevedad, por:","o":["la Unidad Central de Policía Judicial competente en cada Cuerpo policial.","el Centro Nacional de Desaparecidos, en los términos que se determinen reglamentariamente.","el Ministerio Fiscal.","la Unidad receptora de la denuncia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Unidad Central de Policía Judicial competente en cada Cuerpo policial</mark></span>El <span class=\"ref-norma\">9.1.4 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"deberá ratificarse, a la mayor brevedad, por la Unidad Central de Policía Judicial competente en cada Cuerpo policial\"</span>. La ratifica la Unidad Central de Policía Judicial competente de cada Cuerpo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1653","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores desaparecidos. Localizado el menor desaparecido y puesto a salvo de situaciones de riesgo, será entregado, a la mayor brevedad, a la persona o entidad encargada de su guarda o custodia o, en su defecto, a:","o":["quien indique la Fiscalía.","quien indique el Juez de Menores.","la entidad pública de protección.","la autoridad reclamante."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">quien indique la Fiscalía</mark></span>El <span class=\"ref-norma\">9.2.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"o, en su defecto, a quién indique la Fiscalía\"</span>. En su defecto, a quien indique la Fiscalía. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1658","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Registros policiales de datos personales de menores. Señale la INCORRECTA. En el Libro-Registro de actuaciones con Menores e Incapaces en Situaciones de Riesgo se anotarán las actuaciones policiales con:","o":["menores de edad inferior a catorce años presuntamente responsables de la comisión de infracciones penales.","menores de dieciocho años en situación de riesgo o desamparo, incluyendo los fugados del domicilio familiar o institucional y los desaparecidos por distintas causas.","personas con discapacidad intelectual necesitadas de especial protección, sean mayores o menores de edad.","menores de edad entre catorce y dieciocho años presuntamente responsables de infracciones penales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">menores de edad entre catorce y dieciocho años presuntamente responsables de infracciones penales</mark></span>El <span class=\"ref-norma\">10.2.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"a. Menores de edad inferior a catorce años presuntamente responsables de la comisión de infracciones penales. b. Menores de dieciocho años en situación de riesgo o desamparo\"</span>. Los de entre catorce y dieciocho años se anotan en el Libro-Registro de Menores Detenidos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1661","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Registros policiales de datos personales de menores. El Registro de Menores Extranjeros No Acompañados (RMENA) está ubicado en el subfichero de la aplicación ADEXTRA cuya titularidad corresponde a la Dirección General de la Policía, y su gestión a:","o":["la Comisaría General de Extranjería y Fronteras.","la Comisaría General de Policía Judicial.","la Secretaría de Estado de Seguridad.","la Brigada Provincial de Extranjería y Fronteras."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Comisaría General de Extranjería y Fronteras</mark></span>El <span class=\"ref-norma\">10.3.5 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"cuya titularidad corresponde a la Dirección General de la Policía, y su gestión a la Comisaría General de Extranjería y Fronteras\"</span>. La titularidad es de la Dirección General de la Policía y la gestión de la Comisaría General de Extranjería y Fronteras. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Instrucciones (texto leído en la imagen de tu temario subrayado)","q":[{"i":"17-18","p":"Instrucción 1/2017. ¿Cuándo entró en vigor esta instrucción?","o":["A los veinte días de su publicación.","Al día siguiente de su publicación.","Al mes de su publicación.","A los dos meses de su publicación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al día siguiente de su publicación</mark></span>Texto leído en la imagen de la pág. 47 de tu temario subrayado. Según el <span class=\"ref-norma\">Instrucciones, cuarta de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"La presente Instrucción surtirá plenos efectos a partir del día siguiente de su publicación\"</span> (verificado con el temario oficial)."},{"i":"17-19","p":"Instrucción 1/2017. La instrucción 1/2017 deroga:","o":["La Orden de la Secretaría de Estado de Seguridad 11/2004, de 12 de octubre.","La Orden de la Secretaría de Estado de Seguridad 11/2007, de 12 de septiembre.","La Instrucción de la Secretaría de Estado de Seguridad 11/2007, de 12 de septiembre.","La Instrucción de la Secretaría de Estado de Seguridad 11/2004, de 3 de octubre."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Instrucción de la Secretaría de Estado de Seguridad 11/2007, de 12 de septiembre.</mark></span>*Explicación: La Disposición Derogatoria Única de la Instrucción 1/2017 deroga expresamente la Instrucción 11/2007, de 12 de septiembre.*"},{"i":"17-ia-1501","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Derogación. Todas las referencias efectuadas al Protocolo de Actuación Policial con Menores contenidas en normas anteriores de igual o inferior rango se entenderán realizadas en lo sucesivo:","o":["a este texto.","a la Instrucción 11/2007, de 12 de septiembre.","a la Ley Orgánica 5/2000, de 12 de enero.","al Real Decreto 1774/2004, de 30 de julio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a este texto</mark></span>El <span class=\"ref-norma\">Instrucción tercera de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Todas las referencias efectuadas al Protocolo de Actuación Policial con Menores contenidas en normas anteriores de igual o inferior rango se entenderán realizadas en lo sucesivo a este texto\"</span>. Las referencias al protocolo anterior pasan a entenderse hechas a este texto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 5 — Modo de llevar a cabo las soluciones extrajudiciales EX","q":[{"i":"17-22","p":"Real Decreto 1774/2004. Modo de llevar a cabo las soluciones extrajudiciales. Señale la opción incorrecta:","o":["Recibida la solicitud por el equipo técnico, cita a su presencia al menor, a sus representantes legales y a su letrado defensor.","El equipo técnico expondrá al menor la posibilidad de solución en materia de protección de los menores.","Si la víctima fuese menor de edad o incapaz, este consentimiento deberá ser confirmado por sus representantes legales y ser puesto en conocimiento del juez de menores competente.","No siendo posible la conciliación o la reparación directa o social, o cuando el equipo técnico lo considere más adecuado al interés del menor, proponer la realización de tareas socioeducativas o la prestación de servicios en beneficio de la comunidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El equipo técnico expondrá al menor la posibilidad de solución en materia de protección de los menores</mark></span>C también estaba alterada («fiscal de menores»); la incorrecta sigue siendo B. Según el <span class=\"ref-norma\">art. 5.1.d) de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"Si la víctima fuese menor de edad o incapaz, este consentimiento deberá ser confirmado por sus representantes legales y ser puesto en conocimiento del juez de menores competente\"</span> (verificado con el temario oficial)."},{"i":"17-54","p":"Real Decreto 1774/2004. Si el Ministerio Fiscal, a la vista de las circunstancias concurrentes o a instancia del letrado del menor, apreciara la posibilidad de desistir de la continuación del expediente:","o":["Solicitará del equipo técnico informe sobre la conveniencia de adoptar la solución extrajudicial más adecuada al interés del menor y al de la víctima.","Citará a su presencia al menor, a sus representantes legales y a su letrado defensor.","Preguntará a la víctima si está conforme en participar en la mediación.","El equipo técnico propondrá al menor la posibilidad de solución extrajudicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Solicitará del equipo técnico informe sobre la conveniencia de adoptar la solución extrajudicial más adecuada al interés del menor y al de …</mark></span><span class=\"ref-norma\">Art. 24.1 · Real Decreto 1774/2004</span>. *Explicación: El artículo 24.1 del RD 1774/2004 establece que el Fiscal solicitará informe al equipo técnico sobre la conveniencia de la solución extrajudicial.*"},{"i":"17-ia-1432","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo las soluciones extrajudiciales. En las soluciones extrajudiciales, recibida la solicitud por el equipo técnico, éste citará a su presencia:","o":["al menor y a la víctima.","al menor, a sus representantes legales y a su letrado defensor.","al menor y a sus representantes legales, sin su letrado, en los términos que se determinen reglamentariamente.","al menor, a la víctima y al Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al menor, a sus representantes legales y a su letrado defensor</mark></span>El <span class=\"ref-norma\">art. 5.1.b de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"citará a su presencia al menor, a sus representantes legales y a su letrado defensor\"</span>. Cita al menor, a sus representantes legales y a su letrado defensor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1433","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo las soluciones extrajudiciales. Si, con audiencia de su letrado, el menor aceptara alguna de las soluciones que el equipo técnico le propone, a ser posible en el mismo acto, se recabará:","o":["la conformidad de sus representantes legales.","la conformidad del Ministerio Fiscal, salvo que la autoridad judicial disponga otra cosa.","la aprobación del Juez de Menores.","la conformidad de la víctima."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la conformidad de sus representantes legales</mark></span>El <span class=\"ref-norma\">art. 5.1.c de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"a ser posible en el mismo acto, se recabará la conformidad de sus representantes legales\"</span>. Se recaba la conformidad de sus representantes legales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1434","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo las soluciones extrajudiciales. Si el menor o sus representantes legales manifestaran su negativa a aceptar una solución extrajudicial, el equipo técnico lo comunicará al Ministerio Fiscal e iniciará:","o":["la mediación con la víctima.","el archivo de las actuaciones, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","la propuesta de medidas.","la elaboración del informe previsto en la Ley Orgánica 5/2000 para la instrucción."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la elaboración del informe previsto en la Ley Orgánica 5/2000 para la instrucción</mark></span>El <span class=\"ref-norma\">art. 5.1.c de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"el equipo técnico lo comunicará al Ministerio Fiscal e iniciará la elaboración del informe al que alude el artículo 27 de la Ley Orgánica 5/2000\"</span>. Ante la negativa se inicia la elaboración del informe del equipo técnico de la instrucción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1435","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo las soluciones extrajudiciales. El equipo técnico se pondrá en contacto con la víctima para que manifieste su conformidad o disconformidad a participar en un procedimiento de mediación, ya sea a través de comparecencia personal ante el equipo técnico, ya sea por cualquier otro medio que:","o":["garantice su identidad, en los términos que se determinen reglamentariamente.","autorice el Fiscal.","permita dejar constancia.","sea presencial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">permita dejar constancia</mark></span>El <span class=\"ref-norma\">art. 5.1.d de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"ya sea por cualquier otro medio que permita dejar constancia\"</span>. Cualquier medio que permita dejar constancia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1436","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo las soluciones extrajudiciales. Si la víctima fuese menor de edad o incapaz, el consentimiento para participar en la mediación deberá ser confirmado por sus representantes legales y ser puesto en conocimiento del:","o":["Ministerio Fiscal, salvo que la autoridad judicial disponga otra cosa.","juez de menores competente.","equipo técnico.","letrado del menor."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">juez de menores competente</mark></span>El <span class=\"ref-norma\">art. 5.1.d de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"este consentimiento deberá ser confirmado por sus representantes legales y ser puesto en conocimiento del juez de menores competente\"</span>. Se pone en conocimiento del juez de menores competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1437","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo las soluciones extrajudiciales. Si la víctima se mostrase conforme a participar en la mediación, el equipo técnico citará a ambos a un encuentro para concretar los acuerdos de conciliación o reparación. No obstante, estos podrán llevarse a cabo sin encuentro, a petición de:","o":["la víctima, por cualquier otro medio que permita dejar constancia de los acuerdos.","el menor, por escrito ante el equipo técnico.","el Ministerio Fiscal, por cualquier medio.","el equipo técnico, con el consentimiento del Fiscal, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la víctima, por cualquier otro medio que permita dejar constancia de los acuerdos</mark></span>El <span class=\"ref-norma\">art. 5.1.e de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"también podrán llevarse a cabo sin encuentro, a petición de la víctima, por cualquier otro medio que permita dejar constancia de los acuerdos\"</span>. Sin encuentro, a petición de la víctima. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1438","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo las soluciones extrajudiciales. No siendo posible la conciliación o la reparación directa o social, o cuando el equipo técnico lo considere más adecuado al interés del menor, propondrá a este la realización de:","o":["una amonestación o tareas socioeducativas.","libertad vigilada o prestaciones en beneficio de la comunidad, sin perjuicio de lo previsto en la normativa vigente.","tratamiento ambulatorio o tareas socioeducativas.","tareas socioeducativas o la prestación de servicios en beneficio de la comunidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tareas socioeducativas o la prestación de servicios en beneficio de la comunidad</mark></span>El <span class=\"ref-norma\">art. 5.1.f de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"propondrá a este la realización de tareas socioeducativas o la prestación de servicios en beneficio de la comunidad\"</span>. Propone tareas socioeducativas o prestación de servicios en beneficio de la comunidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1439","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo las soluciones extrajudiciales. El equipo técnico pondrá en conocimiento del Ministerio Fiscal el resultado del proceso de mediación, los acuerdos alcanzados por las partes y su grado de cumplimiento o, en su caso, los motivos por los que:","o":["la víctima rechazó la mediación.","el menor incumplió la medida impuesta, en los términos que se determinen reglamentariamente.","no han podido llevarse a efecto los compromisos alcanzados por las partes.","no se alcanzó acuerdo alguno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no han podido llevarse a efecto los compromisos alcanzados por las partes</mark></span>El <span class=\"ref-norma\">art. 5.1.g de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"o, en su caso, los motivos por los que no han podido llevarse a efecto los compromisos alcanzados por las partes\"</span>. Informa de los motivos por los que no se llevaron a efecto los compromisos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1441","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Modo de llevar a cabo las soluciones extrajudiciales. Las referencias al equipo técnico hechas en el precepto sobre soluciones extrajudiciales se entenderán efectuadas a la entidad pública cuando dicha entidad realice las funciones de:","o":["mediación.","ejecución de medidas.","protección.","informe."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">mediación</mark></span>El <span class=\"ref-norma\">art. 5.3 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"dicha entidad realice las funciones de mediación\"</span>. Se entienden efectuadas a la entidad pública cuando esta realice las funciones de mediación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"5.1. Protección de la víctima menor de edad EX","q":[{"i":"17-25","p":"Instrucción 1/2017. Protección de la víctima menor de edad. En las distintas dependencias policiales en las que se desarrollen diligencias con víctimas menores de edad, se evitará entre éstas y sus familiares, de una parte, y el investigado por la comisión del ilícito penal, de otra:","o":["El contacto directo.","El contacto, aunque sea indirecto.","La interacción.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El contacto directo</mark></span>Según el <span class=\"ref-norma\">punto 5.1.2 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"se evitará el contacto directo entre éstas y sus familiares\"</span> (verificado con el temario oficial)."},{"i":"17-45","p":"Instrucción 1/2017. Protección de la víctima menor de edad. Indique la CORRECTA:","o":["En la dependencia policial se evitará el contacto directo entre éstas y sus familiares, de una parte, y el investigado por la comisión del ilícito penal, de otra.","El interés superior del menor debe actuar a modo de guía en cualquier medida o decisión que haya de tomarse en relación con las mismas.","Todo menor víctima de delitos cometidos en España o que puedan ser perseguidos por su jurisdicción tiene los derechos recogidos en la Ley 4/2015, del Estatuto de la víctima del delito.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span>*Explicación: Todas las afirmaciones son principios y derechos recogidos en la Instrucción 1/2017 para la protección de menores víctimas.*"},{"i":"17-201","p":"Instrucción nº 1/2017 de la Secretaría de Estado de Seguridad, por la que se actualiza el protocolo de actuación policial con menores. Atención policial al menor, víctima o testigo. ¿Qué documento regula la intervención contra el maltrato infantil en el ámbito familiar?","o":["La Ley Orgánica 5/2000 sobre responsabilidad penal de menores.","El Código Penal.","La Oficialía 5/2000 sobre menores infractores.","El Protocolo básico de intervención contra el maltrato infantil en el ámbito familiar."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Protocolo básico de intervención contra el maltrato infantil en el ámbito familiar.</mark></span>El Protocolo básico de intervención contra el maltrato infantil."},{"i":"17-ia-1520","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Atención policial al menor víctima o testigo. Protección de la víctima menor de edad. Cuando se trate de menores, su interés superior debe actuar:","o":["como criterio preferente sobre el interés público general, salvo que la autoridad judicial disponga otra cosa.","a modo de guía en cualquier medida o decisión que haya de tomarse en relación con los mismos.","como límite de las actuaciones de investigación.","como principio subsidiario cuando no haya norma aplicable."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a modo de guía en cualquier medida o decisión que haya de tomarse en relación con los mismos</mark></span>El <span class=\"ref-norma\">5.1.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"su interés superior debe actuar a modo de guía en cualquier medida o decisión que haya de tomarse en relación con los mismos\"</span>. Actúa a modo de guía en cualquier medida o decisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1522","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Atención policial al menor víctima o testigo. Protección de la víctima menor de edad. Todos los funcionarios que intervengan en actuaciones con víctimas menores adoptarán las medidas necesarias para garantizar sus derechos y su protección, evitando la posibilidad de su victimización secundaria o reiterada, dispensándoles un trato:","o":["respetuoso, profesional, uniforme y no discriminatorio, previo informe de la unidad policial competente.","cercano, profesional, individualizado y confidencial.","respetuoso, urgente, individualizado y reservado.","respetuoso, profesional, individualizado y no discriminatorio."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">respetuoso, profesional, individualizado y no discriminatorio</mark></span>El <span class=\"ref-norma\">5.1.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"dispensándoles un trato respetuoso, profesional, individualizado y no discriminatorio\"</span>. El trato es respetuoso, profesional, individualizado y no discriminatorio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1523","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Atención policial al menor víctima o testigo. Protección de la víctima menor de edad. Durante las entrevistas o exploraciones a víctimas menores resultará de vital importancia establecer una relación empática con el menor para transmitirle confianza y seguridad, debiéndose adecuar el ritmo de la exploración a su capacidad de atención y fatiga, así como utilizar un lenguaje adaptado a:","o":["su edad y grado de madurez.","su nivel educativo y estado emocional.","su edad y estado emocional.","su edad y entorno familiar."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">su edad y estado emocional</mark></span>El <span class=\"ref-norma\">5.1.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"así como utilizar un lenguaje adaptado a su edad y estado emocional\"</span>. El lenguaje se adapta a su edad y estado emocional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RECUERDA del temario · RD 1774/2004 (R8 y R9) R8 R9","q":[{"i":"17-26","p":"Real Decreto 1774/2004. Los profesionales integrantes de los equipos técnicos estarán adscritos:","o":["Al Ministerio de Justicia.","A las comunidades autónomas con competencias asumidas.","A los juzgados de menores.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A los juzgados de menores</mark></span>Dependen orgánicamente del Ministerio de Justicia o de las comunidades autónomas y están adscritos a los juzgados de menores. Según el <span class=\"ref-norma\">art. 4.2 de la Real Decreto 1774/2004</span>: <span class=\"ref-concepto\">\"y estarán adscritos a los juzgados de menores\"</span> (verificado con el temario oficial)."},{"i":"17-228","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la actuación de la Policía Judicial y del equipo técnico. ¿Desde qué momento los equipos técnicos deben prestar asistencia profesional al menor?","o":["Desde la primera comparecencia ante el juez.","Desde que el Ministerio Fiscal lo requiera.","Desde el momento de su detención.","Tras ser declarado culpable."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Desde el momento de su detención.</mark></span>- La asistencia comienza desde el momento de la detención."},{"i":"17-276","p":"(RD 1774/2004 - Reglamento LORPM) Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Actuación del Equipo Técnico. Los profesionales integrantes de los equipos técnicos:","o":["Dependerán orgánicamente del Ministerio de Justicia o de las comunidades autónomas con competencias asumidas.","Estarán adscritos a los Juzgados de lo Penal.","Antes de la instrucción del expediente, desempeñarán las funciones establecidas en la Ley Orgánica 5/2000, de 12 de enero, bajo la dependencia orgánica del Ministerio Fiscal y del Juez de menores.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dependerán orgánicamente del Ministerio de Justicia o de las comunidades autónomas con competencias asumidas.</mark></span><span class=\"ref-norma\">Art. 47 · Real Decreto 1774/2004</span>. El Reglamento (Art. 47) establece la dependencia orgánica del Ministerio de Justicia o las Comunidades Autónomas. La opción b) es incorrecta (se adscriben a los Juzgados de Menores, no de lo Penal) y la c) es incorrecta porque la dependencia orgánica no es del Fiscal y Juez."}]},{"a":"Artículo 25 — De la acusación particular EX","q":[{"i":"17-27","p":"Ley Orgánica 5/2000. Podrán personarse en el procedimiento como acusadores particulares, a salvo de las acciones previstas por el artículo 61 de esta ley, las personas directamente ofendidas por el delito, sus padres, sus herederos o sus representantes legales si fueran menores de edad o incapaces, con las facultades y derechos que derivan de ser parte en el procedimiento, entre los que están, entre otros, los siguientes:","o":["Impugnar la imposición de las medidas cautelares a las que se refiere esta ley.","Tener constancia de lo actuado, siendo oídos en las diligencias que se soliciten y asuman.","Ejercitar la acusación popular durante el procedimiento.","Participar en la práctica de las pruebas, ya sea en fase de instrucción y ya sea en fase de audiencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Participar en la práctica de las pruebas, ya sea en fase de instrucción y ya sea en fase de audiencia.</mark></span><span class=\"ref-norma\">Art. 28 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 28 de la LO 5/2000 enumera los derechos de las partes, incluyendo el derecho a participar en la práctica de las pruebas tanto en la fase de instrucción como en la audiencia.*"},{"i":"17-93","p":"Ley Orgánica 5/2000. De la acusación particular. ¿Quiénes podrán personarse en el procedimiento como acusadores particulares?:","o":["Personas ofendidas por el delito, directa o indirectamente.","Personas directa o indirectamente ofendidas por el delito, sus padres, sus herederos o sus representantes legales si fueran menores de edad o incapaces.","Personas directa o indirectamente ofendidas por el delito, sus familiares hasta tercer grado de consanguinidad o afines, sus herederos o sus representantes legales si fueran menores de edad o incapaces.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Personas directa o indirectamente ofendidas por el delito, sus padres, sus herederos o sus representantes legales si fueran menores de edad o incapaces</mark></span>Son las personas «directamente» ofendidas, no «directa o indirectamente». Según el <span class=\"ref-norma\">art. 25 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"las personas directamente ofendidas por el delito, sus padres, sus herederos o sus representantes legales si fueran menores de edad o incapaces\"</span> (verificado con el temario oficial)."},{"i":"17-154","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. De la acusación particular. Como acusadores particulares, ¿qué facultades y derechos NO derivan de ser parte en el procedimiento?","o":["Ejercicio de acusación particular durante el procedimiento.","El derecho a la última palabra en la vista, después de las intervenciones de las demás partes.","Tener vista de lo actuado, siendo notificado de las diligencias que se soliciten y acuerden.","Participar en las vistas o audiencias que se celebren."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El derecho a la última palabra en la vista, después de las intervenciones de las demás partes</mark></span>El derecho a la última palabra no figura entre las facultades del acusador particular. Según el <span class=\"ref-norma\">art. 25.c) de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"c) Tener vista de lo actuado, siendo notificado de las diligencias que se soliciten y acuerden\"</span> (verificado con el temario oficial)."},{"i":"17-ia-1305","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la acusación particular. Podrán personarse como acusadores particulares las personas directamente ofendidas por el delito, sus padres, sus herederos o sus representantes legales si fueran:","o":["menores de edad o incapaces.","menores de dieciocho años.","incapaces o ausentes.","menores de catorce años o incapaces."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">menores de edad o incapaces</mark></span>El <span class=\"ref-norma\">art. 25 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"sus padres, sus herederos o sus representantes legales si fueran menores de edad o incapaces\"</span>. Los representantes legales se personan si los ofendidos fueran menores de edad o incapaces. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1306","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la acusación particular. El acusador particular podrá proponer pruebas que versen sobre el hecho delictivo y las circunstancias de su comisión, salvo en lo referente a:","o":["la responsabilidad civil derivada del delito, salvo que la autoridad judicial disponga otra cosa.","la participación del menor en los hechos.","las medidas cautelares.","la situación psicológica, educativa, familiar y social del menor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la situación psicológica, educativa, familiar y social del menor</mark></span>El <span class=\"ref-norma\">art. 25.d de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"salvo en lo referente a la situación psicológica, educativa, familiar y social del menor\"</span>. Queda excluida la prueba sobre la situación psicológica, educativa, familiar y social del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1307","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la acusación particular. El acusador particular podrá participar en la práctica de las pruebas, en fase de instrucción o de audiencia; el órgano actuante podrá denegar la prueba de careo, si fuera solicitada, cuando:","o":["el menor se oponga a ella.","lo informe en contra el equipo técnico, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","no resulte fundamental para la averiguación de los hechos o la participación del menor en los mismos.","ya hubiera declarado el menor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no resulte fundamental para la averiguación de los hechos o la participación del menor en los mismos</mark></span>El <span class=\"ref-norma\">art. 25.e de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"podrá denegar la práctica de la prueba de careo, si esta fuera solicitada, cuando no resulte fundamental para la averiguación de los hechos o la participación del menor en los mismos\"</span>. El careo se puede denegar si no resulta fundamental para averiguar los hechos o la participación del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1308","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la acusación particular. Una vez admitida por el Juez de Menores la personación del acusador particular, se le dará traslado de:","o":["el informe del equipo técnico.","todas las actuaciones sustanciadas de conformidad con esta ley.","el escrito de alegaciones del Ministerio Fiscal.","las actuaciones de la pieza separada de responsabilidad civil, en los términos que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">todas las actuaciones sustanciadas de conformidad con esta ley</mark></span>El <span class=\"ref-norma\">art. 25 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"se le dará traslado de todas las actuaciones sustanciadas de conformidad con esta ley y se le permitirá intervenir en todos los trámites en defensa de sus intereses\"</span>. Se le da traslado de todas las actuaciones y puede intervenir en todos los trámites. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1309","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la acusación particular. Señale la INCORRECTA sobre las facultades del acusador particular:","o":["Proponer pruebas sobre la situación psicológica, educativa, familiar y social del menor.","Ser oído en todos los incidentes que se tramiten durante el procedimiento.","Ser oído en caso de modificación o de sustitución de medidas impuestas al menor, salvo que la autoridad judicial disponga otra cosa.","Participar en las vistas o audiencias que se celebren."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Proponer pruebas sobre la situación psicológica, educativa, familiar y social del menor</mark></span>El <span class=\"ref-norma\">art. 25 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Proponer pruebas que versen sobre el hecho delictivo y las circunstancias de su comisión, salvo en lo referente a la situación psicológica, educativa, familiar y social del menor\"</span>. La prueba sobre la situación psicológica, educativa, familiar y social del menor queda excluida. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"7.2. Actuación específica en casos de acoso escolar","q":[{"i":"17-29","p":"Actuación específica en casos de acoso escolar. En las actuaciones policiales relacionadas con casos de acoso escolar deberán tomarse en consideración las siguientes cuestiones:","o":["Todas las modalidades de acoso son actos agresivos en sentido estricto.","El hogar constituye el primer lugar de lucha contra el acoso escolar.","El juzgado competente es el encargado de revisar el plan de protección de los colegios.","Ninguna es correcta."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ninguna es correcta.</mark></span>*Explicación: Las opciones a, b y c contienen afirmaciones incorrectas o imprecisas respecto al protocolo de actuación policial en casos de acoso escolar.*"},{"i":"17-80","p":"Instrucción 1/2017. Actuación específica en casos de acoso escolar. Los actos de acoso escolar o \"bullying\" pueden constituir delito de trato degradante del artículo 173.1 del Código Penal cuando:","o":["Tengan entidad suficiente para producir un menoscabo grave de la integridad moral de la víctima.","Impliquen actos de humillación de carácter reiterado que, sin llegar a constituir trato degradante, supongan grave acoso.","Impliquen actos de humillación de carácter reiterado que, constituyendo trato degradante, supongan grave acoso.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>A omitía el adjetivo «grave». Según el <span class=\"ref-norma\">punto 7.2.3.a de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"cuando tengan entidad suficiente para producir un menoscabo grave de la integridad moral de la víctima, o impliquen actos de humillación de carácter reiterado que, sin llegar a constituir trato degradante, supongan grave acoso\"</span> (verificado con el temario oficial)."},{"i":"17-96","p":"Instrucción 1/2017. Actuación específica en casos de acoso escolar. En las actuaciones policiales relacionadas con casos de acoso escolar deberán tomarse en consideración las siguientes cuestiones: señale la INCORRECTA.","o":["Todas las modalidades de acoso son actos agresivos en sentido estricto, ya sean físicos o verbales, y no pueden ser constitutivas de infracción penal.","Los centros educativos constituyen el primer lugar de lucha contra el acoso escolar.","Debe comunicarse al Ministerio Fiscal incluso los supuestos de relevancia penal mínima.","Es posible que el fenómeno del acoso pueda pasar desapercibido para los adultos y que no deje huella física susceptible de objetivación, por lo que es importante realizar un acopio suficiente de elementos probatorios."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Todas las modalidades de acoso son actos agresivos en sentido estricto, ya sean físicos o verbales, y no pueden ser constitutivas de infracción penal</mark></span>A pasa a ser la incorrecta: C es el texto literal de la Instrucción. Según el <span class=\"ref-norma\">punto 7.2.2 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"b. Todas las modalidades de acoso son actos agresivos en sentido amplio, ya sean físicos, verbales o psicológicos, y pueden ser constitutivas de infracción penal\"</span> (verificado con el temario oficial)."},{"i":"17-144","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Actuación específica en casos de acoso escolar. En las actuaciones policiales relacionadas con casos de acoso escolar deberán tomarse en consideración las siguientes cuestiones:","o":["Deben comunicarse al Ministerio Fiscal incluso los supuestos de relevancia penal mínima, evitando trivializar o banalizar los hechos. Aunque el autor o autores del posible acoso sean menores de catorce años, se participarán las circunstancias del hecho al Ministerio Fiscal para conocimiento.","Todas las modalidades de acoso son actos agresivos en sentido amplio, ya sean físicos, verbales o psicológicos, y pueden ser constitutivas de infracción penal.","La respuesta policial debe ser individualizada para cada acosador, delimitando posibles delitos contra la integridad moral, amenazas, lesiones, homicidio, inducción al suicidio, delitos cometidos con ocasión del ejercicio de los derechos fundamentales y de las libertades públicas u otros.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">punto 7.2.2 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"Aunque el autor o autores del posible acoso sean menores de catorce años, se participarán las circunstancias del hecho al Ministerio Fiscal para conocimiento\"</span> (verificado con el temario oficial)."},{"i":"17-187","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Menores en entorno escolar. Actuación específica en casos de acoso escolar. En relación con la tramitación de atestados policiales se debe prestar atención a las siguientes observaciones:","o":["Los actos \"stalking\" pueden constituir pueden ser, con frecuencia, constitutivos de delitos de descubrimiento y revelación de secretos.","El \"ciberbullying\" y sus modalidades pueden ser, con frecuencia, constitutivos de delitos de descubrimiento y revelación de secretos.","El sexting pueden ser, con frecuencia, constitutivos de delitos de descubrimiento y revelación de secretos.","El \"trolling\" pueden ser, con frecuencia, constitutivos de delitos de descubrimiento y revelación de secretos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El &quot;ciberbullying&quot; y sus modalidades pueden ser, con frecuencia, constitutivos de delitos de descubrimiento y revelación de secretos.</mark></span>El &quot;ciberbullying&quot; y sus modalidades pueden ser constitutivos de delitos de descubrimiento y revelación de secretos."},{"i":"17-211","p":"Instrucción nº 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"protocolo de actuación policial con menores\". En las actuaciones policiales relacionadas con casos de acoso escolar no deberán tomarse en consideración las siguientes cuestiones:","o":["Los centros educativos constituyen el primer lugar de lucha contra el acoso escolar.","Todas las modalidades de acoso son actos superiores en sentido amplio.","Deben comunicarse al Ministerio Fiscal incluso los supuestos de relevancia penal mínima, evitando trivializar o banalizar los hechos.","La respuesta policial debe ser individualizada para cada acosador."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Todas las modalidades de acoso son actos superiores en sentido amplio</mark></span>B no figura entre las cuestiones («actos superiores»); C pasa a ser el texto literal. Según el <span class=\"ref-norma\">punto 7.2.2 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"b. Todas las modalidades de acoso son actos agresivos en sentido amplio, ya sean físicos, verbales o psicológicos\"</span> (verificado con el temario oficial)."},{"i":"17-214","p":"Instrucción nº 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. En las actuaciones policiales relacionadas con casos de acoso escolar deberán tomarse en consideración las siguientes cuestiones:","o":["Deben comunicarse a las Fuerzas y Cuerpos de Seguridad incluso los supuestos de tolerancia penal mínima, evitando trivializar o banalizar los hechos.","Todas las modalidades de acoso son actos agresivos en sentido amplio, ya sean físicos, verbales o psicológicos, y no pueden ser constitutivos de infracción penal.","Asimismo, el Ministerio Fiscal precisa decirle el primer momento especial atención a la protección de víctimas y testigos.","Al mismo tiempo, deben esclarecerse posibles responsabilidades de adultos: educadores, padres, etc."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Al mismo tiempo, deben esclarecerse posibles responsabilidades de adultos: educadores, padres, etc</mark></span>Según el <span class=\"ref-norma\">punto 7.2.2 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"g. Al mismo tiempo, deben esclarecerse posibles responsabilidades de adultos: educadores, padres, etc\"</span> (verificado con el temario oficial)."},{"i":"17-ia-1612","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Conceptualmente el acoso escolar tiene lugar entre iguales y requiere de una cierta:","o":["gravedad o intensidad.","continuidad o reiteración.","publicidad o difusión.","intencionalidad o premeditación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">continuidad o reiteración</mark></span>El <span class=\"ref-norma\">7.2.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Conceptualmente el acoso escolar tiene lugar entre iguales y requiere de una cierta continuidad o reiteración\"</span>. Requiere continuidad o reiteración y se distingue de los incidentes aislados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1613","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Los actos concretos que integran el acoso escolar pueden consistir en agresiones físicas, amenazas, vejaciones, coacciones, insultos o en:","o":["el aislamiento deliberado de la víctima.","la difusión de rumores.","la sustracción de pertenencias, en los términos que se determinen reglamentariamente.","la exclusión de actividades."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el aislamiento deliberado de la víctima</mark></span>El <span class=\"ref-norma\">7.2.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"insultos o en el aislamiento deliberado de la víctima\"</span>. Incluye el aislamiento deliberado de la víctima. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1614","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Respecto de los incidentes aislados en el ámbito docente, el acoso escolar:","o":["no puede apreciarse nunca en un incidente aislado, salvo que la autoridad judicial disponga otra cosa.","se aprecia en todo caso en un incidente aislado.","solo se aprecia si lo solicita la víctima.","puede justificarse como tal, en atención a la gravedad del incidente aislado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">puede justificarse como tal, en atención a la gravedad del incidente aislado</mark></span>El <span class=\"ref-norma\">7.2.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"No obstante, también un incidente aislado, en atención a su gravedad y cuando tenga lugar en el ámbito docente, puede justificar su tratamiento como tal\"</span>. También un incidente aislado grave en el ámbito docente puede tratarse como acoso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1615","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Los centros educativos constituyen el primer lugar de lucha contra el acoso escolar, por lo que se considera esencial la circulación de la información relevante con el Ministerio Fiscal y:","o":["las asociaciones de padres de alumnos, previo informe de la unidad policial competente.","los servicios sociales municipales.","los responsables de los centros docentes.","el Defensor del Menor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los responsables de los centros docentes</mark></span>El <span class=\"ref-norma\">7.2.2.a de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"se considera esencial la circulación de la información relevante con el Ministerio Fiscal y los responsable de los centros docentes\"</span>. La información circula con el Ministerio Fiscal y los responsables de los centros docentes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1616","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Se aprovechará la impartición de charlas y conferencias a los alumnos para:","o":["informar sobre las consecuencias penales del acoso, sin perjuicio de lo previsto en la normativa vigente.","obtener información directa de los estudiantes sobre posibles situaciones de acoso escolar.","identificar a los alumnos acosadores.","recabar la colaboración de los profesores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">obtener información directa de los estudiantes sobre posibles situaciones de acoso escolar</mark></span>El <span class=\"ref-norma\">7.2.2.a de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Se aprovechará la impartición de charlas y conferencias a los alumnos para obtener información directa de los estudiantes sobre posibles situaciones de acoso escolar\"</span>. Se aprovechan para obtener información directa de los estudiantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1617","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Todas las modalidades de acoso son actos agresivos en sentido amplio, ya sean físicos, verbales o psicológicos, y:","o":["pueden ser constitutivas de infracción penal.","son siempre constitutivas de infracción penal.","solo son infracción penal si son físicos.","solo son infracción penal si son reiterados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">pueden ser constitutivas de infracción penal</mark></span>El <span class=\"ref-norma\">7.2.2.b de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"ya sean físicos, verbales o psicológicos, y pueden ser constitutivas de infracción penal\"</span>. Pueden ser constitutivas de infracción penal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1618","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Deben comunicarse al Ministerio Fiscal incluso los supuestos de relevancia penal mínima, evitando:","o":["su calificación penal inmediata, en los términos que se determinen reglamentariamente.","la revictimización.","duplicar actuaciones.","trivializar o banalizar los hechos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">trivializar o banalizar los hechos</mark></span>El <span class=\"ref-norma\">7.2.2.c de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Deben comunicarse al Ministerio Fiscal incluso los supuestos de relevancia penal mínima, evitando trivializar o banalizar los hechos\"</span>. Se comunican incluso los de relevancia penal mínima, evitando trivializar o banalizar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1619","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. La respuesta policial ante el acoso escolar debe ser:","o":["conjunta para todos los acosadores.","inmediata y colectiva.","individualizada para cada acosador.","coordinada exclusivamente por el centro."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">individualizada para cada acosador</mark></span>El <span class=\"ref-norma\">7.2.2.d de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"La respuesta policial debe ser individualizada para cada acosador\"</span>. Es individualizada para cada acosador. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1620","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Dado que el acoso puede pasar desapercibido para los adultos y no dejar huella física, es importante realizar un acopio suficiente de elementos probatorios, siendo especialmente relevante:","o":["el informe del tutor del centro.","el testimonio de los amigos y de los compañeros de clase del menor.","el informe psicológico de la víctima, salvo que la autoridad judicial disponga otra cosa.","el testimonio de los padres."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el testimonio de los amigos y de los compañeros de clase del menor</mark></span>El <span class=\"ref-norma\">7.2.2.e de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Entre éstos puede ser especialmente relevante el testimonio de los amigos y de los compañeros de clase del menor\"</span>. Es especialmente relevante el testimonio de amigos y compañeros de clase. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1621","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Las Fuerzas y Cuerpos de Seguridad prestarán desde el primer momento especial atención a la protección de víctimas y testigos, así como a la prevención de posibles casos de suicidio, debiendo considerarse el acoso continuado:","o":["una situación de riesgo.","una situación de desamparo.","un delito grave.","una circunstancia agravante."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">una situación de riesgo</mark></span>El <span class=\"ref-norma\">7.2.2.f de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"debiendo considerarse el acoso continuado una situación de riesgo\"</span>. El acoso continuado es una situación de riesgo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1622","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Ante el acoso escolar, se instará del centro escolar la activación, si no lo hubiera hecho ya, de:","o":["el protocolo de convivencia escolar.","el procedimiento sancionador.","la denuncia ante el Ministerio Fiscal, previo informe de la unidad policial competente.","las medidas preventivas y de protección necesarias, en el ámbito de sus competencias."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las medidas preventivas y de protección necesarias, en el ámbito de sus competencias</mark></span>El <span class=\"ref-norma\">7.2.2.f de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Se instará del centro escolar la activación, si no lo hubiera hecho ya, de las medidas preventivas y de protección necesarias, en el ámbito de sus competencias\"</span>. Se insta la activación de las medidas preventivas y de protección necesarias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1623","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Los actos de acoso escolar pueden constituir delito de trato degradante cuando tengan entidad suficiente para producir un menoscabo grave de la integridad moral de la víctima, o impliquen actos de humillación de carácter reiterado que, sin llegar a constituir trato degradante, supongan:","o":["acoso leve.","coacción.","grave acoso.","amenaza condicional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">grave acoso</mark></span>El <span class=\"ref-norma\">7.2.3.a de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"sin llegar a constituir trato degradante, supongan grave acoso\"</span>. También los actos reiterados de humillación que supongan grave acoso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1624","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Cuando los actos de acoso escolar se traduzcan además en la comisión de otros tipos delictivos (lesiones, coacciones, amenazas, etc.) se imputará:","o":["solo el delito más grave.","en concurso con aquellos.","como delito continuado.","como circunstancia agravante."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en concurso con aquellos</mark></span>El <span class=\"ref-norma\">7.2.3.a de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"se imputará en concurso con aquellos\"</span>. Se imputa en concurso con los otros tipos delictivos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1625","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. Los actos concretos del ciberacoso escolar o cyberbullying pueden ser, con frecuencia, constitutivos de delitos de:","o":["descubrimiento y revelación de secretos.","injurias y calumnias.","omisión del deber de socorro, sin perjuicio de lo previsto en la normativa vigente.","coacciones leves."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">descubrimiento y revelación de secretos</mark></span>El <span class=\"ref-norma\">7.2.3.b de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"pueden ser, con frecuencia, constitutivos de delitos de descubrimiento y revelación de secretos\"</span>. Con frecuencia, descubrimiento y revelación de secretos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1626","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Actuación específica en casos de acoso escolar. El delito de acoso u hostigamiento (stalking) permite sancionar situaciones en las que, sin llegar a concretarse una amenaza o coacción, se producen:","o":["conductas aisladas por medio de las que se coarta gravemente la libertad de la víctima, en los términos que se determinen reglamentariamente.","amenazas condicionales por medio de las que se coarta la libertad de la víctima.","conductas reiteradas por medio de las que se menoscaba la intimidad de la víctima.","conductas reiteradas por medio de las que se coarta gravemente la libertad y sentimiento de seguridad de la víctima."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">conductas reiteradas por medio de las que se coarta gravemente la libertad y sentimiento de seguridad de la víctima</mark></span>El <span class=\"ref-norma\">7.2.3.c de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"se producen conductas reiteradas por medio de las que se coarta gravemente la libertad y sentimiento de seguridad de la víctima\"</span>. Conductas reiteradas que coartan gravemente la libertad y el sentimiento de seguridad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 27 — Informe del equipo técnico EX","q":[{"i":"17-30","p":"Ley Orgánica 5/2000. Durante la instrucción del expediente, el Ministerio Fiscal requerirá del equipo técnico, que a estos efectos dependerá funcionalmente de aquél sea cual fuere su dependencia orgánica, la elaboración de un informe o actualización de los anteriormente emitidos, que deberá serle entregado en el plazo máximo de _____, prorrogable por un período no superior a ____ en casos de gran complejidad.","o":["Diez días / un mes.","Diez días / cinco días.","Un mes / quince días.","Veinte días / diez días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días / un mes</mark></span>Según el <span class=\"ref-norma\">art. 27.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"en el plazo máximo de diez días, prorrogable por un período no superior a un mes en casos de gran complejidad\"</span> (verificado con el temario oficial)."},{"i":"17-33","p":"Real Decreto 1774/2004. El informe del equipo técnico es preceptivo para:","o":["La adopción de cualquier medida definitiva.","La imposición de una medida de internamiento.","La propuesta de solución extrajudicial.","Todas las anteriores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las anteriores.</mark></span> *Explicación: El informe del equipo técnico es un elemento esencial y preceptivo en todo el procedimiento, requerido para la adopción de medidas definitivas, la imposición de internamiento y las soluciones extrajudiciales (Arts. 6, 19 y 27 de la LO 5/2000 y RD 1774/2004).* TEST 3 He analizado las imágenes del"},{"i":"17-48","p":"Real Decreto 1774/2004. El informe del equipo técnico deberá ser entregado al Ministerio Fiscal en un plazo máximo de:","o":["10 días.","15 días.","20 días.","1 mes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">10 días</mark></span>Según el <span class=\"ref-norma\">art. 27.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"en el plazo máximo de diez días, prorrogable por un período no superior a un mes en casos de gran complejidad\"</span> (verificado con el temario oficial)."},{"i":"17-76","p":"Ley Orgánica 5/2000. Informe del Equipo Técnico. Durante la instrucción del expediente, el Ministerio Fiscal requerirá del equipo técnico la elaboración de un informe. Deberá serle entregado en el plazo máximo de:","o":["Diez días, prorrogable por un período no superior a un mes en casos de gran complejidad.","Quince días, prorrogable por un período no superior a diez días en casos de gran complejidad.","Quince días, prorrogable por un período no superior a un mes en casos de gran complejidad.","Un mes, prorrogable por un período no superior a dos meses en casos de gran complejidad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días, prorrogable por un período no superior a un mes en casos de gran complejidad</mark></span>Según el <span class=\"ref-norma\">art. 27.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"en el plazo máximo de diez días, prorrogable por un período no superior a un mes en casos de gran complejidad\"</span> (verificado con el temario oficial)."},{"i":"17-104","p":"Ley Orgánica 5/2000. Informe del Equipo Técnico. Durante la instrucción del expediente, el Ministerio Fiscal requerirá del equipo técnico la elaboración de un informe o actualización de los anteriormente emitidos, que deberá serle entregado en el plazo:","o":["Máximo de siete días, prorrogable por un período no superior a veinte días en casos de gran complejidad.","Máximo de diez días, prorrogable por un período no superior a un mes en casos de gran complejidad.","Máximo de veinte días, prorrogable por un período no superior a quince días en casos de gran complejidad.","Máximo de un mes, prorrogable por un período no superior a quince días en casos de gran complejidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Máximo de diez días, prorrogable por un período no superior a un mes en casos de gran complejidad</mark></span>Según el <span class=\"ref-norma\">art. 27.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"en el plazo máximo de diez días, prorrogable por un período no superior a un mes en casos de gran complejidad\"</span> (verificado con el temario oficial)."},{"i":"17-181","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Durante la instrucción del expediente, el Ministerio Fiscal requerirá ______ que a estos efectos dependerá funcionamiento de aquél sea cual fuere su dependencia orgánica, la elaboración de un informe o actualización de los anteriormente emitidos.","o":["Del equipo técnico.","Del equipo asesor.","Del equipo cometido.","Del equipo mediador."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Del equipo técnico.</mark></span>Del equipo técnico."},{"i":"17-227","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Informe del equipo técnico. Durante la instrucción del expediente, el Ministerio Fiscal requerirá del equipo técnico, que a estos efectos dependerá funcionalmente de aquél sea cual fuere su dependencia orgánica, la elaboración de un informe o actualización de los anteriormente emitidos, que deberá serle entregado en el plazo máximo de _______ prorrogable por un período no superior a un mes en casos de gran complejidad, sobre la situación psicológica, educativa y familiar del menor.","o":["Cuarenta días.","Quince días.","Siete días.","Diez días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Diez días</mark></span>Según el <span class=\"ref-norma\">art. 27.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"en el plazo máximo de diez días, prorrogable por un período no superior a un mes en casos de gran complejidad\"</span> (verificado con el temario oficial)."},{"i":"17-ia-1314","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Informe del equipo técnico. Durante la instrucción del expediente, el equipo técnico dependerá funcionalmente del Ministerio Fiscal, sea cual fuere su dependencia:","o":["administrativa.","territorial.","jerárquica.","orgánica."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">orgánica</mark></span>El <span class=\"ref-norma\">art. 27.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"que a estos efectos dependerá funcionalmente de aquél sea cual fuere su dependencia orgánica\"</span>. La dependencia funcional del Fiscal es sea cual fuere la dependencia orgánica. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1315","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Informe del equipo técnico. El informe del equipo técnico versará sobre la situación psicológica, educativa y familiar del menor, así como sobre:","o":["su situación económica y su historial delictivo.","su grado de madurez y la gravedad de los hechos.","su entorno social, y en general sobre cualquier otra circunstancia relevante a los efectos de la adopción de alguna de las medidas.","su entorno social, con exclusión de otras circunstancias personales, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">su entorno social, y en general sobre cualquier otra circunstancia relevante a los efectos de la adopción de alguna de las medidas</mark></span>El <span class=\"ref-norma\">art. 27.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"sobre la situación psicológica, educativa y familiar del menor, así como sobre su entorno social, y en general sobre cualquier otra circunstancia relevante a los efectos de la adopción de alguna de las medidas previstas en la presente Ley\"</span>. Incluye el entorno social y cualquier otra circunstancia relevante para las medidas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1316","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Informe del equipo técnico. El equipo técnico podrá proponer, asimismo, una intervención:","o":["terapéutica sobre el menor y su familia.","socio-educativa sobre el menor.","educativa sobre la familia del menor.","psicológica sobre la víctima."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">socio-educativa sobre el menor</mark></span>El <span class=\"ref-norma\">art. 27.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"El equipo técnico podrá proponer, asimismo, una intervención socio-educativa sobre el menor\"</span>. La intervención que puede proponer es socio-educativa sobre el menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1317","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Informe del equipo técnico. Cuando el equipo técnico informe sobre la posibilidad de que el menor efectúe una actividad reparadora o de conciliación con la víctima, con indicación expresa del contenido y la finalidad de la actividad, en este caso:","o":["no será preciso elaborar el informe sobre la situación psicológica, educativa y familiar del menor.","deberá elaborar igualmente el informe completo sobre su situación, salvo que la autoridad judicial disponga otra cosa.","deberá remitirlo directamente al Juez de Menores.","el Ministerio Fiscal deberá archivar las actuaciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no será preciso elaborar el informe sobre la situación psicológica, educativa y familiar del menor</mark></span>El <span class=\"ref-norma\">art. 27.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"con indicación expresa del contenido y la finalidad de la mencionada actividad. En este caso, no será preciso elaborar un informe de las características y contenidos del apartado 1 de este artículo\"</span>. En ese caso no es preciso el informe del apartado 1 (situación psicológica, educativa y familiar). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1318","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Informe del equipo técnico. El equipo técnico podrá proponer en su informe la conveniencia de no continuar la tramitación del expediente en interés del menor, por haber sido expresado suficientemente el reproche al mismo a través de los trámites ya practicados, o por considerar inadecuada para el interés del menor cualquier intervención, dado:","o":["la gravedad de los hechos.","la edad del menor.","la falta de colaboración de la víctima, previo informe de la unidad policial competente.","el tiempo transcurrido desde la comisión de los hechos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el tiempo transcurrido desde la comisión de los hechos</mark></span>El <span class=\"ref-norma\">art. 27.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"o por considerar inadecuada para el interés del menor cualquier intervención, dado el tiempo transcurrido desde la comisión de los hechos\"</span>. La inadecuación de la intervención se funda en el tiempo transcurrido desde la comisión de los hechos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1319","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Informe del equipo técnico. Si el equipo técnico propone no continuar la tramitación y se reunieran los requisitos del desistimiento, el Ministerio Fiscal podrá remitir el expediente al Juez con propuesta de sobreseimiento, remitiendo además, en su caso, testimonio de lo actuado a:","o":["la Sección de Menores de la Fiscalía.","el equipo técnico.","la entidad pública de protección de menores que corresponda.","la entidad pública de reforma de menores, sin perjuicio de lo previsto en la normativa vigente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la entidad pública de protección de menores que corresponda</mark></span>El <span class=\"ref-norma\">art. 27.4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"remitiendo además, en su caso, testimonio de lo actuado a la entidad pública de protección de menores que corresponda\"</span>. El testimonio va a la entidad pública de protección de menores que corresponda. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1321","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Informe del equipo técnico. El informe del equipo técnico podrá ser elaborado o complementado por aquellas entidades públicas o privadas que:","o":["trabajen en el ámbito de la educación de menores y conozcan la situación del menor expedientado.","hayan ejecutado una medida anterior con el menor, en los términos que se determinen reglamentariamente.","estén acreditadas por el Ministerio de Justicia.","colaboren con la Fiscalía de Menores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">trabajen en el ámbito de la educación de menores y conozcan la situación del menor expedientado</mark></span>El <span class=\"ref-norma\">art. 27.6 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"podrá ser elaborado o complementado por aquellas entidades públicas o privadas que trabajen en el ámbito de la educación de menores y conozcan la situación del menor expedientado\"</span>. Pueden hacerlo las entidades que trabajen en la educación de menores y conozcan la situación del menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"6.1. Aplicación de la normativa sobre Protección de la Seguridad Ciudadana EXOF EX R18","q":[{"i":"17-35","p":"Instrucción 1/2017. El registro corporal externo y superficial de los menores no detenidos se ajustará en todo caso a los criterios establecidos en:","o":["La Ley Orgánica 4/2015 de protección de la seguridad ciudadana.","La Ley Orgánica 5/2000 de responsabilidad penal del menor.","La Instrucción 7/2015 de la Secretaría de Estado de Seguridad, de 30 de junio.","A y C son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y C son correctas.</mark></span>*Explicación: El registro se rige por la LO 4/2015 y se desarrolla por la Instrucción 7/2015, que establece los protocolos específicos.*"},{"i":"17-37","p":"Instrucción 1/2017. Aplicación de la normativa sobre Protección de la Seguridad Ciudadana. En caso de comisión de infracciones en este ámbito por parte de menores no emancipados de entre ______ se cursará la correspondiente denuncia ante la autoridad competente.","o":["Doce y catorce años.","Catorce y dieciocho años.","Doce y dieciocho años.","Dieciséis y dieciocho años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Catorce y dieciocho años.</mark></span>*Explicación: La Instrucción 1/2017 se refiere a menores no emancipados entre 14 y 18 años para infracciones en el ámbito de la seguridad ciudadana, ya que los menores de 14 no son responsables.*"},{"i":"17-64","p":"Instrucción 1/2017. Aplicación de la normativa sobre protección de la seguridad ciudadana. Los menores de _____ están exentos de responsabilidad administrativa por la comisión de conductas tipificadas como infracciones en la Ley Orgánica 4/2015, de protección de la seguridad ciudadana.","o":["Dieciocho años.","Dieciséis años.","Catorce años.","Doce años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Catorce años.</mark></span>*Explicación: Los menores de 14 años están exentos de responsabilidad administrativa según la legislación de protección de la seguridad ciudadana.*"},{"i":"17-69","p":"Instrucción 1/2017. Aplicación de la normativa sobre protección de la seguridad ciudadana. Se cursará la correspondiente denuncia ante la autoridad competente y se participarán, de forma fehaciente y lo antes posible, los hechos y circunstancias ocurridos a quienes ejerzan la patria potestad, la tutela o la guarda de hecho, quienes serán responsables solidarios de los daños y perjuicios causados por los menores que se encuentren bajo su guarda, en caso de comisión de infracciones en este ámbito por parte de:","o":["Menores no emancipados de entre catorce y dieciséis años.","Menores no emancipados de entre catorce y dieciocho años.","Menores no emancipados de entre dieciséis y dieciocho años.","Menores emancipados de entre catorce y dieciocho años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Menores no emancipados de entre catorce y dieciocho años.</mark></span>*Explicación: La Instrucción 1/2017 se refiere a menores no emancipados de 14 a 18 años para infracciones en el ámbito de la seguridad ciudadana.*"},{"i":"17-243","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores infractores a la normativa de seguridad ciudadana. Salvo que exista una situación de urgencia por riesgo grave e inminente para los agentes, el registro corporal externo y superficial de un menor no detenido se realizará:","o":["Por un agente especializado en menores, con independencia de su sexo, respetando el criterio del máximo respeto a su identidad sexual, salvo que el órgano competente acuerde otra cosa de forma motivada.","Por un agente del mismo sexo, exigiéndose siempre la presencia de un representante legal del menor.","Por un agente del mismo sexo que la persona sobre la que se practique la diligencia, respetando el criterio del máximo respeto a su identidad sexual.","Por dos agentes, uno de ellos del mismo sexo que la persona sobre la que se practique la diligencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por un agente del mismo sexo que la persona sobre la que se practique la diligencia, respetando el criterio del máximo respeto a su identidad sexual</mark></span>El <span class=\"ref-norma\">punto 6.1.8.a de la Instrucción 1/2017</span> dispone: <span class=\"ref-concepto\">\"El registro se realizará por un agente del mismo sexo que la persona sobre la que se practique la diligencia, respetando el criterio del máximo respeto a su identidad sexual\"</span>"},{"i":"17-ia-1601","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores infractores a la normativa de seguridad ciudadana. Los menores de catorce años están exentos de responsabilidad administrativa por la comisión de conductas tipificadas como infracciones en:","o":["la Ley Orgánica 4/2015, de protección de la seguridad ciudadana.","la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores.","la Ley Orgánica 1/1992, sobre protección de la seguridad ciudadana.","la Ley Orgánica 1/1996, de protección jurídica del menor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Ley Orgánica 4/2015, de protección de la seguridad ciudadana</mark></span>El <span class=\"ref-norma\">6.1.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Los menores de catorce años están exentos de responsabilidad administrativa por la comisión de conductas tipificadas como infracciones en la Ley Orgánica 4/2015, de protección de la seguridad ciudadana\"</span>. Están exentos de responsabilidad administrativa por infracciones de la LO 4/2015. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1602","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores infractores a la normativa de seguridad ciudadana. En las infracciones de seguridad ciudadana cometidas por menores no emancipados de entre catorce y dieciocho años es importante la inclusión en el correspondiente procedimiento sancionador de:","o":["el informe del equipo técnico de menores, en los términos que se determinen reglamentariamente.","la autorización del Ministerio Fiscal.","el domicilio y los datos de la víctima.","los datos identificativos de sus padres, tutores o responsables legales o de hecho."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los datos identificativos de sus padres, tutores o responsables legales o de hecho</mark></span>El <span class=\"ref-norma\">6.1.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"es importante la inclusión en el correspondiente procedimiento sancionador de los datos identificativos de sus padres, tutores o responsables legales o de hecho\"</span>. Se incluyen los datos identificativos de padres, tutores o responsables legales o de hecho. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1603","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores infractores a la normativa de seguridad ciudadana. Cuando de las actuaciones practicadas por infracciones de seguridad ciudadana se determine que la persona es menor de catorce años, se levantará acta de los hechos, poniéndose a disposición de la Autoridad u organismo competente junto con los efectos incautados, remitiendo copia de lo actuado al:","o":["Juez de Menores, actuando conforme a lo previsto para menores en situación de riesgo o desamparo, salvo que la autoridad judicial disponga otra cosa.","Ministerio Fiscal, procediendo después al archivo de lo actuado.","Ministerio Fiscal, actuando conforme a lo previsto para menores en situación de riesgo o desamparo.","equipo técnico, actuando conforme a lo previsto para menores infractores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ministerio Fiscal, actuando conforme a lo previsto para menores en situación de riesgo o desamparo</mark></span>El <span class=\"ref-norma\">6.1.4 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"remitiendo copia de lo actuado al Ministerio Fiscal, y actuando conforme a lo previsto en el apartado 8 de este Protocolo para el caso de menores en situación de riesgo o desamparo\"</span>. Copia al Ministerio Fiscal y actuación como en riesgo o desamparo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1606","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores infractores a la normativa de seguridad ciudadana. Salvo que exista una situación de urgencia por riesgo grave e inminente para los agentes, el registro corporal de un menor se realizará por un agente:","o":["del mismo sexo que el menor, sin excepción alguna.","especializado en menores, acompañado de un representante legal.","de la unidad especializada en menores, preferentemente del mismo sexo, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","del mismo sexo que la persona sobre la que se practique la diligencia, respetando el criterio del máximo respeto a su identidad sexual."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">del mismo sexo que la persona sobre la que se practique la diligencia, respetando el criterio del máximo respeto a su identidad sexual</mark></span>El <span class=\"ref-norma\">6.1.8 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"El registro se realizará por un agente del mismo sexo que la persona sobre la que se practique la diligencia, respetando el criterio del máximo respeto a su identidad sexual\"</span>. Agente del mismo sexo, con máximo respeto a su identidad sexual. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1607","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores infractores a la normativa de seguridad ciudadana. Si el registro corporal de un menor exigiera dejar a la vista partes del cuerpo normalmente cubiertas por ropa, se efectuará en un lugar reservado y fuera de la vista de terceros. Se dejará constancia escrita de esta diligencia, así como de:","o":["el resultado de la diligencia y de la identidad del menor, en los términos que se determinen reglamentariamente.","la presencia de testigos y de las causas que la motivaron.","las causas que la motivaron y de la identidad del agente que la adoptó.","la autorización del Fiscal y de la identidad del agente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las causas que la motivaron y de la identidad del agente que la adoptó</mark></span>El <span class=\"ref-norma\">6.1.8 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Se dejará constancia escrita de esta diligencia, así como de las causas que la motivaron y de la identidad del agente que la adoptó\"</span>. Consta por escrito la diligencia, sus causas y el agente que la adoptó. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1700","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Aplicación de la normativa sobre Protección de la Seguridad Ciudadana. Cuando sea necesario requerir la identidad de un menor de edad en las vías o lugares públicos y realizar un control superficial sobre sus efectos personales, se evitará, en la medida de lo posible:","o":["La presencia de terceras personas, el empleo de esposas y la exhibición de armas.","La información al menor sobre los hechos que motivan la intervención y en qué va a consistir.","La espectacularidad, la comunicación a quienes ejerzan su guarda y la exhibición de armas.","La espectacularidad, el empleo de lenguaje duro, la violencia y la exhibición de armas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La espectacularidad, el empleo de lenguaje duro, la violencia y la exhibición de armas</mark></span>El <span class=\"ref-norma\">punto 6.1.6.b de la Instrucción 1/2017</span> dispone: <span class=\"ref-concepto\">\"Se evitará, en la medida de lo posible, la espectacularidad, el empleo de lenguaje duro, la violencia y la exhibición de armas\"</span>"}]},{"a":"10.1. Acceso y confidencialidad de los registros","q":[{"i":"17-36","p":"Real Decreto 1774/2004. Los registros policiales donde conste la identidad y otros datos que afecten a la intimidad de los menores serán de carácter estrictamente confidencial y no podrán ser consultados por terceros, distinguiéndose tres tipos en función del soporte:","o":["Libros registro, en soporte papel.","Bases de datos, en soporte informático.","Álbumes fotográficos, colección de fotografías.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Son libros-registro, bases de datos y álbumes fotográficos (no «archivos»). Según el <span class=\"ref-norma\">punto 10.1.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"c. Álbumes fotográficos, colección de fotografías\"</span> (verificado con el temario oficial)."},{"i":"17-ia-1654","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Registros policiales de datos personales de menores. Los registros policiales donde conste la identidad y otros datos que afecten a la intimidad de los menores se distinguen en tres tipos en función del soporte:","o":["libros-registro, bases de datos y archivos de reseñas.","archivos físicos, bases de datos y álbumes fotográficos.","libros-registro, archivos informáticos y reseñas dactilares.","libros-registro, bases de datos y álbumes fotográficos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">libros-registro, bases de datos y álbumes fotográficos</mark></span>El <span class=\"ref-norma\">10.1.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"distinguiéndose tres tipos en función del soporte: a. Libros-registro, en soporte papel. b. Bases de datos, en soporte informático. c. Álbumes fotográficos, colección de fotografías\"</span>. Libros-registro, bases de datos y álbumes fotográficos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1655","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Registros policiales de datos personales de menores. Sólo tendrán acceso a los registros policiales de menores las personas que participen directamente en la investigación de un caso en trámite o que, en ejercicio de sus competencias, sean expresamente autorizados para ello por:","o":["el Juez de Menores o el Fiscal Jefe.","el Ministerio del Interior.","el Juez de Menores o el Fiscal de la Sección de Menores.","la Secretaría de Estado de Seguridad, sin perjuicio de lo previsto en la normativa vigente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Juez de Menores o el Fiscal de la Sección de Menores</mark></span>El <span class=\"ref-norma\">10.1.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"sean expresamente autorizados para ello por el Juez de Menores o el Fiscal de la Sección de Menores\"</span>. Autoriza el Juez de Menores o el Fiscal de la Sección de Menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"5.3. Exploración del menor y valoración de las necesidades de la víctima EX R17","q":[{"i":"17-44","p":"Instrucción 1/2017. Cuando se realicen o tramiten atestados en los que existan indicios de malos tratos o abusos a menores en el ámbito familiar y se aprecie una posible situación de riesgo o desamparo, se remitirá con carácter de urgencia:","o":["El original a la Sección de Menores de la Fiscalía.","El original al juzgado de menores.","Una copia a la Sección de Menores de la Fiscalía.","Una copia al juez de menores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Una copia a la Sección de Menores de la Fiscalía.</mark></span>*Explicación: El protocolo establece el envío de una copia urgente a la Fiscalía de Menores para que valore la situación de riesgo o desamparo.*"},{"i":"17-160","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. Actuación del equipo técnico. Los equipos técnicos de protección de menores NO están formados por:","o":["Psicólogos.","Abogados.","Educadores.","Trabajadores sociales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Abogados.</mark></span>Abogados."},{"i":"17-169","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Los agentes actuantes, cuando lo estimen adecuado y necesario, podrán elevar al Ministerio Fiscal la conveniencia de que éste recabe del Juez o Tribunal correspondiente la designación de un defensor judicial de la víctima menor de edad, para que la represente en la investigación, en los siguientes casos:","o":["Cuando se valore que puede tener con los mismos un conflicto de intereses, derivado o no del hecho investigado que no permita confiar en una gestión adecuada de sus intereses.","Cuando exista un conflicto con uno de los progenitores y el otro no se encuentre en condiciones de ejercer adecuadamente sus funciones de representación y asistencia de la víctima menor.","Cuando no esté acompañada o no se encuentre a quienes ejerzan la patria potestad o cargos tutelares.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">punto 5.3.7 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"a. Cuando se valore que puede tener con los mismos un conflicto de intereses, derivado o no del hecho investigado que no permita confiar en una gestión adecuada de sus intereses\"</span> (verificado con el temario oficial)."},{"i":"17-230","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Necesidades de la víctima menor de edad. La primera valoración de las necesidades de la víctima y la adopción de las primeras medidas de protección, durante la fase de investigación policial del delito, corresponde:","o":["A la Autoridad Judicial.","A los funcionarios policiales que actúan en la fase inicial de las investigaciones.","A la Autoridad Fiscal.","A los equipos técnicos de trabajadores sociales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A los funcionarios policiales que actúan en la fase inicial de las investigaciones.</mark></span>- Los funcionarios policiales realizan la primera valoración."},{"i":"17-ia-1527","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. En la exploración del menor víctima, salvo que las circunstancias aconsejen lo contrario, se notificará inmediatamente el hecho ocurrido y el lugar donde se encuentra el menor víctima a:","o":["la Fiscalía de Menores.","la entidad pública de protección, en los términos que se determinen reglamentariamente.","sus padres o responsables legales.","el Juez de Guardia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">sus padres o responsables legales</mark></span>El <span class=\"ref-norma\">5.3.1.a de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"se notifique inmediatamente el hecho ocurrido y el lugar donde se encuentra el menor víctima a sus padres o responsables legales\"</span>. Se notifica a sus padres o responsables legales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1529","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Al entrevistar al menor víctima, es recomendable que no sean más de dos los funcionarios que lo entrevisten, y evitar:","o":["la sustitución de los entrevistadores que el menor ya conoce.","la presencia de familiares del menor.","que los entrevistadores vistan de uniforme, previo informe de la unidad policial competente.","la grabación de la entrevista."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la sustitución de los entrevistadores que el menor ya conoce</mark></span>El <span class=\"ref-norma\">5.3.1.b de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Es recomendable que no sean más de dos los funcionarios que entrevisten al menor, y evitar la sustitución de los entrevistadores que el menor ya conoce\"</span>. No más de dos funcionarios y sin sustituir a los entrevistadores que el menor ya conoce. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1530","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. No resultará recomendable la toma de declaración en sede policial al menor víctima, salvo por profesionales específicamente formados, cuando:","o":["el menor sea mayor de catorce años.","el menor haya declarado con anterioridad.","el menor no esté acompañado de sus representantes legales, sin perjuicio de lo previsto en la normativa vigente.","el menor padezca una grave alteración psicofísica, su grado de inmadurez sea alto o tenga muy corta edad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el menor padezca una grave alteración psicofísica, su grado de inmadurez sea alto o tenga muy corta edad</mark></span>El <span class=\"ref-norma\">5.3.1.c de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"cuando el menor padezca una grave alteración psicofísica, su grado de inmadurez sea alto o tenga muy corta edad\"</span>. No es recomendable en grave alteración psicofísica, alta inmadurez o muy corta edad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1531","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Se velará porque se reciba declaración al menor víctima:","o":["una sola vez, en todo caso.","dos veces como máximo.","el menor número de veces posible, y únicamente cuando resulte estrictamente ineludible para los fines de la investigación penal.","cuantas veces lo solicite el Fiscal, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el menor número de veces posible, y únicamente cuando resulte estrictamente ineludible para los fines de la investigación penal</mark></span>El <span class=\"ref-norma\">5.3.1.d de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Se reciba declaración el menor número de veces posible, y únicamente cuando resulte estrictamente ineludible para los fines de la investigación penal\"</span>. El menor número de veces posible y solo cuando sea estrictamente ineludible. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1532","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Las víctimas menores podrán estar acompañadas, además de por su abogado y, en su caso, su progenitor y tutor legal, por una persona de su elección, durante la toma de declaración, salvo que:","o":["lo autorice el Fiscal de Menores.","motivadamente, se resuelva lo contrario por el funcionario encargado de la práctica de tal diligencia para garantizar el correcto desarrollo de la misma y la protección del menor.","el menor sea mayor de dieciséis años, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","el Juez de Menores lo deniegue."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">motivadamente, se resuelva lo contrario por el funcionario encargado de la práctica de tal diligencia para garantizar el correcto desarrollo de la misma y la protección del menor</mark></span>El <span class=\"ref-norma\">5.3.1.e de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"salvo que, motivadamente, se resuelva lo contrario por el funcionario encargado de la práctica de tal diligencia para garantizar el correcto desarrollo de la misma y la protección del menor\"</span>. Lo resuelve motivadamente el funcionario encargado de la diligencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1533","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Cabe limitar el derecho del menor a estar acompañado durante su declaración en los casos en los que el acompañante:","o":["deba intervenir en el procedimiento como testigo, pretenda intervenir en la declaración de la víctima o pueda cohibir o limitar su capacidad de declarar.","sea el investigado o un familiar de éste, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","no sea familiar de la víctima.","no hubiera sido propuesto por el abogado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">deba intervenir en el procedimiento como testigo, pretenda intervenir en la declaración de la víctima o pueda cohibir o limitar su capacidad de declarar</mark></span>El <span class=\"ref-norma\">5.3.1.e de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"en los casos en los que el acompañante deba intervenir en el procedimiento como testigo, pretenda o intente intervenir en la declaración de la víctima o que, con su presencia, pueda cohibir o limitar la capacidad o las posibilidades de declarar de ésta\"</span>. Se limita si el acompañante es testigo, intenta intervenir o puede cohibir a la víctima. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1534","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Si fuera necesario, se podrá solicitar la designación de un representante para acompañar al menor, a través de:","o":["la Fiscalía de Menores.","las Oficinas de Asistencia a las Víctimas.","el Colegio de Abogados.","los Servicios de Atención al Menor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los Servicios de Atención al Menor</mark></span>El <span class=\"ref-norma\">5.3.1.e de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"se podrá solicitar la designación de un represente para acompañar al menor, a través de los Servicios de Atención al Menor\"</span>. La designación se solicita a través de los Servicios de Atención al Menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1535","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Si fuera posible, la entrevista al menor víctima será realizada en dependencias específicamente adaptadas a tal fin, de tal manera que permitan:","o":["la presencia del Fiscal.","su transcripción inmediata.","su grabación por medios audiovisuales.","la observación desde el exterior por los representantes legales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">su grabación por medios audiovisuales</mark></span>El <span class=\"ref-norma\">5.3.1.f de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"de tal manera que permitan su grabación por medios audiovisuales\"</span>. Las dependencias deben permitir la grabación por medios audiovisuales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1536","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Los reconocimientos médicos de las víctimas menores solamente se llevarán a cabo cuando resulten imprescindibles, reduciendo al mínimo:","o":["su duración.","el número de los mismos.","la presencia de familiares.","las pruebas invasivas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el número de los mismos</mark></span>El <span class=\"ref-norma\">5.3.1.g de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"solamente se lleven a cabo cuando resulten imprescindibles, reduciendo al mínimo el número de los mismos\"</span>. Se reduce al mínimo el número de reconocimientos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1537","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. En el caso de menores de edad víctimas de delitos contra la libertad o indemnidad sexual, la entrevista se realizará necesariamente en dependencias especialmente concebidas o adaptadas para ello, y siempre por:","o":["la misma persona, con la debida formación especializada para reducir o limitar los perjuicios a la víctima.","dos funcionarios especializados.","un funcionario del mismo sexo que la víctima, en todo caso, en los términos que se determinen reglamentariamente.","el Juez o el Fiscal, en todo caso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la misma persona, con la debida formación especializada para reducir o limitar los perjuicios a la víctima</mark></span>El <span class=\"ref-norma\">5.3.1.h de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"y siempre por la misma persona, con la debida formación especializada para reducir o limitar los perjuicios a la víctima, o con su ayuda\"</span>. Siempre por la misma persona, con formación especializada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1539","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Cuando se trate de víctimas de delitos de violencia de género o doméstica, contra la libertad o indemnidad sexual o de trata de seres humanos con fines de explotación sexual, la declaración será tomada por una persona del mismo sexo que la víctima:","o":["en todo caso.","si así lo solicita el representante legal.","si así lo hubiera solicitado, salvo que ello pueda perjudicar de forma relevante el desarrollo del proceso, o deba tomarse la declaración directamente por un Juez o Fiscal.","salvo que lo desaconseje el equipo técnico, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">si así lo hubiera solicitado, salvo que ello pueda perjudicar de forma relevante el desarrollo del proceso, o deba tomarse la declaración directamente por un Juez o Fiscal</mark></span>El <span class=\"ref-norma\">5.3.1.i de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"la declaración sea tomada por una persona del mismo sexo que la víctima si así lo hubiera solicitado, salvo que ello pueda perjudicar de forma relevante el desarrollo del proceso, o deba tomarse la declaración directamente por un Juez o Fiscal\"</span>. Solo si lo hubiera solicitado y salvo perjuicio relevante del proceso o declaración ante Juez o Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1540","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. La primera valoración de las necesidades de la víctima y la adopción de las primeras medidas de protección, durante la fase de investigación policial del delito, corresponde a:","o":["la Unidad de Policía Judicial especializada en menores, en los términos que se determinen reglamentariamente.","los funcionarios policiales que actúen en la fase inicial de las investigaciones.","el Ministerio Fiscal.","la Oficina de Asistencia a las Víctimas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los funcionarios policiales que actúen en la fase inicial de las investigaciones</mark></span>El <span class=\"ref-norma\">5.3.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"corresponde a los funcionarios policiales que actúen en la fase inicial de las investigaciones\"</span>. La primera valoración corresponde a los funcionarios policiales de la fase inicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1541","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. La evaluación y resolución definitiva de las necesidades de protección de la víctima menor corresponden:","o":["a la Autoridad Judicial, que tomará en consideración sus opiniones e intereses.","al Ministerio Fiscal, previa audiencia del menor, salvo que la autoridad judicial disponga otra cosa.","a la Oficina de Asistencia a las Víctimas.","a la entidad pública de protección de menores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a la Autoridad Judicial, que tomará en consideración sus opiniones e intereses</mark></span>El <span class=\"ref-norma\">5.3.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"La evaluación y resolución definitiva corresponden a la Autoridad Judicial, en la que tomará en consideración sus opiniones e intereses\"</span>. La resolución definitiva es de la Autoridad Judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1542","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Se informará desde el primer momento de la existencia del derecho de justicia gratuita para todos los menores de edad cuando sean víctimas de actos de trata de seres humanos así como de situaciones de:","o":["violencia de género o doméstica.","abandono o desamparo.","acoso escolar.","abuso o maltrato."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">abuso o maltrato</mark></span>El <span class=\"ref-norma\">5.3.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"cuando sean víctimas de actos de trata de seres humanos así como de situaciones de abuso o maltrato\"</span>. Víctimas de trata y de situaciones de abuso o maltrato. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1544","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Los agentes policiales podrán instar la adopción de alguna de las medidas de protección a las que se hace referencia en la Ley Orgánica 19/1994, de 23 de diciembre, de:","o":["protección jurídica del menor.","protección a testigos y peritos en causas criminales.","protección de la seguridad ciudadana.","ayudas y asistencia a las víctimas de delitos violentos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">protección a testigos y peritos en causas criminales</mark></span>El <span class=\"ref-norma\">5.3.4 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"la Ley Orgánica 19/1994, de 23 de diciembre, de protección a testigos y peritos en causas criminales\"</span>. La LO 19/1994 es la de protección a testigos y peritos en causas criminales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1545","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Se podrá instar de la Autoridad Judicial, cuando el tipo o la gravedad del delito así lo aconseje a juicio de los investigadores, que la declaración del menor se tome:","o":["en sede judicial con todas las garantías de la prueba preconstituida.","en sede policial con grabación audiovisual.","ante el Fiscal con presencia de un psicólogo, previo informe de la unidad policial competente.","en la Oficina de Asistencia a las Víctimas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en sede judicial con todas las garantías de la prueba preconstituida</mark></span>El <span class=\"ref-norma\">5.3.5 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"que la declaración se tome en sede judicial con todas las garantías de la prueba preconstituida\"</span>. Se pide que se tome en sede judicial con garantías de prueba preconstituida. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1547","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Exploración del menor y valoración de las necesidades de la víctima. Cuando los menores sean directa o indirectamente víctimas de violencia de género, se actuará de conformidad con la Instrucción 7/2016, de la Secretaría de Estado de Seguridad, por la que se establece un nuevo protocolo para:","o":["la actuación policial ante la desaparición de menores, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","la intervención policial en entornos escolares.","la valoración policial del nivel de riesgo de violencia de género y de gestión de la seguridad de las víctimas.","la atención a víctimas de trata de seres humanos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la valoración policial del nivel de riesgo de violencia de género y de gestión de la seguridad de las víctimas</mark></span>El <span class=\"ref-norma\">5.3.9 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Instrucción 7/2016, de la Secretaría de Estado de Seguridad, por la que se establece un nuevo protocolo para la valoración policial del nivel de riesgo de violencia de género y de gestión de la seguridad de las víctimas\"</span>. La Instrucción 7/2016 regula la valoración del riesgo en violencia de género. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"9.2. Actuación específica en caso de localización de menores EX","q":[{"i":"17-46","p":"Instrucción 1/2017. Menores desaparecidos. Una vez localizado el menor desaparecido, se llevará a cabo las siguientes acciones:","o":["Se notificará el hallazgo a la Autoridad reclamante y, en su caso, al Ministerio Fiscal, recabando la información necesaria sobre las medidas de protección o cuidado que requiere el menor.","Será entregado, a la mayor brevedad, a la persona o entidad encargada de su guarda o custodia, o, en su defecto, a quién indique la Fiscalía.","Se procederá al cese del señalamiento en la BDSN y en el SIS, así como, en su caso, a remitir al CEPIC el formulario para el cese de la alerta por menor desaparecido.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">punto 9.2.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"a. Se notificará el hallazgo a la Autoridad reclamante y, en su caso, al Ministerio Fiscal, recabando la información necesaria sobre las medidas de protección o cuidado que requiere el menor\"</span> (verificado con el temario oficial)."},{"i":"17-78","p":"Instrucción 1/2017. Actuación específica en caso de localización de menores. Una vez localizado el menor desaparecido y puesto a salvo de situaciones de riesgo, se dispondrán las medidas de protección necesarias para preservar su integridad y, además:","o":["Será entregado, a la mayor brevedad, a la persona o entidad encargada de su guarda o custodia, o, en su defecto, a quien indique la Autoridad reclamante.","Se notificará el hallazgo a la Autoridad reclamante y, en su caso, al Ministerio Fiscal, recabando la información necesaria sobre las medidas de protección o cuidado que requiere el menor.","Se procederá al cese del señalamiento en la BEDN y en el SBL así como, en su caso, a remitir al Ministerio Fiscal el formulario para el cierre de la alerta por menor desaparecido.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Se notificará el hallazgo a la Autoridad reclamante y, en su caso, al Ministerio Fiscal, recabando la información necesaria sobre las medidas de protección o cuidado que requiere el menor</mark></span>A (entrega «a quien indique la Autoridad reclamante», es la Fiscalía) y C (formulario «al Ministerio Fiscal», es al CEPIC) son falsas. Según el <span class=\"ref-norma\">punto 9.2.1 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"a. Se notificará el hallazgo a la Autoridad reclamante y, en su caso, al Ministerio Fiscal, recabando la información necesaria sobre las medidas de protección o cuidado que requiere el menor\"</span> (verificado con el temario oficial)."}]},{"a":"Artículo 1 — Objeto y ámbito de aplicación","q":[{"i":"17-47","p":"Ley Orgánica 5/2000. El plazo máximo de duración de la medida de internamiento en régimen cerrado será de:","o":["1 año.","2 años.","5 años.","8 años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">2 años.</mark></span><span class=\"ref-norma\">Art. 9.1 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 9.1 de la LO 5/2000 establece que el plazo máximo de internamiento en régimen cerrado es de 2 años.*"},{"i":"17-68","p":"Ley Orgánica 5/2000. El plazo máximo de duración de la medida de libertad vigilada será de:","o":["6 meses.","1 año.","2 años.","3 años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">2 años.</mark></span><span class=\"ref-norma\">Art. 9.1 · Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores</span>. *Explicación: El artículo 9.1 de la LO 5/2000 establece que la libertad vigilada no podrá exceder de dos años.*"},{"i":"17-155","p":"Real Decreto 1774/2004, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores. Al efecto de designar a las personas a quienes se aplica este reglamento, en su articulado se utiliza el término menores para referirse a las personas que no han cumplido:","o":["14 años.","16 años.","15 años.","18 años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">18 años.</mark></span>18 años."},{"i":"17-223","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Disposiciones generales. ¿Qué entidades pueden establecer normas complementarias dentro de sus competencias?","o":["Sólo el Ministerio Fiscal y el Juez de Menores.","Los Tribunales Superiores de Justicia.","La Policía Judicial y el equipo técnico.","Las comunidades autónomas y las Ciudades de Ceuta y Melilla."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las comunidades autónomas y las Ciudades de Ceuta y Melilla.</mark></span>- Las CCAA y Ciudades Autónomas pueden establecer normas complementarias."},{"i":"17-ia-1401","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Objeto y ámbito de aplicación. Este reglamento tiene por objeto el desarrollo de la Ley Orgánica 5/2000 en lo referente a la actuación del equipo técnico y de la Policía Judicial, a la ejecución de las medidas cautelares y definitivas adoptadas de conformidad con aquella y:","o":["al régimen disciplinario de los centros para la ejecución de las medidas privativas de libertad.","al régimen penitenciario de los centros de internamiento.","al procedimiento de determinación de la edad de los menores, en los términos que se determinen reglamentariamente.","a la responsabilidad civil de los padres y tutores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al régimen disciplinario de los centros para la ejecución de las medidas privativas de libertad</mark></span>El <span class=\"ref-norma\">art. 1.1 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"al régimen disciplinario de los centros para la ejecución de las medidas privativas de libertad\"</span>. El Reglamento alcanza también al régimen disciplinario de los centros de ejecución de medidas privativas de libertad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1402","p":"Real Decreto 1774/2004, de 30 de julio, por el que se aprueba el Reglamento de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Objeto y ámbito de aplicación. En el articulado del reglamento se utiliza el término menores para referirse a las personas que no han cumplido __________ años, sin perjuicio de lo previsto en la Ley Orgánica 5/2000 cuando sea aplicable:","o":["16, salvo que la autoridad judicial disponga otra cosa.","14","21","18"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">18</mark></span>El <span class=\"ref-norma\">art. 1.2 de la RD 1774/2004</span> se dispone: <span class=\"ref-concepto\">\"el término menores para referirse a las personas que no han cumplido 18 años\"</span>. El término menores se refiere a quienes no han cumplido 18 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 22 — De la incoación del expediente EX","q":[{"i":"17-67","p":"Ley Orgánica 5/2000. De la incoación del expediente. Desde el mismo momento de la incoación del expediente, el menor tendrá derecho a:","o":["Ser oído por el Juez o Tribunal antes de adoptar cualquier resolución que le concierna personalmente.","La asistencia de los servicios del equipo técnico adscrito al Juzgado de Menores.","Designar abogado que le defienda, o a que le sea designado de oficio y a entrevistarse reservadamente con él, incluso antes de prestar declaración.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 22.1.b) de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Designar abogado que le defienda, o a que le sea designado de oficio y a entrevistarse reservadamente con él, incluso antes de prestar declaración\"</span> (verificado con el temario oficial)."},{"i":"17-116","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la incoación del expediente. Desde el mismo momento de la incoación del expediente, el menor tendrá derecho a:","o":["Ser oído por el Juez o Tribunal antes de adoptar cualquier resolución que le concierna personalmente.","La asistencia de los servicios del equipo técnico adscrito al Juzgado de Menores.","Designar abogado que le defienda, o a que le sea designado de oficio y a entrevistarse reservadamente con él, incluso antes de prestar declaración.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Enunciado y opciones tenían errores de transcripción: las tres primeras son derechos de la Ley. Según el <span class=\"ref-norma\">art. 22.1.d) de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"Ser oído por el Juez o Tribunal antes de adoptar cualquier resolución que le concierna personalmente\"</span> (verificado con el temario oficial)."},{"i":"17-239","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la incoación del expediente. El Fiscal requerirá al menor y a sus representantes legales para que designen letrado en el plazo de _____, advirtiéndoles que, de no hacerlo, se le nombrará de oficio de entre los integrantes del turno de especialistas del correspondiente Colegio de Abogados:","o":["Cinco días.","Diez días.","Tres días.","Cuarenta y ocho horas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Tres días</mark></span>El <span class=\"ref-norma\">art. 22.2 de la LO 5/2000</span> dispone: <span class=\"ref-concepto\">\"para que designen letrado en el plazo de tres días\"</span>"},{"i":"17-ia-1238","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la incoación del expediente. Desde el mismo momento de la incoación del expediente, el menor tendrá derecho a ser informado de los derechos que le asisten por:","o":["el Juez o el Ministerio Fiscal, con exclusión de la policía.","el Ministerio Fiscal o el letrado del menor.","el Juez, el Ministerio Fiscal o el equipo técnico.","el Juez, el Ministerio Fiscal, o agente de policía."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el Juez, el Ministerio Fiscal, o agente de policía</mark></span>El <span class=\"ref-norma\">art. 22.1.a de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Ser informado por el Juez, el Ministerio Fiscal, o agente de policía de los derechos que le asisten\"</span>. Informan el Juez, el Ministerio Fiscal o agente de policía. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1239","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la incoación del expediente. Desde la incoación del expediente, el menor tendrá derecho a designar abogado que le defienda, o a que le sea designado de oficio y a entrevistarse reservadamente con él:","o":["únicamente después de prestar declaración.","siempre en presencia de sus padres.","incluso antes de prestar declaración.","en presencia del Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">incluso antes de prestar declaración</mark></span>El <span class=\"ref-norma\">art. 22.1.b de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"a entrevistarse reservadamente con él, incluso antes de prestar declaración\"</span>. La entrevista reservada puede ser incluso antes de prestar declaración. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1240","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la incoación del expediente. Desde la incoación del expediente, el menor tendrá derecho a ser oído por el Juez o Tribunal antes de adoptar cualquier resolución que:","o":["afecte a su libertad.","le concierna personalmente.","imponga una medida.","afecte a sus derechos fundamentales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">le concierna personalmente</mark></span>El <span class=\"ref-norma\">art. 22.1.d de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Ser oído por el Juez o Tribunal antes de adoptar cualquier resolución que le concierna personalmente\"</span>. Se le oye antes de cualquier resolución que le concierna personalmente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1241","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la incoación del expediente. El menor tiene derecho a la asistencia afectiva y psicológica en cualquier estado y grado del procedimiento, con la presencia de los padres o de otra persona que indique el menor, si:","o":["el Juez de Menores autoriza su presencia.","el Ministerio Fiscal autoriza su presencia.","lo solicita el letrado del menor.","lo informa favorablemente el equipo técnico."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Juez de Menores autoriza su presencia</mark></span>El <span class=\"ref-norma\">art. 22.1.e de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"con la presencia de los padres o de otra persona que indique el menor, si el Juez de Menores autoriza su presencia\"</span>. La presencia depende de que el Juez de Menores la autorice. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1242","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la incoación del expediente. El Fiscal requerirá al menor y a sus representantes legales para que designen letrado en el plazo de __________, advirtiéndoles que, de no hacerlo, se le nombrará de oficio:","o":["cinco días","cuarenta y ocho horas","diez días","tres días"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tres días</mark></span>El <span class=\"ref-norma\">art. 22.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"para que designen letrado en el plazo de tres días\"</span>. El plazo es de tres días. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1243","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la incoación del expediente. Si el menor y sus representantes legales no designan letrado en plazo, se le nombrará de oficio de entre los integrantes del:","o":["turno de oficio general del Colegio de Abogados, salvo que la autoridad judicial disponga otra cosa.","listado de letrados de la Fiscalía de Menores.","turno de especialistas del correspondiente Colegio de Abogados.","turno de guardia del Juzgado de Menores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">turno de especialistas del correspondiente Colegio de Abogados</mark></span>El <span class=\"ref-norma\">art. 22.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"se le nombrará de oficio de entre los integrantes del turno de especialistas del correspondiente Colegio de Abogados\"</span>. El nombramiento es del turno de especialistas del Colegio de Abogados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1244","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De la incoación del expediente. El Ministerio Fiscal notificará a quien aparezca como perjudicado, desde el momento en que así conste en la instrucción del expediente, la posibilidad de:","o":["personarse como acusador particular en el procedimiento principal.","ejercer las acciones civiles que le puedan corresponder, personándose ante el Juez de Menores en la pieza de responsabilidad civil.","solicitar la imposición de medidas cautelares al Juez de Menores.","ejercer las acciones civiles ante la jurisdicción civil, con exclusión de la pieza de responsabilidad civil, previo informe de la unidad policial competente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">ejercer las acciones civiles que le puedan corresponder, personándose ante el Juez de Menores en la pieza de responsabilidad civil</mark></span>El <span class=\"ref-norma\">art. 22.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"la posibilidad de ejercer las acciones civiles que le puedan corresponder, personándose ante el Juez de Menores en la pieza de responsabilidad civil que se tramitará por el mismo\"</span>. El perjudicado puede ejercer las acciones civiles personándose en la pieza de responsabilidad civil. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"2.1. Organización EX","q":[{"i":"17-85","p":"Instrucción 1/2017. Organización. En el ámbito de la Guardia Civil, los especialistas en actuación con menores se integran en los Puntos de Atención Especializada (PAE), como órganos de las Unidades Orgánicas de Policía Judicial (UOPJ):","o":["En todas las Secciones de investigación (nivel provincial).","En todos los Equipos Territoriales (nivel comarcal).","Las opciones A y B son correctas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las opciones A y B son correctas</mark></span>El nivel comarcal son los «Equipos Territoriales», no las «Comandancias Territoriales». Según el <span class=\"ref-norma\">punto 2.1.2 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"en todas las Secciones de Investigación (nivel provincial) y en todos los Equipos Territoriales (nivel comarcal)\"</span> (verificado con el temario oficial)."},{"i":"17-103","p":"Instrucción 1/2017. Organización. En el ámbito de la Guardia Civil, los especialistas en actuación con menores no se integran en:","o":["Las Unidades de Atención Familia y Mujer (UFAM).","Los Puntos de Atención Especializada (PAE), como órganos de las Unidades Orgánicas de Policía Judicial (UOPJ).","Todas las Secciones de investigación (nivel provincial).","Todas las Comandancias Territoriales (nivel comarcal)."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Unidades de Atención Familia y Mujer (UFAM).</mark></span>*Explicación: Las UFAM se dedican a protección de víctimas, no a menores infractores. Los especialistas en menores se integran en PAE dentro de las UOPJ.*"},{"i":"17-ia-1506","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. En el ámbito del Cuerpo de Policía Nacional, los especialistas en materia de menores se integran en:","o":["los Grupos de Menores de las Brigadas Provinciales de Policía Judicial.","las Brigadas Provinciales de Extranjería y Fronteras.","las Unidades de Atención Familia y Mujer existentes solo en las Comisarías Locales, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","las Unidades de Atención Familia y Mujer (UFAM) existentes en todas las Brigadas Provinciales de Policía Judicial y Comisarias Locales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las Unidades de Atención Familia y Mujer (UFAM) existentes en todas las Brigadas Provinciales de Policía Judicial y Comisarias Locales</mark></span>El <span class=\"ref-norma\">2.1.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"los especialistas en materia de menores se integran en las Unidades de Atención Familia y Mujer (UFAM) existentes en todas las Brigadas Provinciales de Policía Judicial y Comisarias Locales\"</span>. Se integran en las UFAM de todas las Brigadas Provinciales y Comisarías Locales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1507","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. Los especialistas en materia de menores de la Policía Nacional, integrados en las Unidades de Atención Familia y Mujer, están apoyados por:","o":["la UFAM Central de la Comisaría General de Extranjería y Fronteras.","el Grupo Central de Menores de la Dirección General de la Policía.","la UFAM Central de la Comisaría General de Policía Judicial.","la Unidad Técnica de Policía Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la UFAM Central de la Comisaría General de Policía Judicial</mark></span>El <span class=\"ref-norma\">2.1.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"apoyados por la UFAM Central de la Comisaría General de Policía Judicial\"</span>. El apoyo es de la UFAM Central de la Comisaría General de Policía Judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1509","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. En la Guardia Civil los Puntos de Atención Especializada se encuentran en todas las Secciones de Investigación (nivel provincial) y en todos los:","o":["Equipos Territoriales (nivel comarcal).","Puestos (nivel local).","Equipos de Policía Judicial (nivel comarcal).","Grupos de Investigación (nivel provincial)."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Equipos Territoriales (nivel comarcal)</mark></span>El <span class=\"ref-norma\">2.1.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"en todas las Secciones de Investigación (nivel provincial) y en todos los Equipos Territoriales (nivel comarcal)\"</span>. Provincial: Secciones de Investigación; comarcal: Equipos Territoriales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1510","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. En los municipios que tengan suscrito un Acuerdo Específico con el Ministerio del Interior para que parte de su Policía Local ejerza funciones de Policía Judicial, podrán crearse:","o":["Grupos de Menores de la Policía Local con competencias plenas de protección y reforma, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","Unidades Municipales de Atención a la Infancia dependientes de los servicios sociales.","Equipos de Policía Judicial Municipal con competencia sobre cualquier delito.","Equipos Municipales Especializados en Menores para la investigación de los hechos delictivos recogidos en el citado Acuerdo Específico donde se encuentren implicados menores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Equipos Municipales Especializados en Menores para la investigación de los hechos delictivos recogidos en el citado Acuerdo Específico donde se encuentren implicados menores</mark></span>El <span class=\"ref-norma\">2.1.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"podrán crearse Equipos Municipales Especializados en Menores para la investigación de los hechos delictivos recogidos en el citado Acuerdo Específico donde se encuentren implicados menores\"</span>. Se crean Equipos Municipales Especializados en Menores para los hechos del Acuerdo Específico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1511","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Especialización policial en materia de menores. El Acuerdo Específico de las Policías Locales para ejercer funciones de Policía Judicial se enmarca en lo establecido en los convenios generales suscritos entre el Ministerio del Interior y:","o":["las Comunidades Autónomas.","el Consejo General del Poder Judicial, salvo que la autoridad judicial disponga otra cosa.","la Federación Española de Municipios y Provincias.","la Fiscalía General del Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Federación Española de Municipios y Provincias</mark></span>El <span class=\"ref-norma\">2.1.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"en el marco de lo establecido en los convenios generales suscritos entre el Ministerio del Interior y la Federación Española de Municipios y Provincias\"</span>. Los convenios generales son con la Federación Española de Municipios y Provincias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"10.3. Bases de datos EX","q":[{"i":"17-101","p":"Instrucción 1/2017. Bases de datos. Quedarán registradas en una aplicación específica donde consten los antecedentes policiales de menores las detenciones de menores infractores:","o":["Entre catorce y dieciocho años.","Entre doce y dieciocho años.","Entre catorce y dieciséis años.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Entre catorce y dieciocho años.</mark></span>*Explicación: Solo se registran las detenciones de menores entre 14 y 18 años, que son los sujetos a responsabilidad penal.*"},{"i":"17-140","p":"Instrucción número 1/2017, de la secretaría de estado seguridad, por la que se actualiza el protocolo de actuación policial con menores. Base de datos. Existirá una aplicación específica donde se registrarán los datos correspondientes a menores entre ______ encartados en una investigación policial.","o":["Dieciocho años.","Dieciséis años.","Quince años.","Catorce y dieciocho años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Catorce y dieciocho años.</mark></span>Entre 14 y 18 años."},{"i":"17-ia-1660","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Registros policiales de datos personales de menores. Todas las reseñas policiales de menores quedarán contenidas en su correspondiente aplicación, debiendo mantener separadas y sin comunicación directa las reseñas de menores detenidos de aquellas otras practicadas con ocasión de:","o":["diligencias de identificación en la vía pública, sin perjuicio de lo previsto en la normativa vigente.","trámites de determinación de edad o de identificación de menores no acompañados o indocumentados.","situaciones de riesgo o desamparo.","menores desaparecidos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">trámites de determinación de edad o de identificación de menores no acompañados o indocumentados</mark></span>El <span class=\"ref-norma\">10.3.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"las reseñas de menores detenidos de aquellas otras practicadas con ocasión de trámites de determinación de edad o de identificación de menores no acompañados o indocumentados\"</span>. Se separan las de detenidos de las de determinación de edad e identificación de no acompañados o indocumentados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1662","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Registros policiales de datos personales de menores. El Registro de Menores Extranjeros No Acompañados es un registro de naturaleza administrativa a efectos exclusivos de:","o":["protección.","investigación, en los términos que se determinen reglamentariamente.","estadística.","identificación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">identificación</mark></span>El <span class=\"ref-norma\">10.3.5 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Se trata de un registro de naturaleza administrativa a efectos exclusivos de identificación\"</span>. Es un registro administrativo a efectos exclusivos de identificación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 26 — Diligencias propuestas por las partes EX","q":[{"i":"17-113","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Diligencias propuestas por las partes. Las partes podrán solicitar del Ministerio Fiscal la práctica de cuantas diligencias consideren necesarias. ¿Quién decidirá sobre su admisión, mediante resolución motivada?:","o":["El Juez de Menores, previa audiencia del Ministerio Fiscal.","El Juez de Menores, que notificará al Ministerio Fiscal y al letrado del menor.","El Ministerio Fiscal, que notificará al Juez de Menores y a quien en su caso ejercite la acción penal.","El Ministerio Fiscal, que notificará al letrado del menor y a quien en su caso ejercite la acción penal y que pondrá en conocimiento del Juez de Menores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Ministerio Fiscal, que notificará al letrado del menor y a quien en su caso ejercite la acción penal y que pondrá en conocimiento del Juez de Menores</mark></span>Según el <span class=\"ref-norma\">art. 26.1 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"El Ministerio Fiscal decidirá sobre su admisión, mediante resolución motivada que notificará al letrado del menor y a quien en su caso ejercite la acción penal y que pondrá en conocimiento del Juez de Menores\"</span> (verificado con el temario oficial)."},{"i":"17-ia-1310","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Diligencias propuestas por las partes. El Ministerio Fiscal decidirá sobre la admisión de las diligencias solicitadas por las partes mediante resolución motivada que notificará al letrado del menor y a quien en su caso ejercite la acción penal y que pondrá en conocimiento del:","o":["Fiscal Jefe.","equipo técnico.","Letrado de la Administración de Justicia.","Juez de Menores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Juez de Menores</mark></span>El <span class=\"ref-norma\">art. 26.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"mediante resolución motivada que notificará al letrado del menor y a quien en su caso ejercite la acción penal y que pondrá en conocimiento del Juez de Menores\"</span>. La resolución motivada se pone en conocimiento del Juez de Menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1311","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Diligencias propuestas por las partes. Las partes podrán, en cualquier momento, reproducir ante el Juzgado de Menores:","o":["la petición de las diligencias denegadas, en el plazo de tres días.","la solicitud de sobreseimiento.","la petición de las diligencias no practicadas.","el recurso contra la resolución del Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la petición de las diligencias no practicadas</mark></span>El <span class=\"ref-norma\">art. 26.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Las partes podrán, en cualquier momento, reproducir ante el Juzgado de Menores la petición de las diligencias no practicadas\"</span>. Pueden reproducir en cualquier momento la petición de diligencias no practicadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1312","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Diligencias propuestas por las partes. Cuando alguna de las partes proponga que se lleve a efecto la declaración del menor, el Ministerio Fiscal deberá recibirla en el expediente, salvo que:","o":["el menor se niegue a declarar.","ya hubiese concluido la instrucción y el expediente hubiese sido elevado al Juzgado de Menores.","el letrado del menor se oponga.","ya se hubiese acordado el secreto del expediente, previo informe de la unidad policial competente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">ya hubiese concluido la instrucción y el expediente hubiese sido elevado al Juzgado de Menores</mark></span>El <span class=\"ref-norma\">art. 26.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"el Ministerio Fiscal deberá recibirla en el expediente, salvo que ya hubiese concluido la instrucción y el expediente hubiese sido elevado al Juzgado de Menores\"</span>. La excepción: instrucción concluida y expediente ya elevado al Juzgado de Menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1313","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Diligencias propuestas por las partes. Si las diligencias propuestas por alguna de las partes afectaren a derechos fundamentales del menor o de otras personas, el Ministerio Fiscal, de estimar pertinente la solicitud, se dirigirá:","o":["al Juez de Menores.","al Juez de Instrucción.","a la Sala de Menores.","al equipo técnico."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al Juez de Menores</mark></span>El <span class=\"ref-norma\">art. 26.3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"el Ministerio Fiscal, de estimar pertinente la solicitud, se dirigirá al Juez de Menores\"</span>. Se dirige al Juez de Menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 12 — Procedimiento de aplicación de medidas en supuestos de pluralidad de infracciones EX","q":[{"i":"17-126","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. En el caso de existencia de pluralidad de infracciones y medidas firmes en ejecución, pendientes de ejecución o suspendidas condicionalmente, impuestas al mismo menor por otros jueces de menores en anteriores sentencias, el Juez competente para la ejecución procederá:","o":["A seguir todas las medidas impuestas.","A la acumulación y suspensión de todas las medidas impuestas.","A la unificación y sustitución de todas las medidas impuestas.","A la refundición y a ordenar la ejecución de todas las medidas impuestas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A la refundición y a ordenar la ejecución de todas las medidas impuestas</mark></span>Según el <span class=\"ref-norma\">art. 12.2 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"procederá a la refundición y a ordenar la ejecución de todas las medidas impuestas\"</span> (verificado con el temario oficial)."},{"i":"17-177","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. En cuanto el Juez sentenciador tenga conocimiento de la existencia de otras medidas firmes en ejecución, pendientes de ejecución o suspendidas condicionalmente, impuestas al mismo menor por otros jueces de menores en anteriores sentencias, y una vez que la medida o medidas por él impuestas sean firmes, ordenará _____ que dé traslado del testimonio de su sentencia, por el medio más rápido posible, al Juez que haya dictado la primera sentencia firme.","o":["Al Ministerio Fiscal.","Al Fiscal General del Estado.","Al Secretario Judicial.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al Secretario Judicial.</mark></span>Al Secretario Judicial."},{"i":"17-ia-1123","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Procedimiento de aplicación de medidas en supuestos de pluralidad de infracciones. El Juez sentenciador, una vez que la medida o medidas por él impuestas sean firmes, ordenará al secretario judicial que dé traslado del testimonio de su sentencia, por el medio más rápido posible, al:","o":["Juez que haya dictado la última sentencia firme, sin perjuicio de lo previsto en la normativa vigente.","Juez Central de Menores.","Juez que haya dictado la primera sentencia firme.","Juez del lugar del domicilio del menor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Juez que haya dictado la primera sentencia firme</mark></span>El <span class=\"ref-norma\">art. 12.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"por el medio más rápido posible, al Juez que haya dictado la primera sentencia firme, el cual será el competente para la ejecución de todas\"</span>. El competente para la ejecución de todas es el Juez que dictó la primera sentencia firme. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1124","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Procedimiento de aplicación de medidas en supuestos de pluralidad de infracciones. El Juez competente para la ejecución procederá a la __________ y a ordenar la ejecución de todas las medidas impuestas:","o":["acumulación, en los términos que se determinen reglamentariamente.","refundición","revisión","unificación"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">refundición</mark></span>El <span class=\"ref-norma\">art. 12.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"procederá a la refundición y a ordenar la ejecución de todas las medidas impuestas\"</span>. El término literal es refundición. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1125","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Procedimiento de aplicación de medidas en supuestos de pluralidad de infracciones. Desde el momento de la refundición, el Juez competente para la ejecución pasará a ser competente a todos los efectos con exclusión de:","o":["los órganos judiciales que hubieran dictado las posteriores resoluciones.","los equipos técnicos adscritos a los Juzgados de Menores.","el Ministerio Fiscal y los órganos que hubieran dictado las posteriores resoluciones.","los órganos judiciales que hubieran dictado las anteriores resoluciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los órganos judiciales que hubieran dictado las posteriores resoluciones</mark></span>El <span class=\"ref-norma\">art. 12.2 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"pasará a ser competente a todos los efectos con exclusión de los órganos judiciales que hubieran dictado las posteriores resoluciones\"</span>. La exclusión alcanza a los órganos judiciales que dictaron las posteriores resoluciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1143","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Procedimiento de aplicación de medidas en supuestos de pluralidad de infracciones. El Juez sentenciador ordenará al secretario judicial que dé traslado del testimonio de su sentencia, por el medio __________, al Juez que haya dictado la primera sentencia firme:","o":["más seguro posible","que estime oportuno","más rápido posible","ordinario"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">más rápido posible</mark></span>El <span class=\"ref-norma\">art. 12.1 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"ordenará al secretario judicial que dé traslado del testimonio de su sentencia, por el medio más rápido posible\"</span>. El traslado se hace por el medio más rápido posible. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 18 — Desistimiento de la incoación del expediente por corrección en el ámbito educativo y familiar EX","q":[{"i":"17-134","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Desistimiento de la incoación del expediente por corrección en el ámbito educativo y familiar. El Ministerio Fiscal deberá incoar el expediente:","o":["Cuando conste que el menor ha cometido los hechos junto con otras personas, sean mayores o menores de edad.","Cuando conste que el menor ha cometido con anterioridad otros hechos de la misma naturaleza.","Cuando conste que el menor ha cometido los hechos con violencia o intimidación en las personas.","Cuando no consten indicios de arrepentimiento en el menor."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando conste que el menor ha cometido con anterioridad otros hechos de la misma naturaleza</mark></span>Las opciones tenían errores de transcripción: la regla es que el menor haya cometido con anterioridad otros hechos de la misma naturaleza. Según el <span class=\"ref-norma\">art. 18 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"cuando conste que el menor ha cometido con anterioridad otros hechos de la misma naturaleza, el Ministerio Fiscal deberá incoar el expediente\"</span> (verificado con el temario oficial)."},{"i":"17-262","p":"(LO 5/2000 - Responsabilidad Penal del Menor) Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. De la instrucción del procedimiento. El Ministerio Fiscal podrá desistir de la incoación del expediente cuando los hechos denunciados constituyan:","o":["Delitos menos graves sin violencia o intimidación en las personas o faltas, tipificados en el Código Penal o en las leyes penales especiales.","Delitos leves de lesiones en las personas.","Delitos graves sin fuerza en las cosas.","Delitos graves sin violencia o intimidación en las personas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Delitos menos graves sin violencia o intimidación en las personas o faltas, tipificados en el Código Penal o en las leyes penales especiale…</mark></span><span class=\"ref-norma\">Art. 18.1 · Responsabilidad Penal de los Menores</span>. El Art. 18.1 de la LORPM permite el desistimiento por el Ministerio Fiscal cuando los hechos denunciados constituyan delito leve sin violencia o intimidación en las personas o falta. La opción A se adapta mejor a la redacción de un test pre-reforma del CP, que consideraba las faltas, o al espíritu de la norma (delitos leves o faltas)."},{"i":"17-274","p":"(LO 5/2000 - LORPM) Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. De la instrucción del procedimiento. El Ministerio Fiscal podrá desistir de la incoación del expediente cuando los hechos denunciados constituyan:","o":["Delitos menos graves sin violencia o intimidación en las personas o faltas, tipificados en el Código Penal o en las leyes penales especiales.","Delitos leves de lesiones en las personas.","Delitos graves sin fuerza en las cosas.","Delitos graves sin violencia o intimidación en las personas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Delitos menos graves sin violencia o intimidación en las personas o faltas, tipificados en el Código Penal o en las leyes penales especiale…</mark></span><span class=\"ref-norma\">Art. 18.1 · Responsabilidad Penal de los Menores</span>. (Según el Art. 18.1 de la LORPM, el desistimiento es posible cuando los hechos constituyan delito leve sin violencia o intimidación o falta. La opción 'a' refleja más fielmente el espíritu normativo)."},{"i":"17-ia-1222","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Desistimiento de la incoación del expediente por corrección en el ámbito educativo y familiar. El Ministerio Fiscal podrá desistir de la incoación del expediente cuando los hechos denunciados constituyan delitos menos graves sin violencia o intimidación en las personas o faltas; en tal caso, dará traslado de lo actuado a:","o":["el equipo técnico.","el Juez de Menores.","los representantes legales del menor, salvo que la autoridad judicial disponga otra cosa.","la entidad pública de protección de menores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la entidad pública de protección de menores</mark></span>El <span class=\"ref-norma\">art. 18 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"el Ministerio Fiscal dará traslado de lo actuado a la entidad pública de protección de menores\"</span>. El traslado es a la entidad pública de protección de menores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1223","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Desistimiento de la incoación del expediente por corrección en el ámbito educativo y familiar. Cuando el Ministerio Fiscal desista de la incoación del expediente, comunicará a los ofendidos o perjudicados conocidos:","o":["el archivo de las actuaciones.","la incoación de un expediente de protección.","el desistimiento acordado.","el traslado a la entidad pública."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el desistimiento acordado</mark></span>El <span class=\"ref-norma\">art. 18 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"el Ministerio Fiscal comunicará a los ofendidos o perjudicados conocidos el desistimiento acordado\"</span>. Se comunica el desistimiento acordado a ofendidos o perjudicados conocidos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1224","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Desistimiento de la incoación del expediente por corrección en el ámbito educativo y familiar. Cuando conste que el menor ha cometido con anterioridad otros hechos de la misma naturaleza, el Ministerio Fiscal:","o":["podrá incoar el expediente.","deberá incoar el expediente.","deberá archivar las actuaciones.","solicitará una medida cautelar."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">deberá incoar el expediente</mark></span>El <span class=\"ref-norma\">art. 18 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"cuando conste que el menor ha cometido con anterioridad otros hechos de la misma naturaleza, el Ministerio Fiscal deberá incoar el expediente\"</span>. Hay obligación (deberá) de incoar el expediente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 10 — Reglas especiales de aplicación y duración de las medidas EX","q":[{"i":"17-137","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Prisión igual o superior a quince años, el Juez deberá imponer las medidas siguientes:","o":["Si al tiempo de cometer los hechos el menor tuviere catorce o quince años de edad una medida de internamiento en régimen cerrado de uno a ocho años de duración, complementada en su caso por otra medida de libertad vigilada de hasta tres años.","Si al tiempo de cometer los hechos el menor tuviere catorce o quince años de edad una medida de internamiento en régimen cerrado de uno a cuatro años de duración, complementada en su caso por otra medida de libertad vigilada de hasta tres años.","Si al tiempo de cometer los hechos el menor tuviere dieciséis o diecisiete años de edad una medida de internamiento en régimen cerrado de uno a ocho años de duración, complementada en su caso por otra medida de libertad vigilada con asistencia educativa de hasta cinco años.","Si al tiempo de cometer los hechos el menor tuviere dieciséis o diecisiete años de edad una medida de internamiento en régimen cerrado de uno a cuatro años de duración, complementada en su caso por otra medida de libertad vigilada con asistencia educativa de hasta cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Si al tiempo de cometer los hechos el menor tuviere dieciséis o diecisiete años de edad una medida de internamiento en régimen cerrado de u…</mark></span>Para 16-17 años: internamiento cerrado 1-8 años + libertad vigilada hasta 5 años."},{"i":"17-175","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. De las medidas. Las medidas que pueden imponer los Jueces de Menores, ordenadas según la restricción de derechos que suponen, son las siguientes: señale la INCORRECTA.","o":["Asistencia a un centro de día.","Permanencia de una semana.","Libertad vigilada.","La prohibición de aproximarse o comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el Juez."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Permanencia de una semana.</mark></span>Es incorrecta porque la medida es &quot;permanencia de fin de semana&quot;, no &quot;de una semana&quot;."}]},{"a":"5.4. Tratamiento del testigo menor de edad EX","q":[{"i":"17-139","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Tratamiento del testigo menor de edad. Cuando el testigo de una infracción penal sea menor de edad el tratamiento se adecuará en función de:","o":["Edad.","Grado de madurez.","Circunstancias personales.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span>Todas las circunstancias son correctas para adecuar el tratamiento."},{"i":"17-205","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". Testigos menores de edad. Cuando el testigo de una infracción penal sea menor de edad, el tratamiento se adecuará:","o":["En función de su edad, grado de madurez y circunstancias personales.","A la naturaleza de los hechos que originan la intervención.","A la necesidad de garantizar su igualdad y no discriminación.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span>Todas son correctas."},{"i":"17-218","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad. Por la que se actualiza el protocolo de actuación policial con menores y tratamiento del testigo menor de edad. Al realizar la exploración policial de un menor que ha sido testigo de un hecho criminal del que no sea víctima o denunciante, se tendrá en cuenta lo siguiente:","o":["El menor podrá ser obligado a declarar.","Cuando no acceda voluntariamente a declarar, lo hará en presencia de sus representantes legales.","Se le podrá tomar declaración mediante la intervención o con la colaboración de expertos.","Si el menor no desea declarar no se hará constar en las diligencias."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Se le podrá tomar declaración mediante la intervención o con la colaboración de expertos.</mark></span>Se le podrá tomar declaración mediante la intervención o con la colaboración de expertos."},{"i":"17-ia-1548","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Tratamiento del testigo menor de edad. Cuando el testigo de una infracción penal sea menor de edad, se procurará que reciba de inmediato los cuidados, protección y asistencia:","o":["social, psicológica y jurídica que requieran.","social, psicológica, médica y física que requieran.","médica, psicológica y jurídica que precisen.","social, educativa, médica y psicológica que precisen."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">social, psicológica, médica y física que requieran</mark></span>El <span class=\"ref-norma\">5.4.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"procurando que reciban de inmediato los cuidados, protección, y asistencia social, psicológica, médica y física que requieran\"</span>. Asistencia social, psicológica, médica y física. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1549","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Tratamiento del testigo menor de edad. En la exploración policial de un menor que ha sido testigo de un hecho criminal del que no sea víctima o denunciante, el menor no podrá ser obligado a declarar y, si no desea declarar:","o":["se hará constar en las diligencias.","se comunicará al Fiscal.","se le citará ante el Juez de Menores.","se podrá insistir en presencia de sus representantes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se hará constar en las diligencias</mark></span>El <span class=\"ref-norma\">5.4.2.a de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"El menor no podrá ser obligado a declarar. Si no desea declarar se hará constar en las diligencias\"</span>. Si no desea declarar se hace constar en las diligencias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1550","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Tratamiento del testigo menor de edad. Cuando el menor testigo voluntariamente accediera a declarar, salvo que las circunstancias aconsejen lo contrario, lo hará en presencia de sus representantes legales y, en caso necesario, se comunicará:","o":["al Juez de Menores para que autorice la declaración, salvo que la autoridad judicial disponga otra cosa.","a la entidad pública de protección de menores.","a la Oficina de Asistencia a las Víctimas.","al Fiscal competente para que disponga lo conveniente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al Fiscal competente para que disponga lo conveniente</mark></span>El <span class=\"ref-norma\">5.4.2.b de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"en caso necesario, se comunicará al Fiscal competente para que disponga lo conveniente\"</span>. Se comunica, en caso necesario, al Fiscal competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1551","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Tratamiento del testigo menor de edad. A un menor que ha sido testigo de un hecho criminal se le podrá tomar declaración mediante:","o":["la intervención de la Fiscalía, en todo caso.","grabación audiovisual obligatoria.","la intervención o con la colaboración de expertos.","un psicólogo del equipo técnico, en todo caso, previo informe de la unidad policial competente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la intervención o con la colaboración de expertos</mark></span>El <span class=\"ref-norma\">5.4.2.c de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"Se le podrá tomar declaración mediante la intervención o con la colaboración de expertos\"</span>. Mediante la intervención o colaboración de expertos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1552","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Tratamiento del testigo menor de edad. Al objeto de garantizar su protección y su posterior actuación procesal, se evitará en todo momento el contacto o la confrontación visual de los menores testigos, y de sus familiares, con:","o":["los medios de comunicación, sin perjuicio de lo previsto en la normativa vigente.","los inculpados o investigados.","otros testigos.","las víctimas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los inculpados o investigados</mark></span>El <span class=\"ref-norma\">5.4.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"se evitará, en todo momento, el contacto o la confrontación visual de éstos, y de sus familiares, con los inculpados o investigados\"</span>. Se evita el contacto o la confrontación visual con los inculpados o investigados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 3 — Régimen de los menores de catorce años EX","q":[{"i":"17-141","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Régimen de los menores de catorce años. Cuando el autor de un hechos tipificado como delito sea menor de catorce años, no se le exigirá responsabilidad con arreglo a la presente Ley, sino que se le aplicará lo dispuesto en las normas sobre protección de menores previstas en:","o":["La legislación automatizada.","El Código Civil y demás disposiciones vigentes.","La responsabilidad de menores.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Código Civil y demás disposiciones vigentes.</mark></span>Código Civil y disposiciones sobre protección de menores."},{"i":"17-200","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Ámbito de aplicación de la Ley. ¿Qué sucede cuando el autor de los hechos cometidos es menor de catorce años?","o":["Se le aplicarán las mismas sanciones que a los mayores de catorce años.","Se le exigirá responsabilidad conforme a la Ley Orgánica de Responsabilidad Penal de los Menores.","No se le exigirá responsabilidad penal según esta Ley, sino que se le aplicarán las normas de protección de menores.","Se le llevará directamente a un centro de menores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No se le exigirá responsabilidad penal según esta Ley, sino que se le aplicarán las normas de protección de menores.</mark></span>No se le exige responsabilidad penal, se aplican normas de protección de menores."},{"i":"17-209","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. El Ministerio Fiscal deberá remitir a la entidad pública de protección de menores testimonio de los particulares que considere precisos respecto al menor, a fin de valorar su situación, y dicha entidad habrá de promover las medidas de protección adecuadas a las circunstancias de aquel conforme a lo dispuesto en:","o":["La Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial.","La Ley Orgánica 1/1996, de 15 de enero.","La Ley General de Derechos de la Infancia.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Ley Orgánica 1/1996, de 15 de enero.</mark></span>La Ley Orgánica 1/1996, de 15 de enero (Ley de Protección Jurídica del Menor)."},{"i":"17-ia-1009","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen de los menores de catorce años. Cuando el autor de los hechos sea menor de catorce años, no se le exigirá responsabilidad con arreglo a la presente Ley, sino que se le aplicará lo dispuesto en las normas sobre protección de menores previstas en:","o":["el Código Civil y demás disposiciones vigentes.","el Código Penal y demás disposiciones vigentes.","la Ley Orgánica 5/2000 con carácter supletorio.","la Ley de Enjuiciamiento Criminal y demás disposiciones vigentes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Código Civil y demás disposiciones vigentes</mark></span>El <span class=\"ref-norma\">art. 3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"sino que se le aplicará lo dispuesto en las normas sobre protección de menores previstas en el Código Civil y demás disposiciones vigentes\"</span>. La protección de los menores de catorce años se rige por el Código Civil y demás disposiciones vigentes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1010","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen de los menores de catorce años. El Ministerio Fiscal deberá remitir a la entidad pública de protección de menores __________ de los particulares que considere precisos respecto al menor, a fin de valorar su situación:","o":["copia íntegra","informe","certificación","testimonio"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">testimonio</mark></span>El <span class=\"ref-norma\">art. 3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"deberá remitir a la entidad pública de protección de menores testimonio de los particulares que considere precisos respecto al menor, a fin de valorar su situación\"</span>. Se remite testimonio de los particulares que el Fiscal considere precisos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1011","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Régimen de los menores de catorce años. La entidad pública de protección de menores habrá de promover las medidas de protección adecuadas a las circunstancias del menor de catorce años, conforme a lo dispuesto en:","o":["la Ley Orgánica 8/2015, de 22 de julio, previo informe de la unidad policial competente.","la Ley Orgánica 5/2000, de 12 de enero.","la Ley Orgánica 1/1996, de 15 de enero.","la Ley 26/2015, de 28 de julio."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Ley Orgánica 1/1996, de 15 de enero</mark></span>El <span class=\"ref-norma\">art. 3 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"conforme a lo dispuesto en la Ley Orgánica 1/1996, de 15 de enero\"</span>. La remisión es a la LO 1/1996, de Protección Jurídica del Menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"7.1. Actuación policial en los entornos escolares","q":[{"i":"17-191","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de Actuación Policial con Menores\". En las labores de vigilancia policial en las inmediaciones de los centros escolares NO se prestará singular atención a aquellas cuestiones de seguridad ciudadana que más afectan a los menores, como:","o":["Acoso escolar.","Bandas juveniles violentas.","Crimen organizado.","Acceso a drogas y alcohol, vandalismo, xenofobia o racismo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Crimen organizado</mark></span>El absentismo escolar tampoco figura, pero el acoso escolar sí; solo «crimen organizado» queda fuera de la lista. Según el <span class=\"ref-norma\">punto 7.1.2 de la Instrucción 1/2017 de la SES</span>: <span class=\"ref-concepto\">\"como acoso escolar, bandas juveniles violentas, acceso a drogas y alcohol, vandalismo, xenofobia o racismo, violencia de género en los jóvenes, riesgos de Internet y las nuevas tecnologías\"</span> (verificado con el temario oficial)."},{"i":"17-ia-1608","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores en el entorno escolar. Se prestará una atención especial a las cuestiones relacionadas con la seguridad de niños y jóvenes en la escuela y su entorno, en el marco de lo dispuesto en la Instrucción 7/2013, sobre el:","o":["«Plan de actuación y coordinación policial contra grupos organizados y violentos de carácter juvenil», salvo que la autoridad judicial disponga otra cosa.","«Plan Director para la convivencia y mejora de la seguridad en los centros educativos y sus entornos».","«Plan operativo de respuesta policial al tráfico minorista y consumo de drogas».","«Plan Estratégico de convivencia escolar y prevención del acoso»."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">«Plan Director para la convivencia y mejora de la seguridad en los centros educativos y sus entornos»</mark></span>El <span class=\"ref-norma\">7.1.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"en el marco de lo dispuesto en la Instrucción 7/2013, sobre el Plan Director para la convivencia y mejora de la seguridad en los centros educativos y sus entornos\"</span>. La Instrucción 7/2013 es el Plan Director para la convivencia y mejora de la seguridad en centros educativos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1609","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores en el entorno escolar. En las labores de vigilancia policial en las inmediaciones de los centros escolares se prestará singular atención a cuestiones como acoso escolar, bandas juveniles violentas, acceso a drogas y alcohol, vandalismo, xenofobia o racismo, violencia de género en los jóvenes y:","o":["riesgos de Internet y las nuevas tecnologías.","absentismo escolar.","consumo de tabaco.","mendicidad infantil, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">riesgos de Internet y las nuevas tecnologías</mark></span>El <span class=\"ref-norma\">7.1.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"violencia de género en los jóvenes, riesgos de Internet y las nuevas tecnologías\"</span>. Incluye los riesgos de Internet y las nuevas tecnologías. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1610","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores en el entorno escolar. Entre las Instrucciones de la Secretaría de Estado de Seguridad a las que se presta especial atención en la vigilancia de los centros escolares, la número 17/2014 trata sobre el:","o":["«Plan Director para la convivencia y mejora de la seguridad en los centros educativos y sus entornos».","«Plan operativo de respuesta policial al tráfico minorista y consumo de drogas en zonas, lugares y locales de ocio».","«Protocolo de actuación policial con menores».","«Plan de actuación y coordinación policial contra grupos organizados y violentos de carácter juvenil»."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">«Plan de actuación y coordinación policial contra grupos organizados y violentos de carácter juvenil»</mark></span>El <span class=\"ref-norma\">7.1.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"número 17/2014, sobre el Plan de actuación y coordinación policial contra grupos organizados y violentos de carácter juvenil\"</span>. La Instrucción 17/2014 es el plan contra grupos organizados y violentos de carácter juvenil. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1611","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores en el entorno escolar. La Instrucción 3/2011 de la Secretaría de Estado de Seguridad regula el Plan operativo de respuesta policial al:","o":["acoso escolar en los centros educativos.","tráfico de drogas en los entornos escolares.","tráfico minorista y consumo de drogas en zonas, lugares y locales de ocio.","consumo de alcohol por menores en la vía pública, sin perjuicio de lo previsto en la normativa vigente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">tráfico minorista y consumo de drogas en zonas, lugares y locales de ocio</mark></span>El <span class=\"ref-norma\">7.1.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"3/2011 sobre el Plan operativo de respuesta policial al tráfico minorista y consumo de drogas en zonas, lugares y locales de ocio\"</span>. La Instrucción 3/2011 es el plan operativo contra el tráfico minorista y consumo de drogas en zonas de ocio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 4 — Derechos de las víctimas y de las personas perjudicadas EX","q":[{"i":"17-192","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. El Ministerio Fiscal y el Juez de Menores velarán en todo momento por la protección de los derechos de las víctimas y de las personas perjudicadas por las infracciones cometidas por las personas menores de edad. ______ se les instruirá de las medidas de asistencia a las víctimas que prevé la legislación vigente, debiendo el Letrado de la Administración de Justicia derivar a la víctima de violencia a la Oficina de Atención a la Victima competente.","o":["Tan pronto como sea posible.","Inmediatamente.","De manera inmediata.","Lo antes posible."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De manera inmediata</mark></span>La expresión literal es «de manera inmediata». Según el <span class=\"ref-norma\">art. 4 de la Ley Orgánica 5/2000, de 12 de enero</span>: <span class=\"ref-concepto\">\"De manera inmediata se les instruirá de las medidas de asistencia a las víctimas\"</span> (verificado con el temario oficial)."},{"i":"17-197","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Ámbito de aplicación de la Ley. ¿Qué derecho tienen las víctimas y las personas perjudicadas en el expediente incoado por las infracciones cometidas por las personas menores de edad?","o":["Derecho a personarse y ser parte en el expediente.","Derecho a ser notificados de todas las resoluciones del Juez de Menores.","Derecho a que el Ministerio Fiscal se haga cargo de todas las acciones civiles, en todo caso.","Derecho a presentar toda la documentación pertinente sobre el caso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Derecho a personarse y ser parte en el expediente.</mark></span>Derecho a personarse y ser parte en el expediente."},{"i":"17-ia-1012","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Derechos de las víctimas y de las personas perjudicadas. De manera inmediata se les instruirá de las medidas de asistencia a las víctimas que prevé la legislación vigente, debiendo el Letrado de la Administración de Justicia derivar a la víctima de violencia a:","o":["la Oficina de Asistencia a las Víctimas del Delito del lugar de los hechos.","la Oficina de Atención a la Víctima competente.","el servicio de protección de menores de la Comunidad Autónoma.","la Sección de Menores de la Fiscalía."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Oficina de Atención a la Víctima competente</mark></span>El <span class=\"ref-norma\">art. 4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"debiendo el Letrado de la Administración de Justicia derivar a la víctima de violencia a la Oficina de Atención a la Víctima competente\"</span>. La derivación es a la Oficina de Atención a la Víctima competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1013","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Derechos de las víctimas y de las personas perjudicadas. Las víctimas y las personas perjudicadas tendrán derecho a personarse y ser parte en el expediente que se incoe al efecto, instruyéndoles el Letrado de la Administración de Justicia de su derecho a nombrar dirección letrada o instar su nombramiento de oficio en caso de ser titulares del derecho a:","o":["la asistencia jurídica gratuita.","la asistencia letrada especializada.","la justicia gratuita en todo caso.","la defensa jurídica de oficio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la asistencia jurídica gratuita</mark></span>El <span class=\"ref-norma\">art. 4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"instruyéndoles de su derecho a nombrar dirección letrada o instar su nombramiento de oficio en caso de ser titulares del derecho a la asistencia jurídica gratuita\"</span>. El nombramiento de oficio procede si son titulares del derecho a la asistencia jurídica gratuita. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1015","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Derechos de las víctimas y de las personas perjudicadas. Se garantizará especialmente que las declaraciones o interrogatorios de las partes acusadoras, testigos o peritos se realicen de forma telemática en determinados supuestos, salvo que el Juez, Tribunal o Ministerio Fiscal, mediante resolución motivada, en atención a las circunstancias del caso concreto, estime necesaria:","o":["la presencia del letrado del menor.","su declaración en el acto del juicio.","su presencia física.","la comparecencia ante el Juez de Menores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">su presencia física</mark></span>El <span class=\"ref-norma\">art. 4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"salvo que el Juez, Tribunal o Ministerio Fiscal, mediante resolución motivada, en atención a las circunstancias del caso concreto, estime necesaria su presencia física\"</span>. La excepción es que se estime necesaria su presencia física, mediante resolución motivada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1016","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Derechos de las víctimas y de las personas perjudicadas. Señale la INCORRECTA. Las declaraciones o interrogatorios se realizarán de forma telemática, salvo resolución motivada, cuando sean víctimas de:","o":["violencia de género.","cualquier delito cometido por menores de edad, en todo caso.","trata de seres humanos, sin perjuicio de lo previsto en la normativa vigente.","violencia sexual."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cualquier delito cometido por menores de edad, en todo caso</mark></span>El <span class=\"ref-norma\">art. 4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"Cuando sean víctimas de violencia de género, de violencia sexual, de trata de seres humanos o cuando sean víctimas menores de edad o con discapacidad\"</span>. Los supuestos son los enumerados: violencia de género, sexual, trata, o víctimas menores de edad o con discapacidad; no cualquier delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1017","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Derechos de las víctimas y de las personas perjudicadas. Las víctimas podrán intervenir desde los lugares donde se encuentren recibiendo oficialmente asistencia, atención, asesoramiento o protección, o desde cualquier otro lugar, siempre que dispongan de medios suficientes para asegurar:","o":["su identidad y las adecuadas condiciones de la intervención.","la seguridad de la comunicación y la confidencialidad de la intervención.","su identidad y la grabación de la intervención.","la presencia de un representante legal y la identificación del lugar."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">su identidad y las adecuadas condiciones de la intervención</mark></span>El <span class=\"ref-norma\">art. 4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"siempre que dispongan de medios suficientes para asegurar su identidad y las adecuadas condiciones de la intervención\"</span>. Los medios deben asegurar la identidad y las adecuadas condiciones de la intervención. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1018","p":"Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores. Derechos de las víctimas y de las personas perjudicadas. El Letrado de la Administración de Justicia notificará por escrito la sentencia que se dicte a las víctimas y las personas perjudicadas por la infracción penal, aunque:","o":["hayan renunciado a las acciones civiles.","no hayan sido informadas de sus derechos, en los términos que se determinen reglamentariamente.","la sentencia todavía no sea firme.","no se hayan mostrado parte en el expediente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no se hayan mostrado parte en el expediente</mark></span>El <span class=\"ref-norma\">art. 4 de la LO 5/2000</span> se dispone: <span class=\"ref-concepto\">\"notificará por escrito la sentencia que se dicte a las víctimas y las personas perjudicadas por la infracción penal, aunque no se hayan mostrado parte en el expediente\"</span>. Se notifica aunque no se hayan mostrado parte (párrafo recogido en tu temario). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"8.1. Actuación con menores en situación de riesgo o desamparo","q":[{"i":"17-203","p":"Instrucción nº 1/2017 de la Secretaría de Estado de Seguridad, por la que se actualiza el protocolo de actuación policial con menores. Menores en situación de desamparo. ¿Qué acción debe realizar la policía cuando detecta a un menor en situación de riesgo?","o":["Sólo se debe realizar la situación al Ministerio Fiscal sin intervenir directamente.","El menor debe ser entregado inmediatamente a los padres sin importar las circunstancias.","Se le prestará asistencia inmediata y se investigarán las causas de su situación.","Se procederá a colocar al menor en un centro de acogida sin más intervenciones."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Se le prestará asistencia inmediata y se investigarán las causas de su situación.</mark></span>Se prestará asistencia inmediata e investigación de causas."},{"i":"17-ia-1628","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores en situación de riesgo o desamparo. Se considera situación de riesgo aquella en la que, sin llegar a la intensidad que fundamentaría su declaración de desamparo, sea precisa la intervención de la administración para eliminar o reducir las dificultades que afectan al menor, sin tener que ser:","o":["ingresado en un centro de protección.","separado de su entorno familiar.","declarado en desamparo.","puesto bajo tutela de la entidad pública."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">separado de su entorno familiar</mark></span>El <span class=\"ref-norma\">8.1.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"sea precisa la intervención de la administración para eliminar o reducir las dificultades que le afectan, sin tener que ser separado de su entorno familiar\"</span>. En el riesgo no es preciso separar al menor de su entorno familiar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1629","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores en situación de riesgo o desamparo. Se considera situación de desamparo la que se produce de hecho a causa del incumplimiento, o del imposible o inadecuado ejercicio de los deberes de protección establecidos por las leyes para la guarda de los menores, cuando éstos queden privados de:","o":["la necesaria asistencia moral o material.","la necesaria asistencia educativa o sanitaria.","un entorno familiar estable.","la guarda de sus progenitores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la necesaria asistencia moral o material</mark></span>El <span class=\"ref-norma\">8.1.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"cuando éstos queden privados de la necesaria asistencia moral o material\"</span>. Quedan privados de la necesaria asistencia moral o material. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1630","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores en situación de riesgo o desamparo. A los solos efectos de actuación policial, un menor está en aparente situación de riesgo cuando existen indicios racionales de peligro, inminente o no, a su:","o":["integridad física o moral.","salud y su integridad física, salvo que la autoridad judicial disponga otra cosa.","desarrollo personal y social.","integridad física, psíquica o moral."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">integridad física, psíquica o moral</mark></span>El <span class=\"ref-norma\">8.1.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"existen indicios racionales de peligro, inminente o no, a su integridad física, psíquica o moral\"</span>. Peligro a su integridad física, psíquica o moral. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1631","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores en situación de riesgo o desamparo. Señale la INCORRECTA entre las situaciones en las que los agentes deben valorar la edad, estado y circunstancias del entorno ante una aparente situación de riesgo del menor:","o":["Absentismo escolar.","Posible fuga domiciliaria.","Consumo de tabaco.","Mendicidad voluntaria u obligada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Consumo de tabaco</mark></span>El <span class=\"ref-norma\">8.1.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"debiendo valorar su edad, estado y las circunstancias del entorno en casos de absentismo escolar, posible fuga domiciliaria, consumo de alcohol o estupefacientes, mendicidad voluntaria u obligada, vagabundeo\"</span>. Se cita el consumo de alcohol o estupefacientes, no el de tabaco. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1633","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Menores en situación de riesgo o desamparo. Un menor está en aparente situación de desamparo o desprotección cuando, al ser detectado o entrar en contacto con los agentes de policía, carece de:","o":["la presencia inmediata o de la posterior referencia de un adulto responsable en calidad de ejerciente de la patria potestad, tutela, custodia, guarda legal o de hecho.","la presencia inmediata de sus padres o tutores legales.","documentación acreditativa de su identidad y de su domicilio, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","la referencia de un familiar hasta el cuarto grado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la presencia inmediata o de la posterior referencia de un adulto responsable en calidad de ejerciente de la patria potestad, tutela, custodia, guarda legal o de hecho</mark></span>El <span class=\"ref-norma\">8.1.3 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"carece de la presencia inmediata o de la posterior referencia de un adulto responsable en calidad de ejerciente de la patria potestad, tutela, custodia, guarda legal o de hecho\"</span>. Carece de presencia inmediata o referencia posterior de un adulto responsable. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"10.2. Libros-Registros EX","q":[{"i":"17-248","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Registros policiales de datos personales de menores. El Libro-Registro de Menores Detenidos, regulado en la Instrucción 7/2005, de 25 de abril, de la Secretaría de Estado de Seguridad, tendrá carácter confidencial y será único para todo lo concerniente al menor, no consignándose sus datos:","o":["En el Libro de Registro y Custodia de Detenidos, aunque sí en otros libros de la dependencia policial.","En ningún libro de otras dependencias policiales, aunque sí en el Libro de Registro y Custodia de Detenidos.","En el Libro-Registro de Diligencias de Identificación ni en el de actuaciones con menores en situación de riesgo.","En el Libro de Registro y Custodia de Detenidos ni en ningún otro libro de la dependencia policial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En el Libro de Registro y Custodia de Detenidos ni en ningún otro libro de la dependencia policial</mark></span>El <span class=\"ref-norma\">punto 10.2.1.b de la Instrucción 1/2017</span> dispone: <span class=\"ref-concepto\">\"Tendrá carácter confidencial y será único para todo lo concerniente al menor, no consignándose sus datos en el Libro de Registro y Custodia de Detenidos ni en ningún otro libro de la dependencia policial\"</span>"},{"i":"17-ia-1656","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Registros policiales de datos personales de menores. En el Libro-Registro de Menores Detenidos se anotarán las incidencias que puedan producirse en las dependencias policiales durante la permanencia en las mismas de menores:","o":["menores de dieciocho años, presuntamente responsables de infracciones penales, en los términos que se determinen reglamentariamente.","entre catorce y dieciocho años, presuntamente responsables de la comisión de infracciones penales.","entre dieciséis y dieciocho años, presuntamente responsables de delitos.","menores de catorce años, presuntamente responsables de infracciones penales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">entre catorce y dieciocho años, presuntamente responsables de la comisión de infracciones penales</mark></span>El <span class=\"ref-norma\">10.2.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"durante la permanencia en las mismas de menores entre catorce y dieciocho años, presuntamente responsables de la comisión de infracciones penales\"</span>. Menores entre catorce y dieciocho años presuntamente responsables de infracciones penales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1657","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Registros policiales de datos personales de menores. El Libro-Registro de actuaciones con Menores e Incapaces en Situaciones de Riesgo está regulado en la Instrucción __________, de 4 de julio, de la Secretaría de Estado de Seguridad:","o":["2/2001","7/2005, salvo que la autoridad judicial disponga otra cosa.","2/2005","7/2001"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">2/2001</mark></span>El <span class=\"ref-norma\">10.2.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"regulado en la Instrucción 2/2001, de 4 de julio, de la Secretaría de Estado de Seguridad\"</span>. Es la Instrucción 2/2001, de 4 de julio (la 7/2005, de 25 de abril, regula el de Menores Detenidos). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1659","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Registros policiales de datos personales de menores. En el ámbito de la Inspección de Personal y Servicios de Seguridad (IPSS) de la Secretaría de Estado de Seguridad se encuentra en desarrollo un proyecto de:","o":["unificación de las bases de datos de menores, previo informe de la unidad policial competente.","creación del Registro Central de Menores.","digitalización y estandarización del contenido de los libros de registro.","centralización de los álbumes fotográficos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">digitalización y estandarización del contenido de los libros de registro</mark></span>El <span class=\"ref-norma\">10.2.4 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"un proyecto de digitalización y estandarización del contenido de los libros de registro de la Secretaría de Estado de Seguridad\"</span>. Se desarrolla un proyecto de digitalización y estandarización de los libros de registro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"General / Responsabilidad Penal de los Menores","q":[{"i":"17-270","p":"(LO 5/2000 - LORPM) Ley Orgánica 5/2000, de 12 de enero, reguladora de la Responsabilidad Penal de los Menores. Instrucción del procedimiento. Sobreseimiento del expediente por conciliación o reparación entre el menor y la víctima. Señale la correcta.","o":["El desistimiento en la continuación del expediente sólo será posible cuando el hecho imputado al menor constituya delito menos grave o falta.","El único requisito será la falta de violencia o intimidación.","Será posible cuando el hecho imputado al menor no constituya delito menos grave.","A y B son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Será posible cuando el hecho imputado al menor no constituya delito menos grave.</mark></span><span class=\"ref-norma\">Art. 19.1 · Responsabilidad Penal de los Menores</span>. El artículo 19.1 de la LO 5/2000, LORPM, regula el sobreseimiento del expediente por conciliación o reparación entre el menor y la víctima y establece que «el desistimiento en la continuación del expediente sólo será posible cuando el hecho imputado al menor constituya delito menos grave o falta». Dicho de otro modo, esta vía de sobreseimiento es posible siempre que el hecho no constituya un delito grave, esto es, «cuando el hecho imputado al menor no constituya delito menos grave» en el sentido restrictivo que recoge la opción C conforme al banco de preguntas."},{"i":"17-ia-1503","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Objeto y ámbito de aplicación. La actuación policial con menores se ajustará, entre otras normas, a la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores, y su reglamento, aprobado en el Real Decreto __________:","o":["1109/2015, de 11 de diciembre","557/2011, de 20 de abril","1774/2004, de 30 de julio","1774/2004, de 12 de enero"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">1774/2004, de 30 de julio</mark></span>El <span class=\"ref-norma\">1.2.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"su reglamento, aprobado en el Real Decreto 1774/2004, de 30 de julio\"</span>. El reglamento es el Real Decreto 1774/2004, de 30 de julio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1504","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Objeto y ámbito de aplicación. El Real Decreto 1109/2015, de 11 de diciembre, desarrolla la Ley 4/2015, del Estatuto de la víctima del delito, y regula:","o":["el Registro de Menores Infractores.","las Oficinas de Asistencia a las Víctimas del Delito.","los equipos técnicos de menores.","las Unidades de Atención a la Familia y Mujer, en los términos que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las Oficinas de Asistencia a las Víctimas del Delito</mark></span>El <span class=\"ref-norma\">1.2.1 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"el Real Decreto 1109/2015, de 11 de diciembre, por el que se desarrolla la Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito, y se regulan las Oficinas de Asistencia a las Víctimas del Delito\"</span>. Regula las Oficinas de Asistencia a las Víctimas del Delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1505","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Objeto y ámbito de aplicación. Las diligencias o trámites procedimentales que no estén previstos expresamente en la Ley Orgánica 5/2000 se regularán, con carácter supletorio, conforme al:","o":["Código Penal, leyes penales especiales, Ley de Enjuiciamiento Criminal y Código Civil.","Código Penal, Ley de Enjuiciamiento Criminal y Ley Orgánica de Protección Jurídica del Menor.","Código Penal y Ley de Enjuiciamiento Criminal, exclusivamente.","Código Penal, Código Civil y Ley Orgánica 1/1996."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Código Penal, leyes penales especiales, Ley de Enjuiciamiento Criminal y Código Civil</mark></span>El <span class=\"ref-norma\">1.2.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"se regularán, con carácter supletorio, conforme al Código Penal, leyes penales especiales, Ley de Enjuiciamiento Criminal y Código Civil\"</span>. La supletoriedad es del Código Penal, leyes penales especiales, LECrim y Código Civil. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"5.2. Recepción de denuncias a menores de edad víctimas o testigos de delitos EX","q":[{"i":"17-ia-1524","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Recepción de denuncias a menores de edad víctimas o testigos de delitos. Los menores de edad víctimas o testigos del delito ostentan legitimación para interponer denuncia ante los agentes policiales:","o":["siempre que sean mayores de dieciséis años, sin perjuicio de lo previsto en la normativa vigente.","sin necesidad de la presencia de quienes ejerzan su patria potestad o tutela.","acompañados de un representante legal.","previa autorización del Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sin necesidad de la presencia de quienes ejerzan su patria potestad o tutela</mark></span>El <span class=\"ref-norma\">5.2.1.a de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"ostentan legitimación para interponer denuncia ante los agentes policiales sin necesidad de la presencia de quienes ejerzan su patria potestad o tutela\"</span>. Tienen legitimación sin necesidad de la presencia de sus representantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"17-ia-1526","p":"Instrucción 1/2017, de la Secretaría de Estado de Seguridad, por la que se actualiza el \"Protocolo de actuación policial con menores\". Recepción de denuncias a menores de edad víctimas o testigos de delitos. Los agentes policiales, evaluando las condiciones particulares del menor y del supuesto a denunciar, determinarán provisionalmente las medidas de protección que resulten adecuadas, sin perjuicio de la decisión final que pueda adoptar:","o":["el Ministerio Fiscal.","la entidad pública de protección de menores.","el Juez de Menores o el Fiscal.","la Autoridad Judicial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la Autoridad Judicial</mark></span>El <span class=\"ref-norma\">5.2.2 de la Instrucción 1/2017</span> se dispone: <span class=\"ref-concepto\">\"sin perjuicio de la decisión final que, con relación a las mismas, pueda adoptar la Autoridad Judicial\"</span>. La decisión final es de la Autoridad Judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]}];
